// BUILD-57 §2b — BULK-IMPORT ids carry FULL uuid entropy (32 hex). The 8-hex
// ids minted elsewhere are fine one-at-a-time, but the import writes 500 rows
// per statement, where a single global-pkey collision (8 hex = 32 bits —
// birthday-collides at real multi-tenant scale) aborted the WHOLE batch and
// lost its rows (the BUILD-54 finding, hit live in a pre-push run). Width,
// not retry: 2^128 puts the class out of reach on every import mint site.
const importId = prefix => prefix + uuid().replace(/-/g, "");
// WIRE-1: an imported gift names its campaign; Reports filtered by campaign
// match on campaign_id. One org-scoped lookup, exact and case-insensitive. A
// name two campaigns share is left unresolved rather than guessed.
async function campaignIdResolver(orgId) {
  const rows = await query("SELECT id, name FROM campaigns WHERE org_id=?", [orgId]);
  const byName = new Map();
  for (const r of rows) {
    const k = String(r.name || "").trim().toLowerCase();
    if (!k) continue;
    byName.set(k, byName.has(k) ? null : r.id);
  }
  return name => byName.get(String(name || "").trim().toLowerCase()) || null;
}
const IMPORT_RUN_ID_RE = /^imp_[A-Za-z0-9_-]{4,40}$/;
function invalidateOrgTz(orgId) { _tzCache.delete(orgId); }

// BUILD-72 Part 1 — an import that does not reconcile is not a 500. The
// transaction has already rolled back by the time this runs (db.js's
// withTransaction ROLLBACKs on throw), so nothing landed; the caller gets 409
// plus the equation that failed, and the client renders the dollar discrepancy
// on the summary screen. Wrap an import handler in this instead of `wrap`.
const wrapImport = fn => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(e => {
  if (e && e.code === "import_unreconciled") {
    console.error("[import] ABORTED — did not reconcile:", e.message, JSON.stringify(e.reconciliation));
    return res.status(409).json({
      error: "import_unreconciled",
      message: e.message,
      reconciliation: e.reconciliation,
    });
  }
  return next(e);
});

// ── BUILD-88c C.2 — NEVER A BLANK BOX ─────────────────────────────────────
// Communications opened on an empty editor and a blinking cursor. That is the
// moment a fundraiser closes the tab: writing an appeal from nothing, in a box,
// with a send button underneath, is the hardest thing on the screen and Steward
// was asking for it first. Six real emails instead, in the org's own words and
// colours.
const templatesMod = () => import("../shared/emailTemplates.js");
const birthdayMod = () => import("../shared/birthday.js");   // PARITY-3 6a

app.get("/campaigns/templates", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const T = await templatesMod();
  const [org] = await query("SELECT name, vocabulary_json FROM orgs WHERE id=?", [orgId]);
  const V = await import("../shared/vocabulary.js");
  const vocab = (() => { try { return org?.vocabulary_json ? JSON.parse(org.vocabulary_json) : null; } catch { return null; } })();
  const t = V.makeT(vocab);
  const theme = await resolveOrgBrandTheme(orgId).catch(() => null);
  const dfName = await donorFacingOrgName(orgId, org?.name || "").catch(() => org?.name || "");
  const list = T.templatesFor({ orgName: dfName, t });
  // PARITY-1 E — which starters a person here has already made their own.
  const reviewedRows = await query("SELECT starter_key FROM email_starter_reviews WHERE org_id=?", [orgId]).catch(() => []);
  const reviewed = new Set(reviewedRows.map(r => r.starter_key));
  res.json({
    orgName: dfName,
    // The org's own colours and logo, so the gallery is THEIR email and not a
    // stock one with their name pasted in.
    brand: theme ? { band: theme.band, bandFg: theme.bandFg, logo: theme.logoDataUri || theme.logoAbsUrl || null, displayName: theme.displayName } : null,
    mergeFields: T.MERGE_FIELDS,
    templates: list.map(x => ({ key: x.key, label: x.label, blurb: x.blurb, subject: x.subject, body: x.body, reviewed: reviewed.has(x.key) })),
  });
}));

// PARITY-1 E — A STARTER BECOMES THE ORG'S OWN when somebody saves a campaign
// from it with its words changed. The comparison is against the starter as
// THIS org is offered it (its name, its vocabulary), by text rather than markup,
// so an editor's re-serialised HTML is not mistaken for an edit. A key that is
// not one of the org's starters is ignored, never stored.
async function markStarterReviewed(req, starterKey, body, campaignId) {
  const key = String(starterKey || "").slice(0, 60);
  if (!key) return;
  const orgId = req.user.orgId;
  const T = await templatesMod();
  const [org] = await query("SELECT name, vocabulary_json FROM orgs WHERE id=?", [orgId]);
  const V = await import("../shared/vocabulary.js");
  const vocab = (() => { try { return org?.vocabulary_json ? JSON.parse(org.vocabulary_json) : null; } catch { return null; } })();
  const dfName = await donorFacingOrgName(orgId, org?.name || "").catch(() => org?.name || "");
  const tpl = T.templatesFor({ orgName: dfName, t: V.makeT(vocab) }).find(x => x.key === key);
  if (!tpl || !T.starterEdited(tpl, body)) return;
  await run(
    `INSERT INTO email_starter_reviews (org_id, starter_key, campaign_id, created_by, created_by_name)
     VALUES (?,?,?,?,?) ON CONFLICT (org_id, starter_key) DO NOTHING`,
    [orgId, key, campaignId || null, actor(req).id, actor(req).name]);
}

// The segment, as PEOPLE. "17 recipients" is a number; "17 sponsors, including
// Margaret Chen and Bob Harmon" is a group — and a name that should not be on
// the list is the only thing anybody actually notices.
app.post("/campaigns/segment-preview", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const T = await templatesMod();
  const seg = req.body?.segment && typeof req.body.segment === "object" ? req.body.segment : {};
  // FIX-26: the count is the send's own decision for each person, so the
  // number on the button is the number of messages the send creates.
  const aud = await campaignAudience({ segment: JSON.stringify(seg) }, orgId)
    .catch(() => ({ recipients: [], leftOut: [], leftOutCount: 0, orgGate: { send: false, reason: "unreadable" } }));
  const donors = aud.recipients;
  const [org] = await query("SELECT vocabulary_json FROM orgs WHERE id=?", [orgId]);
  const V = await import("../shared/vocabulary.js");
  const vocab = (() => { try { return org?.vocabulary_json ? JSON.parse(org.vocabulary_json) : null; } catch { return null; } })();
  const t = V.makeT(vocab);
  // The vocabulary key for a giver is `giver`, not `donor` — asking for
  // "donor" returns null and the sentence reads "3 null, including Margaret".
  // BUILD-94 Part 2 — a segment that crosses types reads as PEOPLE. "6 donors"
  // under a Volunteers segment is exactly the contradiction this part removes,
  // and the org's own word for a giver is still wrong for a volunteer.
  const PERSON_SEGMENTS = new Set(["everyone", "volunteers", "staff_board"]);
  const noun = seg.mode === "recurring" ? t("monthly_giver", 2)
    : PERSON_SEGMENTS.has(seg.mode) ? "people"
    : t("giver", 2);
  const names = donors.slice(0, 2).map(d => displayNameCase(d.name || ""));
  res.json({
    count: donors.length,
    names: donors.slice(0, 8).map(d => ({ id: d.id, name: displayNameCase(d.name || ""), email: d.email })),
    sentence: T.segmentSentence(donors.length, names, noun),
    // The first recipient is whose name the preview shows, so what she reads on
    // the right of the screen is the email the first person will get.
    first: donors[0] ? { name: displayNameCase(donors[0].name || ""), firstName: String(donors[0].name || "").trim().split(/\s+/)[0] || "Margaret" } : null,
    // Who the segment holds and this send will not reach, by reason, with the
    // first names of each so "3 left out" opens onto people, not a number.
    leftOutCount: aud.leftOutCount,
    leftOut: aud.leftOut.map(g => ({
      reason: g.reason, count: g.count,
      people: g.people.slice(0, 25).map(d => ({ id: d.id, name: displayNameCase(d.name || "") })),
    })),
    // The organisation itself sends no mail (the demonstration org, or mail
    // switched off): nobody gets it, said once rather than per person.
    orgSends: !!(aud.orgGate && aud.orgGate.send),
    orgReason: aud.orgGate && !aud.orgGate.send ? aud.orgGate.reason : null,
  });
}));

// SEND ME A TEST — one copy, to the person pressing the button, under whatever
// sending identity is in force. It is not a recipient: no `campaign_recipients`
// row, no interaction on anybody's record, and the campaign's own count does
// not move. A test that counted would make every campaign's numbers wrong by
// one, forever.
app.post("/campaigns/:id/test", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [campaign] = await query("SELECT * FROM campaigns WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!campaign) return res.status(404).json({ error: "Campaign not found" });
  const [me] = await query("SELECT email, name FROM users WHERE id=? AND org_id=?", [req.user.userId, orgId]);
  const to = String(req.body?.to || me?.email || "").trim();
  if (!to) return res.status(400).json({ error: "No address to send the test to." });
  if (to !== me?.email) return res.status(403).json({ error: "test_to_self",
    message: "A test goes to you. Sending a draft to somebody else is a send, and it belongs on the campaign." });

  const T = await templatesMod();
  const [org] = await query("SELECT * FROM orgs WHERE id=?", [orgId]);
  const first = String(me?.name || "").trim().split(/\s+/)[0] || "Margaret";
  const testNote = `<div style="margin-top:28px;padding-top:14px;border-top:1px solid #e5e0d5;font-family:'DM Sans',Helvetica,Arial,sans-serif;font-size:12px;color:#8fa896;">
         This is a test of "${escapeHtml(campaign.name || "")}". Nobody else received it, and it is not counted.
       </div>`;
  // EMAIL-1 — a template campaign's test is rendered exactly as the send
  // renders it, with her own name in it and the real footer where the
  // renderer left its slot. A copy the send would refuse is refused here too.
  let blocksHtml = null;
  let testSubject = campaign.subject || campaign.name || "";
  if (emailCompose.hasBlocks(campaign)) {
    const ctx = await emailCompose.orgRenderContext(orgId);
    const r = await emailCompose.render(ctx, {
      blocks: campaign.email_blocks, subject: campaign.subject, preheader: campaign.preheader,
      fields: emailCompose.sampleFields(ctx, { name: me?.name || "", email: to, campaignName: campaign.name || "" }),
      mode: "send" });
    if (r.problems.length) return res.status(400).json({ error: "email_not_ready", message: emailCompose.refusalSentence(r.problems), problems: r.problems });
    blocksHtml = emailCompose.withFooter(r, await unsubscribeEmailFooterHtml(to, orgId, "campaign") + testNote, "");
    testSubject = await emailCompose.subjectFor(campaign.subject, emailCompose.sampleFields(ctx, { name: me?.name || "", email: to }));
  }
  const html = blocksHtml || await brandEmailHeaderHtml(orgId)
    + T.renderMergeFields(campaign.body || "", {
        first_name: first, donor_name: me?.name || first,
        org_name: displayNameCase(org?.name || ""), gift_amount: "$250", total_giving: "$4,150",
        year: String(new Date().getUTCFullYear()),
      })
    + testNote;
  const identity = await orgSendingIdentity(orgId);
  let delivered = false;
  if (process.env.RESEND_API_KEY) {
    try {
      const { error } = await resend.emails.send({
        from: identity.from, ...(identity.replyTo ? { replyTo: identity.replyTo } : {}),
        to, subject: `[Test] ${testSubject}`,
        _stewardOrgId: orgId, _stewardKind: "campaign_test",   // MAIL-1: waits for onboarding like the campaign
        html: blocksHtml ? html : T.renderMergeFields(html, { first_name: first }),
      });
      if (error) throw new Error(error.message);
      delivered = true;
    } catch (e) {
      console.error("[campaign] test send failed:", e.message);
      return res.status(502).json({ error: "send_failed", message: "The test could not be sent just now. Nothing about the campaign changed." });
    }
  }
  res.json({ sent: delivered, to, from: identity.from, verified: identity.verified, counted: false });
}));

// ── EMAIL-1 · WAITING FOR APPROVAL ────────────────────────────────────────
// Somebody writes a campaign and asks an admin to approve it. While it waits
// its status is `awaiting_approval`, which the scheduler never picks up (it
// reads status='scheduled' only). Approving stamps who and when and makes it
// `scheduled`; with no send time it waits as an approved draft. Undo is
// /unapprove, back to waiting.
async function campaignForApproval(req, res) {
  const [c] = await query("SELECT * FROM campaigns WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!c) { res.status(404).json({ error: "Campaign not found" }); return null; }
  return c;
}

app.post("/campaigns/:id/request-approval", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const c = await campaignForApproval(req, res); if (!c) return;
  if (!["draft", "scheduled"].includes(c.status)) {
    return res.status(400).json({ error: "not_a_draft", message: "Only a draft or a scheduled campaign can be sent for approval." });
  }
  const pre = await emailCompose.campaignPreflight(c, req.user.orgId);
  if (!pre.ok) return res.status(400).json({ error: "email_not_ready", message: pre.message, problems: pre.problems });
  await run(
    `UPDATE campaigns SET status='awaiting_approval', approved_at=NULL, approved_by=NULL, approved_by_name=NULL, updated_at=NOW()
      WHERE id=? AND org_id=? AND status IN ('draft','scheduled')`, [c.id, req.user.orgId]);
  req.audit.entity("campaign", c.id, c.name);
  req.audit.action("asked for approval");
  res.json({ ok: true, status: "awaiting_approval", previousStatus: c.status,
    sentence: `${c.name || "The campaign"} is waiting for an admin to approve it. It will not go before then.` });
}));

// Undo of a request: back to a draft (or to scheduled, if that is where it was
// and the caller is an admin, whose scheduling needs nobody's approval).
app.post("/campaigns/:id/withdraw-approval", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const c = await campaignForApproval(req, res); if (!c) return;
  if (c.status !== "awaiting_approval") return res.status(400).json({ error: "not_waiting", message: "That campaign is not waiting for approval." });
  const [me] = await query("SELECT role FROM users WHERE id=?", [req.user.userId]);
  const back = req.body && req.body.status === "scheduled" && me && me.role === "admin" && c.scheduled_at ? "scheduled" : "draft";
  await run("UPDATE campaigns SET status=?, updated_at=NOW() WHERE id=? AND org_id=? AND status='awaiting_approval'",
    [back, c.id, req.user.orgId]);
  res.json({ ok: true, status: back, sentence: back === "draft" ? "Back to a draft." : "Back to scheduled." });
}));

app.post("/campaigns/:id/approve", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const c = await campaignForApproval(req, res); if (!c) return;
  if (c.status !== "awaiting_approval") return res.status(400).json({ error: "not_waiting", message: "That campaign is not waiting for approval." });
  const pre = await emailCompose.campaignPreflight(c, req.user.orgId);
  if (!pre.ok) return res.status(400).json({ error: "email_not_ready", message: pre.message, problems: pre.problems });
  const nextStatus = c.scheduled_at ? "scheduled" : "draft";
  const who = actor(req);
  const [me] = await query("SELECT name FROM users WHERE id=? AND org_id=?", [req.user.userId, req.user.orgId]);
  await run(
    `UPDATE campaigns SET status=?, approved_at=NOW(), approved_by=?, approved_by_name=?, updated_at=NOW()
      WHERE id=? AND org_id=? AND status='awaiting_approval'`,
    [nextStatus, who.id, (me && me.name) || who.name, c.id, req.user.orgId]);
  req.audit.entity("campaign", c.id, c.name);
  req.audit.action("approved the campaign");
  const when = c.scheduled_at ? new Date(c.scheduled_at) : null;
  res.json({ ok: true, status: nextStatus,
    sentence: !when ? "Approved. It has no send time, so it waits as a draft until somebody sends it."
      : when <= new Date() ? "Approved. Its send time has passed, so it goes out within five minutes."
      : "Approved. It goes out at its scheduled time." });
}));

app.post("/campaigns/:id/unapprove", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const c = await campaignForApproval(req, res); if (!c) return;
  if (!c.approved_at || !["scheduled", "draft"].includes(c.status)) {
    return res.status(400).json({ error: "not_approved", message: "That campaign is not approved, or it has already started sending." });
  }
  await run(
    `UPDATE campaigns SET status='awaiting_approval', approved_at=NULL, approved_by=NULL, approved_by_name=NULL, updated_at=NOW()
      WHERE id=? AND org_id=? AND status IN ('scheduled','draft')`, [c.id, req.user.orgId]);
  req.audit.entity("campaign", c.id, c.name);
  req.audit.action("took back the approval");
  res.json({ ok: true, status: "awaiting_approval", sentence: "The approval is taken back. It is waiting again." });
}));

// ── BUILD-88c C.1 — HER OWN DOMAIN, VERIFIED ──────────────────────────────
// Three routes and no fourth: READ the state, CLAIM a domain, CHECK it. The
// claim creates the domain on Resend and stores the DNS records the org must
// publish; the check asks Resend whether they hold and flips the state.
//
// A DOMAIN BELONGS TO ONE ORG. The uniqueness is a GLOBAL index at the
// database, not an application check, because "mail from this domain is that
// organisation's" is the entire content of the claim. A second org asking for
// a domain the first has is refused with the reason, never a silent no-op.
//
// Nobody is ever blocked from sending while unverified: the identity seam falls
// back to Steward's shared domain with the org's name in the display slot and a
// Reply-To that reaches a human, and every screen says which of the two is in
// force.
const DOMAIN_RE = /^(?!-)[a-z0-9-]{1,63}(?<!-)(\.(?!-)[a-z0-9-]{1,63}(?<!-))+$/i;
const RESERVED_SENDING_DOMAINS = new Set(["stewardapp.dev", "send.stewardapp.dev", "resend.dev", "gmail.com",
  "googlemail.com", "outlook.com", "hotmail.com", "yahoo.com", "icloud.com", "aol.com", "me.com", "live.com"]);

function sendingDomainPayload(org) {
  const records = Array.isArray(org?.sending_domain_records) ? org.sending_domain_records
    : (typeof org?.sending_domain_records === "string" ? JSON.parse(org.sending_domain_records || "[]") : []);
  const verified = org?.sending_domain_status === "verified";
  return {
    domain: org?.sending_domain || null,
    fromEmail: org?.sending_from_email || null,
    status: org?.sending_domain_status || "none",
    verified,
    verifiedAt: org?.sending_domain_verified_at || null,
    checkedAt: org?.sending_domain_checked_at || null,
    records,
    // The one sentence the screen shows, written HERE so the screen and the
    // send agree about what is happening.
    sentence: verified
      ? `Your email goes out from ${org.sending_from_email}. Donors see your address and your domain, and nothing of Steward's.`
      : org?.sending_domain
        ? `Until ${org.sending_domain} verifies, your email goes out from Steward's address with your organisation's name on it, and replies come to you.`
        : "Your email goes out from Steward's address with your organisation's name on it, and replies come to you. Add your own domain and donors will see yours instead.",
  };
}

app.get("/org/sending-domain", requireAuth, wrap(async (req, res) => {
  const [org] = await query(
    `SELECT sending_domain, sending_domain_status, sending_domain_records, sending_domain_verified_at,
            sending_domain_checked_at, sending_from_email FROM orgs WHERE id=?`, [req.user.orgId]);
  if (!org) return res.status(404).json({ error: "Org not found" });
  res.json(sendingDomainPayload(org));
}));

app.post("/org/sending-domain", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const fromEmail = String(req.body?.fromEmail || "").trim().toLowerCase();
  if (!/^[^\s@]+@[^\s@]+$/.test(fromEmail)) return res.status(400).json({ error: "A real address at your own domain is required, for example ada@yourcharity.org." });
  const domain = String(req.body?.domain || fromEmail.split("@")[1] || "").trim().toLowerCase().replace(/^@/, "");
  if (!DOMAIN_RE.test(domain)) return res.status(400).json({ error: `"${domain}" is not a domain Steward can send from.` });
  if (RESERVED_SENDING_DOMAINS.has(domain)) {
    return res.status(400).json({ error: "reserved_domain",
      message: `${domain} cannot be used: it is either Steward's own, or a mailbox provider you do not control the DNS for. Use a domain your organisation owns.` });
  }
  if (fromEmail.split("@")[1] !== domain) {
    return res.status(400).json({ error: "address_domain_mismatch",
      message: `${fromEmail} is not at ${domain}. The address donors see has to be at the domain you are verifying.` });
  }
  // THE WALL. Claimed at the database by a global unique index, so two orgs
  // racing for one domain cannot both win.
  const [taken] = await query("SELECT id FROM orgs WHERE LOWER(sending_domain)=? AND id<>?", [domain, orgId]);
  if (taken) {
    return res.status(409).json({ error: "domain_taken",
      message: `${domain} is already verified for another organisation on Steward. A sending domain belongs to one organisation; if this is yours, the other organisation has to release it first.` });
  }

  // Resend owns the DNS records; Steward stores what it is told and never
  // invents one. A provider failure is reported, not swallowed into a screen
  // that shows records nobody can publish.
  let created = null;
  try {
    const out = await resend.domains.create({ name: domain });
    if (out?.error) throw new Error(out.error.message || String(out.error));
    created = out?.data || out;
  } catch (e) {
    console.error("[sending-domain] create failed:", e.message);
    return res.status(502).json({ error: "provider_unavailable",
      message: "Steward could not reach the mail provider to set up that domain. Nothing was changed; try again in a minute." });
  }
  const records = Array.isArray(created?.records) ? created.records : [];
  try {
    await run(
      `UPDATE orgs SET sending_domain=?, sending_domain_id=?, sending_domain_status=?,
                       sending_domain_records=?::jsonb, sending_domain_verified_at=NULL,
                       sending_domain_checked_at=NOW(), sending_from_email=?
        WHERE id=?`,
      [domain, created?.id || null, created?.status === "verified" ? "verified" : "pending",
       JSON.stringify(records), fromEmail, orgId]);
  } catch (e) {
    if (/uq_orgs_sending_domain/.test(e.message)) {
      return res.status(409).json({ error: "domain_taken",
        message: `${domain} was claimed by another organisation a moment ago. A sending domain belongs to one organisation.` });
    }
    throw e;
  }
  writeAuditLog(orgId, req.user.userId, req.user.email, "updated", "sending_domain", domain, {
    description: `Claimed ${domain} as the organisation's sending domain (from ${fromEmail})`,
    new: { domain, fromEmail },
  }).catch(() => {});
  const [org] = await query(
    `SELECT sending_domain, sending_domain_status, sending_domain_records, sending_domain_verified_at,
            sending_domain_checked_at, sending_from_email FROM orgs WHERE id=?`, [orgId]);
  res.status(201).json(sendingDomainPayload(org));
}));

// CHECK — ask the provider whether the records she published hold. Every press
// is a real call; the answer is stored with the moment it was asked, so the
// screen shows a fact with a date on it rather than a spinner's memory.
app.post("/org/sending-domain/check", requireAuth, requireAdmin, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [org0] = await query("SELECT sending_domain, sending_domain_id FROM orgs WHERE id=?", [orgId]);
  if (!org0?.sending_domain) return res.status(400).json({ error: "no_domain", message: "Add your domain first." });
  let got = null;
  try {
    const out = org0.sending_domain_id
      ? await resend.domains.get(org0.sending_domain_id)
      : await resend.domains.list();
    if (out?.error) throw new Error(out.error.message || String(out.error));
    got = out?.data ?? out;
    if (Array.isArray(got?.data)) got = got.data.find(d => String(d.name).toLowerCase() === org0.sending_domain) || null;
    else if (Array.isArray(got)) got = got.find(d => String(d.name).toLowerCase() === org0.sending_domain) || null;
  } catch (e) {
    console.error("[sending-domain] check failed:", e.message);
    return res.status(502).json({ error: "provider_unavailable",
      message: "Steward could not reach the mail provider just now. Nothing has changed; try the check again in a minute." });
  }
  const status = String(got?.status || "pending").toLowerCase();
  const verified = status === "verified";
  await run(
    `UPDATE orgs SET sending_domain_status=?, sending_domain_checked_at=NOW(),
                     sending_domain_verified_at = CASE WHEN ? THEN COALESCE(sending_domain_verified_at, NOW()) ELSE NULL END,
                     sending_domain_records = COALESCE(?::jsonb, sending_domain_records)
      WHERE id=?`,
    [verified ? "verified" : status === "failed" ? "failed" : "pending", verified,
     Array.isArray(got?.records) && got.records.length ? JSON.stringify(got.records) : null, orgId]);
  const [org] = await query(
    `SELECT sending_domain, sending_domain_status, sending_domain_records, sending_domain_verified_at,
            sending_domain_checked_at, sending_from_email FROM orgs WHERE id=?`, [orgId]);
  res.json(sendingDomainPayload(org));
}));

// Releasing it drops back to the shared domain — and frees the domain for
// whichever organisation actually owns it.
app.delete("/org/sending-domain", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const [org0] = await query("SELECT sending_domain FROM orgs WHERE id=?", [req.user.orgId]);
  await run(
    `UPDATE orgs SET sending_domain=NULL, sending_domain_id=NULL, sending_domain_status=NULL,
                     sending_domain_records=NULL, sending_domain_verified_at=NULL,
                     sending_domain_checked_at=NULL, sending_from_email=NULL WHERE id=?`, [req.user.orgId]);
  if (org0?.sending_domain) {
    writeAuditLog(req.user.orgId, req.user.userId, req.user.email, "deleted", "sending_domain", org0.sending_domain, {
      description: `Released ${org0.sending_domain}; email goes out on Steward's shared domain again`,
    }).catch(() => {});
  }
  res.json({ released: org0?.sending_domain || null });
}));

// ── BUILD-88b B.3 — THE QUEUE, AND THE THREE THINGS SHE CAN DO WITH IT ────
// Copy, Mark sent, Skip. That is all, and "Mark all as sent" only after every
// draft has been OPENED — a bulk action over letters nobody read is the thing
// that makes a thank-you queue a lie.
app.get("/thank-yous", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const rows = await query(
    `SELECT t.id, t.donor_id, t.gift_id, t.body, t.voice, t.opened_at, t.created_at,
            d.name AS donor_name, d.email AS donor_email,
            g.amount::float AS amount, g.date AS gift_date, f.name AS fund_name
       FROM thank_you_drafts t
       JOIN donors d ON d.id = t.donor_id AND d.org_id = t.org_id
       JOIN gifts g ON g.id = t.gift_id AND g.org_id = t.org_id
       LEFT JOIN fin_funds f ON f.id = g.fund_id AND f.org_id = t.org_id
      WHERE t.org_id = ? AND t.sent_at IS NULL AND t.skipped_at IS NULL
        AND d.deleted_at IS NULL
      ORDER BY g.amount DESC, t.created_at ASC`, [orgId]);
  const [org] = await query("SELECT voice_samples FROM orgs WHERE id=?", [orgId]);
  const samples = Array.isArray(org?.voice_samples) ? org.voice_samples
    : (typeof org?.voice_samples === "string" ? JSON.parse(org.voice_samples || "[]") : []);
  const draftMod = await import("../shared/draftNote.js");
  const voice = draftMod.voiceFrom(samples);
  res.json({
    count: rows.length,
    // The sentence Home shows. Numbers under ten spelled, BUILD-86 C.2's rule.
    headline: rows.length === 0 ? null
      : `${["No", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine"][rows.length] || rows.length} thank-you${rows.length === 1 ? "" : "s"} ready.`,
    // "Mark all as sent" is offered only when every draft has been opened.
    allOpened: rows.length > 0 && rows.every(r => !!r.opened_at),
    voice: { ready: voice.ready, samples: voice.count, needs: Math.max(0, draftMod.VOICE_SAMPLE_MIN - voice.count) },
    drafts: rows.map(r => ({ id: r.id, donorId: r.donor_id, giftId: r.gift_id, donorName: r.donor_name,
      donorEmail: r.donor_email || null, amount: r.amount, giftDate: r.gift_date,
      fundName: r.fund_name || null, body: r.body, voiceUsed: r.voice, opened: !!r.opened_at })),
  });
}));

// Opening a draft is recorded, because "Mark all as sent" depends on it.
app.post("/thank-yous/:id/opened", requireAuth, wrap(async (req, res) => {
  const r = await run("UPDATE thank_you_drafts SET opened_at=COALESCE(opened_at,NOW()) WHERE id=? AND org_id=?",
    [req.params.id, req.user.orgId]);
  if (!r.changes) return res.status(404).json({ error: "Draft not found" });
  res.json({ ok: true });
}));

// MARK SENT logs a conversation, which is what runs the Thread cycle: closing
// one conversation opens the next (BUILD-81's spine). Steward did not send it —
// she did — so the timeline says so in her name.
app.post("/thank-yous/:id/sent", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [d] = await query("SELECT * FROM thank_you_drafts WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!d) return res.status(404).json({ error: "Draft not found" });
  if (d.sent_at) return res.json({ ok: true, alreadySent: true });
  const org = await orgTz(orgId);
  const today = orgToday(org);                                     // ORG_TZ_SEAM_OK
  const act = actor(req);
  // SHE sent it, so the timeline says her NAME. `actor(req).name` falls back to
  // the email (it is the identifier that is always present); a colleague on a
  // record is a person, and BUILD-87 F.3.7's rule is that a row reads as one.
  const [me] = await query("SELECT name FROM users WHERE id=? AND org_id=?", [req.user.userId, orgId]);
  const actorName = (me && me.name) || act.name;
  const intId = "int_" + uuid().slice(0, 8);
  await run(
    `INSERT INTO interactions (id,org_id,donor_id,type,note,date,created_by,logged_by_name,gift_id,metadata)
     VALUES (?,?,?,?,?,?,?,?,?,?)`,
    [intId, orgId, d.donor_id, "stewardship", "Thank-you sent.", today, act.id, actorName, d.gift_id,
     JSON.stringify({ via: "thank_you_queue", draftId: d.id })]);
  await run("UPDATE thank_you_drafts SET sent_at=NOW(), opened_at=COALESCE(opened_at,NOW()) WHERE id=? AND org_id=?", [d.id, orgId]);
  await run("UPDATE gifts SET acknowledgement_sent=true, acknowledgement_sent_at=COALESCE(acknowledgement_sent_at, NOW()) WHERE id=? AND org_id=?", [d.gift_id, orgId]);
  // The thread cycle: a thank-you thread this closes closes as an OUTCOME.
  const closed = await query(
    `UPDATE threads SET closed_at=NOW(), close_kind='outcome', closing_interaction_id=?
      WHERE org_id=? AND donor_id=? AND closed_at IS NULL
        AND next_step_type IN ('thank','thank_you_note') RETURNING id`,
    [intId, orgId, d.donor_id]);
  res.json({ ok: true, interactionId: intId, threadClosed: closed[0]?.id || null });
}));

// SKIP, with no reason asked. Sometimes a gift does not need a letter and
// making her justify that is how a queue stops being used.
app.post("/thank-yous/:id/skip", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const r = await run("UPDATE thank_you_drafts SET skipped_at=NOW() WHERE id=? AND org_id=? AND sent_at IS NULL",
    [req.params.id, req.user.orgId]);
  if (!r.changes) return res.status(404).json({ error: "Draft not found" });
  res.json({ ok: true });
}));

app.post("/thank-yous/mark-all-sent", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const open = await query(
    "SELECT id, opened_at FROM thank_you_drafts WHERE org_id=? AND sent_at IS NULL AND skipped_at IS NULL", [orgId]);
  if (!open.length) return res.json({ marked: 0 });
  const unopened = open.filter(d => !d.opened_at).length;
  if (unopened) {
    return res.status(409).json({ error: "unopened_drafts", unopened,
      message: `${unopened} draft${unopened === 1 ? " has" : "s have"} not been opened. Marking a letter sent that nobody read is how this queue stops meaning anything.` });
  }
  const org = await orgTz(orgId);
  const today = orgToday(org);                                     // ORG_TZ_SEAM_OK
  const act = actor(req);
  const [meAll] = await query("SELECT name FROM users WHERE id=? AND org_id=?", [req.user.userId, orgId]);
  const actorNameAll = (meAll && meAll.name) || act.name;
  let marked = 0;
  for (const d of open) {
    const [full] = await query("SELECT donor_id, gift_id FROM thank_you_drafts WHERE id=?", [d.id]);
    await run(
      `INSERT INTO interactions (id,org_id,donor_id,type,note,date,created_by,logged_by_name,gift_id,metadata)
       VALUES (?,?,?,?,?,?,?,?,?,?)`,
      ["int_" + uuid().slice(0, 8), orgId, full.donor_id, "stewardship", "Thank-you sent.", today, act.id, actorNameAll,
       full.gift_id, JSON.stringify({ via: "thank_you_queue_all", draftId: d.id })]);
    await run("UPDATE gifts SET acknowledgement_sent=true, acknowledgement_sent_at=COALESCE(acknowledgement_sent_at, NOW()) WHERE id=? AND org_id=?", [full.gift_id, orgId]);
    marked++;
  }
  await run("UPDATE thank_you_drafts SET sent_at=NOW() WHERE org_id=? AND sent_at IS NULL AND skipped_at IS NULL", [orgId]);
  res.json({ marked });
}));

// Her voice: three samples she pastes in Settings. Fewer than three and the
// draft stays one plain sentence — Steward never invents a voice.
app.put("/org/voice-samples", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const raw = Array.isArray(req.body?.samples) ? req.body.samples : [];
  const samples = raw.map(x => String(x || "").trim()).filter(x => x.length >= 40).slice(0, 5).map(x => x.slice(0, 4000));
  await run("UPDATE orgs SET voice_samples=?::jsonb WHERE id=?", [samples.length ? JSON.stringify(samples) : null, req.user.orgId]);
  const draftMod = await import("../shared/draftNote.js");
  const voice = draftMod.voiceFrom(samples);
  res.json({ samples: samples.length, ready: voice.ready,
             needs: Math.max(0, draftMod.VOICE_SAMPLE_MIN - samples.length),
             greeting: voice.greeting || null, signoff: voice.signoff || null, signature: voice.signature || null });
}));

app.get("/org/voice-samples", requireAuth, wrap(async (req, res) => {
  const [org] = await query("SELECT voice_samples FROM orgs WHERE id=?", [req.user.orgId]);
  const samples = Array.isArray(org?.voice_samples) ? org.voice_samples
    : (typeof org?.voice_samples === "string" ? JSON.parse(org.voice_samples || "[]") : []);
  const draftMod = await import("../shared/draftNote.js");
  const voice = draftMod.voiceFrom(samples);
  res.json({ samples, ready: voice.ready, needs: Math.max(0, draftMod.VOICE_SAMPLE_MIN - samples.length),
             greeting: voice.greeting || null, signoff: voice.signoff || null, signature: voice.signature || null });
}));

// POST /pledges/run-reminders — drive the sweep for the caller's org now
// (ops/test hook, the /nudges/run bar). {today} pins the date.
app.post("/pledges/run-reminders", requireAuth, requireAdmin, wrap(async (req, res) => {
  const today = (req.body && /^\d{4}-\d{2}-\d{2}$/.test(String(req.body.today))) ? String(req.body.today) : null;
  const out = await processPledgeInstallmentReminders({ orgId: req.user.orgId, today });
  res.json(out);
}));

// ── Gift date normalization ────────────────────────────────────────────────
// Enforces ISO YYYY-MM-DD so MAX(date) string comparison = chronological order.
// BUILD-77 Part 2a — NO date default, anywhere. This used to fall back to
// today() twice (empty → today, unparseable → today, via the
// platform-dependent native Date parser in between): a real file's
// "03-16-2020" failed in the BROWSER's parser upstream, fell through to
// now(), and turned a drifting seasonal donor into "Gave $25,000 on
// September 4 — not yet thanked" (September 4 because new Date() is UTC —
// tomorrow's date every evening, while the page header still said the
// org-local September 3). A gift with an unparseable date is an ERROR with
// its line number, never a gift dated today. The CLIENT parses the messy
// formats (importShape.normalizeDate, nine explicit formats, no native
// fallback); the server accepts calendar-valid ISO and refuses everything
// else — refusal is visible, a default is not.
function normalizeGiftDate(raw) {
  if (!raw) return null;
  const s = String(raw).trim();
  const m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return null;
  const y = +m[1], mo = +m[2], d = +m[3];
  if (mo < 1 || mo > 12 || d < 1 || y < 1900 || y > 2100) return null;
  const leap = (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
  const dim = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][mo - 1];
  return d <= dim ? s : null;
}
// A "Last, First" flip must NOT eat a corporate name like "Acme, Inc." → "Inc. Acme".
const _CORP_SUFFIX = /^(inc|llc|l\.l\.c|llp|ltd|co|corp|company|foundation|fdn|trust|fund|society|assn|association|partners|group|plc|gmbh|nfp)\.?$/i;
function normalizeName(raw) {
  if (raw == null) return raw;
  let s = String(raw).replace(/\s+/g, " ").trim();
  if (!s) return s;
  const parts = s.split(",");
  if (parts.length === 2 && parts[0].trim() && parts[1].trim() && !_CORP_SUFFIX.test(parts[1].trim()))
    s = parts[1].trim() + " " + parts[0].trim();
  const letters = s.replace(/[^A-Za-zÀ-ÿ]/g, "");
  const allUpper = letters && letters === letters.toUpperCase();
  const allLower = letters && letters === letters.toLowerCase();
  if (allUpper || allLower) s = s.replace(/[A-Za-zÀ-ÿ][A-Za-zÀ-ÿ'’.\-]*/g, w => _titleCaseWord(w));
  return s;
}
// Stage-weighted forecast: a donor's current stage is a rough close-probability
// for their open asks. Solicit is near the ask; prospect is far off.
const STAGE_WEIGHT = { prospect: 0.1, qualify: 0.2, cultivate: 0.4, solicit: 0.7, steward: 0.9, lapsed: 0.05 };

// ── assignment = portfolio = pipeline membership (BUILD-30, the ONE definition) ─
// A donor assigned to an officer IS in that officer's portfolio, and a donor in
// a portfolio IS on that officer's pipeline board. Assignment is the single
// membership state — there is NO separate "on the board" flag (the old
// `in_pipeline` column is retired/dormant; nothing reads or writes it). Every
// count, label, and board render for portfolio/pipeline derives from this one
// helper, so Home's Portfolio card, Home's Pipeline card, the Pipeline board,
// and the Donors "My Pipeline"/Team views can never disagree again.
//
// Returns a SQL WHERE fragment (using the given table alias) + params selecting
// an officer's portfolio, org-scoped. Unassigned donors match NOTHING here —
// they live in the Directory only and never appear on any board (preserving the
// "the board is not the whole donor list" guarantee). scope:
//   'mine'      → the caller's own assigned donors (assigned_to = userId)
//   'all'       → every assigned donor in the org (assigned_to IS NOT NULL)
//   assignedTo  → one specific officer's portfolio (overrides scope)
function portfolioMembership({ orgId, userId, scope = "mine", assignedTo = null, alias = "d" }) {
  const a = alias ? alias + "." : "";
  // stage ∈ the 6 canonical pipeline stages — every real donor has one (validation
  // only permits these), so for real data "assigned" ⟺ "member". The clause is a
  // belt-and-braces guard so a donor in some non-pipeline stage can never make the
  // Portfolio card, the Pipeline card, and the board disagree — all three exclude
  // it identically. It also keeps the board's per-stage columns exhaustive.
  // BUILD-83 Part 3.5 — an imported donor's `stage` is NULL until a human
  // places them, but assignment IS membership (BUILD-30's single definition):
  // assigning someone from an import must never make them vanish off the board.
  // So membership reads the placed stage OR the suggestion, and the CARD says
  // which it is. Moving the card writes `stage` and the suggestion stops
  // mattering for that donor.
  const clauses = [`${a}org_id = ?`, `${a}deleted_at IS NULL`, `COALESCE(${a}stage, ${a}suggested_stage) = ANY(?)`];
  const params = [orgId, ALL_PIPELINE_STAGES];
  if (assignedTo) {
    clauses.push(`${a}assigned_to = ?`); params.push(String(assignedTo));
  } else if (scope === "all") {
    clauses.push(`${a}assigned_to IS NOT NULL`);
  } else {
    clauses.push(`${a}assigned_to = ?`); params.push(String(userId));
  }
  return { where: clauses.join(" AND "), params };
}
// BUILD-73 Part 3 — QUIET_DAYS is the "going quiet" threshold, and it already
// existed: computeMoveSuggestions fires `going_quiet` at 180 days with the
// reason "reach out before they lapse." That is the whole Steward thesis — a
// donor drifting is the moment to act, and waiting for the 365-day lapse line
// is waiting too long. The at-risk figure on the home screen uses THIS
// threshold, not the lapse one, so the demo leads with drift rather than with
// recapture. Named here so the two thresholds sit together and neither can
// drift from the other unnoticed.
const QUIET_DAYS = 180;

// Auto-un-lapse: a lapsed donor just gave, so move them out of Lapsed to
// Steward automatically ("they just gave"), logged, editable. Called from every
// gift-insert path with the donor's PRE-gift stage. No-op unless they were
// lapsed. The UPDATE is guarded on stage='lapsed' so a concurrent human move
// can't be clobbered.
async function autoUnlapseOnGift(orgId, donorId, preStage) {
  if (preStage !== "lapsed") return false;
  const upd = await query(
    "UPDATE donors SET stage='steward', updated_at=NOW() WHERE id=? AND org_id=? AND stage='lapsed' RETURNING id",
    [donorId, orgId]);
  if (!upd.length) return false; // someone moved them first — respect it
  await recordAutoMove(orgId, donorId, "lapsed", "steward", "Auto: new gift after a year-long gap");
  return true;
}

// Signal-based move SUGGESTIONS for a donor (never auto-applied). The officer
// reviews and one-click accepts (which applies via the normal move route) or
// dismisses. Pure function over the donor row + light context.
function computeMoveSuggestions(donor, ctx = {}) {
  const out = [];
  const stage = donor.stage;
  const giftCount = Number(donor.gift_count) || 0;
  const lastGift = donor.last_gift_date && donor.last_gift_date !== "" ? donor.last_gift_date : null;
  const daysSinceGift = lastGift ? Math.floor((Date.now() - new Date(lastGift)) / 86400000) : null;
  // First gift in hand but still parked at prospect → qualify them.
  if (giftCount >= 1 && stage === "prospect") {
    out.push({ signal: "first_gift", toStage: "qualify",
      reason: "First gift received — qualify this donor and start cultivating." });
  }
  // A gift landed while being solicited → the ask effectively closed; steward.
  if (stage === "solicit" && daysSinceGift != null && daysSinceGift <= 90) {
    out.push({ signal: "gift_after_solicit", toStage: "steward",
      reason: "A gift landed after your solicitation — move to Stewardship." });
  }
  // In active cultivation but gone quiet (not yet lapsed) → take a look.
  if (["qualify", "cultivate"].includes(stage) && daysSinceGift != null
      && daysSinceGift > 180 && daysSinceGift < LAPSE_DAYS) {
    out.push({ signal: "going_quiet", toStage: null,
      reason: `No gift in ${Math.round(daysSinceGift / 30)} months — reach out before they lapse.` });
  }
  return out;
}

// Set-based recalc for MANY donors in ONE query — the import hang fix. The
// per-donor recalcDonorSummary loop was ~2 round trips per donor; at 1,500+
// donors that's thousands of sequential queries whose latency (small locally,
// large against a remote Supabase) made a big import appear to hang on
// "Importing…". This computes total/count/last-gift-date and the amount of the
// most-recent gift (tie-break by created_at) for the whole set at once, matching
// recalcDonorSummary's semantics exactly. No-op on an empty set.
async function recalcDonorSummaryBatch(donorIds, orgId) {
  const ids = [...new Set(donorIds)].filter(Boolean);
  if (!ids.length) return;
  await run(
    `WITH agg AS (
       SELECT donor_id,
              COALESCE(SUM(amount),0) AS total,
              COUNT(*) AS cnt,
              MAX(date) AS last_date
       FROM gifts WHERE org_id=? AND donor_id = ANY(?)
       GROUP BY donor_id
     ),
     last_amt AS (
       SELECT DISTINCT ON (donor_id) donor_id, amount
       FROM gifts WHERE org_id=? AND donor_id = ANY(?)
       ORDER BY donor_id, date DESC, created_at DESC
     )
     UPDATE donors d
        SET total_giving     = agg.total,
            gift_count       = agg.cnt,
            last_gift_date   = agg.last_date,
            last_gift_amount = COALESCE(last_amt.amount, 0),
            updated_at       = NOW()
       FROM agg LEFT JOIN last_amt ON last_amt.donor_id = agg.donor_id
      WHERE d.id = agg.donor_id AND d.org_id = ?`,
    [orgId, ids, orgId, ids, orgId]
  );
}

// ── Wealth Score ────────────────────────────────────────────────────────────
async function calcWealthScore(donorId, orgId) {
  try {
    const [donorRows, gifts, interactions] = await Promise.all([
      query("SELECT * FROM donors WHERE id = ? AND org_id = ?", [donorId, orgId]),
      query("SELECT amount FROM gifts WHERE donor_id = ? AND org_id = ? ORDER BY date DESC", [donorId, orgId]),
      query("SELECT type, note FROM interactions WHERE donor_id = ? AND org_id = ? ORDER BY date DESC", [donorId, orgId]),
    ]);
    if (!donorRows.length) return null;
    const d = donorRows[0];

    let score = 0;
    const total = d.total_giving || 0;

    // Lifetime giving (0–3 pts)
    if      (total >= 100000) score += 3;
    else if (total >= 50000)  score += 2.75;
    else if (total >= 25000)  score += 2.5;
    else if (total >= 10000)  score += 2;
    else if (total >= 5000)   score += 1.5;
    else if (total >= 1000)   score += 1;
    else if (total >= 500)    score += 0.5;

    // Largest single gift (0–2 pts)
    const maxGift = gifts.length ? Math.max(...gifts.map(g => g.amount)) : 0;
    if      (maxGift >= 10000) score += 2;
    else if (maxGift >= 5000)  score += 1.5;
    else if (maxGift >= 1000)  score += 1;
    else if (maxGift >= 500)   score += 0.5;
    else if (maxGift >= 100)   score += 0.25;

    // Gift frequency (0–2 pts)
    const gc = d.gift_count || 0;
    if      (gc >= 7) score += 2;
    else if (gc >= 4) score += 1.5;
    else if (gc >= 2) score += 1;
    else if (gc >= 1) score += 0.5;
    // Recency penalty
    if (d.last_gift_date) {
      const daysSince = Math.floor((Date.now() - new Date(d.last_gift_date)) / 86400000);
      if (daysSince > 730) score -= 0.5;
    }

    // Average gift size (0–1 pt)
    const avgGift = gc > 0 ? total / gc : 0;
    if      (avgGift >= 2500) score += 1;
    else if (avgGift >= 1000) score += 0.75;
    else if (avgGift >= 500)  score += 0.5;
    else if (avgGift >= 100)  score += 0.25;

    // Behavioral signals (0–2 pts)
    score += Math.min(interactions.length * 0.1, 0.8);
    const calls = interactions.filter(i => i.type === "call");
    const answered = calls.filter(i => (i.note || "").toLowerCase().includes("answered: yes"));
    if (calls.length > 0 && answered.length / calls.length > 0.5) score += 0.5;
    const eventsAttended = interactions.filter(i => i.type === "event" && (i.note || "").toLowerCase().includes("donor attended: yes"));
    score += Math.min(eventsAttended.length * 0.15, 0.3);
    const stageBonus = { steward: 0.4, major: 0.3, pledge: 0.2, cultivate: 0.1, prospect: 0, lapsed: -0.3 };
    score += stageBonus[d.stage] || 0;

    const finalScore = Math.round(Math.min(10, Math.max(1, score)));
    const capacityTier = finalScore <= 3 ? "Micro" : finalScore <= 5 ? "Small" : finalScore <= 7 ? "Mid" : finalScore <= 9 ? "Major" : "Principal";
    const dataPoints = gc + interactions.length;
    const confidence = dataPoints >= 6 ? "High" : dataPoints >= 3 ? "Medium" : "Low";

    // Claude rationale (2 sentences, non-blocking on failure)
    const avgGiftAmt = gc > 0 ? Math.round(total / gc) : 0;
    let rationale = `${d.name} scored ${finalScore}/10 based on ${gc} gift${gc !== 1 ? "s" : ""} totaling $${total.toLocaleString()} and ${interactions.length} recorded touchpoints.`;
    try {
      const client = anthropicFor(orgId);
      const msg = await client.messages.create({
        model: "claude-sonnet-4-6",
        max_tokens: 130,
        thinking: { type: "disabled" },   // FIX-28: two sentences need no thinking (the ASK-3 rule)
        messages: [{
          role: "user",
          content: `Write exactly 2 sentences: first explain why this donor scored ${finalScore}/10 (${capacityTier} tier, ${confidence} confidence) referencing their specific numbers; second, name one concrete action that would raise their score. No labels, no headers.

Data: ${d.name} | Total giving: $${total.toLocaleString()} | ${gc} gifts avg $${avgGiftAmt.toLocaleString()} | Largest gift: $${maxGift.toLocaleString()} | Last gift: ${d.last_gift_date || "none"} | Stage: ${d.stage} | Touchpoints: ${interactions.length}`,
        }],
      });
      // FIX-28: an unfinished reply is never shown; the template rationale stands.
      const text = (msg.content || []).filter(b => b.type === "text").map(b => b.text).join("").trim();
      if ((!msg.stop_reason || msg.stop_reason === "end_turn") && text) rationale = text;
    } catch(e) {
      console.error("Score rationale:", e.message);
    }

    await run(
      "UPDATE donors SET wealth_score=?,capacity_tier=?,score_confidence=?,score_last_updated=NOW(),score_rationale=? WHERE id=? AND org_id=?",
      [finalScore, capacityTier, confidence, rationale, donorId, orgId]
    );
    return { wealthScore: finalScore, capacityTier, scoreConfidence: confidence, scoreRationale: rationale };
  } catch(e) {
    console.error("calcWealthScore:", e.message);
    return null;
  }
}
app = routers.r1;
// ═══ SEC-1 · TWO-FACTOR AND SESSIONS ═══════════════════════════════════════
// Every route below is the signed-in person's own, except the three marked
// OWNER, which take an admin and a teammate in the same organisation. Every
// one is audited by the trail above every router; the verbs are named here.
const TF = require("../twoFactor");
const bcrypt = require("bcryptjs");
const meRow = async userId => (await query(`SELECT * FROM users WHERE id=?`, [userId]))[0] || null;
const orgOf = async orgId => (await query(`SELECT id, is_demo_org, require_mfa, require_admin_mfa FROM orgs WHERE id=?`, [orgId]))[0] || null;
const mustKeepMfa = (u, o) => !!(u.is_super_admin || (o && o.require_mfa) || (u.role === "admin" && o && o.require_admin_mfa));
// One check for "is this a current code of yours", whatever the method.
async function currentCodeOk(u, code) {
  const c = String(code || "").trim();
  if (!c) return false;
  if (TF.looksLikeRecovery(c)) return TF.useRecoveryCode(u, c);
  if (u.mfa_method === "email") return TF.useEmailCode(u, c);
  return (await mfaVerifyForUser(u, c)) !== null;
}

app.get("/me/mfa", requireAuth, wrap(async (req, res) => {
  const u = await meRow(req.user.userId);
  const o = await orgOf(req.user.orgId);
  res.json({ enabled: !!(u && u.mfa_enabled_at), enabledAt: u ? u.mfa_enabled_at : null, method: u?.mfa_method || (u?.mfa_enabled_at ? "totp" : null),
    recoveryCodesLeft: u?.mfa_enabled_at ? await TF.recoveryLeft(u.id) : 0,
    orgRequires: !!(o && o.require_mfa), orgRequiresForAdmins: !!(o && o.require_admin_mfa),
    mustKeep: !!(u && mustKeepMfa(u, o)), demo: TF.isDemoOrg(o), demoSentence: TF.isDemoOrg(o) ? TF.DEMO_SENTENCE : null });
}));

// Start setup. Authenticator: a new secret, sealed as PENDING, with its QR
// code. Email: a code to the sign-in address. Never on a shared demo login.
app.post("/me/mfa/setup", requireAuth, wrap(async (req, res) => {
  const o = await orgOf(req.user.orgId);
  if (TF.isDemoOrg(o)) return res.status(409).json({ error: "demo_org", message: TF.DEMO_SENTENCE });
  const u = await meRow(req.user.userId);
  if (req.body?.method === "email") {
    const r = await TF.sendEmailCode(u, resend, "turn on two-factor");
    if (!r.sent && r.reason === "too_soon") return res.status(429).json({ error: "too_soon", message: "A code was sent a moment ago. Check your inbox, or try again in a minute." });
    if (!r.sent) return res.status(502).json({ error: "not_delivered", message: `Steward could not email a code to ${u.email} just now. Try again in a minute, or use an authenticator app.` });
    return res.json({ method: "email", sentence: `We emailed a six-digit code to ${u.email}. Type it here to finish.` });
  }
  const { seal, credentialsConfigured } = await import("../shared/secretBox.js");
  // FIX-10 D — a customer never reads a variable name. The reason is in the
  // server log, where somebody can act on it.
  if (!credentialsConfigured()) {
    console.error("[mfa] setup refused: no credential key is configured on this server");
    return res.status(503).json({ error: "Two-step sign-in isn't available yet. We'll let you know when it is." });
  }
  const secret = TOTP.newSecret();
  await run(`UPDATE users SET mfa_pending_sealed=? WHERE id=?`, [seal(secret, { aad: "mfa:" + req.user.orgId + ":" + req.user.userId }), req.user.userId]);
  const otpauthUrl = TOTP.otpauthUrl(secret, { account: req.user.email || req.user.userId });
  let qr = null;
  try { qr = await require("qrcode").toDataURL(otpauthUrl, { margin: 1, width: 220, errorCorrectionLevel: "M" }); } catch { qr = null; }
  res.json({ method: "totp", secret, otpauthUrl, qr,
    sentence: "Scan this with your authenticator app, or type the key, then enter the six-digit code it shows." });
}));

// Finish setup with one good code. Returns the recovery codes ONCE and a full
// session: a setup-only session becomes a real one here, and nowhere else.
app.post("/me/mfa/enable", requireAuth, wrap(async (req, res) => {
  const u = await meRow(req.user.userId);
  const o = await orgOf(req.user.orgId);
  if (TF.isDemoOrg(o)) return res.status(409).json({ error: "demo_org", message: TF.DEMO_SENTENCE });
  if (!u) return res.status(400).json({ error: "Start setup first." });
  if (req.body?.method === "email") {
    if (!(await TF.useEmailCode(u, req.body.code))) return res.status(400).json({ error: "mfa_invalid", message: "That code did not match, or it has expired." });
    await run(`UPDATE users SET mfa_method='email', mfa_secret_sealed=NULL, mfa_pending_sealed=NULL, mfa_enabled_at=NOW(), mfa_must_setup=false WHERE id=?`, [u.id]);
  } else {
    if (!u.mfa_pending_sealed) return res.status(400).json({ error: "Start setup first." });
    const { open } = await import("../shared/secretBox.js");
    const secret = open(u.mfa_pending_sealed, { aad: "mfa:" + u.org_id + ":" + u.id });
    const ctr = TOTP.verify(secret, req.body && req.body.code);
    if (ctr === null) return res.status(400).json({ error: "mfa_invalid", message: "That code did not match. Codes change every 30 seconds." });
    await run(`UPDATE users SET mfa_method='totp', mfa_secret_sealed=mfa_pending_sealed, mfa_pending_sealed=NULL, mfa_enabled_at=NOW(), mfa_last_counter=?, mfa_must_setup=false WHERE id=?`, [ctr, u.id]);
  }
  const recoveryCodes = await TF.makeRecoveryCodes(u);
  req.audit.action("two-factor turned on"); req.audit.entity("user", u.id, u.email);
  const isSuperAdmin = !!u.is_super_admin;
  const { token } = await TF.issueSession(u, req, signToken);
  const [org] = await query(`SELECT * FROM orgs WHERE id=?`, [u.org_id]);
  res.json({ enabled: true, token, recoveryCodes,
    recoverySentence: "Keep these somewhere safe. Each works once, instead of a code, if you lose your phone. They will not be shown again.",
    user: { id: u.id, email: u.email, name: u.name, role: u.role, isSuperAdmin, mfaEnabled: true },
    org: org ? { ...org, onboarding_complete: org.onboarding_complete ?? 1 } : null });
}));

// A code by email, for someone whose method is email and who needs one now
// (to turn it off, or to make new recovery codes).
app.post("/me/mfa/email-code", requireAuth, wrap(async (req, res) => {
  const u = await meRow(req.user.userId);
  if (!u || u.mfa_method !== "email") return res.status(400).json({ error: "Your two-factor uses an authenticator app." });
  const r = await TF.sendEmailCode(u, resend, "confirm a change to two-factor");
  req.audit.skip("a code sent to oneself");
  res.json({ sent: r.sent, sentence: r.sent ? `We emailed a code to ${u.email}.`
    : r.reason === "too_soon" ? "A code was sent a moment ago. Check your inbox."
    : `Steward could not email a code to ${u.email} just now. Try again in a minute.` });
}));

// Turning it off takes a current code, and is refused where it is required.
app.post("/me/mfa/disable", requireAuth, wrap(async (req, res) => {
  const u = await meRow(req.user.userId);
  if (!u || !u.mfa_enabled_at) return res.status(400).json({ error: "Two-step sign-in is not on." });
  const o = await orgOf(u.org_id);
  if (mustKeepMfa(u, o)) return res.status(409).json({ error: u.is_super_admin ? "Super-admin accounts always use two-factor." : "Your organisation requires two-factor sign-in." });
  if (!(await currentCodeOk(u, req.body && req.body.code))) return res.status(400).json({ error: "mfa_invalid", message: "That code did not match." });
  await run(`UPDATE users SET mfa_secret_sealed=NULL, mfa_pending_sealed=NULL, mfa_enabled_at=NULL, mfa_last_counter=NULL, mfa_method=NULL WHERE id=?`, [u.id]);
  await run(`DELETE FROM mfa_recovery_codes WHERE user_id=?`, [u.id]);
  await run(`DELETE FROM mfa_trusted_browsers WHERE user_id=?`, [u.id]);
  req.audit.action("two-factor turned off"); req.audit.entity("user", u.id, u.email);
  res.json({ enabled: false });
}));

// New recovery codes: the old set stops working the moment these exist.
app.post("/me/mfa/recovery-codes", requireAuth, wrap(async (req, res) => {
  const u = await meRow(req.user.userId);
  if (!u || !u.mfa_enabled_at) return res.status(400).json({ error: "Turn on two-factor first." });
  if (!(await currentCodeOk(u, req.body && req.body.code))) return res.status(400).json({ error: "mfa_invalid", message: "That code did not match." });
  const recoveryCodes = await TF.makeRecoveryCodes(u);
  req.audit.action("recovery codes replaced"); req.audit.entity("user", u.id, u.email);
  res.json({ recoveryCodes, recoverySentence: "Your old recovery codes no longer work. Keep these somewhere safe; they will not be shown again." });
}));

// The org rule, OWNER. Only an admin who already has two-factor on may switch
// either one on, so nobody locks themselves out by clicking a box.
app.put("/org/security", requireAuth, requireAdmin, wrap(async (req, res) => {
  const want = req.body || {};
  const sets = [], args = [];
  for (const [k, col] of [["requireMfa", "require_mfa"], ["requireAdminMfa", "require_admin_mfa"]]) {
    if (want[k] === undefined) continue;
    if (typeof want[k] !== "boolean") return res.status(400).json({ error: `${k} must be true or false` });
    sets.push(`${col}=?`); args.push(want[k]);
  }
  if (!sets.length) return res.status(400).json({ error: "requireMfa or requireAdminMfa is required" });
  if (want.requireMfa === true || want.requireAdminMfa === true) {
    const u = await meRow(req.user.userId);
    if (!u || !u.mfa_enabled_at) return res.status(409).json({ error: "Turn on two-factor for yourself first." });
  }
  const o = await orgOf(req.user.orgId);
  if (TF.isDemoOrg(o)) return res.status(409).json({ error: "demo_org", message: TF.DEMO_SENTENCE });
  await run(`UPDATE orgs SET ${sets.join(", ")} WHERE id=?`, [...args, req.user.orgId]);
  const [after] = await query(`SELECT require_mfa, require_admin_mfa FROM orgs WHERE id=?`, [req.user.orgId]);
  res.json({ requireMfa: !!after.require_mfa, requireAdminMfa: !!after.require_admin_mfa });
}));

// RESET A TEAMMATE'S TWO-FACTOR, OWNER. They set it up again at their next
// sign-in; every session they have ends now; they are told who and when.
app.post("/org/users/:id/mfa/reset", requireAuth, requireAdmin, wrap(async (req, res) => {
  if (TF.isDemoOrg(await orgOf(req.user.orgId))) return res.status(409).json({ error: "demo_org", message: "The shared demo login is used by many people at once, so it cannot sign others out or change its password. In your own account this works as described." });
  const [t] = await query(`SELECT * FROM users WHERE id=? AND org_id=?`, [req.params.id, req.user.orgId]);
  if (!t) return res.status(404).json({ error: "That person is not on your team." });
  const [me] = await query(`SELECT name, email FROM users WHERE id=?`, [req.user.userId]);
  await run(`UPDATE users SET mfa_secret_sealed=NULL, mfa_pending_sealed=NULL, mfa_enabled_at=NULL, mfa_last_counter=NULL, mfa_method=NULL,
                              mfa_must_setup=true, mfa_failed_count=0, mfa_locked_until=NULL, sessions_valid_after=NOW() WHERE id=?`, [t.id]);
  await run(`DELETE FROM mfa_recovery_codes WHERE user_id=?`, [t.id]);
  await run(`DELETE FROM mfa_trusted_browsers WHERE user_id=?`, [t.id]);
  await TF.revokeSessions("user_id=?", [t.id], req.user.userId);
  require("../sessionCache").sessionCache.evict(t.id);
  const when = new Date().toUTCString();
  const mailed = await TF.mailUser(t, resend, "Your Steward two-factor was reset",
    `${me?.name || me?.email || "An owner"} reset two-factor on your Steward account on ${when}. You will be asked to set it up again the next time you sign in. If you did not expect this, reply to your team's owner.`);
  req.audit.action("two-factor reset by an owner"); req.audit.entity("user", t.id, t.email);
  res.json({ ok: true, emailed: mailed, sentence: `Reset. ${t.name || t.email} sets two-factor up again at their next sign-in, `
    + (mailed ? "and was emailed to say you did this." : "but Steward could not email them about it, so tell them yourself.") });
}));

// SIGN A TEAMMATE OUT EVERYWHERE, OWNER.
app.post("/org/users/:id/sign-out-everywhere", requireAuth, requireAdmin, wrap(async (req, res) => {
  if (TF.isDemoOrg(await orgOf(req.user.orgId))) return res.status(409).json({ error: "demo_org", message: "The shared demo login is used by many people at once, so it cannot sign others out or change its password. In your own account this works as described." });
  const [t] = await query(`SELECT id, name, email FROM users WHERE id=? AND org_id=?`, [req.params.id, req.user.orgId]);
  if (!t) return res.status(404).json({ error: "That person is not on your team." });
  await run(`UPDATE users SET sessions_valid_after=NOW() WHERE id=?`, [t.id]);
  require("../sessionCache").sessionCache.evict(t.id);
  const n = await TF.revokeSessions("user_id=?", [t.id], req.user.userId);
  req.audit.action("signed a teammate out everywhere"); req.audit.entity("user", t.id, t.email);
  res.json({ ok: true, ended: n, sentence: `${t.name || t.email} is signed out of every browser.` });
}));

// YOUR SESSIONS.
app.get("/me/sessions", requireAuth, wrap(async (req, res) => {
  const rows = await query(
    `SELECT id, user_agent, ip_prefix, created_at, last_active_at FROM user_sessions
      WHERE user_id=? AND revoked_at IS NULL AND last_active_at > NOW() - INTERVAL '8 days'
      ORDER BY last_active_at DESC LIMIT 50`, [req.user.userId]);
  res.json({ sessions: rows.map(r => ({ id: r.id, ...TF.describeAgent(r.user_agent), ipPrefix: r.ip_prefix,
      createdAt: r.created_at, lastActiveAt: r.last_active_at, thisBrowser: r.id === req.user.sid })),
    sentence: "Every browser signed in to your account in the last week. Sign one out and it is asked for a password on its next click." });
}));
app.post("/me/sessions/:id/sign-out", requireAuth, wrap(async (req, res) => {
  const n = await TF.revokeSessions("id=? AND user_id=?", [req.params.id, req.user.userId], req.user.userId);
  if (!n) return res.status(404).json({ error: "That session is not yours, or it has already ended." });
  req.audit.action("signed a session out"); req.audit.entity("session", req.params.id);
  res.json({ ok: true });
}));
// Everywhere else. The cut-off moves too, which also ends any token from
// before sessions were rows; this browser gets a fresh token for its session.
app.post("/me/sessions/sign-out-others", requireAuth, wrap(async (req, res) => {
  if (TF.isDemoOrg(await orgOf(req.user.orgId))) return res.status(409).json({ error: "demo_org", message: "The shared demo login is used by many people at once, so it cannot sign others out or change its password. In your own account this works as described." });
  const u = await meRow(req.user.userId);
  const n = await TF.revokeSessions("user_id=? AND id <> ?", [u.id, req.user.sid || ""], u.id);
  await run(`UPDATE users SET sessions_valid_after=NOW() - INTERVAL '2 seconds' WHERE id=?`, [u.id]);
  require("../sessionCache").sessionCache.evict(u.id);
  let token = null;
  if (req.user.sid) { token = signToken({ userId: u.id, orgId: u.org_id, email: u.email, role: u.role, isSuperAdmin: !!u.is_super_admin, sid: req.user.sid }); }
  else token = (await TF.issueSession(u, req, signToken)).token;
  req.audit.action("signed out everywhere else"); req.audit.entity("user", u.id, u.email);
  res.json({ ok: true, ended: n, token });
}));

// CHANGE YOUR PASSWORD, signed in. Every other session ends; this one stays.
app.post("/me/password", requireAuth, wrap(async (req, res) => {
  if (TF.isDemoOrg(await orgOf(req.user.orgId))) return res.status(409).json({ error: "demo_org", message: "The shared demo login is used by many people at once, so it cannot sign others out or change its password. In your own account this works as described." });
  const u = await meRow(req.user.userId);
  const cur = String(req.body?.current || ""), next = String(req.body?.next || "");
  if (!u || !bcrypt.compareSync(cur, u.password_hash)) return res.status(400).json({ error: "wrong_password", message: "Your current password did not match." });
  if (next.length < 8) return res.status(400).json({ error: "Your new password needs at least 8 characters." });
  await run(`UPDATE users SET password_hash=? WHERE id=?`, [bcrypt.hashSync(next, 12), u.id]);
  const n = await TF.revokeSessions("user_id=? AND id <> ?", [u.id, req.user.sid || ""], u.id);
  await run(`UPDATE users SET sessions_valid_after=NOW() - INTERVAL '2 seconds' WHERE id=?`, [u.id]);
  require("../sessionCache").sessionCache.evict(u.id);
  const token = req.user.sid ? signToken({ userId: u.id, orgId: u.org_id, email: u.email, role: u.role, isSuperAdmin: !!u.is_super_admin, sid: req.user.sid })
    : (await TF.issueSession(u, req, signToken)).token;
  req.audit.action("password changed"); req.audit.entity("user", u.id, u.email);
  res.json({ ok: true, ended: n, token, sentence: n ? `Password changed. ${n} other ${n === 1 ? "session was" : "sessions were"} signed out.` : "Password changed." });
}));

