// Server-side backstop for donor material uploads. The client only checks
// file.size<1MB before base64-encoding — trivially bypassed by calling the
// API directly, so it's not a real limit on its own. The MIME allowlist is
// the actual fix for the stored-XSS risk: file_type is attacker/uploader-
// controlled and the frontend's viewMaterial() trusts it verbatim to build a
// Blob it opens via window.open(URL.createObjectURL(...)) — if file_type
// were ever "text/html" or "image/svg+xml", that blob would execute as
// script in the browser. That path isn't reachable today only because
// GET /donors/:id/materials happens to exclude file_data from its SELECT
// (an apparently unrelated bug that also makes the "View" button do nothing
// for base64 uploads) — an accident, not a real control. Constraining
// file_type to genuinely inert formats at write time closes the actual gap,
// so it stays closed even if that unrelated bug gets "fixed" later by
// someone adding file_data back to a read response.
const MATERIAL_MAX_BYTES = 1024 * 1024; // 1MB, matches the documented convention
const MATERIAL_ALLOWED_MIME_TYPES = new Set([
  "application/pdf",
  "image/jpeg", "image/png", "image/gif", "image/webp",
  "application/msword",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  "application/vnd.ms-excel",
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  "text/plain",
  "text/csv",
  "application/octet-stream",
]);

app.post("/donors/:id/materials", requireAuth, wrap(async (req, res) => {
  const { file_name, file_type, file_url, file_data, notes } = req.body;
  if (!file_name) return res.status(400).json({ error: "file_name required" });
  if (file_type && !MATERIAL_ALLOWED_MIME_TYPES.has(file_type)) {
    return res.status(400).json({ error: `Unsupported file type: ${file_type}` });
  }
  if (file_data && Buffer.byteLength(file_data, "base64") > MATERIAL_MAX_BYTES) {
    return res.status(400).json({ error: "File too large. Maximum size is 1MB." });
  }
  const donorCheck = await query("SELECT id FROM donors WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!donorCheck.length) return res.status(404).json({ error: "Donor not found" });
  const userRow = await query("SELECT name FROM users WHERE id=?", [req.user.userId]);
  const id = "mat_" + uuid().slice(0,8);
  await run(
    "INSERT INTO donor_materials (id,org_id,donor_id,file_name,file_type,file_url,file_data,notes,uploaded_by) VALUES (?,?,?,?,?,?,?,?,?)",
    [id, req.user.orgId, req.params.id, file_name, file_type||"", file_url||null, file_data||null, notes||"", userRow[0]?.name||""]
  );
  const rows = await query("SELECT id,org_id,donor_id,file_name,file_type,file_url,notes,uploaded_by,uploaded_at FROM donor_materials WHERE id=?", [id]);
  // Log interaction
  try {
    const ext = file_type ? file_type.split("/").pop() : "file";
    await run(
      "INSERT INTO interactions (id,org_id,donor_id,type,note,date,created_by,logged_by_name) VALUES (?,?,?,?,?,?,?,?)",
      ["int_"+uuid().slice(0,8), req.user.orgId, req.params.id, "material",
       `Material added: ${file_name} (${ext})`,
       orgToday(await orgTz(req.user.orgId)), req.user.userId, userRow[0]?.name||""]   // ORG_TZ_SEAM_OK FIX-14 Part 1 — was the UTC day
    );
  } catch(e) { console.error("Material log:", e.message); }
  res.status(201).json(rows[0]);
}));

app.delete("/materials/:id", requireAuth, wrap(async (req, res) => {
  const existing = await query("SELECT * FROM donor_materials WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!existing.length) return res.status(404).json({ error: "Not found" });
  if (existing[0].major_gifts_only && !(await require("../prospect").canSee(req.user.userId))) return res.status(404).json({ error: "Not found" });
  const undoId = await trashRow("donor_materials", req.params.id, req);
  if (!undoId) return res.status(404).json({ error: "Not found" });
  res.json({ ok: true, deleted: 1, undoId, undoSeconds: UNDO_SECONDS });
}));

// ── Households / soft credit (BUILD-14) ────────────────────────────────────
// A household groups 2+ constituents. HARD CREDIT NEVER MOVES: donors.
// total_giving stays each donor's own gift sum, org hard total = SUM(all
// gifts) regardless of grouping. Combined giving and soft credit are DERIVED
// (never stored counters), so they cannot double-count. See db.js migration.
function lastName(name) {
  const parts = String(name || "").trim().split(/\s+/);
  return parts.length ? parts[parts.length - 1] : "";
}

// Full derived view of a household: members (with per-member hard credit +
// primary flag), combined giving, member count. Combined = SUM(members'
// hard credit) — a pure aggregation over the same gift rows.
async function householdView(householdId, orgId) {
  const hh = await query("SELECT * FROM households WHERE id=? AND org_id=?", [householdId, orgId]);
  if (!hh.length) return null;
  const members = await query(
    `SELECT id, name, email, phone, total_giving, gift_count, last_gift_date, last_gift_amount,
            stage, status, assigned_to, assigned_to_name
     FROM donors WHERE household_id=? AND org_id=? AND deleted_at IS NULL
     ORDER BY total_giving DESC, id`, [householdId, orgId]);
  // REPORTS-4: combined giving is the `household-giving` source's value (the
  // same members, added in cents), so it opens onto them and foots exactly.
  const combinedSource = { key: "household-giving", params: { household: householdId } };
  const combinedGiving = (await figureSources.figureValue(orgId, combinedSource)).value;
  const combinedGiftCount = members.reduce((s, m) => s + (parseInt(m.gift_count, 10) || 0), 0);
  return {
    ...hh[0],
    members: members.map(m => ({
      ...m,
      total_giving: parseFloat(m.total_giving) || 0,
      last_gift_amount: parseFloat(m.last_gift_amount) || 0,
      gift_count: parseInt(m.gift_count, 10) || 0,
      is_primary: m.id === hh[0].primary_donor_id,
      // per-member soft credit = combined − own hard credit = other members' gifts
      soft_credit: (Math.round(combinedGiving * 100) - Math.round((parseFloat(m.total_giving) || 0) * 100)) / 100,
      source: { key: "household-giving", params: { household: householdId, only: m.id } },
    })),
    member_count: members.length,
    combined_giving: combinedGiving,
    combined_source: combinedSource,
    combined_gift_count: combinedGiftCount,
  };
}

app.get("/households", requireAuth, wrap(async (req, res) => {
  const rows = await query(
    `SELECT h.id, h.name, h.primary_donor_id, h.joint_acknowledgment, h.created_at,
            COUNT(d.id)::int AS member_count, COALESCE(SUM(d.total_giving),0) AS combined_giving
     FROM households h
     LEFT JOIN donors d ON d.household_id = h.id AND d.org_id = h.org_id AND d.deleted_at IS NULL
     WHERE h.org_id=?
     GROUP BY h.id
     ORDER BY combined_giving DESC, h.name`, [req.user.orgId]);
  res.json(rows.map(r => ({ ...r, member_count: parseInt(r.member_count, 10) || 0, combined_giving: parseFloat(r.combined_giving) || 0 })));
}));

app.get("/households/:id", requireAuth, wrap(async (req, res) => {
  const view = await householdView(req.params.id, req.user.orgId);
  if (!view) return res.status(404).json({ error: "Household not found" });
  // Combined giving history — all members' gifts merged, newest first
  const gifts = await query(
    `SELECT g.id, g.donor_id, d.name AS donor_name, g.amount, g.date, g.type, g.campaign
     FROM gifts g JOIN donors d ON d.id = g.donor_id
     WHERE d.household_id=? AND g.org_id=? AND d.deleted_at IS NULL
     ORDER BY g.date DESC, g.id DESC LIMIT 200`, [req.params.id, req.user.orgId]);
  view.giving_history = gifts.map(g => ({ ...g, amount: parseFloat(g.amount) || 0 }));
  res.json(view);
}));

// Validate a proposed member set: all ids exist in this org, none already in
// a DIFFERENT household. Returns { error } (with status) or { ids, primary }.
// ── BUILD-97 Part 2 — AN ORGANISATION IS NOT A PERSON, AND THE PERSON
// SURFACES ARE WHERE THAT HAS TEETH ────────────────────────────────────────
// BUILD-80 Part 7 gave `donors.kind` three values and used it to keep
// organisations off Drift and the re-engage list, and stopped there. Two person
// surfaces were left open, and both are the kind of wrong that reaches a donor:
//
//   · A HOUSEHOLD is a marriage or a family living at one address, combined for
//     acknowledgment. "The Sunrise Foundation Household" is not a thing, and
//     the combined figure it produces would put a foundation's grants on a
//     person's giving record.
//   · A PLANNED GIFT is a bequest, an estate, an IRA beneficiary designation, a
//     life-insurance policy. Every one of them is a thing that happens because
//     a PERSON died. A foundation does not leave a bequest, and a chip on its
//     record saying it might is the product not knowing what it is looking at.
//
// One helper, one sentence, so the two refusals cannot drift apart. Kind NULL
// is a legacy row and reads as a person (the BUILD-84 rule), so nothing that
// predates the column is refused.
const PERSON_ONLY_SENTENCE = (what, name) =>
  `${name || "That record"} is an organisation, not a person, so it cannot ${what}. ` +
  `Organisations have their own list, with grant-cycle language rather than household and estate language.`;

async function validateHouseholdMembers(memberIds, primaryDonorId, orgId, allowHouseholdId) {
  const ids = Array.isArray(memberIds) ? [...new Set(memberIds.filter(Boolean))] : [];
  if (ids.length < 2) return { status: 400, error: "A household needs at least two members." };
  const members = await query(
    "SELECT id, name, kind, household_id FROM donors WHERE id = ANY(?) AND org_id=? AND deleted_at IS NULL",
    [ids, orgId]);
  if (members.length !== ids.length) return { status: 404, error: "One or more donors not found in this organization." };
  const foreign = members.find(m => m.household_id && m.household_id !== allowHouseholdId);
  if (foreign) return { status: 400, error: "A donor is already in another household." };
  // BUILD-97 Part 2 — a household is people. Checked on the MEMBER LIST rather
  // than at either route, so the create path and the edit path cannot disagree.
  const orgMember = members.find(m => m.kind === "organisation" || m.kind === "anonymous");
  if (orgMember) return { status: 400, error: PERSON_ONLY_SENTENCE("be part of a household", orgMember.name) };
  const primary = primaryDonorId && ids.includes(primaryDonorId) ? primaryDonorId : ids[0];
  return { ids, primary };
}

app.post("/households", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { name, memberIds, primaryDonorId, jointAcknowledgment } = req.body;
  const v = await validateHouseholdMembers(memberIds, primaryDonorId, req.user.orgId, null);
  if (v.error) return res.status(v.status).json({ error: v.error });
  // Default name: "The {primary's last name} Household"
  let hhName = (name && String(name).trim()) || "";
  if (!hhName) {
    const primaryRow = await query("SELECT name FROM donors WHERE id=? AND org_id=?", [v.primary, req.user.orgId]);
    const ln = lastName(primaryRow[0]?.name);
    hhName = ln ? `The ${ln} Household` : "Household";
  }
  const id = "hh_" + uuid().slice(0, 8);
  await withTransaction(async (client) => {
    await runTx(client, "INSERT INTO households (id,org_id,name,primary_donor_id,joint_acknowledgment,created_by,created_by_name) VALUES (?,?,?,?,?,?,?)",
      [id, req.user.orgId, hhName, v.primary, jointAcknowledgment !== false, actor(req).id, actor(req).name]);
    await runTx(client, "UPDATE donors SET household_id=? WHERE id = ANY(?) AND org_id=?", [id, v.ids, req.user.orgId]);
  });
  await householdLines(req, hhName, id, v.ids, []);   // WIRE-1
  res.status(201).json(await householdView(id, req.user.orgId));
}));

app.put("/households/:id", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const hh = await query("SELECT * FROM households WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!hh.length) return res.status(404).json({ error: "Household not found" });
  // FIX-14 Part 2b: whoever made the household, or an admin. The audit row
  // carries the members before and after, so it can say who was removed.
  if (!(await mayEditLogged(req, hh[0]))) return res.status(403).json(NOT_YOURS);
  const hhBefore = await auditShape("households", hh[0], req.user.orgId);
  const { name, memberIds, primaryDonorId, jointAcknowledgment } = req.body;
  let ids = null, primary = hh[0].primary_donor_id;
  if (memberIds !== undefined) {
    const v = await validateHouseholdMembers(memberIds, primaryDonorId, req.user.orgId, req.params.id);
    if (v.error) return res.status(v.status).json({ error: v.error });
    ids = v.ids; primary = v.primary;
  } else if (primaryDonorId) {
    // primary change without member change — must be an existing member
    const m = await query("SELECT id FROM donors WHERE id=? AND org_id=? AND household_id=?", [primaryDonorId, req.user.orgId, req.params.id]);
    if (!m.length) return res.status(400).json({ error: "New primary must be a member of the household." });
    primary = primaryDonorId;
  }
  const membersBefore = ids ? (await query("SELECT id FROM donors WHERE household_id=? AND org_id=?", [req.params.id, req.user.orgId])).map(r => r.id) : [];
  await withTransaction(async (client) => {
    if (ids) {
      // drop members no longer in the set, then (re)attach the set
      await runTx(client, "UPDATE donors SET household_id=NULL WHERE household_id=? AND org_id=? AND NOT (id = ANY(?))", [req.params.id, req.user.orgId, ids]);
      await runTx(client, "UPDATE donors SET household_id=? WHERE id = ANY(?) AND org_id=?", [req.params.id, ids, req.user.orgId]);
    }
    await runTx(client,
      "UPDATE households SET name=COALESCE(?,name), primary_donor_id=?, joint_acknowledgment=COALESCE(?,joint_acknowledgment), updated_at=NOW() WHERE id=? AND org_id=?",
      [name && String(name).trim() ? String(name).trim() : null, primary,
       jointAcknowledgment === undefined ? null : (jointAcknowledgment !== false), req.params.id, req.user.orgId]);
  });
  const [hhRow] = await query("SELECT * FROM households WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (ids) await householdLines(req, hhRow?.name || "the household", req.params.id,
    ids.filter(x => !membersBefore.includes(x)), membersBefore.filter(x => !ids.includes(x)));   // WIRE-1
  const hhAfter = await auditShape("households", hhRow, req.user.orgId);
  if (auditTrailMod.diffFields(hhBefore, hhAfter)) {
    await run("UPDATE households SET edited_at=NOW(), edited_by=?, edited_by_name=? WHERE id=? AND org_id=?",
      [...(await editStamp(req)), req.params.id, req.user.orgId]);
  }
  if (req.audit) { req.audit.before(hhBefore); req.audit.after(hhAfter); }
  res.json(await householdView(req.params.id, req.user.orgId));
}));

// WIRE-1 · joining or leaving a household is a line on the person.
async function householdLines(req, hhName, householdId, joined, left) {
  const who = await staffWho(req);
  for (const [list, word] of [[joined, "Joined"], [left, "Left"]]) {
    for (const donorId of list || []) {
      await TL.timelineLine({ orgId: req.user.orgId, donorId, note: `${word} ${hhName}.`,
        actorId: who.id, actorName: who.name, metadata: { via: "household", household_id: householdId, change: word.toLowerCase() } });
    }
  }
}

// FIX-14 Part 2b: the household goes to the trash with its member list, and
// Undo re-links every member who has not joined another household since.
app.delete("/households/:id", requireAuth, wrap(async (req, res) => {
  const hh = await query("SELECT * FROM households WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!hh.length) return res.status(404).json({ error: "Household not found" });
  if (!(await mayEditLogged(req, hh[0]))) return res.status(403).json(NOT_YOURS);
  if (req.audit) req.audit.before(await auditShape("households", hh[0], req.user.orgId));
  const undoId = await trashRow("households", req.params.id, req);
  if (!undoId) return res.status(404).json({ error: "Household not found" });
  res.json({ ok: true, deleted: 1, undoId, undoSeconds: UNDO_SECONDS });
}));

// Per-donor soft-credit breakdown: hard = own gifts, soft = other household
// members' gifts, combined = the household total. Derived, no stored counter.
app.get("/donors/:id/soft-credit", requireAuth, wrap(async (req, res) => {
  const d = await query("SELECT id, household_id, total_giving FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL", [req.params.id, req.user.orgId]);
  if (!d.length) return res.status(404).json({ error: "Donor not found" });
  const hardCredit = parseFloat(d[0].total_giving) || 0;
  const householdId = d[0].household_id || null;
  let householdCombined = hardCredit, softCredit = 0;
  if (householdId) {
    const agg = await query(
      "SELECT COALESCE(SUM(total_giving),0) AS combined FROM donors WHERE household_id=? AND org_id=? AND deleted_at IS NULL",
      [householdId, req.user.orgId]);
    householdCombined = parseFloat(agg[0].combined) || 0;
    softCredit = (Math.round(householdCombined * 100) - Math.round(hardCredit * 100)) / 100;
  }
  // REPORTS-4: the household panel's three figures open their members.
  const householdSources = householdId ? {
    hardCredit: { key: "household-giving", params: { household: householdId, only: req.params.id } },
    softCredit: { key: "household-giving", params: { household: householdId, except: req.params.id } },
    householdCombined: { key: "household-giving", params: { household: householdId } },
  } : null;
  // BUILD-98 Part 1 — the soft credits on OTHER people's gifts, which is a
  // different thing from the household view above: a DAF recommender, the
  // spouse on a joint cheque, the board member who asked. Hard stays hard;
  // "with soft credit" is its own figure, beside it and labelled.
  // FIX-7 Part 1 — the PAGE a peer-to-peer soft credit came through, so the
  // record can say "raised $1,900 for Harbor Run" in the one sentence a
  // fundraiser would use. A soft credit is never this person's giving: it
  // does not move their lifetime total, their last gift, their drift, their
  // LYBUNT or their retention, and every one of those reads `gifts` alone.
  const scRows = await query(
    `SELECT sc.id, sc.amount, sc.pct, sc.role, g.id AS gift_id, g.date, g.amount AS gift_amount,
            dg.id AS giver_id, dg.name AS giver_name,
            gp.id AS page_id, gp.title AS page_title
       FROM gift_soft_credits sc
       JOIN gifts g ON g.id = sc.gift_id AND g.org_id = sc.org_id
       JOIN donors dg ON dg.id = g.donor_id AND dg.org_id = g.org_id
       LEFT JOIN giving_pages gp ON gp.id = g.giving_page_id AND gp.org_id = g.org_id
      WHERE sc.org_id=? AND sc.donor_id=? ORDER BY g.date DESC LIMIT 200`, [req.user.orgId, req.params.id]);
  const giftSoftCents = scRows.reduce((t, r) => t + Math.round(Number(r.amount) * 100), 0);
  // One line per page they raised for, newest gift first, in cents.
  const raisedFor = [];
  for (const r of scRows) {
    if (r.role !== "peer_fundraiser" || !r.page_id) continue;
    let row = raisedFor.find(x => x.pageId === r.page_id);
    if (!row) raisedFor.push(row = { pageId: r.page_id, pageTitle: r.page_title, amountCents: 0, giftCount: 0 });
    row.amountCents += Math.round(Number(r.amount) * 100);
    row.giftCount += 1;
  }
  res.json({ donorId: d[0].id, householdId, hardCredit, softCredit, householdCombined, householdSources,
    giftSoftCredit: giftSoftCents / 100,
    hardPlusGiftSoft: (Math.round(hardCredit * 100) + giftSoftCents) / 100,
    raisedFor,
    raisedForSentence: "Money other people gave through their fundraiser page. It is recognition, not their own giving, and it changes nothing about their record.",
    giftSoftCredits: scRows.map(r => ({ id: r.id, amount: Number(r.amount), pct: r.pct == null ? null : Number(r.pct), role: r.role,
      giftId: r.gift_id, date: r.date, giftAmount: Number(r.gift_amount), giverId: r.giver_id, giverName: r.giver_name,
      pageId: r.page_id || null, pageTitle: r.page_title || null })) });
}));


// BUILD-98 Part 1 — an imported gift's soft credit, tribute and matching
// employer, from NAMES. Resolution is deterministic and org-scoped: an email or
// an exact name that points at exactly one record is that record; a person
// named as a soft credit who is not on file is CREATED (a DAF recommender is a
// person the org should know); an honouree who is not on file stays a NAME
// (a memorial is often for somebody who never gave); a matching employer is
// found by exact name or created as an organisation.
// ── BUILD-99 (major gifts) Part 6 — PROPOSALS FROM A FILE ──────────────────
// Written AFTER the import transaction commits, the same seam BUILD-98's gift
// extras use and for the same reason: a proposal points at a person, and the
// people are created inside that transaction.
//
// THREE RULES, and each one is why this is not just an INSERT loop:
//   · A PROPOSAL IS NOT A GIFT. Nothing here touches `gifts`, `donors.total_giving`
//     or the ledger. An imported open ask is money that has NOT arrived, and the
//     import receipt routes it off the cash total by name ("open proposals").
//   · ONE OPEN PER FUND STILL HOLDS. A file carrying two open asks on one person
//     for one fund is a file with a duplicate in it; the second is SKIPPED and
//     COUNTED, never written and never silently merged into the first.
//   · A STAGE OR PROBABILITY THE PRODUCT DOES NOT RECOGNISE IS NOT GUESSED. An
//     unreadable stage falls back to `identified` and is COUNTED as having done
//     so; an unreadable probability is left BLANK, which the weighted total
//     already knows how to say out loud. Neither is invented.
async function importProposals(orgId, rows, who, donorIdByIndex) {
  const P = await import("../shared/proposalShape.js");
  const out = { written: 0, skippedDuplicate: 0, stageDefaulted: 0, probabilityDropped: 0,
                unresolved: [], fundsCreated: 0 };
  if (!Array.isArray(rows) || !rows.length) return out;

  const fundCache = new Map();
  const fundIdFor = async (name) => {
    const nm = String(name || "").trim();
    if (!nm) return null;
    const key = nm.toLowerCase();
    if (fundCache.has(key)) return fundCache.get(key);
    const [hit] = await query("SELECT id FROM fin_funds WHERE org_id=? AND LOWER(name)=LOWER(?) LIMIT 1", [orgId, nm]);
    let id = hit ? hit.id : null;
    if (!id) {
      // A fund named in a file IS a fund (BUILD-88a A.7), created UNRESTRICTED —
      // a restriction is a board decision, not a column.
      id = "fund_" + uuid().slice(0, 10);
      await run("INSERT INTO fin_funds (id,org_id,name,restricted,description) VALUES (?,?,?,false,'Created by an import')",
        [id, orgId, nm.slice(0, 120)]);
      out.fundsCreated++;
    }
    fundCache.set(key, id);
    return id;
  };
  const ownerCache = new Map();
  const ownerFor = async (name) => {
    const nm = String(name || "").trim();
    if (!nm) return null;
    const key = nm.toLowerCase();
    if (ownerCache.has(key)) return ownerCache.get(key);
    // Matched to a user of THIS org by name or email, exactly; ambiguity resolves
    // to nobody (the import owner-matching rule — never mis-assign).
    const hits = await query(
      "SELECT id, name FROM users WHERE org_id=? AND (LOWER(name)=LOWER(?) OR LOWER(email)=LOWER(?)) LIMIT 2", [orgId, nm, nm]);
    const u = hits.length === 1 ? hits[0] : null;
    ownerCache.set(key, u);
    return u;
  };

  for (const r of rows) {
    let donorId = null;
    if (r.donorIndex !== undefined && r.donorIndex !== null) donorId = donorIdByIndex(Number(r.donorIndex));
    if (!donorId && r.donorName) {
      const [d] = await query("SELECT id FROM donors WHERE org_id=? AND deleted_at IS NULL AND LOWER(name)=LOWER(?) ORDER BY created_at, id LIMIT 1",
        [orgId, String(r.donorName).trim()]);
      donorId = d ? d.id : null;
    }
    if (!donorId) { out.unresolved.push({ purpose: String(r.purpose || "").slice(0, 80), donorName: r.donorName || null, why: "nobody on file to put it on" }); continue; }

    let askCents = 0;
    try { askCents = parseMoneyOrThrow(r.askAmount, "askAmount"); } catch { askCents = 0; }
    if (!(askCents > 0)) { out.unresolved.push({ purpose: String(r.purpose || "").slice(0, 80), why: "no ask amount that could be read" }); continue; }

    // THE STAGE WORD MAY BE THE FILE'S, NOT STEWARD'S. A Salesforce export says
    // "Prospecting"; a Bloomerang or DonorPerfect one says "Submitted" or
    // "Negotiation". Steward's own key is tried first, then NPSP's documented
    // ladder (which those words overlap), and only then does it default — so a
    // real export's vocabulary is READ rather than flattened to Identified and
    // counted as a failure.
    let stage = String(r.stage || "").trim().toLowerCase();
    if (!P.stageFor(stage)) {
      const NP = await import("../shared/npspPreset.js");
      const mapped = NP.npspProposalStage(r.stage);
      if (mapped) stage = mapped;
      else { stage = "identified"; out.stageDefaulted++; }
    }
    const prob = P.normalizeProbability(r.probability);
    if (prob === undefined) out.probabilityDropped++;

    const fundId = await fundIdFor(r.fund);
    const owner = await ownerFor(r.owner);
    const purpose = P.sanitizePurpose(r.purpose) || "Ask";
    const close = /^\d{4}-\d{2}-\d{2}$/.test(String(r.expectedClose || "")) ? String(r.expectedClose) : null;

    const id = "opp_" + uuid().slice(0, 8);
    const ins = await query(
      `INSERT INTO opportunities
         (id,org_id,donor_id,name,target_amount,status,proposal_stage,probability,fund_id,notes,
          officer_id,officer_name,expected_close,created_by,created_by_name,updated_at)
       SELECT ?::text,?::text,?::text,?::text,?::numeric,?::text,?::text,?::integer,?::text,?::text,
              ?::text,?::text,?::date,?::text,?::text,NOW()
        WHERE NOT EXISTS (
          SELECT 1 FROM opportunities x WHERE x.org_id=?::text AND x.donor_id=?::text
            AND COALESCE(x.fund_id,'') = ?::text AND x.proposal_stage = ANY(?::text[]))
       RETURNING id`,
      [id, orgId, donorId, purpose, toDollars(askCents), P.statusForStage(stage), stage,
       prob == null || prob === undefined ? null : prob, fundId, P.sanitizeNotes(r.notes),
       owner ? owner.id : null, owner ? owner.name : null, close, who.id, who.name,
       orgId, donorId, fundId || "", P.isOpenStage(stage) ? P.OPEN_STAGE_KEYS : []]);
    if (ins.length) out.written++;
    else out.skippedDuplicate++;
  }
  return out;
}

async function importGiftExtras(orgId, pending, who) {
  await GC_READY;
  const out = { softCredits: 0, tributes: 0, tributeNotices: 0, matches: 0, peopleCreated: 0, unresolved: [] };
  const cache = new Map();
  const made = { count: 0 };
  const byName = async (name, opts = {}) => {
    const id = await donorByNameOrCreate(orgId, name, { ...opts, who, cache, made });
    out.peopleCreated = made.count;
    return id;
  };
  for (const { giftId, g } of pending) {
    const [gift] = await query("SELECT * FROM gifts WHERE id=? AND org_id=?", [giftId, orgId]);
    if (!gift) continue;
    const cents = Math.round(Number(gift.amount) * 100);
    const raw = {};
    const c = g.credit;
    if (c.softCredit && c.softCredit.name) {
      const pid = await byName(c.softCredit.name, { create: true });
      if (pid && pid !== gift.donor_id) raw.softCredits = [{ donorId: pid, amount: c.softCredit.amount ?? null, pct: c.softCredit.pct ?? null, role: "recommender" }];
      else if (!pid) out.unresolved.push({ kind: "soft_credit", name: c.softCredit.name });
    }
    if (c.tribute && c.tribute.name) {
      const type = GC.normaliseTributeType(c.tribute.type) || GC.TRIBUTE_HONOR;
      if (!GC.normaliseTributeType(c.tribute.type) && c.tribute.type) out.unresolved.push({ kind: "tribute_type", name: c.tribute.type });
      const hid = await byName(c.tribute.name);
      raw.tribute = { type, donorId: hid, name: c.tribute.name, notifyName: c.tribute.notifyName || null };
    }
    if (c.matchEmployer) {
      const eid = await byName(c.matchEmployer, { create: true, kind: "organisation" });
      if (eid && eid !== gift.donor_id) raw.match = { employerId: eid };
    }
    const ck = await checkGiftExtras(orgId, gift.donor_id, cents, raw);
    if (ck.errors || ck.notFound) { out.unresolved.push({ kind: "gift_credit", name: giftId, why: (ck.errors || ["not found"]).join("; ") }); continue; }
    const r = await writeGiftExtras(orgId, gift, ck.extras, { actorId: who.id, actorName: who.name });
    out.softCredits += r.softCredits; if (ck.extras.tribute) out.tributes++;
    if (r.tributeNotice) out.tributeNotices++; if (r.matchPledgeId) out.matches++;
  }
  return out;
}
// ── BUILD-98 Part 1 — a gift's soft credits, tribute and match ─────────────
app.get("/gifts/:id/extras", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [g] = await query("SELECT id, donor_id, amount, tribute_type, tribute_donor_id, tribute_name, match_employer_id, match_pledge_id FROM gifts WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!g) return res.status(404).json({ error: "Gift not found" });
  const [soft, notice, match] = await Promise.all([
    query(`SELECT sc.donor_id, sc.amount, sc.pct, sc.role, d.name FROM gift_soft_credits sc
             JOIN donors d ON d.id = sc.donor_id AND d.org_id = sc.org_id
            WHERE sc.gift_id=? AND sc.org_id=? ORDER BY d.name`, [g.id, orgId]),
    query("SELECT id, status, notify_name, notify_email, notify_address, body FROM tribute_notices WHERE gift_id=? AND org_id=?", [g.id, orgId]),
    g.match_pledge_id ? query(
      `SELECT p.id, p.amount, p.status, p.due_date, d.name AS employer_name, COALESCE(pp.paid,0) AS paid
         FROM pledges p JOIN donors d ON d.id = p.donor_id AND d.org_id = p.org_id
         LEFT JOIN (SELECT pledge_id, SUM(amount) AS paid FROM gifts WHERE org_id=? AND pledge_id IS NOT NULL GROUP BY pledge_id) pp ON pp.pledge_id = p.id
        WHERE p.id=? AND p.org_id=?`, [orgId, g.match_pledge_id, orgId]) : [],
  ]);
  res.json({
    softCredits: soft.map(r => ({ donorId: r.donor_id, name: r.name, amount: Number(r.amount), pct: r.pct == null ? null : Number(r.pct), role: r.role })),
    tribute: g.tribute_type ? { type: g.tribute_type, donorId: g.tribute_donor_id, name: g.tribute_name } : null,
    tributeNotice: notice[0] || null,
    match: match[0] ? { pledgeId: match[0].id, employerId: g.match_employer_id, employerName: match[0].employer_name,
      expected: Number(match[0].amount), received: Number(match[0].paid), status: match[0].status, dueDate: match[0].due_date } : null,
  });
}));

// Add or change them after the gift exists. Soft credits are REPLACED as a set;
// a tribute is set; a match is added once (a second one is refused by the
// database, not by an if-statement).
app.put("/gifts/:id/extras", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [g] = await query("SELECT * FROM gifts WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!g) return res.status(404).json({ error: "Gift not found" });
  const ck = await checkGiftExtras(orgId, g.donor_id, Math.round(Number(g.amount) * 100),
    { softCredits: req.body?.softCredits, tribute: req.body?.tribute, match: req.body?.match });
  if (ck.notFound) return res.status(404).json({ error: "Donor not found" });
  if (ck.errors) return res.status(400).json({ error: ck.errors.join("; ") });
  const extras = { ...ck.extras };
  if (!Array.isArray(req.body?.softCredits)) delete extras.softCredits;   // absent means "leave them"
  const result = await writeGiftExtras(orgId, g, extras, { actorId: actor(req).id, actorName: actor(req).name });
  res.json({ ok: true, ...result });
}));

// The notices waiting to go to families. Steward never sends one: she prints
// or copies it, and marks it sent.
app.get("/tribute-notices", requireAuth, wrap(async (req, res) => {
  const rows = await query(
    `SELECT t.id, t.gift_id, t.tribute_type, t.honouree_name, t.notify_name, t.notify_email, t.notify_address, t.body, t.status, t.created_at,
            d.id AS donor_id, d.name AS donor_name
       FROM tribute_notices t JOIN donors d ON d.id = t.donor_id AND d.org_id = t.org_id
      WHERE t.org_id=? AND t.status='waiting' AND d.deleted_at IS NULL ORDER BY t.created_at DESC LIMIT 200`, [req.user.orgId]);
  res.json({ notices: rows });
}));
app.post("/tribute-notices/:id/sent", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { changes } = await run("UPDATE tribute_notices SET status='sent', sent_at=NOW(), sent_by=?, sent_by_name=? WHERE id=? AND org_id=? AND status='waiting'",
    [actor(req).id, actor(req).name, req.params.id, req.user.orgId]);
  if (!changes) return res.status(404).json({ error: "Not found" });
  res.json({ ok: true });
}));
app.post("/tribute-notices/:id/skip", requireAuth, wrap(async (req, res) => {
  const { changes } = await run("UPDATE tribute_notices SET status='skipped' WHERE id=? AND org_id=? AND status='waiting'", [req.params.id, req.user.orgId]);
  if (!changes) return res.status(404).json({ error: "Not found" });
  res.json({ ok: true });
}));

async function ackOrg(orgId) {
  const [o] = await query(
    `SELECT id, name, legal_name, receipt_address, receipt_signature_name, receipt_signature_title,
            logo_data, brand_accent, brand_accent_fg, ack_backlog_days FROM orgs WHERE id=?`, [orgId]);
  if (!o) return null;
  const display = await donorFacingOrgName(orgId, o.name || "").catch(() => o.name || "");
  return { ...o, display };
}

async function ackTemplate(orgId, templateId) {
  await ACK_READY;
  if (templateId) {
    const [t] = await query("SELECT * FROM ack_letter_templates WHERE id=? AND org_id=?", [templateId, orgId]);
    return t || null;
  }
  // Only a template somebody MARKED default stands in for "no choice". Taking
  // whichever saved template came first would print the wrong letter.
  const [t] = await query("SELECT * FROM ack_letter_templates WHERE org_id=? AND is_default=true ORDER BY created_at ASC LIMIT 1", [orgId]);
  return t || { id: null, name: "Standard thank-you", body: ACK.DEFAULT_ACK_TEMPLATE, is_default: true, builtIn: true };
}

// The gifts, grouped into one letter per donor. Every id is checked against
// this org; a foreign id is simply not found.
async function ackLetterSet(orgId, giftIds, templateId, { addressesOnly = false, signerFallback = null } = {}) {
  await ACK_READY;
  const ids = [...new Set((Array.isArray(giftIds) ? giftIds : []).map(String).filter(Boolean))].slice(0, 1000);
  if (!ids.length) return { error: "Choose the gifts to write letters for." };
  const tpl = await ackTemplate(orgId, templateId);
  if (!tpl) return { notFound: true };
  const org = await ackOrg(orgId);
  const rows = await query(
    `SELECT g.id, g.donor_id, g.amount, g.date, g.tribute_type, g.tribute_name, f.name AS fund,
            d.name, d.kind, d.salutation, d.address, d.address2, d.city, d.state, d.zip, d.country, d.deceased
       FROM gifts g JOIN donors d ON d.id = g.donor_id AND d.org_id = g.org_id
       LEFT JOIN fin_funds f ON f.id = g.fund_id
      WHERE g.org_id=? AND g.id = ANY(?) AND d.deleted_at IS NULL
      ORDER BY d.name, g.date`, [orgId, ids]);
  const byDonor = new Map();
  for (const r of rows) {
    const e = byDonor.get(r.donor_id) || { donor: r, gifts: [] };
    e.gifts.push({ id: r.id, amount: r.amount, date: r.date, fund: r.fund, tributeType: r.tribute_type, tributeName: r.tribute_name });
    byDonor.set(r.donor_id, e);
  }
  // The letter is signed by the org's receipt signer when one is set, and
  // otherwise by the person printing it — a letter she prints goes out over
  // her name, which is true. Never blank: an unsigned letter is not posted.
  const signer = org.receipt_signature_name || signerFallback || "";
  const orgFields = { name: org.display, signer, signerTitle: org.receipt_signature_name ? (org.receipt_signature_title || "") : "" };
  const letters = [], skipped = [];
  for (const { donor, gifts } of byDonor.values()) {
    const giftIdsHere = gifts.map(g => g.id);
    // A letter to somebody who has died is not a thank-you; it goes to the
    // family by hand, and the batch says so rather than printing it.
    if (donor.deceased) { skipped.push({ donorId: donor.donor_id, name: donor.name, giftIds: giftIdsHere, why: "marked deceased" }); continue; }
    const address = ACK.addressLines(donor);
    if (!address) { skipped.push({ donorId: donor.donor_id, name: donor.name, giftIds: giftIdsHere, why: "no postal address on file" }); continue; }
    // Labels need an address and nothing else; a template the gift cannot fill
    // must not cost somebody their envelope.
    if (addressesOnly) { letters.push({ donorId: donor.donor_id, name: donor.name, address, text: "", giftIds: giftIdsHere, totalCents: 0 }); continue; }
    const fields = ACK.letterFields({ donor, gifts, org: orgFields });
    const r = ACK.renderLetter(tpl.body, fields);
    if (r.missing.length) { skipped.push({ donorId: donor.donor_id, name: donor.name, giftIds: giftIdsHere, why: `nothing to put in ${r.missing.map(k => `{{${k}}}`).join(", ")}` }); continue; }
    letters.push({ donorId: donor.donor_id, name: donor.name, address, text: r.text, giftIds: giftIdsHere, totalCents: fields._totalCents });
  }
  const found = new Set(rows.map(r => r.id));
  return { template: { id: tpl.id, name: tpl.name, builtIn: !!tpl.builtIn }, org, letters, skipped,
           notFound: ids.filter(id => !found.has(id)).length };
}

function renderLettersPdf(org, letters, { dateLine }) {
  const PDFDocument = require("pdfkit");
  const doc = new PDFDocument({ size: "LETTER", margins: { top: 50, bottom: 40, left: 72, right: 72 }, autoFirstPage: false });
  return new Promise((resolve, reject) => {
    const chunks = [];
    doc.on("data", c => chunks.push(c));
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);
    const INK = "#0f1a12", SUB = "#5a554f";
    const accent = org.brand_accent || "#0d5c3a";
    let logo = null;
    if (org.logo_data && /^data:image\/(png|jpe?g);base64,/.test(org.logo_data)) {
      try { logo = Buffer.from(org.logo_data.split(",")[1], "base64"); } catch { logo = null; }
    }
    for (const L of letters) {
      doc.addPage();
      const PW = doc.page.width;
      // Letterhead: the org's name and return address, top left; the logo right.
      doc.rect(0, 0, PW, 6).fill(accent);
      if (logo) { try { doc.image(logo, PW - 72 - 60, 22, { fit: [60, 44] }); } catch { /* a logo that will not draw costs the logo, not the letter */ } }
      doc.font("Helvetica-Bold").fontSize(13).fillColor(INK).text(org.display, 72, 26, { width: PW - 220, lineBreak: false });
      if (org.receipt_address) doc.font("Helvetica").fontSize(8.5).fillColor(SUB).text(org.receipt_address, 72, 44, { width: PW - 220 });
      doc.font("Helvetica").fontSize(10).fillColor(INK).text(dateLine, 72, 100, { width: PW - 144, align: "right" });
      // The address, exactly where the window of a #10 envelope is.
      doc.font("Helvetica").fontSize(11).fillColor(INK)
        .text(L.address.join("\n"), ACK.WINDOW.x, ACK.WINDOW.y, { width: ACK.WINDOW.w, height: ACK.WINDOW.h, lineGap: 1 });
      // The body starts below the window and is held to the page: a long
      // letter is cut at the page, never allowed to spill onto a second.
      const top = ACK.WINDOW.y + ACK.WINDOW.h + 40;
      doc.font("Times-Roman").fontSize(11.5).fillColor(INK)
        .text(L.text, 72, top, { width: PW - 144, height: doc.page.height - top - 50, lineGap: 3, ellipsis: true });
    }
    doc.end();
  });
}

function renderLabelsPdf(addresses) {
  const PDFDocument = require("pdfkit");
  const doc = new PDFDocument({ size: "LETTER", margin: 0, autoFirstPage: false });
  return new Promise((resolve, reject) => {
    const chunks = [];
    doc.on("data", c => chunks.push(c));
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);
    let page = -1;
    addresses.forEach((lines, i) => {
      const o = ACK.labelOrigin(i);
      if (o.page !== page) { doc.addPage(); page = o.page; }
      doc.font("Helvetica").fontSize(10).fillColor("#0f1a12")
        .text(lines.join("\n"), o.x + 12, o.y + 10, { width: ACK.LABELS_5160.w - 24, height: ACK.LABELS_5160.h - 14, lineGap: 0, ellipsis: true });
    });
    doc.end();
  });
}

// ── ACKNOWLEDGMENT ROUTES ──────────────────────────────────────────────────
app.get("/acknowledgments/templates", requireAuth, wrap(async (req, res) => {
  await ACK_READY;
  const rows = await query("SELECT id, name, body, is_default, created_by_name, updated_at FROM ack_letter_templates WHERE org_id=? ORDER BY is_default DESC, name", [req.user.orgId]);
  res.json({
    templates: rows.length ? rows : [{ id: null, name: "Standard thank-you", body: ACK.DEFAULT_ACK_TEMPLATE, is_default: true, builtIn: true }],
    mergeFields: ACK.ACK_MERGE_FIELDS,
  });
}));

app.post("/acknowledgments/templates", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  await ACK_READY;
  const name = String(req.body?.name || "").trim().slice(0, 120);
  const body = String(req.body?.body || "");
  if (!name) return res.status(400).json({ error: "Give the letter a name." });
  const v = ACK.validateTemplate(body);
  if (!v.ok) return res.status(400).json({ error: v.errors.join(" ") });
  const id = "alt_" + uuid().slice(0, 10);
  const makeDefault = req.body?.isDefault === true;
  if (makeDefault) await run("UPDATE ack_letter_templates SET is_default=false WHERE org_id=?", [req.user.orgId]);
  await run(`INSERT INTO ack_letter_templates (id,org_id,name,body,is_default,created_by,created_by_name) VALUES (?,?,?,?,?,?,?)`,
    [id, req.user.orgId, name, body, makeDefault, actor(req).id, actor(req).name]);
  res.status(201).json({ id });
}));

app.put("/acknowledgments/templates/:id", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  await ACK_READY;
  const [t] = await query("SELECT id FROM ack_letter_templates WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!t) return res.status(404).json({ error: "Not found" });
  const name = String(req.body?.name || "").trim().slice(0, 120);
  const body = String(req.body?.body || "");
  const v = ACK.validateTemplate(body);
  if (!name) return res.status(400).json({ error: "Give the letter a name." });
  if (!v.ok) return res.status(400).json({ error: v.errors.join(" ") });
  if (req.body?.isDefault === true) await run("UPDATE ack_letter_templates SET is_default=false WHERE org_id=?", [req.user.orgId]);
  await run("UPDATE ack_letter_templates SET name=?, body=?, is_default=COALESCE(?, is_default), updated_at=NOW() WHERE id=? AND org_id=?",
    [name, body, req.body?.isDefault === true ? true : null, t.id, req.user.orgId]);
  res.json({ ok: true });
}));

app.delete("/acknowledgments/templates/:id", requireAuth, wrap(async (req, res) => {
  const { changes } = await run("DELETE FROM ack_letter_templates WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!changes) return res.status(404).json({ error: "Not found" });
  res.json({ ok: true });
}));

// The backlog: gifts nobody has thanked, older than the org's own N days.
app.get("/acknowledgments/backlog", requireAuth, wrap(async (req, res) => {
  await ACK_READY;
  const orgId = req.user.orgId;
  const org = await ackOrg(orgId);
  const days = Number.isInteger(org?.ack_backlog_days) && org.ack_backlog_days >= 0 ? org.ack_backlog_days : ACK.DEFAULT_ACK_BACKLOG_DAYS;
  const today = orgToday(await orgTz(orgId));                 // ORG_TZ_SEAM_OK
  const cutoff = orgTime.addDays(today, -days);
  const rows = await query(
    `SELECT g.id, g.amount, g.date, g.donor_id, d.name, d.address, d.city, d.state, d.zip, d.deceased, f.name AS fund
       FROM gifts g JOIN donors d ON d.id = g.donor_id AND d.org_id = g.org_id
       LEFT JOIN fin_funds f ON f.id = g.fund_id
      WHERE g.org_id=? AND COALESCE(g.acknowledgement_sent,false) = false AND g.acknowledgement_sent_at IS NULL
        AND g.is_sample IS NOT TRUE AND d.is_sample IS NOT TRUE AND d.deleted_at IS NULL
        AND g.date <= ? AND g.date >= ?
      ORDER BY g.date ASC, d.name LIMIT 500`, [orgId, cutoff, orgTime.addDays(today, -730)]);
  res.json({
    days, cutoff,
    // The one sentence under the count, per BUILD-97 Part 2.
    sentence: `Gifts that arrived more than ${days === 1 ? "a day" : days + " days"} ago and nobody has marked as thanked. An administrator can change the number of days here.`,
    gifts: rows.map(r => ({ id: r.id, amount: Number(r.amount), date: r.date, donorId: r.donor_id, name: r.name, fund: r.fund,
      hasAddress: !!ACK.addressLines(r), deceased: !!r.deceased })),
  });
}));

app.put("/acknowledgments/settings", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const n = Number(req.body?.backlogDays);
  if (!Number.isInteger(n) || n < 0 || n > 365) return res.status(400).json({ error: "backlogDays is a whole number of days, 0 to 365." });
  await run("UPDATE orgs SET ack_backlog_days=? WHERE id=?", [n, req.user.orgId]);
  res.json({ backlogDays: n });
}));

// What the batch WOULD print, and who it would leave out and why. Read-only.
app.post("/acknowledgments/letters/preview", requireAuth, wrap(async (req, res) => {
  const [me] = await query("SELECT name FROM users WHERE id=?", [req.user.userId]);
  const set = await ackLetterSet(req.user.orgId, req.body?.giftIds, req.body?.templateId || null, { signerFallback: me?.name || null });
  if (set.error) return res.status(400).json({ error: set.error });
  if (set.notFound === true) return res.status(404).json({ error: "Template not found" });
  res.json({ template: set.template, letters: set.letters.map(l => ({ donorId: l.donorId, name: l.name, address: l.address, text: l.text, giftIds: l.giftIds, total: l.totalCents / 100 })),
             skipped: set.skipped, giftsNotFound: set.notFound });
}));

// The PDF. One page per donor. A POST, because it carries a selection — and a
// print changes nothing: marking the letters sent is its own request.
app.post("/acknowledgments/letters/pdf", requireAuth, wrap(async (req, res) => {
  const [me] = await query("SELECT name FROM users WHERE id=?", [req.user.userId]);
  const set = await ackLetterSet(req.user.orgId, req.body?.giftIds, req.body?.templateId || null, { signerFallback: me?.name || null });
  if (set.error) return res.status(400).json({ error: set.error });
  if (set.notFound === true) return res.status(404).json({ error: "Template not found" });
  if (!set.letters.length) return res.status(409).json({ error: "no_letters", skipped: set.skipped,
    message: "None of these gifts can be printed yet. The reason is beside each name." });
  const today = orgToday(await orgTz(req.user.orgId));           // ORG_TZ_SEAM_OK
  const pdf = await renderLettersPdf(set.org, set.letters, { dateLine: ACK.formatLetterDate(today) });
  res.setHeader("Content-Type", "application/pdf");
  res.setHeader("Content-Disposition", `attachment; filename="thank-you-letters-${today}.pdf"`);
  res.setHeader("X-Letters-Printed", String(set.letters.length));
  res.setHeader("X-Letters-Skipped", String(set.skipped.length));
  res.setHeader("Access-Control-Expose-Headers", "X-Letters-Printed, X-Letters-Skipped");
  res.end(pdf);
}));

// Mailing labels, Avery 5160: one per donor, never one per gift.
app.post("/acknowledgments/labels/pdf", requireAuth, wrap(async (req, res) => {
  await ACK_READY;
  const set = await ackLetterSet(req.user.orgId, req.body?.giftIds, null, { addressesOnly: true });
  if (set.error) return res.status(400).json({ error: set.error });
  const addresses = set.letters.map(l => l.address);
  if (!addresses.length) return res.status(409).json({ error: "no_addresses", skipped: set.skipped });
  const pdf = await renderLabelsPdf(addresses);
  res.setHeader("Content-Type", "application/pdf");
  res.setHeader("Content-Disposition", `attachment; filename="mailing-labels.pdf"`);
  res.setHeader("X-Labels", String(addresses.length));
  res.setHeader("Access-Control-Expose-Headers", "X-Labels");
  res.end(pdf);
}));

// Who thanked them, when, and how. Idempotent: a gift already marked keeps its
// first stamp, because "who thanked them first" is the fact worth keeping.
app.post("/acknowledgments/mark", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  await ACK_READY;
  const ids = [...new Set((Array.isArray(req.body?.giftIds) ? req.body.giftIds : []).map(String))].slice(0, 1000);
  const via = String(req.body?.via || "");
  if (!ids.length) return res.status(400).json({ error: "Choose the gifts that were thanked." });
  if (!ACK.ACK_VIA.includes(via)) return res.status(400).json({ error: `How were they thanked? One of: ${ACK.ACK_VIA.join(", ")}.` });
  // "Who thanked them" is read by a person, so it is their NAME — actor()'s
  // name is the login email, which is an audit stamp, not a signature.
  const [u] = await query("SELECT name FROM users WHERE id=?", [req.user.userId]);
  const who = u?.name || actor(req).name;
  const rows = await query(
    `UPDATE gifts SET acknowledgement_sent=true, acknowledgement_sent_at=COALESCE(acknowledgement_sent_at, NOW()),
                      acknowledged_by=COALESCE(acknowledged_by, ?), acknowledged_by_name=COALESCE(acknowledged_by_name, ?),
                      acknowledged_via=COALESCE(acknowledged_via, ?)
      WHERE org_id=? AND id = ANY(?) RETURNING id`, [actor(req).id, who, via, req.user.orgId, ids]);
  // The drafted thank-you (88b) for these gifts is done too; leaving it in the
  // queue would ask her to thank somebody twice.
  await run("UPDATE thank_you_drafts SET sent_at=COALESCE(sent_at, NOW()) WHERE org_id=? AND gift_id = ANY(?) AND sent_at IS NULL AND skipped_at IS NULL", [req.user.orgId, ids]).catch(() => {});
  res.json({ marked: rows.length });
}));

// ── Constituent designations (BUILD-14) ────────────────────────────────────
// First-class, filterable, reportable gift-vehicle / planned-giving flags.
// Filter the donor list via GET /donors?designation=<kind>.
const DESIGNATION_KINDS = {
  estate: "Estate giving",
  planned_confirmed: "Planned gift confirmed",
  planned_prospect: "Planned-giving prospect",
};

app.get("/donors/:id/designations", requireAuth, wrap(async (req, res) => {
  const d = await query("SELECT id FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL", [req.params.id, req.user.orgId]);
  if (!d.length) return res.status(404).json({ error: "Donor not found" });
  const rows = await query("SELECT kind, created_at FROM donor_designations WHERE donor_id=? AND org_id=? ORDER BY created_at", [req.params.id, req.user.orgId]);
  res.json(rows.map(r => ({ kind: r.kind, label: DESIGNATION_KINDS[r.kind] || r.kind, created_at: r.created_at })));
}));

app.post("/donors/:id/designations", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { kind } = req.body;
  if (!DESIGNATION_KINDS[kind]) return res.status(400).json({ error: "Unknown designation. Must be one of: " + Object.keys(DESIGNATION_KINDS).join(", ") });
  if (!(await orgOwns("donors", req.params.id, req.user.orgId))) return res.status(404).json({ error: "Donor not found" });
  await run(
    "INSERT INTO donor_designations (id,org_id,donor_id,kind) VALUES (?,?,?,?) ON CONFLICT (donor_id, kind) DO NOTHING",
    ["dsg_" + uuid().slice(0, 8), req.user.orgId, req.params.id, kind]);
  res.status(201).json({ ok: true, kind, label: DESIGNATION_KINDS[kind] });
}));

app.delete("/donors/:id/designations/:kind", requireAuth, wrap(async (req, res) => {
  if (!(await orgOwns("donors", req.params.id, req.user.orgId))) return res.status(404).json({ error: "Donor not found" });
  await run("DELETE FROM donor_designations WHERE donor_id=? AND org_id=? AND kind=?", [req.params.id, req.user.orgId, req.params.kind]);
  res.json({ ok: true });
}));

// ── Officer portfolios + color (BUILD-14, Team plan) ───────────────────────
// Read is ungated (a Core org still sees its officers), but returns `tier` +
// `single_user` so the UI locks the color feature and hides it for a
// one-person shop. Assigning a color is Team-only and admin-gated.
app.get("/portfolio/officers", requireAuth, wrap(async (req, res) => {
  const orgRows = await query("SELECT plan, subscription_status FROM orgs WHERE id=?", [req.user.orgId]);
  const tier = orgRows.length ? orgPlanTier(orgRows[0]) : "core";
  // portfolio_count/giving use the SAME definition as Home's cards + the board
  // (BUILD-30): assigned donors in a pipeline stage. The stage guard lives in the
  // JOIN so a non-pipeline-stage donor can't inflate the legend past the board.
  const officers = await query(
    `SELECT u.id, u.name, u.email, u.role, u.portfolio_color,
            COUNT(d.id)::int AS portfolio_count, COALESCE(SUM(d.total_giving),0) AS portfolio_giving
     FROM users u
     LEFT JOIN donors d ON d.assigned_to = u.id AND d.org_id = u.org_id AND d.deleted_at IS NULL AND COALESCE(d.stage, d.suggested_stage) = ANY(?)
     WHERE u.org_id=? GROUP BY u.id ORDER BY portfolio_giving DESC, u.name`, [ALL_PIPELINE_STAGES, req.user.orgId]);
  // Pending invitees (invited, not yet accepted, unexpired) are surfaced too so
  // the import officer-mapping screen can match + assign donors to them BEFORE
  // they accept (the assignment resolves into their portfolio on acceptance).
  // Includes each invite's held pending-donor count so the UI can show it.
  const invites = await query(
    `SELECT i.id, i.email,
            COUNT(d.id)::int AS pending_count
       FROM invites i
       LEFT JOIN donors d ON d.pending_assignee_invite_id = i.id AND d.org_id = i.org_id AND d.deleted_at IS NULL
      WHERE i.org_id=? AND i.accepted_at IS NULL AND i.expires_at > NOW()
      GROUP BY i.id, i.email ORDER BY i.created_at DESC`, [req.user.orgId]);
  res.json({
    tier,
    single_user: officers.length <= 1,
    officers: officers.map(o => ({
      ...o,
      portfolio_count: parseInt(o.portfolio_count, 10) || 0,
      portfolio_giving: parseFloat(o.portfolio_giving) || 0,
    })),
    invites: invites.map(i => ({ id: i.id, email: i.email, name: inviteeDisplayName(i.email), pending_count: parseInt(i.pending_count, 10) || 0 })),
  });
}));

app.put("/portfolio/officers/:userId/color", requireAuth, requireAdmin, requireCrm, checkWriteAccess, wrap(async (req, res) => {
  const { color } = req.body;
  if (color && !/^#[0-9a-fA-F]{6}$/.test(String(color))) return res.status(400).json({ error: "Color must be a 6-digit hex like #1a6b4a." });
  const u = await query("SELECT id FROM users WHERE id=? AND org_id=?", [req.params.userId, req.user.orgId]);
  if (!u.length) return res.status(404).json({ error: "Officer not found" });
  await run("UPDATE users SET portfolio_color=? WHERE id=? AND org_id=?", [color || null, req.params.userId, req.user.orgId]);
  res.json({ ok: true, userId: req.params.userId, color: color || null });
}));

// ── Moves management & prospect pipeline (BUILD-15, Team plan) ─────────────
// The whole pipeline is a staffed-office capability → Team. Reads return a
// `tier`/`locked` flag rather than 403'ing so a Core org renders a graceful
// "upgrade to manage a major-gifts pipeline" state, not a broken tab. Every
// WRITE (move, opportunity) is hard requireCrm('team') + checkWriteAccess.

// GET /pipeline — the board: prospects grouped by stage, officer color map,
// ask amount + stage age + next task per card, and the forecast. Batched
// queries only (no N+1). Optional ?assignedTo= (portfolio) and ?designation=.
app.get("/pipeline", requireAuth, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  const orgRows = await query("SELECT plan, subscription_status FROM orgs WHERE id=?", [orgId]);
  const tier = orgRows.length ? orgPlanTier(orgRows[0]) : "core";
  const stages = ALL_PIPELINE_STAGES.map(id => ({ id, label: id.charAt(0).toUpperCase() + id.slice(1) }));
  // Core orgs get a READ-only locked preview populated with their OWN data
  // (the board derives entirely from donors.stage / opportunities / moves /
  // tasks — all org-scoped reads a Core user already has). Writes stay hard-
  // gated on POST /pipeline/:donorId/move (requireCrm('team') → 403), so this
  // only softens the read presentation; it does not open a write path.
  const locked = tier !== "team";

  const officers = await query(
    "SELECT id, name, portfolio_color FROM users WHERE org_id=? ORDER BY name", [orgId]);
  const single_user = officers.length <= 1;

  // BUILD-32 Part 4 — the "My portfolio / All portfolios" toggle (and the
  // officer filter) is meaningless unless 2+ officers actually have donors to
  // work. Count distinct officers with ≥1 ASSIGNED donor in a pipeline stage
  // (the same membership definition the board uses). `multiOfficer` drives
  // hiding the single-value pickers client-side; `canViewAll` still gates on
  // admin (a lone admin sees no toggle even though they could "view all").
  const distinctOfficers = await query(
    `SELECT COUNT(DISTINCT assigned_to)::int AS c FROM donors
       WHERE org_id=? AND assigned_to IS NOT NULL AND deleted_at IS NULL
         AND stage = ANY(?)`, [orgId, ALL_PIPELINE_STAGES]);
  const multiOfficer = (distinctOfficers[0]?.c || 0) >= 2;

  // ── The board is a PORTFOLIO, not the donor list ─────────────────────────
  // Membership = ASSIGNMENT (BUILD-30): a donor assigned to an officer is on
  // that officer's board, full stop. There is no separate "on the board" flag.
  // Unassigned (e.g. bulk-imported) donors match nothing here — they live in
  // the Directory with their stage LABEL and never flood this board. `scope`
  // defaults to the caller's own portfolio; a specific `assignedTo` overrides.
  // The exact same `portfolioMembership` helper feeds Home's Portfolio and
  // Pipeline cards, so all three counts are one number by construction.
  // Cross-officer visibility ("All portfolios", or filtering to another officer)
  // is an ADMIN/ED oversight view — the whole-shop forecast Team sells. An
  // individual officer only ever sees their OWN portfolio (BUILD-31 Part 4).
  // Enforced server-side, not just hidden in the UI: a non-admin's scope=all or
  // foreign assignedTo is downgraded to their own portfolio.
  const isAdmin = req.user.role === "admin";
  let scope = req.query.scope === "all" ? "all" : "mine";
  let assignedTo = req.query.assignedTo || null;
  if (!(await OU.orgUser(orgId, assignedTo, { allowInactive: true })).ok) return OU.refuse(res, "assignedTo");
  if (!isAdmin) {
    scope = "mine";
    if (assignedTo && assignedTo !== userId) assignedTo = null;
  }
  const membership = portfolioMembership({ orgId, userId, scope, assignedTo, alias: "d" });
  const filters = [membership.where];
  const params = [...membership.params];
  if (req.query.designation) {
    filters.push("EXISTS (SELECT 1 FROM donor_designations dd WHERE dd.donor_id = d.id AND dd.org_id = d.org_id AND dd.kind = ?)");
    params.push(req.query.designation);
  }
  if (req.query.search && String(req.query.search).trim()) {
    filters.push("LOWER(d.name) LIKE ?"); params.push("%" + String(req.query.search).trim().toLowerCase() + "%");
  }
  const minGiving = parseFloat(req.query.minGiving);
  if (Number.isFinite(minGiving) && minGiving > 0) { filters.push("d.total_giving >= ?"); params.push(minGiving); }

  const donors = await query(
    `SELECT d.id, d.name, COALESCE(d.stage, d.suggested_stage) AS stage, (d.stage IS NULL) AS stage_suggested,
            d.total_giving, d.last_gift_date, d.assigned_to, d.assigned_to_name, d.updated_at, d.created_at
       FROM donors d WHERE ${filters.join(" AND ")}`, params);

  // Open asks aggregated per donor (org-wide, joined in JS).
  const oppAgg = await query(
    `SELECT donor_id, COALESCE(SUM(target_amount),0) AS ask, COUNT(*)::int AS cnt
       FROM opportunities WHERE org_id=? AND status='open' GROUP BY donor_id`, [orgId]);
  const askByDonor = Object.fromEntries(oppAgg.map(o => [o.donor_id, { ask: parseFloat(o.ask) || 0, cnt: o.cnt }]));

  // Most recent move INTO the donor's current stage → stage age.
  const lastMoves = await query(
    `SELECT DISTINCT ON (donor_id, to_stage) donor_id, to_stage, created_at
       FROM moves WHERE org_id=? ORDER BY donor_id, to_stage, created_at DESC`, [orgId]);
  const moveInto = {};
  for (const m of lastMoves) moveInto[m.donor_id + "|" + m.to_stage] = m.created_at;

  // Next open task per donor (earliest due).
  const nextTasks = await query(
    `SELECT DISTINCT ON (donor_id) donor_id, title, due FROM tasks
       WHERE org_id=? AND done=0 AND voided_at IS NULL AND donor_id IS NOT NULL
       ORDER BY donor_id, (NULLIF(due,'')) ASC NULLS LAST`, [orgId]);
  const taskByDonor = Object.fromEntries(nextTasks.map(t => [t.donor_id, { title: t.title, due: t.due }]));

  // BUILD-76 Part 2 — pipeline cards carry the drift badge, same computation
  // as the home list (scoped to the board's own donors).
  const boardIds = donors.map(d => d.id);
  const { map: driftMap } = await computeDriftForDonors(orgId, { donorIds: boardIds.length ? boardIds : ["_none_"] });

  const now = Date.now();
  const columns = {}; ALL_PIPELINE_STAGES.forEach(s => { columns[s] = []; });
  let forecastOpen = 0, forecastWeighted = 0, openCount = 0;
  for (const d of donors) {
    const a = askByDonor[d.id] || { ask: 0, cnt: 0 };
    forecastOpen += a.ask; openCount += a.cnt;
    forecastWeighted += a.ask * (STAGE_WEIGHT[d.stage] || 0);
    const enteredStage = moveInto[d.id + "|" + d.stage] || d.updated_at || d.created_at;
    const stageAge = enteredStage ? Math.max(0, Math.floor((now - new Date(enteredStage).getTime()) / 86400000)) : null;
    (columns[d.stage] = columns[d.stage] || []).push({
      donorId: d.id, name: d.name, stage: d.stage,
      // BUILD-83 Part 3.5 — the card says whether a human placed this donor or
      // the giving history merely suggests it.
      stageSuggested: d.stage_suggested === true || d.stage_suggested === "t",
      totalGiving: parseFloat(d.total_giving) || 0,
      lastGiftDate: d.last_gift_date || null,
      assignedTo: d.assigned_to, assignedToName: d.assigned_to_name,
      askAmount: a.ask, openOppCount: a.cnt, stageAge,
      nextTask: taskByDonor[d.id] || null,
      drift: driftBadgeField(driftMap.get(d.id)),
    });
  }

  // Sort each column + cap the payload so a large portfolio never ships (or
  // renders) hundreds of cards. counts[stage] carries the TRUE size so the UI
  // can show "showing N of M". Sorts: value (default), last gift, stage age.
  const sort = ["value", "last_gift", "stage_age"].includes(req.query.sort) ? req.query.sort : "value";
  const cmp = {
    value: (a, b) => (b.totalGiving - a.totalGiving) || (b.askAmount - a.askAmount),
    last_gift: (a, b) => (b.lastGiftDate ? Date.parse(b.lastGiftDate) : 0) - (a.lastGiftDate ? Date.parse(a.lastGiftDate) : 0),
    stage_age: (a, b) => (b.stageAge || 0) - (a.stageAge || 0),
  }[sort];
  const PER_COLUMN_CAP = 200;
  const counts = {};
  for (const s of ALL_PIPELINE_STAGES) {
    counts[s] = columns[s].length;
    columns[s].sort(cmp);
    if (columns[s].length > PER_COLUMN_CAP) columns[s] = columns[s].slice(0, PER_COLUMN_CAP);
  }

  // Won this quarter (period) — a coarse pipeline health figure.
  const { start } = finPeriodBounds("fiscal", 0, await orgTz(req.user.orgId));   // ORG_TZ_SEAM_OK
  const wonAgg = await query(
    `SELECT COALESCE(SUM(gift_amount),0) AS amt, COUNT(*)::int AS cnt FROM opportunities
       WHERE org_id=? AND status='won' AND closed_at >= ?`, [orgId, start]);
  res.json({
    tier, locked, single_user, multiOfficer, stages, scope, sort, canViewAll: isAdmin,
    officers: officers.map(o => ({ id: o.id, name: o.name, color: o.portfolio_color })),
    columns, counts, total: donors.length, cap: PER_COLUMN_CAP,
    forecast: {
      open: Math.round(forecastOpen), weighted: Math.round(forecastWeighted), openCount,
      wonThisPeriod: parseFloat(wonAgg[0].amt) || 0, wonCount: wonAgg[0].cnt,
    },
  });
}));

// POST /pipeline/add — the deliberate act that puts prospects on the working
// board (single or bulk via `ids`). Assignment IS membership (BUILD-30), so
// "add to my pipeline" = assign to the caller (donors nobody owns yet land on
// the caller's own board; already-owned donors stay with their owner). No
// separate flag. Cross-officer assignment stays the admin `/donors/bulk-assign`.
// Team + write-gated.
app.post("/pipeline/add", requireAuth, requireCrm, checkWriteAccess, wrap(async (req, res) => {
  const ids = Array.isArray(req.body.ids) ? req.body.ids.filter(Boolean) : [];
  if (!ids.length) return res.status(400).json({ error: "ids array required" });
  const owned = await query(
    "SELECT id FROM donors WHERE id = ANY(?) AND org_id = ? AND deleted_at IS NULL", [ids, req.user.orgId]);
  if (owned.length !== ids.length) return res.status(404).json({ error: "One or more donors not found in your org" });
  const userRow = await query("SELECT name FROM users WHERE id=?", [req.user.userId]);
  const myName = userRow[0]?.name || "";
  const result = await run(
    `UPDATE donors
        SET assigned_to      = COALESCE(assigned_to, ?),
            assigned_to_name = COALESCE(assigned_to_name, ?),
            updated_at = NOW()
      WHERE id = ANY(?) AND org_id = ? AND deleted_at IS NULL`,
    [req.user.userId, myName, ids, req.user.orgId]);
  res.json({ added: result.changes });
}));

// POST /pipeline/remove — take a donor OFF the working board (single or bulk).
// Assignment IS membership (BUILD-30), so removing from the board = unassigning;
// the donor stays in the Directory with its stage label untouched. Team +
// write-gated (a curation write, not a delete).
app.post("/pipeline/remove", requireAuth, requireCrm, checkWriteAccess, wrap(async (req, res) => {
  const ids = Array.isArray(req.body.ids) ? req.body.ids.filter(Boolean) : [];
  if (!ids.length) return res.status(400).json({ error: "ids array required" });
  const owned = await query(
    "SELECT id FROM donors WHERE id = ANY(?) AND org_id = ? AND deleted_at IS NULL", [ids, req.user.orgId]);
  if (owned.length !== ids.length) return res.status(404).json({ error: "One or more donors not found in your org" });
  const result = await run(
    `UPDATE donors SET assigned_to = NULL, assigned_to_name = NULL, updated_at = NOW()
      WHERE id = ANY(?) AND org_id = ? AND deleted_at IS NULL`,
    [ids, req.user.orgId]);
  res.json({ removed: result.changes });
}));

// POST /pipeline/:donorId/move — the managed stage change. Description REQUIRED.
app.post("/pipeline/:donorId/move", requireAuth, requireCrm, checkWriteAccess, wrap(async (req, res) => {
  const { toStage, description } = req.body;
  if (!ALL_PIPELINE_STAGES.includes(toStage)) return res.status(400).json({ error: "Invalid stage" });
  if (!description || !String(description).trim()) return res.status(400).json({ error: "A description of the move is required." });
  const rows = await query("SELECT stage FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL", [req.params.donorId, req.user.orgId]);
  if (!rows.length) return res.status(404).json({ error: "Donor not found" });
  const fromStage = rows[0].stage;
  if (fromStage === toStage) return res.status(400).json({ error: "Donor is already in that stage." });

  const userRow = await query("SELECT name FROM users WHERE id=?", [req.user.userId]);
  const officerName = userRow[0]?.name || "";
  await run("UPDATE donors SET stage=?, updated_at=NOW() WHERE id=? AND org_id=?", [toStage, req.params.donorId, req.user.orgId]);
  const moveId = await recordMove(req.user.orgId, req.params.donorId, req.user.userId, officerName, fromStage, toStage, String(description).trim());
  // Keep the donor timeline consistent with the legacy stage_change path.
  try {
    await run(
      "INSERT INTO interactions (id,org_id,donor_id,type,note,date,created_by,logged_by_name) VALUES (?,?,?,?,?,?,?,?)",
      ["int_" + uuid().slice(0, 8), req.user.orgId, req.params.donorId, "stage_change",
       `Moved ${fromStage || "Not set"} → ${toStage}: ${String(description).trim()}`,
       orgToday(await orgTz(req.user.orgId)), req.user.userId, officerName]);   // ORG_TZ_SEAM_OK FIX-14 Part 1 — was the UTC day
  } catch (e) { console.error("move interaction log:", e.message); }
  res.status(201).json({ ok: true, moveId, stage: toStage, fromStage });
}));

// GET /donors/:id/move-suggestions — signal-based suggestions (BUILD-22).
// A read: never changes stage. The officer accepts (→ POST /pipeline/:id/move)
// or dismisses. Org-scoped; foreign donor → 404.
app.get("/donors/:id/move-suggestions", requireAuth, wrap(async (req, res) => {
  const rows = await query("SELECT * FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL", [req.params.id, req.user.orgId]);
  if (!rows.length) return res.status(404).json({ error: "Donor not found" });
  res.json({ suggestions: computeMoveSuggestions(rows[0]) });
}));

// POST /pipeline/run-auto-lapse — run the auto-lapse sweep for the caller's org
// now (drives the exact scheduled path; for ops + tests). Admin-only, same bar
// as /sequences/process and /recurring/process-dunning.
app.post("/pipeline/run-auto-lapse", requireAuth, requireAdmin, wrap(async (req, res) => {
  const moved = await autoLapseOrg(req.user.orgId);
  res.json({ moved });
}));

// GET /donors/:id/moves — full move history for a constituent.
app.get("/donors/:id/moves", requireAuth, wrap(async (req, res) => {
  if (!(await orgOwns("donors", req.params.id, req.user.orgId))) return res.status(404).json({ error: "Donor not found" });
  const rows = await query(
    "SELECT id, officer_id, officer_name, from_stage, to_stage, description, created_at FROM moves WHERE org_id=? AND donor_id=? ORDER BY created_at DESC",
    [req.user.orgId, req.params.id]);
  res.json(rows);
}));

// GET /donors/:id/opportunities — asks on a prospect.
app.get("/donors/:id/opportunities", requireAuth, wrap(async (req, res) => {
  if (!(await orgOwns("donors", req.params.id, req.user.orgId))) return res.status(404).json({ error: "Donor not found" });
  const rows = await query(
    "SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE org_id=? AND donor_id=? ORDER BY (status='open') DESC, created_at DESC",
    [req.user.orgId, req.params.id]);
  res.json(rows.map(o => ({ ...o, target_amount: parseFloat(o.target_amount) || 0, gift_amount: o.gift_amount == null ? null : parseFloat(o.gift_amount) })));
}));

app.post("/donors/:id/opportunities", requireAuth, requireCrm, checkWriteAccess, wrap(async (req, res) => {
  const { name, targetAmount, expectedClose } = req.body;
  const amt = parseFloat(targetAmount);
  if (!(amt > 0)) return res.status(400).json({ error: "A positive target ask amount is required." });
  const d = await query("SELECT assigned_to, assigned_to_name FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL", [req.params.id, req.user.orgId]);
  if (!d.length) return res.status(404).json({ error: "Donor not found" });
  // Officer = the donor's relationship owner; falls back to the creating user.
  let officerId = d[0].assigned_to, officerName = d[0].assigned_to_name;
  if (!officerId) { officerId = req.user.userId; const u = await query("SELECT name FROM users WHERE id=?", [req.user.userId]); officerName = u[0]?.name || ""; }
  // BUILD-99 Part 1 — THIS DOOR AND THE PROPOSALS DOOR ARE ONE OBJECT, so they
  // obey one rule. An ask written here is a proposal at stage `asked` (BUILD-15's
  // own word for what target_amount is), its status is DERIVED from that stage by
  // the one derivation, and "one open at a time per fund" applies — because two
  // doors with two rules over the same rows is how a double-ask gets in. This
  // NARROWS BUILD-15, which allowed several open asks on one prospect; the
  // narrowing is the brief's, and `tests/moves.test.js` was updated to match.
  const P99 = await proposalMod();
  const clash = await openProposalConflict(req.user.orgId, req.params.id, null, null);
  if (clash) return res.status(409).json(clash);
  const id = "opp_" + uuid().slice(0, 8);
  await run(
    "INSERT INTO opportunities (id,org_id,donor_id,name,target_amount,status,proposal_stage,officer_id,officer_name,expected_close,created_by,created_by_name) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",
    [id, req.user.orgId, req.params.id, (name || "").trim() || "Ask", amt,
     P99.statusForStage("asked"), "asked", officerId, officerName || "", expectedClose || null, actor(req).id, actor(req).name]);
  const rows = await query("SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE id=?", [id]);
  res.status(201).json({ ...rows[0], target_amount: parseFloat(rows[0].target_amount) || 0 });
}));

// PUT /opportunities/:id — edit, or close won/lost. Closing 'won' links the
// real gift and records the actual gift amount (the ask-vs-gift accountability).
app.put("/opportunities/:id", requireAuth, requireCrm, checkWriteAccess, wrap(async (req, res) => {
  const existing = await query("SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!existing.length) return res.status(404).json({ error: "Opportunity not found" });
  const { name, targetAmount, expectedClose, status, giftId, giftAmount } = req.body;
  const sets = [], params = [];
  if (name !== undefined) { sets.push("name=?"); params.push((name || "").trim() || "Ask"); }
  if (targetAmount !== undefined) { const a = parseFloat(targetAmount); if (!(a > 0)) return res.status(400).json({ error: "Target ask amount must be positive." }); sets.push("target_amount=?"); params.push(a); }
  if (expectedClose !== undefined) { sets.push("expected_close=?"); params.push(expectedClose || null); }
  if (status !== undefined) {
    if (!["open", "won", "lost"].includes(status)) return res.status(400).json({ error: "Invalid status" });
    sets.push("status=?"); params.push(status);
    // BUILD-99 Part 1 — THE STAGE MOVES WITH THE STATUS, ALWAYS. A status
    // written here without its stage would leave the Proposals screen showing
    // "Asked" on a row the board calls won: one object, two truths, and the way
    // they disagree is a board report that is wrong. `stageFromLegacyStatus` is
    // the same mapping the migration used, so this door and that one agree.
    const P99 = await proposalMod();
    sets.push("proposal_stage=?"); params.push(P99.stageFromLegacyStatus(status));
    if (status === "won") {
      let amt = giftAmount != null ? parseFloat(giftAmount) : null;
      let gId = giftId || null;
      if (gId) {
        const g = await query("SELECT amount FROM gifts WHERE id=? AND org_id=?", [gId, req.user.orgId]);
        if (!g.length) return res.status(404).json({ error: "Linked gift not found" });
        if (amt == null) amt = parseFloat(g[0].amount) || 0;
      }
      sets.push("gift_id=?", "gift_amount=?", "closed_at=NOW()"); params.push(gId, amt);
    } else if (status === "lost") {
      sets.push("gift_id=NULL", "gift_amount=NULL", "closed_at=NOW()");
    } else { // reopen
      sets.push("gift_id=NULL", "gift_amount=NULL", "closed_at=NULL");
    }
  }
  if (!sets.length) return res.status(400).json({ error: "Nothing to update" });
  params.push(req.params.id, req.user.orgId);
  await run(`UPDATE opportunities SET ${sets.join(",")} WHERE id=? AND org_id=?`, params);
  const rows = await query("SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE id=?", [req.params.id]);
  res.json({ ...rows[0], target_amount: parseFloat(rows[0].target_amount) || 0, gift_amount: rows[0].gift_amount == null ? null : parseFloat(rows[0].gift_amount) });
}));

app.delete("/opportunities/:id", requireAuth, wrap(async (req, res) => {
  const { changes } = await run("DELETE FROM opportunities WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!changes) return res.status(404).json({ error: "Not found" }); // BUILD-75 B: a foreign/unknown id answers 404, never a false success — one answer everywhere
  res.json({ success: true });
}));

// ── BUILD-99 Part 1 — PROPOSALS ────────────────────────────────────────────
// A proposal is one ask to one person or household: purpose, ask amount,
// expected close, stage, a probability SHE set, the fund it lands in, the
// officer who owns it, notes. shared/proposalShape.js holds every rule; these
// routes are its only writers. Nothing here infers a capacity, a probability or
// an amount — see that module's header for why the probability list is closed.
//
// The rows live in `opportunities` (BUILD-15's table, extended — db.js says
// why), so the pipeline board's ask totals, wonThisPeriod and officer activity
// keep reading THE SAME ROWS. One ask, one place.
async function proposalMod() { return import("../shared/proposalShape.js"); }

// THE DATABASE FORMATS THE DATE, AND NOTHING HERE PARSES ONE.
// A `DATE` column comes back from pg as a JS Date at LOCAL midnight, so
// `String(d).slice(0,10)` is "Sun Nov 15" — which is what this screen showed on
// its first run. The first fix read the Date's LOCAL calendar parts, which is
// right for THIS input and is still the wrong SHAPE: `tests/date-seam.test.js`
// names any helper that reads a process-local date as tainted, and it is right
// to, because the next caller will hand it something built in a different zone.
// So the date is TO_CHAR'd in SQL (BUILD-86's own gotcha says exactly this) and
// read as the string it already is. There is no date helper here to taint.
// The wire shape. Money leaves as dollars (every other money route does) AND as
// integer cents, because the weighted total is computed in cents and a screen
// that re-derives cents from a float is how a total ends up a penny out.
function proposalRow(r, funds) {
  const askCents = toCents(r.target_amount) || 0;
  return {
    id: r.id, donorId: r.donor_id, donorName: r.donor_name || undefined,
    purpose: r.name || "", askAmount: toDollars(askCents), askCents,
    stage: r.proposal_stage, status: r.status,
    probability: r.probability == null ? null : Number(r.probability),
    expectedClose: r.expected_close_civil || null,
    fundId: r.fund_id || null,
    fundName: r.fund_id ? (funds?.get(r.fund_id) || null) : null,
    officerId: r.officer_id || null, officerName: r.officer_name || "",
    notes: r.notes || "",
    declineReason: r.decline_reason || null, declinedOn: r.declined_on || null,
    commitKind: r.commit_kind || null,
    giftId: r.gift_id || null, pledgeId: r.pledge_id || null,
    giftAmount: r.gift_amount == null ? null : toDollars(toCents(r.gift_amount) || 0),
    createdAt: r.created_at, closedAt: r.closed_at,
    createdByName: r.created_by_name || "",
    // FIX-14 Part 3 — the profile's "Edited" marker reads these.
    edited_at: r.edited_at || null, edited_by_name: r.edited_by_name || null,
  };
}

async function orgFundNames(orgId) {
  const rows = await query("SELECT id, name FROM fin_funds WHERE org_id=?", [orgId]);
  return new Map(rows.map(r => [r.id, r.name]));
}

// A fund id a caller names is checked against THIS org before anything is
// written — never trusted off a payload (the recordGift rule, same reason).
async function checkProposalFund(orgId, fundId) {
  if (!fundId) return { ok: true, fundId: null };
  const rows = await query("SELECT id, name FROM fin_funds WHERE id=? AND org_id=?", [fundId, orgId]);
  if (!rows.length) return { ok: false };
  return { ok: true, fundId: rows[0].id, fundName: rows[0].name };
}

// THE HOUSEHOLD HALF OF "ONE OPEN AT A TIME PER FUND". The per-person half is a
// unique index (db.js); this is the half a partial index cannot express, and it
// is the half that matters most — asking a husband and a wife separately for
// the capital campaign is exactly the double-ask the rule exists to stop.
async function openProposalConflict(orgId, donorId, fundId, excludeId) {
  const [me] = await query("SELECT id, household_id FROM donors WHERE id=? AND org_id=?", [donorId, orgId]);
  if (!me) return null;
  const P = await proposalMod();
  const rows = await query(
    `SELECT o.id, o.donor_id, d.name AS donor_name, d.household_id
       FROM opportunities o JOIN donors d ON d.id = o.donor_id AND d.org_id = o.org_id
      WHERE o.org_id = ? AND o.proposal_stage = ANY(?::text[]) AND COALESCE(o.fund_id,'') = ?
        AND (d.id = ? OR (?::text IS NOT NULL AND d.household_id = ?))
        AND d.deleted_at IS NULL`,
    [orgId, P.OPEN_STAGE_KEYS, fundId || "", donorId, me.household_id, me.household_id]);
  const hit = rows.find(r => r.id !== excludeId);
  if (!hit) return null;
  const fundLabel = fundId ? (await orgFundNames(orgId)).get(fundId) || "fund" : "no particular fund";
  return {
    code: "proposal_already_open",
    error: hit.donor_id === donorId
      ? `There is already an open proposal for ${fundLabel}. Close or move that one first.`
      : `${hit.donor_name} in the same household already has an open proposal for ${fundLabel}. Close or move that one first.`,
    conflictId: hit.id,
  };
}

// GET /donors/:id/proposals — the proposals on one person, newest ask first with
// the open ones on top. The profile panel sits ABOVE giving history.
app.get("/donors/:id/proposals", requireAuth, wrap(async (req, res) => {
  if (!(await orgOwns("donors", req.params.id, req.user.orgId))) return res.status(404).json({ error: "Donor not found" });
  const P = await proposalMod();
  const funds = await orgFundNames(req.user.orgId);
  const rows = await query(
    `SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE org_id=? AND donor_id=?
      ORDER BY (proposal_stage = ANY(?::text[])) DESC, expected_close NULLS LAST, created_at DESC`,
    [req.user.orgId, req.params.id, P.OPEN_STAGE_KEYS]);
  const proposals = rows.map(r => proposalRow(r, funds));
  const w = P.weightedTotal(proposals);
  res.json({
    proposals,
    weighted: { cents: w.cents, amount: toDollars(w.cents), counted: w.counted, unset: w.unset, openCount: w.openCount,
                sentence: P.weightedSentence(w, money.formatCentsPlain) },
    stages: P.PROPOSAL_STAGES, probabilities: P.PROBABILITIES, declineReasons: P.DECLINE_REASONS,
    // The profile's own form needs the pickers too, or it can only ever offer
    // "no fund" and "the relationship owner" — found by the walk.
    funds: [...funds.entries()].map(([id, name]) => ({ id, name })),
    officers: (await query("SELECT id, name FROM users WHERE org_id=? ORDER BY name", [req.user.orgId]).catch(() => []))
      .map(o => ({ id: o.id, name: o.name })),
  });
}));

// POST /donors/:id/proposals — one ask. Team, because the whole major-gifts
// layer is (the BUILD-19/BUILD-20 split; a Core org sees the panel behind glass).
app.post("/donors/:id/proposals", requireAuth, requireCrm, checkWriteAccess, wrap(async (req, res) => {
  const P = await proposalMod();
  const orgId = req.user.orgId;
  const [donor] = await query("SELECT id, name, assigned_to, assigned_to_name FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL",
    [req.params.id, orgId]);
  if (!donor) return res.status(404).json({ error: "Donor not found" });

  // The money seam, never Number(): "$25,000.00" is how a person writes it.
  let askCents;
  try { askCents = parseMoneyOrThrow(req.body.askAmount !== undefined ? req.body.askAmount : req.body.targetAmount, "askAmount"); }
  catch (e) { return res.status(400).json({ error: e.message, code: e.code }); }

  const stage = String(req.body.stage || "identified").toLowerCase();
  const v = P.validateProposal({
    purpose: req.body.purpose !== undefined ? req.body.purpose : req.body.name,
    askCents, expectedClose: req.body.expectedClose, stage,
    probability: req.body.probability, declineReason: req.body.declineReason,
    declinedOn: req.body.declinedOn,
  }, { mode: "create" });
  if (!v.ok) return res.status(400).json({ error: v.errors[0].message, code: "invalid_proposal", errors: v.errors });

  const fund = await checkProposalFund(orgId, req.body.fundId || null);
  if (!fund.ok) return res.status(404).json({ error: "Fund not found" });

  // Officer = the relationship owner (BUILD-30: assignment IS the portfolio),
  // falling back to whoever is typing. An officer id a caller names must belong
  // to this org.
  let officerId = donor.assigned_to, officerName = donor.assigned_to_name;
  if (req.body.officerId) {
    const { ok, user: u } = await OU.orgUser(orgId, req.body.officerId);
    if (!ok) return OU.refuse(res, "officerId");
    officerId = u.id; officerName = u.name;
  }
  if (!officerId) { officerId = req.user.userId; officerName = (await query("SELECT name FROM users WHERE id=?", [req.user.userId]))[0]?.name || ""; }

  if (P.isOpenStage(stage)) {
    const clash = await openProposalConflict(orgId, donor.id, fund.fundId, null);
    if (clash) return res.status(409).json(clash);
  }

  const id = "opp_" + uuid().slice(0, 8);
  const status = P.statusForStage(stage);
  const prob = P.normalizeProbability(req.body.probability);
  // ONE statement, and the WHERE NOT EXISTS is the race guarantee: two officers
  // saving the same ask at the same second cannot both land. The unique index
  // would catch it too where it exists, but it does not exist on every org
  // (db.js says why), so the rule lives here.
  const ins = await query(
    `INSERT INTO opportunities
       (id,org_id,donor_id,name,target_amount,status,proposal_stage,probability,fund_id,notes,
        officer_id,officer_name,expected_close,created_by,created_by_name,updated_at)
     SELECT ?::text,?::text,?::text,?::text,?::numeric,?::text,?::text,?::integer,?::text,?::text,
            ?::text,?::text,?::date,?::text,?::text,NOW()
      WHERE NOT EXISTS (
        SELECT 1 FROM opportunities x WHERE x.org_id=?::text AND x.donor_id=?::text
          AND COALESCE(x.fund_id,'') = ?::text AND x.proposal_stage = ANY(?::text[]))
     RETURNING id`,
    [id, orgId, donor.id, P.sanitizePurpose(req.body.purpose !== undefined ? req.body.purpose : req.body.name),
     toDollars(askCents), status, stage, prob == null ? null : prob, fund.fundId,
     P.sanitizeNotes(req.body.notes), officerId, officerName || "", req.body.expectedClose,
     actor(req).id, actor(req).name,
     orgId, donor.id, fund.fundId || "", P.isOpenStage(stage) ? P.OPEN_STAGE_KEYS : []]);
  if (!ins.length) {
    const clash = await openProposalConflict(orgId, donor.id, fund.fundId, null);
    return res.status(409).json(clash || { code: "proposal_already_open", error: "There is already an open proposal for that fund." });
  }
  await logProposalLine(orgId, donor.id, req, `Proposal opened: ${P.sanitizePurpose(req.body.purpose !== undefined ? req.body.purpose : req.body.name)} — ${money.formatCentsPlain(askCents)}, ${P.stageLabel(stage)}`);
  const funds = await orgFundNames(orgId);
  const [row] = await query("SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE id=?", [id]);
  res.status(201).json(proposalRow(row, funds));
}));

// Every stage change is a line on the person's timeline, because "when did we
// ask, and what happened" has to be answerable from the record and not from
// somebody's memory of a screen.
async function logProposalLine(orgId, donorId, req, note) {
  // THE ORG'S CALENDAR, NOT THE PROCESS'S. `new Date().toISOString().slice(0,10)`
  // is a UTC day, so a proposal moved at 8pm Eastern would be stamped tomorrow
  // — and this row is what "when did we ask" reads off. Found by
  // tests/date-seam.test.js §5, which is what that scan is for.
  const org = await orgTz(orgId);
  await run(
    `INSERT INTO interactions (id,org_id,donor_id,type,date,note,created_by,logged_by_name)
     VALUES (?,?,?,'proposal',?,?,?,?)`,
    ["int_" + uuid().slice(0, 10), orgId, donorId, orgToday(org), note,   // ORG_TZ_SEAM_OK
     actor(req).id, actor(req).name]).catch(e => console.error("[proposal] timeline:", e.message));
}

// PUT /proposals/:id — move it, edit it, or close it.
//
// THE THREE THINGS THIS ROUTE IS FOR:
//   · Committed writes a PLEDGE or a GIFT, never both. Whichever it writes is
//     linked on the row so the money is traceable to the ask, and the other
//     column stays null — a commitment counted twice is the BUILD-98 rule
//     ("a gift is counted once") wearing a different hat.
//   · Declined stores a reason from the list and the date, and does NOT reopen
//     silently: moving it back to an open stage needs `acknowledgeReopen`.
//   · `status` is never sent by a caller. It is derived from the stage, once,
//     by statusForStage — so the twenty BUILD-15/17/85/86 reads that filter on
//     it cannot disagree with what the screen shows.
app.put("/proposals/:id", requireAuth, requireCrm, checkWriteAccess, wrap(async (req, res) => {
  const P = await proposalMod();
  const orgId = req.user.orgId;
  const [existing] = await query("SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!existing) return res.status(404).json({ error: "Proposal not found" });
  // FIX-14 Part 2b: the ask's officer, whoever opened it, or an admin.
  if (existing.officer_id !== req.user.userId && !(await mayEditLogged(req, existing))) return res.status(403).json(NOT_YOURS);

  const patch = {}, sets = [], params = [];
  const put = (col, val) => { sets.push(`${col}=?`); params.push(val); };

  if (req.body.purpose !== undefined) { patch.purpose = req.body.purpose; }
  if (req.body.askAmount !== undefined || req.body.targetAmount !== undefined) {
    try { patch.askCents = parseMoneyOrThrow(req.body.askAmount !== undefined ? req.body.askAmount : req.body.targetAmount, "askAmount"); }
    catch (e) { return res.status(400).json({ error: e.message, code: e.code }); }
  }
  if (req.body.expectedClose !== undefined) patch.expectedClose = req.body.expectedClose;
  if (req.body.probability !== undefined) patch.probability = req.body.probability;
  if (req.body.stage !== undefined) patch.stage = String(req.body.stage || "").toLowerCase();
  if (req.body.declineReason !== undefined) patch.declineReason = req.body.declineReason;
  if (req.body.declinedOn !== undefined) patch.declinedOn = req.body.declinedOn;
  if (req.body.commitKind !== undefined) patch.commitKind = req.body.commitKind;
  if (Object.keys(patch).length === 0 && req.body.notes === undefined && req.body.fundId === undefined
      && req.body.officerId === undefined) {
    return res.status(400).json({ error: "Nothing to update" });
  }

  const v = P.validateProposal(patch, { mode: "patch" });
  if (!v.ok) return res.status(400).json({ error: v.errors[0].message, code: "invalid_proposal", errors: v.errors });

  const toStage = patch.stage || existing.proposal_stage;
  const reopen = P.declineReopenRefusal(existing.proposal_stage, toStage, { acknowledged: req.body.acknowledgeReopen === true });
  if (reopen) return res.status(409).json({ code: reopen.code, error: reopen.message });

  let fundId = existing.fund_id;
  if (req.body.fundId !== undefined) {
    const f = await checkProposalFund(orgId, req.body.fundId || null);
    if (!f.ok) return res.status(404).json({ error: "Fund not found" });
    fundId = f.fundId;
  }
  // Moving INTO an open stage, or onto a different fund while open, re-runs the
  // one-open-per-fund rule. Staying put does not — that would refuse a row
  // because of itself.
  if (P.isOpenStage(toStage)) {
    const clash = await openProposalConflict(orgId, existing.donor_id, fundId, existing.id);
    if (clash) return res.status(409).json(clash);
  }

  if (patch.purpose !== undefined) put("name", P.sanitizePurpose(patch.purpose));
  if (patch.askCents !== undefined) put("target_amount", toDollars(patch.askCents));
  if (patch.expectedClose !== undefined) put("expected_close", patch.expectedClose);
  if (patch.probability !== undefined) put("probability", P.normalizeProbability(patch.probability));
  if (req.body.notes !== undefined) put("notes", P.sanitizeNotes(req.body.notes));
  if (req.body.fundId !== undefined) put("fund_id", fundId);
  if (req.body.officerId !== undefined) {
    const { ok, user: u } = await OU.orgUser(orgId, req.body.officerId);
    if (!ok || !u) return OU.refuse(res, "officerId");
    put("officer_id", u.id); put("officer_name", u.name);
  }

  let wrote = null;
  if (patch.stage !== undefined && patch.stage !== existing.proposal_stage) {
    put("proposal_stage", patch.stage);
    put("status", P.statusForStage(patch.stage));          // DERIVED, never sent
    const askCents = patch.askCents !== undefined ? patch.askCents : (toCents(existing.target_amount) || 0);

    if (patch.stage === "declined") {
      put("decline_reason", req.body.declineReason);
      // The date a decline is RECORDED is the org's civil today, never UTC's —
      // a no at 8pm Eastern is today's no, and this date is on the record for
      // good (reopening keeps it).
      put("declined_on", req.body.declinedOn || orgToday(await orgTz(orgId)));   // ORG_TZ_SEAM_OK
      sets.push("closed_at=NOW()");
      put("gift_id", null); put("pledge_id", null); put("commit_kind", null);
    } else if (patch.stage === "committed" || patch.stage === "stewarding") {
      // EXACTLY ONE of the two doors, and the caller says which. A commitment
      // with no door named is a pledge: "they said yes" without money in hand
      // is a promise, which is what a pledge is for.
      const kind = P.COMMIT_KINDS.includes(String(req.body.commitKind)) ? String(req.body.commitKind) : P.COMMIT_PLEDGE;
      const already = existing.pledge_id || existing.gift_id;
      if (!already) {
        if (kind === P.COMMIT_GIFT) {
          if (!req.body.giftId) return res.status(400).json({ error: "Name the gift this proposal closed with, or record it as a pledge.", code: "gift_required" });
          const [g] = await query("SELECT id, amount FROM gifts WHERE id=? AND org_id=?", [req.body.giftId, orgId]);
          if (!g) return res.status(404).json({ error: "Gift not found" });
          put("gift_id", g.id); put("gift_amount", g.amount); put("pledge_id", null);
          put("commit_kind", P.COMMIT_GIFT);
          wrote = { kind: P.COMMIT_GIFT, id: g.id };
        } else {
          const committedCents = req.body.committedAmount !== undefined
            ? (() => { try { return parseMoneyOrThrow(req.body.committedAmount, "committedAmount"); } catch { return null; } })()
            : askCents;
          if (!(committedCents > 0)) return res.status(400).json({ error: "A positive committed amount is required." });
          const due = req.body.pledgeDueDate || existing.expected_close_civil || orgToday(await orgTz(orgId));   // ORG_TZ_SEAM_OK
          const pid = "pl_" + uuid().slice(0, 8);
          await run(
            `INSERT INTO pledges (id,org_id,donor_id,amount,due_date,status,notes,created_by,created_by_name)
             VALUES (?,?,?,?,?,'open',?,?,?)`,
            [pid, orgId, existing.donor_id, toDollars(committedCents), String(due).slice(0, 10),
             `Committed from the proposal: ${existing.name || "Ask"}`, actor(req).id, actor(req).name]);
          // THE ONE SCHEDULE WRITER (BUILD-88b). A frequency and a count give a
          // real schedule; neither given leaves one instalment for the whole
          // commitment, so the existing rule in recordGift applies her cheque to
          // it from any door, to the cent.
          await writePledgeInstallments(orgId, pid, {
            amountCents: committedCents, schedule: req.body.installments,
            frequency: req.body.frequency, count: req.body.installmentCount,
            firstDue: String(due).slice(0, 10),
          }).catch(e => console.error("[proposal] instalments:", e.message));
          const [n] = await query("SELECT COUNT(*)::int AS c FROM pledge_installments WHERE pledge_id=?", [pid]);
          if (!n.c) await run(`INSERT INTO pledge_installments (id,org_id,pledge_id,seq,due_date,amount) VALUES (?,?,?,1,?,?)`,
            ["pli_" + uuid().slice(0, 10), orgId, pid, String(due).slice(0, 10), toDollars(committedCents)]);
          put("pledge_id", pid); put("commit_kind", P.COMMIT_PLEDGE); put("gift_id", null); put("gift_amount", null);
          wrote = { kind: P.COMMIT_PLEDGE, id: pid };
        }
      }
      sets.push("closed_at=COALESCE(closed_at, NOW())");
    } else {
      // Back to an open stage: the close is undone, and whatever was written
      // stays written. A pledge is a commitment somebody made; reopening the
      // ask does not un-make it, and deleting it here would lose money.
      sets.push("closed_at=NULL");
    }
    await logProposalLine(orgId, existing.donor_id, req,
      `Proposal ${P.stageLabel(existing.proposal_stage)} → ${P.stageLabel(patch.stage)}: ${existing.name || "Ask"}`
      + (patch.stage === "declined" ? ` — ${P.declineReasonLabel(req.body.declineReason)}` : "")
      + (wrote ? ` — recorded as a ${wrote.kind}` : ""));
  }

  sets.push("updated_at=NOW()");
  params.push(req.params.id, orgId);
  await run(`UPDATE opportunities SET ${sets.join(",")} WHERE id=? AND org_id=?`, params);
  const funds = await orgFundNames(orgId);
  let [row] = await query("SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE id=?", [req.params.id]);
  // FIX-14 Part 2b — the table is `opportunities`, which the middleware cannot
  // find from /proposals, so the route hands it the before and after.
  if (auditTrailMod.diffFields(existing, row)) {
    await run("UPDATE opportunities SET edited_at=NOW(), edited_by=?, edited_by_name=? WHERE id=? AND org_id=?",
      [...(await editStamp(req)), req.params.id, orgId]);
    [row] = await query("SELECT *, to_char(expected_close,'YYYY-MM-DD') AS expected_close_civil FROM opportunities WHERE id=?", [req.params.id]);
  }
  if (req.audit) { req.audit.before(existing); req.audit.after(row); }
  res.json({ ...proposalRow(row, funds), wrote });
}));

// FIX-14 Part 2b: to the trash, so Undo can bring the ask back. A pledge or
// gift it closed with is not touched: a commitment is not un-made here.
app.delete("/proposals/:id", requireAuth, wrap(async (req, res) => {
  const [o] = await query("SELECT * FROM opportunities WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!o) return res.status(404).json({ error: "Not found" });
  if (o.officer_id !== req.user.userId && !(await mayEditLogged(req, o))) return res.status(403).json(NOT_YOURS);
  if (req.audit) req.audit.before(o);
  const undoId = await trashRow("opportunities", req.params.id, req);
  if (!undoId) return res.status(404).json({ error: "Not found" });
  res.json({ success: true, deleted: 1, undoId, undoSeconds: UNDO_SECONDS });
}));

// GET /proposals — the Proposals screen under Fundraising. Pipeline by stage in
// dollars and count, filter by officer and fund, sort by expected date.
// EVERY FIGURE CARRIES ITS SENTENCE, including the weighted total, which may
// not be rendered without one (shared/proposalShape.js says why).
app.get("/proposals", requireAuth, wrap(async (req, res) => {
  const P = await proposalMod();
  const orgId = req.user.orgId;
  const where = ["o.org_id = ?", "d.deleted_at IS NULL"], args = [orgId];
  if (!(await OU.orgUser(orgId, req.query.officerId, { allowInactive: true })).ok) return OU.refuse(res, "officerId");
  if (req.query.officerId) { where.push("o.officer_id = ?"); args.push(String(req.query.officerId)); }
  if (req.query.fundId) { where.push("o.fund_id = ?"); args.push(String(req.query.fundId)); }
  if (req.query.stage) {
    const st = String(req.query.stage).split(",").map(s => s.trim().toLowerCase()).filter(s => P.STAGE_KEYS.includes(s));
    if (!st.length) return res.status(400).json({ error: "Unknown stage" });
    where.push("o.proposal_stage = ANY(?::text[])"); args.push(st);
  }
  if (req.query.open === "1") { where.push("o.proposal_stage = ANY(?::text[])"); args.push(P.OPEN_STAGE_KEYS); }
  const rows = await query(
    `SELECT o.*, to_char(o.expected_close,'YYYY-MM-DD') AS expected_close_civil, d.name AS donor_name FROM opportunities o
       JOIN donors d ON d.id = o.donor_id AND d.org_id = o.org_id
      WHERE ${where.join(" AND ")}`, args);
  const funds = await orgFundNames(orgId);
  const all = rows.map(r => proposalRow(r, funds));
  const sort = ["expected", "amount", "stage"].includes(String(req.query.sort)) ? String(req.query.sort) : "expected";
  const proposals = P.sortProposals(all, sort);
  const byStage = P.pipelineByStage(all).map(r => ({
    ...r, amount: toDollars(r.askCents), sentence: P.stageTileSentence(r, money.formatCentsPlain),
  }));
  const w = P.weightedTotal(all);
  const officers = await query(
    `SELECT id, name FROM users WHERE org_id=? ORDER BY name`, [orgId]).catch(() => []);
  res.json({
    proposals, byStage, sort,
    weighted: { cents: w.cents, amount: toDollars(w.cents), counted: w.counted, unset: w.unset,
                openCount: w.openCount, sentence: P.weightedSentence(w, money.formatCentsPlain) },
    openAsk: { cents: w.askCents, amount: toDollars(w.askCents),
               sentence: w.openCount === 0 ? "No open proposals yet."
                 : `${money.formatCentsPlain(w.askCents)} asked for across ${w.openCount} open ${w.openCount === 1 ? "proposal" : "proposals"} — the ask amounts, not what anybody expects to land.` },
    stages: P.PROPOSAL_STAGES, probabilities: P.PROBABILITIES, declineReasons: P.DECLINE_REASONS,
    funds: [...funds.entries()].map(([id, name]) => ({ id, name })),
    officers: officers.map(o => ({ id: o.id, name: o.name })),
  });
}));

// ── BUILD-99 (major gifts) Part 2 — PORTFOLIOS ─────────────────────────────
// `portfolioMembership` above is STILL the one definition of who is in a
// portfolio (BUILD-30, and it cost a build to settle). Nothing here forks it.
// What is new is what she puts AROUND that list: the order she reads it in, the
// target and count cap she typed, and who assigned each person to her.
async function portfolioMod() { return import("../shared/portfolioShape.js"); }

// The org's own word for "major prospect", in cents. A threshold Steward chose
// would be a claim about what a big gift is at an organisation it knows nothing
// about — so the DEFAULT is $1,000 and the answer is the org's.
async function majorProspectCents(orgId) {
  const [o] = await query("SELECT major_prospect_cents FROM orgs WHERE id=?", [orgId]);
  const v = o && o.major_prospect_cents != null ? Number(o.major_prospect_cents) : 100000;
  return Number.isFinite(v) && v > 0 ? Math.round(v) : 100000;
}

// The officer whose portfolio is being read, resolved against THIS org. A
// non-admin may only read their own (the BUILD-31 rule: cross-officer visibility
// is the oversight Team sells, and it is admin-only) — and they are DOWNGRADED
// to their own rather than refused, which is the precedent that route set.
async function resolvePortfolioOfficer(req, wanted) {
  const isAdmin = req.user.role === "admin";
  const want = String(wanted || "").trim();
  const id = (!isAdmin || !want || want === "me") ? req.user.userId : want;
  const [u] = await query("SELECT id, name FROM users WHERE id=? AND org_id=?", [id, req.user.orgId]);
  if (!u) return null;
  return { id: u.id, name: u.name, downgraded: !isAdmin && want && want !== req.user.userId };
}

// ROUTE ORDER IS PART OF THE CONTRACT: this is declared BEFORE
// `/portfolio/:officerId` or Express matches "unassigned-prospects" as an
// officer id and answers 404 for a screen that is not asking about an officer
// at all. (`/portfolio/officers` sits further up the file for the same reason.)
// GET /portfolio/unassigned-prospects — lifetime over the ORG's threshold, no
// owner. This is the list to assign FROM, which is the only reason it exists.
app.get("/portfolio/unassigned-prospects", requireAuth, wrap(async (req, res) => {
  const PF = await portfolioMod();
  const orgId = req.user.orgId;
  const thresholdCents = await majorProspectCents(orgId);
  const limit = Math.min(Number(req.query.limit) || 50, 200);
  const rows = await query(
    `SELECT id, name, email, kind, total_giving, gift_count, last_gift_date, stage, suggested_stage
       FROM donors
      WHERE org_id=? AND deleted_at IS NULL AND assigned_to IS NULL
        AND pending_assignee_invite_id IS NULL
        AND is_sample IS NOT TRUE AND COALESCE(deceased,false) = false
        AND round(COALESCE(total_giving,0)::numeric * 100) >= ?
      ORDER BY total_giving DESC NULLS LAST, id
      LIMIT ?`, [orgId, thresholdCents, limit]);
  const [c] = await query(
    `SELECT COUNT(*)::int AS n FROM donors
      WHERE org_id=? AND deleted_at IS NULL AND assigned_to IS NULL
        AND pending_assignee_invite_id IS NULL
        AND is_sample IS NOT TRUE AND COALESCE(deceased,false) = false
        AND round(COALESCE(total_giving,0)::numeric * 100) >= ?`, [orgId, thresholdCents]);
  res.json({
    thresholdCents, thresholdAmount: toDollars(thresholdCents),
    count: c.n, shown: rows.length,
    sentence: PF.unassignedSentence({ count: c.n, thresholdCents }, money.formatCentsPlain),
    prospects: rows.map(r => ({
      donorId: r.id, name: r.name, email: r.email, kind: r.kind || "person",
      lifetime: toDollars(toCents(r.total_giving) || 0), giftCount: Number(r.gift_count) || 0,
      lastGiftDate: r.last_gift_date || null, stage: r.stage || r.suggested_stage || null,
    })),
  });
}));

// GET /portfolio/:officerId — her people, in the order the brief asks for.
// ONE batch of reads (the BUILD-54 §1 pattern), never a query per person.
app.get("/portfolio/:officerId", requireAuth, wrap(async (req, res) => {
  const PF = await portfolioMod();
  const P = await proposalMod();
  const orgId = req.user.orgId;
  const officer = await resolvePortfolioOfficer(req, req.params.officerId);
  if (!officer) return res.status(404).json({ error: "Officer not found" });

  const [org] = await query("SELECT * FROM orgs WHERE id=?", [orgId]);
  const fy = orgPeriodBounds(org, "fiscal_year", 0);
  const fyYear = Number(String(fy.key).replace("fy:", ""));
  const today = orgToday(org);

  // THE MEMBERSHIP IS THE SHARED ONE. Read it, then decorate it.
  const m = portfolioMembership({ orgId, userId: officer.id, scope: "mine", assignedTo: officer.id, alias: "d" });
  const people = await query(
    `SELECT d.id, d.name, d.email, d.kind, d.stage, d.suggested_stage, d.total_giving,
            d.last_gift_date, d.last_gift_amount, d.assigned_by_name, d.assigned_at
       FROM donors d WHERE ${m.where} ORDER BY d.id`, m.params);
  const ids = people.map(p => p.id);

  const openAsk = new Map(), lastConv = new Map(), nextStep = new Map();
  if (ids.length) {
    for (const r of await query(
      `SELECT donor_id, COALESCE(SUM(target_amount),0) AS amt, COUNT(*)::int AS n
         FROM opportunities WHERE org_id=? AND donor_id = ANY(?) AND proposal_stage = ANY(?::text[])
        GROUP BY donor_id`, [orgId, ids, P.OPEN_STAGE_KEYS]))
      openAsk.set(r.donor_id, { cents: toCents(r.amt) || 0, count: r.n });
    // The LAST LOGGED CONVERSATION, which is a fact on the interactions table —
    // one row per donor via DISTINCT ON, not a correlated subquery per person.
    for (const r of await query(
      `SELECT DISTINCT ON (donor_id) donor_id, type, date, note, logged_by_name
         FROM interactions WHERE org_id=? AND donor_id = ANY(?)
          AND type = ANY(ARRAY['call','meeting','email','ask','note','stewardship','gift','event'])
        ORDER BY donor_id, date DESC, created_at DESC`, [orgId, ids]))
      lastConv.set(r.donor_id, { type: r.type, date: r.date, note: (r.note || "").slice(0, 220), by: r.logged_by_name || "" });
    // The NEXT STEP comes from the Thread (BUILD-81) — the one open one per
    // donor, which the partial unique index makes true by construction.
    for (const r of await query(
      `SELECT donor_id, next_step_label, next_step_type, due_date, due_time
         FROM threads WHERE org_id=? AND donor_id = ANY(?) AND closed_at IS NULL`, [orgId, ids]))
      nextStep.set(r.donor_id, { label: r.next_step_label, type: r.next_step_type, due: r.due_date, time: r.due_time });
  }

  const rows = people.map(p => {
    const lc = lastConv.get(p.id) || null;
    const days = lc && /^\d{4}-\d{2}-\d{2}$/.test(String(lc.date))
      ? Math.max(0, orgTime.daysBetween(String(lc.date), today)) : null;
    const ask = openAsk.get(p.id) || { cents: 0, count: 0 };
    return {
      donorId: p.id, name: p.name, email: p.email, kind: p.kind || "person",
      stage: p.stage || p.suggested_stage || null, placed: !!p.stage,
      lifetime: toDollars(toCents(p.total_giving) || 0),
      lifetimeCents: toCents(p.total_giving) || 0,
      openAskCents: ask.cents, openAskAmount: toDollars(ask.cents), openProposals: ask.count,
      daysSinceContact: days,
      contactPhrase: PF.contactPhrase(days), quiet: PF.isQuiet(days),
      lastConversation: lc, nextStep: nextStep.get(p.id) || null,
      assignedByName: p.assigned_by_name || null, assignedAt: p.assigned_at || null,
    };
  });
  const ranked = PF.rankPortfolio(rows);

  // Committed THIS FISCAL YEAR, against the target she typed. Committed, not
  // asked — a target is about money that landed.
  const [won] = await query(
    `SELECT COALESCE(SUM(COALESCE(gift_amount, target_amount)),0) AS amt, COUNT(*)::int AS n
       FROM opportunities WHERE org_id=? AND officer_id=? AND status='won'
        AND closed_at >= ?::date AND closed_at < (?::date + 1)`, [orgId, officer.id, fy.start, fy.end]);
  const [t] = await query("SELECT target_amount, count_cap FROM portfolio_targets WHERE org_id=? AND user_id=? AND fiscal_year=?",
    [orgId, officer.id, fyYear]);
  const prog = PF.targetProgress({
    targetCents: t && t.target_amount != null ? toCents(t.target_amount) : null,
    committedCents: toCents(won.amt) || 0,
    fiscalLabel: `FY ${fyYear}–${String(fyYear + 1).slice(2)}`,
  });
  const cap = PF.capState({ capCount: t ? t.count_cap : null, actualCount: ranked.length });

  res.json({
    officer: { id: officer.id, name: officer.name }, downgraded: !!officer.downgraded,
    fiscalYear: fyYear, fiscalLabel: prog.fiscalLabel,
    people: ranked,
    count: { value: ranked.length, sentence: PF.portfolioCountSentence(ranked.length, officer.name) },
    target: { ...prog, amount: prog.targetCents == null ? null : toDollars(prog.targetCents),
              committedAmount: toDollars(prog.committedCents), committedCount: won.n,
              sentence: PF.targetSentence(prog, money.formatCentsPlain) },
    cap: { ...cap, sentence: PF.capSentence(cap) },
  });
}));

// PUT /portfolio/:officerId/target — the target and the cap, both hers, both
// optional. Sending null CLEARS one, which is how "I have not decided" is said.
app.put("/portfolio/:officerId/target", requireAuth, requireCrm, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const isAdmin = req.user.role === "admin";
  const want = String(req.params.officerId || "").trim();
  // A staff member may set their OWN target and nobody else's; an admin may set
  // anyone's in this org. REFUSED rather than downgraded, because a WRITE
  // silently landing on a different row is worse than an error — and the first
  // cut of this collapsed `want` into the caller's own id BEFORE the check, so
  // the refusal could never fire and a staff member's attempt quietly wrote to
  // her own target instead. Found by this part's own suite.
  if (!isAdmin && want && want !== "me" && want !== req.user.userId) {
    return res.status(403).json({ error: "You can set your own target." });
  }
  const id = (!isAdmin || !want || want === "me") ? req.user.userId : want;
  const [u] = await query("SELECT id, name FROM users WHERE id=? AND org_id=?", [id, orgId]);
  if (!u) return res.status(404).json({ error: "Officer not found" });

  const [org] = await query("SELECT * FROM orgs WHERE id=?", [orgId]);
  const fyYear = req.body.fiscalYear != null
    ? Number(req.body.fiscalYear)
    : Number(String(orgPeriodBounds(org, "fiscal_year", 0).key).replace("fy:", ""));
  if (!Number.isInteger(fyYear) || fyYear < 2000 || fyYear > 2100) return res.status(400).json({ error: "A fiscal year is required." });

  let targetCents = null;
  if (req.body.target !== undefined && req.body.target !== null && String(req.body.target).trim() !== "") {
    try { targetCents = parseMoneyOrThrow(req.body.target, "target"); }
    catch (e) { return res.status(400).json({ error: e.message, code: e.code }); }
    if (targetCents <= 0) return res.status(400).json({ error: "A target has to be a positive amount, or blank." });
  }
  let cap = null;
  if (req.body.countCap !== undefined && req.body.countCap !== null && String(req.body.countCap).trim() !== "") {
    cap = Number(req.body.countCap);
    if (!Number.isInteger(cap) || cap <= 0) return res.status(400).json({ error: "A count cap has to be a whole number, or blank." });
  }

  await run(
    `INSERT INTO portfolio_targets (id,org_id,user_id,fiscal_year,target_amount,count_cap,created_by,created_by_name,updated_at)
     VALUES (?,?,?,?,?,?,?,?,NOW())
     ON CONFLICT (org_id, user_id, fiscal_year) DO UPDATE
       SET target_amount=EXCLUDED.target_amount, count_cap=EXCLUDED.count_cap, updated_at=NOW()`,
    ["pt_" + uuid().slice(0, 10), orgId, id, fyYear,
     targetCents == null ? null : toDollars(targetCents), cap, actor(req).id, actor(req).name]);
  const [row] = await query("SELECT * FROM portfolio_targets WHERE org_id=? AND user_id=? AND fiscal_year=?", [orgId, id, fyYear]);
  res.json({
    officer: { id: u.id, name: u.name }, fiscalYear: fyYear,
    target: row.target_amount == null ? null : toDollars(toCents(row.target_amount) || 0),
    countCap: row.count_cap == null ? null : Number(row.count_cap),
  });
}));

// PUT /orgs/major-prospect-threshold — the org's own number, in its own money.
app.put("/orgs/major-prospect-threshold", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  let cents;
  try { cents = parseMoneyOrThrow(req.body.threshold, "threshold"); }
  catch (e) { return res.status(400).json({ error: e.message, code: e.code }); }
  if (!(cents > 0)) return res.status(400).json({ error: "A positive amount is required." });
  await run("UPDATE orgs SET major_prospect_cents=? WHERE id=?", [cents, req.user.orgId]);
  res.json({ thresholdCents: cents, thresholdAmount: toDollars(cents) });
}));

// ── BUILD-99 (major gifts) Part 3 — CULTIVATION PLANS ──────────────────────
// A plan is a sequence of BUILD-81 threads for one person, authored by the
// officer. It does NOT fork the Thread engine: each step, when its turn comes,
// is a thread, opened through `openThreadTx` like every other, and it closes
// through the paths that already exist. shared/planShape.js holds the rules.
//
// NOTHING IN A PLAN SENDS ANYTHING. There is no email field and no schedule that
// fires; every step is a human action that ends in a logged line. That is what
// keeps a four-step cultivation of a major donor from being a sequence.
async function planMod() { return import("../shared/planShape.js"); }

// THE CHAINING, IN ONE FUNCTION, CALLED FROM EVERY PLACE A THREAD CLOSES.
//
// It is idempotent and it SELF-HEALS, which is the property that matters here
// because production runs with background ticks off (NEEDS-JONATHAN §1) and
// there is no sweep to fall back on. If the next step cannot open — because the
// donor already has an open thread, which the conversation route legitimately
// creates from the officer's own next step — the step stays PENDING and the next
// close calls this again. So a plan can never be stalled by a race; it is only
// ever waiting, and `planSentence` says so out loud.
// ── THREAD-2a · THE JOURNEY ENGINE ────────────────────────────────────────
//
// ONE function starts a journey, and every trigger calls it. There is no
// second place that decides who goes into what, which is why "a donor is in
// at most one journey" can be true rather than aspirational.
//
// It uses the PLAN path underneath — the same `cultivation_plans` row, the
// same partial unique index, the same `advanceCultivationPlan` — so a journey
// and a plan an officer applied by hand are the same object, and every screen
// that already reads plans reads journeys for free.
//
// IT NEVER SENDS ANYTHING. It writes a plan and its pending steps. Each step
// becomes a thread when its turn comes, and a thread closes when a person
// logs that they did something. tests/thread2a-no-send.test.js is the guard.
async function journeyMod() { return import("../shared/journeyShape.js"); }

// The actor on every write this engine makes. It is not a user: nobody
// pressed anything, a rule fired, and the record has to say so rather than
// attributing it to whoever happened to be signed in.
const JOURNEY_ACTOR = { id: "system:journey", name: "Steward (journey)" };

async function maybeStartJourney(orgId, donorId, triggerKey, opts = {}) {
  const J = await journeyMod();
  const PL = await planMod();
  if (!J.TRIGGER_KEYS.includes(triggerKey)) return { started: false, reason: "unknown_trigger" };

  const [donor] = await query(
    `SELECT id, name, assigned_to, assigned_to_name FROM donors
      WHERE id=? AND org_id=? AND deleted_at IS NULL`, [donorId, orgId]);
  if (!donor) return { started: false, reason: "donor_not_found" };

  // A PERSON CHOOSING beats a rule picking. `forceJourneyId` is the by-hand
  // path (and the "apply to everyone who qualifies" button): it names the
  // journey, so `journey_enabled` is not consulted — arming a journey is
  // about whether it fires ON ITS OWN, and somebody pressing a button has
  // already answered that question for this donor.
  const rows = opts.forceJourneyId
    ? await query(`SELECT * FROM cultivation_templates WHERE id=? AND org_id=? AND archived_at IS NULL`,
        [opts.forceJourneyId, orgId])
    : await query(
        `SELECT * FROM cultivation_templates
          WHERE org_id=? AND trigger_key=? AND journey_enabled=true AND archived_at IS NULL`,
        [orgId, triggerKey]);
  if (!rows.length) return { started: false, reason: opts.forceJourneyId ? "journey_not_found" : "no_journey_for_trigger" };

  // `gift_over` is the one trigger that NEEDS a number, and the number is the
  // ORG's. PARITY-1 Part D: every gift trigger may carry one as a floor, and a
  // fund or a campaign; "joins a group" names its group. A journey whose
  // narrowing this event does not meet is simply not a candidate.
  const amountCents = Number(opts.amountCents);
  const filtered = rows.filter(t => {
    if (opts.forceJourneyId) return true;      // named by a person, not matched by a rule
    const tf = t.trigger_filters || {};
    const need = Number(t.trigger_amount_cents);
    if (triggerKey === "gift_over" && !(Number.isFinite(need) && need > 0)) return false;
    if (J.isGiftTrigger(triggerKey) && Number.isFinite(need) && need > 0
        && !(Number.isFinite(amountCents) && amountCents >= need)) return false;
    if (tf.fundId && String(tf.fundId) !== String(opts.fundId || "")) return false;
    if (tf.campaignId && String(tf.campaignId) !== String(opts.campaignId || "")) return false;
    if (triggerKey === "joined_group" && String(tf.groupId || "") !== String(opts.groupId || "")) return false;
    // JOURNEYS-3 — an hours journey that watches one milestone fires on that one.
    if (triggerKey === "volunteer_hours" && tf.hours && !(opts.crossed || []).includes(Number(tf.hours))) return false;
    return true;
  });
  if (!filtered.length) return { started: false, reason: "below_threshold" };

  // PARITY-1 Part D · WHO IT IS FOR, AT THE MOMENT IT FIRES. The audience was
  // only ever read by the "who already qualifies" offer; a live trigger
  // started the journey on anybody it touched. A journey narrowed to members
  // now starts only on a member, by either door.
  const audienceOk = [];
  for (const t of filtered) {
    if (opts.forceJourneyId || await donorInAudience(orgId, donor.id, t.audience || {})) audienceOk.push(t);
  }
  if (!audienceOk.length) return { started: false, reason: "outside_audience" };

  // ONCE AND ONLY ONCE PER EVENT. The event a trigger is about (this gift,
  // their first gift ever, joining this group today) is written on the plan,
  // and a unique index holds it: replaying the same event, a retried webhook,
  // or a first gift deleted and entered again cannot enrol them a second time.
  const org0 = await orgTz(orgId);
  const eventKey = opts.forceJourneyId ? null
    : (opts.eventKey || journeyEventKey(triggerKey, opts, opts.today || orgToday(org0)));   // ORG_TZ_SEAM_OK
  let eligible = audienceOk;
  if (eventKey) {
    const done = await query(
      `SELECT template_id FROM cultivation_plans WHERE org_id=? AND donor_id=? AND trigger_event=?`,
      [orgId, donor.id, eventKey]);
    const seen = new Set(done.map(r => r.template_id));
    eligible = audienceOk.filter(t => !seen.has(t.id));
    if (!eligible.length) return { started: false, reason: "already_enrolled_for_event", eventKey };
  }

  // JOURNEYS-3 · EVERY JOURNEY THIS EVENT STARTS, HIGHEST FIRST. A person may
  // be in several journeys at once; their steps are spaced a week apart by
  // spaceDonorTouches. Two journeys marked "only one of these at a time" keep
  // the old ranking rule between them. A person pressing a button names one.
  const order = eligible.slice().sort((x, y) => (J.winningJourney([x, y]) === x ? -1 : 1));
  let first = null;
  const also = [];
  for (const t of order) {
    const r = await startOneJourney(orgId, donor, t, triggerKey, eventKey, opts);
    if (!first) first = r;
    else if (r.started) also.push(r);
    if (opts.forceJourneyId) break;
  }
  if (first && !first.started && also.length) return { ...also[0], also: also.slice(1) };
  return also.length ? { ...first, also } : first;
}

// One journey, one person. Refuses only for a reason it can name: already in
// this journey, in a higher exclusive one, or (when the person asked to leave
// people where they are) in any other journey.
async function startOneJourney(orgId, donor, winner, triggerKey, eventKey, opts = {}) {
  const J = await journeyMod();
  const PL = await planMod();
  const v = J.validateJourney({
    name: winner.name, trigger: winner.trigger_key, priority: winner.priority,
    amountCents: winner.trigger_amount_cents, steps: winner.steps,
    triggerFilters: winner.trigger_filters || {},
  });
  if (!v.ok) {
    console.error(`[journey] ${winner.id} is armed but invalid: ${v.errors[0].message}`);
    return { started: false, reason: "invalid_journey", detail: v.errors[0].message };
  }

  const org = await orgTz(orgId);
  const today = opts.today || orgToday(org);                    // ORG_TZ_SEAM_OK
  const steps = PL.planFromTemplate({ steps: v.steps, today }, orgTime.addDays);

  const current = await query(
    `SELECT p.id, p.template_id, p.template_name, p.priority, COALESCE(t.exclusive, false) AS exclusive
       FROM cultivation_plans p LEFT JOIN cultivation_templates t ON t.id = p.template_id AND t.org_id = p.org_id
      WHERE p.org_id=? AND p.donor_id=? AND p.status='active'`, [orgId, donor.id]);
  const same = current.find(c => c.template_id === winner.id);
  if (same) return { started: false, reason: "already_in_this_journey", currentPlanId: same.id, currentName: same.template_name };
  if (opts.joinOthers === false && current.length) {
    return { started: false, reason: "in_another_journey", currentPlanId: current[0].id, currentName: current[0].template_name };
  }

  // ── ONLY ONE OF THESE AT A TIME, AND THE REASON IS WRITTEN DOWN ────────
  // Between exclusive journeys, a person already working through one is left
  // alone UNLESS the new one outranks it. Equal priority does not replace.
  let replacedId = null, reason = null, replacedStep = null;
  const rival = winner.exclusive ? current.filter(c => c.exclusive)
    .sort((x, y) => Number(y.priority) - Number(x.priority))[0] : null;
  if (rival) {
    if (!J.shouldReplace({ priority: rival.priority }, { priority: v.priority })) {
      return { started: false, reason: "already_in_a_journey", currentPlanId: rival.id,
               currentName: rival.template_name };
    }
    reason = J.replacementReason(rival.template_name, v.name);
    await run(`UPDATE cultivation_plans SET status='abandoned', closed_at=NOW(), replaced_reason=?
                WHERE id=? AND status='active'`, [reason, rival.id]);
    const [openStep] = await query(
      `SELECT id, thread_id FROM cultivation_plan_steps WHERE plan_id=? AND status='open'`, [rival.id]);
    if (openStep) {
      // Its thread is handed on rather than left holding a stopped plan's step.
      await run(`UPDATE cultivation_plan_steps SET status='skipped', closed_at=NOW(),
                   closed_by=?, closed_by_name=?, skip_reason=? WHERE id=?`,
        [JOURNEY_ACTOR.id, JOURNEY_ACTOR.name, reason, openStep.id]);
      replacedStep = openStep;
    }
    replacedId = rival.id;
  }

  const planId = "cp_" + uuid().slice(0, 10);
  let ins;
  try {
    ins = await query(
    `INSERT INTO cultivation_plans (id,org_id,donor_id,template_id,template_name,applied_on,status,
                                    owner_id,owner_name,created_by,created_by_name,
                                    trigger_key,priority,replaced_plan_id,replaced_reason,trigger_event)
     SELECT ?::text,?::text,?::text,?::text,?::text,?::text,'active',?::text,?::text,?::text,?::text,
            ?::text,?::int,?::text,?::text,?::text
      WHERE NOT EXISTS (SELECT 1 FROM cultivation_plans x WHERE x.org_id=?::text AND x.donor_id=?::text
                          AND x.template_id=?::text AND x.status='active')
     RETURNING id`,
    [planId, orgId, donor.id, winner.id, v.name, today,
     donor.assigned_to || null, donor.assigned_to_name || null,
     JOURNEY_ACTOR.id, JOURNEY_ACTOR.name,
     // The trigger RECORDED is the journey's own, so a by-hand apply of a
     // first-gift journey still says what kind of journey it is; `by_hand` is
     // recorded only for a journey that genuinely has that trigger.
     opts.forceJourneyId ? (winner.trigger_key || triggerKey) : triggerKey,
     v.priority, replacedId, reason, eventKey, orgId, donor.id, winner.id]);
  } catch (e) {
    // A unique index: a concurrent fire of the same event, or the same journey, won.
    if (e.code === "23505") return { started: false, reason: "already_enrolled_for_event", eventKey };
    throw e;
  }
  if (!ins.length) return { started: false, reason: "race_lost" };

  for (const s of steps) {
    const src = v.steps[s.seq - 1] || {};
    await run(
      `INSERT INTO cultivation_plan_steps (id,org_id,plan_id,seq,step_type,label,due_date,status,draft_kind,owner_id,owner_name)
       VALUES (?,?,?,?,?,?,?,'pending',?,?,?)`,
      ["cs_" + uuid().slice(0, 10), orgId, planId, s.seq, s.type, s.label, s.dueDate,
       src.draft || null,
       // The owner defaults to the RELATIONSHIP OWNER, which is the donor's
       // assigned officer — the brief's own answer, and the one that makes
       // the Thread owner-scoped without anybody configuring anything.
       src.ownerMode === "specific" ? (src.ownerId || null) : (donor.assigned_to || null),
       src.ownerMode === "specific" ? null : (donor.assigned_to_name || null)]);
  }
  // A replaced exclusive journey's open thread is closed with its reason, so
  // the new journey's first step can take the person's one open thread.
  if (replacedStep && replacedStep.thread_id) {
    await run(`UPDATE threads SET closed_at=NOW(), close_kind='dismissed', close_reason='handled_outside'
                WHERE id=? AND org_id=? AND closed_at IS NULL`, [replacedStep.thread_id, orgId]);
  }

  // The timeline says it, in the same words the screen does.
  const line = reason
    ? reason
    : `Journey started: ${v.name} (${steps.length} ${steps.length === 1 ? "step" : "steps"}).`;
  const lineId = "int_" + uuid().slice(0, 10);
  await run(
    `INSERT INTO interactions (id,org_id,donor_id,type,date,note,created_by,logged_by_name)
     VALUES (?,?,?,'note',?,?,?,?)`,
    [lineId, orgId, donor.id, today, line, JOURNEY_ACTOR.id, JOURNEY_ACTOR.name])
    .then(() => run(`UPDATE cultivation_plans SET start_interaction_id=? WHERE id=?`, [lineId, planId]))
    .catch(e => console.error("[journey] timeline:", e.message));

  // One touch a week across every journey this person is in, then the
  // soonest step takes their one open thread.
  await spaceDonorTouches(orgId, donor.id);
  await advanceCultivationPlan(orgId, donor.id,
    { actorId: JOURNEY_ACTOR.id, actorName: JOURNEY_ACTOR.name, today });

  console.log(`[journey] ${donor.id} → ${v.name} on ${triggerKey}`
    + (replacedId ? ` (replaced ${replacedId})` : ""));
  return { started: true, planId, journeyId: winner.id, name: v.name, trigger: triggerKey,
           steps: steps.length, replacedPlanId: replacedId, reason };
}

// ── JOURNEYS-3 · ONE TOUCH A WEEK ──────────────────────────────────────────
// Every active journey this person is in, spaced by shared/journeyShape.js
// spaceTouches with the org's gap (Journey settings, 7 days by default). A
// moved step keeps the date it had and the journey that moved it, and the
// reason lands on the step and on the timeline.
async function journeyTouchGap(orgId) {
  const [o] = await query(`SELECT journey_touch_gap_days FROM orgs WHERE id=?`, [orgId]);
  return Number(o && o.journey_touch_gap_days) || 7;
}
async function spaceDonorTouches(orgId, donorId) {
  const J = await journeyMod();
  const plans = await query(
    `SELECT id, template_name AS name, priority, applied_on FROM cultivation_plans
      WHERE org_id=? AND donor_id=? AND status='active'`, [orgId, donorId]);
  if (plans.length < 2) return [];
  const steps = await query(
    `SELECT id, plan_id, seq, due_date, status FROM cultivation_plan_steps
      WHERE org_id=? AND plan_id = ANY(?::text[]) AND status IN ('pending','open')`, [orgId, plans.map(p => p.id)]);
  const moves = J.spaceTouches(plans.map(p => ({ id: p.id, name: p.name, priority: p.priority, appliedOn: p.applied_on,
    steps: steps.filter(s => s.plan_id === p.id).map(s => ({ id: s.id, seq: s.seq, dueDate: s.due_date, status: s.status })) })),
    await journeyTouchGap(orgId));
  for (const m of moves) {
    const name = (plans.find(p => p.id === m.planId) || {}).name || "A journey";
    const why = J.movedSentence(m, name);
    const { changes } = await run(
      `UPDATE cultivation_plan_steps SET due_date=?, moved_from=COALESCE(moved_from, ?), moved_reason=?,
              moved_by_plan_id=COALESCE(moved_by_plan_id, ?)
        WHERE id=? AND org_id=? AND status='pending'`, [m.to, m.from, why, m.becausePlanId, m.stepId, orgId]);
    if (changes) {
      await TL.timelineLine({ orgId, donorId, note: why, actorId: JOURNEY_ACTOR.id, actorName: JOURNEY_ACTOR.name,
        key: `journey-moved:${m.stepId}:${m.to}`, metadata: { via: "journey_spacing", step_id: m.stepId, plan_id: m.planId } });
    }
  }
  return moves;
}

// PARITY-1 Part D · the event a trigger is about, as a key written on the
// plan. null means the trigger has no single event to hold it to.
function journeyEventKey(triggerKey, opts = {}, today = "") {
  switch (triggerKey) {
    case "first_gift": return "first_gift";
    case "first_recurring": return "first_recurring";
    case "new_volunteer": return "new_volunteer";
    case "gift_over": case "next_gift": case "lapsed_return": case "membership_payment":
      return opts.giftId ? `gift:${opts.giftId}` : null;
    case "became_member": return opts.membershipId ? `membership:${opts.membershipId}` : `became_member:${today}`;
    case "stage_change": case "became_prospect": return `stage:${opts.toStage || ""}:${today}`;
    case "joined_group": return `group:${opts.groupId || ""}:${today}`;
    case "giving_anniversary": return `anniversary:${String(today).slice(0, 4)}`;
    case "birthday": return `birthday:${String(today).slice(0, 4)}`;   // PARITY-3 6a: once a year
    case "attended_event": return opts.eventId ? `event:${opts.eventId}` : null;
    case "first_event": return "first_event";
    default: return null;
  }
}

// A journey may name a group, a fund or a campaign. Each must be this org's,
// or the save is refused as not found (the tenant rule: never confirm another
// org's id exists).
async function journeyRefsRefused(orgId, v) {
  const tf = v.triggerFilters || {};
  for (const gid of [tf.groupId, (v.audience || {}).groupId].filter(Boolean)) {
    if (!(await GR.groupById(orgId, gid))) return { error: "group_not_found", message: "That group is not one of yours." };
  }
  if (tf.fundId && !(await orgOwns("fin_funds", tf.fundId, orgId))) return { error: "fund_not_found", message: "That fund is not one of yours." };
  if (tf.campaignId && !(await orgOwns("campaigns", tf.campaignId, orgId)))
    return { error: "campaign_not_found", message: "That campaign is not one of yours." };
  // EMAIL-1 — a step's draft that names a template names one of THIS org's.
  for (const st of v.steps || []) {
    const tid = String(st.draft || "").startsWith("template:") ? String(st.draft).slice(9) : null;
    if (tid && !(await emailCompose.templateFor(orgId, tid)))
      return { error: "template_not_found", message: "A step names an email template that is not one of yours." };
  }
  return null;
}
// Switching on a "joins a group" journey on a group by rule: today's members
// are the starting line, so it fires on people who join from now on and not
// on everybody already in it.
async function baselineJourneyGroup(orgId, v) {
  if (v.trigger !== "joined_group" || !(v.triggerFilters || {}).groupId) return;
  const g = await GR.groupById(orgId, v.triggerFilters.groupId);
  if (g && g.kind === "dynamic") await GR.baselineGroup(orgId, g).catch(e => console.error("[journey] group baseline:", e.message));
}

// Is this person inside a journey's audience right now? The same clauses the
// "who already qualifies" offer reads (audienceClauses), plus the group.
async function donorInAudience(orgId, donorId, audience = {}) {
  const a = audienceClauses(audience, "d");
  if (a.sql) {
    const rows = await query(`SELECT 1 FROM donors d WHERE d.id=? AND d.org_id=? AND d.deleted_at IS NULL${a.sql}`,
      [donorId, orgId, ...a.params]);
    if (!rows.length) return false;
  }
  if (audience.groupId) {
    const g = await GR.groupById(orgId, audience.groupId);
    if (!g || !(await GR.isMember(orgId, g, donorId))) return false;
  }
  return true;
}

// JOURNEYS-3 · A PERSON IN SEVERAL JOURNEYS STILL HAS ONE NEXT STEP. Each
// active plan's open step is closed when its thread has closed, a plan with
// nothing left is done, and then the person's SOONEST step across every
// journey holds their one open thread: the next step of each plan is a
// candidate and the earliest due wins (a tie goes to the higher priority).
// When a journey step already holds the thread but another journey's step is
// due sooner, the thread is handed to the sooner one and the other step goes
// back to waiting, so the Thread always shows what is next.
async function advanceCultivationPlan(orgId, donorId, { actorId, actorName, today } = {}) {
  const PL = await planMod();
  const plans = await query(
    `SELECT * FROM cultivation_plans WHERE org_id=? AND donor_id=? AND status='active'
      ORDER BY priority DESC, applied_on, id`, [orgId, donorId]);
  if (!plans.length) return null;
  const all = await query(
    `SELECT * FROM cultivation_plan_steps WHERE org_id=? AND plan_id = ANY(?::text[]) ORDER BY seq`,
    [orgId, plans.map(p => p.id)]);
  const live = [];
  for (const plan of plans) {
    const steps = all.filter(s => s.plan_id === plan.id);
    // A step whose thread has closed is DONE. The thread's own close is the fact;
    // this only reads it back, so the two can never disagree about whether the
    // officer did the thing.
    const open = steps.find(s => s.status === "open");
    if (open && open.thread_id) {
      const [th] = await query("SELECT id, closed_at, close_kind FROM threads WHERE id=? AND org_id=?", [open.thread_id, orgId]);
      if (!th || th.closed_at) {
        await run("UPDATE cultivation_plan_steps SET status='done', closed_at=NOW(), closed_by=?, closed_by_name=? WHERE id=? AND status='open'",
          [actorId || null, actorName || null, open.id]);
        open.status = "done";
      }
    }
    if (steps.some(s => s.status === "open")) { live.push({ plan, steps }); continue; }
    if (PL.nextPendingSeq(steps) == null) {
      // Every step is done or skipped — the plan is finished, and that is a fact
      // about the plan rather than an outcome anybody has to record.
      await run("UPDATE cultivation_plans SET status='done', closed_at=NOW() WHERE id=? AND status='active'", [plan.id]);
      continue;
    }
    live.push({ plan, steps });
  }
  if (!live.length) return plans[0].id;

  // The candidates: each plan's next pending step. The soonest wins.
  const cands = [];
  for (const { plan, steps } of live) {
    if (steps.some(s => s.status === "open")) continue;
    const nextSeq = PL.nextPendingSeq(steps);
    const step = steps.find(s => Number(s.seq) === Number(nextSeq));
    if (step) cands.push({ plan, step });
  }
  if (!cands.length) return live[0].plan.id;   // a journey step already holds the thread
  cands.sort((x, y) => String(x.step.due_date).localeCompare(String(y.step.due_date))
    || Number(y.plan.priority) - Number(x.plan.priority));
  const { plan, step } = cands[0];

  // A journey step holding the thread but due LATER than this one hands it over.
  const holder = live.map(l => ({ plan: l.plan, step: l.steps.find(s => s.status === "open") })).find(h => h.step);
  if (holder && holder.step.thread_id && String(holder.step.due_date) > String(step.due_date)) {
    const { changes } = await run(
      `UPDATE threads SET next_step_type=?, next_step_label=?, due_date=?
        WHERE id=? AND org_id=? AND closed_at IS NULL`,
      [step.step_type, step.label, step.due_date, holder.step.thread_id, orgId]);
    if (changes) {
      await run("UPDATE cultivation_plan_steps SET status='pending', thread_id=NULL WHERE id=? AND status='open'", [holder.step.id]);
      await run("UPDATE cultivation_plan_steps SET status='open', thread_id=? WHERE id=? AND status='pending'", [holder.step.thread_id, step.id]);
      await journeyStepOpened(orgId, donorId, plan, step);
      return plan.id;
    }
  }
  if (holder) return holder.plan.id;

  const opened = await withTransaction(async client => openThreadTx(client, {
    orgId, donorId,
    step: { type: step.step_type, label: step.label, due: step.due_date },
    openedOn: today || step.due_date,
    ownerId: plan.owner_id, ownerName: plan.owner_name,
    actorId: actorId || plan.created_by, actorName: actorName || plan.created_by_name,
  }));
  // `openThreadTx` returns null when the donor already has an open thread (the
  // ON CONFLICT is the arbiter, never a check-then-insert). The step waits.
  if (!opened) return plan.id;
  await run("UPDATE cultivation_plan_steps SET status='open', thread_id=? WHERE id=? AND status='pending'", [opened.id, step.id]);
  await journeyStepOpened(orgId, donorId, plan, step);
  return plan.id;
}

// A step that opens lands in three places: the Thread (its thread), the
// Calendar (calendar.js reads the step and the thread as one item), and the
// person's timeline, one line per step, here. Its template draft, if any, is
// written for review.
async function journeyStepOpened(orgId, donorId, plan, step) {
  await TL.timelineLine({ orgId, donorId, actorId: JOURNEY_ACTOR.id, actorName: JOURNEY_ACTOR.name,
    note: `Journey step: ${step.label}, due ${step.due_date} (${plan.template_name}).`,
    key: `journey-step:${step.id}`, metadata: { via: "journey_step", step_id: step.id, plan_id: plan.id } });
  await journeyTemplateDraft(orgId, donorId, step).catch(e => console.error("[journey] template draft:", e.message));
}

// EMAIL-1 — A STEP THAT NAMES A TEMPLATE GETS ITS WORDS WRITTEN, NOT SENT.
// When the step opens, the template's subject and its text (with this
// person's name and last gift in it) become ONE draft in the review queue
// (milestone_drafts, key `journey-step:<step id>`), remembering the template.
// A person reads it there and presses Send; this function has no send in it,
// and tests/thread2a-no-send.test.js holds the whole journey path to that.
async function journeyTemplateDraft(orgId, donorId, step) {
  const tid = String(step.draft_kind || "").startsWith("template:") ? String(step.draft_kind).slice(9) : null;
  if (!tid) return null;
  const t = await emailCompose.templateFor(orgId, tid);
  if (!t) return null;
  const [donor] = await query("SELECT * FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL", [donorId, orgId]);
  if (!donor) return null;
  const words = await emailCompose.templateTextFor(orgId, t, donor);
  if (!words.body) return null;
  const key = `journey-step:${step.id}`;
  const id = "md_" + uuid().slice(0, 10);
  await run(
    `INSERT INTO milestone_drafts (id,org_id,donor_id,milestone_key,subject,body,status,source,template_id,created_by,created_by_name)
     SELECT ?::text,?::text,?::text,?::text,?::text,?::text,'pending_review','journey',?::text,?::text,?::text
      WHERE NOT EXISTS (SELECT 1 FROM milestone_drafts WHERE org_id=?::text AND milestone_key=?::text)`,
    [id, orgId, donorId, key, words.subject || step.label || t.name, words.body, t.id,
     JOURNEY_ACTOR.id, JOURNEY_ACTOR.name, orgId, key]);
  return id;
}

// GET /cultivation-templates — the plans the organisation keeps.
app.get("/cultivation-templates", requireAuth, wrap(async (req, res) => {
  const PL = await planMod();
  const rows = await query(
    "SELECT * FROM cultivation_templates WHERE org_id=? AND archived_at IS NULL ORDER BY name", [req.user.orgId]);
  res.json({
    templates: rows.map(r => ({
      id: r.id, name: r.name, steps: Array.isArray(r.steps) ? r.steps : [],
      createdByName: r.created_by_name || "",
    })),
    stepTypes: PL.PLAN_STEP_TYPES, maxSteps: PL.MAX_STEPS,
  });
}));

app.post("/cultivation-templates", requireAuth, requireCrm, checkWriteAccess, wrap(async (req, res) => {
  const PL = await planMod();
  const v = PL.validateTemplate({ name: req.body.name, steps: req.body.steps });
  if (!v.ok) return res.status(400).json({ error: v.errors[0].message, code: "invalid_template", errors: v.errors });
  const id = "ct_" + uuid().slice(0, 10);
  await run(
    `INSERT INTO cultivation_templates (id,org_id,name,steps,created_by,created_by_name) VALUES (?,?,?,?,?,?)`,
    [id, req.user.orgId, v.name, JSON.stringify(v.steps), actor(req).id, actor(req).name]);
  const [row] = await query("SELECT * FROM cultivation_templates WHERE id=?", [id]);
  res.status(201).json({ id: row.id, name: row.name, steps: row.steps });
}));

app.put("/cultivation-templates/:id", requireAuth, requireCrm, checkWriteAccess, wrap(async (req, res) => {
  const PL = await planMod();
  const [ex] = await query("SELECT * FROM cultivation_templates WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!ex) return res.status(404).json({ error: "Template not found" });
  const v = PL.validateTemplate({
    name: req.body.name !== undefined ? req.body.name : ex.name,
    steps: req.body.steps !== undefined ? req.body.steps : ex.steps,
  });
  if (!v.ok) return res.status(400).json({ error: v.errors[0].message, code: "invalid_template", errors: v.errors });
  await run("UPDATE cultivation_templates SET name=?, steps=?, updated_at=NOW() WHERE id=? AND org_id=?",
    [v.name, JSON.stringify(v.steps), req.params.id, req.user.orgId]);
  // EDITING A TEMPLATE DOES NOT REWRITE AN APPLIED PLAN. A plan copied its name
  // and its steps at apply time precisely so that what an officer is working
  // through cannot change under her.
  res.json({ id: req.params.id, name: v.name, steps: v.steps });
}));

app.delete("/cultivation-templates/:id", requireAuth, wrap(async (req, res) => {
  // ARCHIVED, not deleted: applied plans point at this id, and a plan whose
  // origin vanished is a record with a hole in it.
  const { changes } = await run("UPDATE cultivation_templates SET archived_at=NOW() WHERE id=? AND org_id=? AND archived_at IS NULL",
    [req.params.id, req.user.orgId]);
  if (!changes) return res.status(404).json({ error: "Not found" });
  res.json({ success: true, archived: true });
}));

// The seam back to server.js, so `recordGift` can fire a trigger without this
// file being importable from there (it is required after server.js's body).
registerJourneyEngine(maybeStartJourney);

// ── PARITY-1 Part D · THE MORNING LOOK ─────────────────────────────────────
// Two triggers have no moment of their own to fire from: somebody drifting
// into a group by rule for a reason that is not a gift (their closeness
// warming, a role added), and the anniversary of a first gift. Both are
// noticed by this sweep, hourly so each org gets its own morning, and each is
// idempotent: the group look remembers who it has seen, and every plan holds
// its event key. Latency: a group join that is not a gift is seen within the
// hour; an anniversary fires on the day, within the hour after midnight in
// the org's own timezone. PARITY-3 6a: a birthday fires the same way, on the
// org's own date, for people with a birthday on file (shared/birthday.js).
async function runJourneySweep(onlyOrgId = null) {
  const orgs = await query(
    `SELECT DISTINCT org_id FROM cultivation_templates
      WHERE journey_enabled=true AND archived_at IS NULL
        AND trigger_key IN ('joined_group','giving_anniversary','birthday',
                            'membership_ending','membership_lapsed','recurring_failed','recurring_cancelled',
                            'card_expiring','volunteer_hours','grant_awarded','p2p_goal')
        ${onlyOrgId ? "AND org_id = ?" : ""}`, onlyOrgId ? [onlyOrgId] : []);
  let fired = 0;
  for (const { org_id: orgId } of orgs) {
    try {
      const org = await orgTz(orgId);
      const today = orgToday(org);   // ORG_TZ_SEAM_OK
      fired += await GR.dynamicJoins(orgId, { today,
        fire: (did, gid) => maybeStartJourney(orgId, did, "joined_group", { groupId: gid, today }) });
      const [armed] = await query(
        `SELECT 1 FROM cultivation_templates WHERE org_id=? AND trigger_key='giving_anniversary'
            AND journey_enabled=true AND archived_at IS NULL LIMIT 1`, [orgId]);
      if (armed) {
        const due = await query(
          `SELECT g.donor_id FROM gifts g JOIN donors d ON d.id=g.donor_id AND d.org_id=g.org_id AND d.deleted_at IS NULL
            WHERE g.org_id=? AND g.amount > 0
            GROUP BY g.donor_id
           HAVING SUBSTRING(MIN(LEFT(g.date,10)), 6, 5) = ? AND LEFT(MIN(LEFT(g.date,10)), 4) < ?`,
          [orgId, today.slice(5, 10), today.slice(0, 4)]);
        for (const r of due) {
          const out = await maybeStartJourney(orgId, r.donor_id, "giving_anniversary", { today });
          if (out && out.started) fired++;
        }
      }
      // PARITY-3 6a — birthdays, on the org's own date. February 29 is
      // remembered on the 28th in a year without one (shared/birthday.js).
      const [bdArmed] = await query(
        `SELECT 1 FROM cultivation_templates WHERE org_id=? AND trigger_key='birthday'
            AND journey_enabled=true AND archived_at IS NULL LIMIT 1`, [orgId]);
      if (bdArmed) {
        const B = await birthdayMod();
        const mm = Number(today.slice(5, 7));
        const born = await query(
          `SELECT id, birth_month, birth_day FROM donors
            WHERE org_id=? AND deleted_at IS NULL AND birth_month=? AND birth_day IN (?, 29)`,
          [orgId, mm, Number(today.slice(8, 10))]);
        for (const r of born) {
          if (!B.isBirthdayOn(Number(r.birth_month), Number(r.birth_day), today)) continue;
          const out = await maybeStartJourney(orgId, r.id, "birthday", { today });
          if (out && out.started) fired++;
        }
      }
      // JOURNEYS-3 — memberships, monthly gifts, cards, hours, grants, pages.
      fired += await runLifecycleTriggers(orgId, today);
    } catch (e) { console.error(`[journey] sweep ${orgId}:`, e.message); }
  }
  return fired;
}
// ── JOURNEYS-3 · THE MOMENTS A SMALL TEAM MISSES ───────────────────────────
// One definition per trigger of who it touches now, and the event each one is
// about. The hourly sweep fires them; "apply to people who already qualify"
// reads the same rows, so the offer and the trigger are one definition.
// `windowDays` is how far back an event still counts (the sweep looks back a
// fortnight, so a missed hour never loses one; the offer uses its own days).
// Everybody is a live record who may be contacted.
const LIVE_PERSON = `d.deleted_at IS NULL AND d.deceased IS NOT TRUE AND d.do_not_contact IS NOT TRUE`;
async function lifecycleRows(orgId, key, today, windowDays = 14) {
  const J = await journeyMod();
  const w = Math.max(1, Math.min(365, Number(windowDays) || 14));
  const P = (sql, params) => query(sql, params).catch(e => { console.error(`[journey] ${key}:`, e.message); return []; });
  if (key === "membership_ending") {
    return P(`SELECT m.donor_id, 'membership_ending:' || m.id || ':' || m.expires_on AS event_key
                FROM memberships m JOIN donors d ON d.id=m.donor_id AND d.org_id=m.org_id AND ${LIVE_PERSON}
               WHERE m.org_id=? AND m.status IN ('active','grace') AND COALESCE(m.expires_on,'') <> ''
                 AND m.expires_on::date BETWEEN ?::date AND ?::date + 30`, [orgId, today, today]);
  }
  if (key === "membership_lapsed") {
    return P(`SELECT m.donor_id, 'membership_lapsed:' || m.id || ':' || m.expires_on AS event_key
                FROM memberships m JOIN donors d ON d.id=m.donor_id AND d.org_id=m.org_id AND ${LIVE_PERSON}
               WHERE m.org_id=? AND m.status NOT IN ('cancelled','canceled') AND COALESCE(m.expires_on,'') <> ''
                 AND m.expires_on::date < ?::date AND m.expires_on::date >= ?::date - ?::int
                 AND NOT EXISTS (SELECT 1 FROM memberships m2 WHERE m2.org_id=m.org_id AND m2.donor_id=m.donor_id AND m2.id<>m.id
                                   AND m2.status IN ('active','grace')
                                   AND (COALESCE(m2.expires_on,'') = '' OR m2.expires_on::date >= ?::date))`,
      [orgId, today, today, w, today]);
  }
  if (key === "recurring_failed") {
    return P(`SELECT rs.donor_id, 'recurring_failed:' || rs.id || ':' || COALESCE(to_char(rs.first_failed_at, 'YYYY-MM-DD'), '') AS event_key
                FROM recurring_subscriptions rs JOIN donors d ON d.id=rs.donor_id AND d.org_id=rs.org_id AND ${LIVE_PERSON}
               WHERE rs.org_id=? AND rs.status IN ('past_due','failed','unpaid','recovering')
                 AND rs.last_failed_at IS NOT NULL AND rs.last_failed_at >= ?::date - ?::int`, [orgId, today, w]);
  }
  if (key === "recurring_cancelled") {
    return P(`SELECT rs.donor_id, 'recurring_cancelled:' || rs.id AS event_key
                FROM recurring_subscriptions rs JOIN donors d ON d.id=rs.donor_id AND d.org_id=rs.org_id AND ${LIVE_PERSON}
               WHERE rs.org_id=? AND rs.status IN ('canceled','cancelled')
                 AND rs.canceled_at IS NOT NULL AND rs.canceled_at >= ?::date - ?::int`, [orgId, today, w]);
  }
  if (key === "card_expiring") {
    // "Next month" in the org's own calendar.
    const [y, m] = String(today).slice(0, 7).split("-").map(Number);
    const ny = m === 12 ? y + 1 : y, nm = m === 12 ? 1 : m + 1;
    return P(`SELECT rs.donor_id, 'card_expiring:' || rs.id || ':' || ?::text AS event_key
                FROM recurring_subscriptions rs JOIN donors d ON d.id=rs.donor_id AND d.org_id=rs.org_id AND ${LIVE_PERSON}
               WHERE rs.org_id=? AND rs.status = ANY(?::text[]) AND rs.card_exp_year=? AND rs.card_exp_month=?`,
      [`${ny}-${String(nm).padStart(2, "0")}`, orgId, GR.ACTIVE_RECURRING_STATUSES, ny, nm]);
  }
  if (key === "volunteer_hours") {
    const rows = await P(
      `SELECT v.person_id AS donor_id,
              COALESCE(SUM(v.hours) FILTER (WHERE v.date::date < ?::date - ?::int), 0)::float AS before,
              COALESCE(SUM(v.hours), 0)::float AS after
         FROM volunteer_shifts v JOIN donors d ON d.id=v.person_id AND d.org_id=v.org_id AND ${LIVE_PERSON}
        WHERE v.org_id=? AND COALESCE(v.date,'') <> '' GROUP BY v.person_id HAVING SUM(v.hours) >= ?`,
      [today, w, orgId, J.HOUR_MILESTONES[0]]);
    return rows.map(r => {
      const crossed = J.HOUR_MILESTONES.filter(m => r.before < m && r.after >= m);
      return crossed.length ? { donor_id: r.donor_id, event_key: `volunteer_hours:${crossed[crossed.length - 1]}`, crossed } : null;
    }).filter(Boolean);
  }
  if (key === "first_event") {
    return P(`SELECT ea.donor_id, 'first_event' AS event_key
                FROM event_attendees ea JOIN events e ON e.id=ea.event_id
                JOIN donors d ON d.id=ea.donor_id AND d.org_id=ea.org_id AND ${LIVE_PERSON}
               WHERE ea.org_id=? AND lower(coalesce(ea.status,'')) = 'attended'
               GROUP BY ea.donor_id
              HAVING MIN(COALESCE(e.date::date, ea.created_at::date)) >= ?::date - ?::int`, [orgId, today, w]);
  }
  if (key === "grant_awarded") {
    return P(`SELECT g.funder_donor_id AS donor_id, 'grant:' || g.id AS event_key
                FROM grants g JOIN donors d ON d.id=g.funder_donor_id AND d.org_id=g.org_id AND d.deleted_at IS NULL
               WHERE g.org_id=? AND g.status='awarded' AND g.awarded_at IS NOT NULL
                 AND g.awarded_at >= ?::date - ?::int`, [orgId, today, w]);
  }
  if (key === "p2p_goal") {
    return P(`SELECT f.person_id AS donor_id, 'p2p_goal:' || f.id AS event_key
                FROM peer_fundraisers f JOIN donors d ON d.id=f.person_id AND d.org_id=f.org_id AND ${LIVE_PERSON}
               WHERE f.org_id=? AND COALESCE(f.personal_goal_amount, 0) > 0
                 AND (SELECT COALESCE(SUM(x.amount),0) FROM gifts x
                       WHERE x.org_id=f.org_id AND x.peer_fundraiser_id=f.id AND x.amount > 0) >= f.personal_goal_amount
                 AND EXISTS (SELECT 1 FROM gifts x WHERE x.org_id=f.org_id AND x.peer_fundraiser_id=f.id
                               AND COALESCE(x.date,'') <> '' AND x.date::date >= ?::date - ?::int)`, [orgId, today, w]);
  }
  return [];
}
async function runLifecycleTriggers(orgId, today) {
  const J = await journeyMod();
  const armed = await query(
    `SELECT DISTINCT trigger_key FROM cultivation_templates
      WHERE org_id=? AND journey_enabled=true AND archived_at IS NULL AND trigger_key = ANY(?::text[])`,
    [orgId, J.SWEEP_TRIGGER_KEYS]);
  let fired = 0;
  for (const { trigger_key: key } of armed) {
    for (const r of await lifecycleRows(orgId, key, today)) {
      const out = await maybeStartJourney(orgId, r.donor_id, key, { today, eventKey: r.event_key, crossed: r.crossed })
        .catch(e => { console.error(`[journey] ${key}:`, e.message); return null; });
      if (out && out.started) fired += 1 + (out.also || []).length;
    }
  }
  return fired;
}

// PARITY-3 6a — the morning look, run now for the caller's own org only, so
// a birthday or anniversary journey can be checked without waiting an hour.
// It starts only what the hourly sweep would start anyway (every plan holds
// its event key, so running it twice starts nothing twice).
app.post("/journeys/run-sweep", requireAuth, requireAdmin, wrap(async (req, res) => {
  const fired = await runJourneySweep(req.user.orgId);
  res.json({ fired });
}));
if (process.env.DISABLE_BACKGROUND_TICKS !== "1") {
  setTimeout(() => runJourneySweep().catch(e => console.error("[journey] sweep:", e.message)), 90000);
  setInterval(() => runJourneySweep().catch(e => console.error("[journey] sweep:", e.message)), 60 * 60 * 1000);
}

// ── THREAD-2a · THE JOURNEY ROUTES ────────────────────────────────────────
// Journeys live at Settings → Journeys and are reachable from Fundraising.
// They read and write `cultivation_templates`, because a journey IS one.

// The catalogue: the five presets, the triggers, and what this org has armed.
app.get("/journeys", requireAuth, wrap(async (req, res) => {
  const J = await journeyMod();
  const rows = await query(
    `SELECT * FROM cultivation_templates WHERE org_id=? AND archived_at IS NULL ORDER BY priority DESC, name`,
    [req.user.orgId]);
  // How many people are in each one right now, and how the steps are going.
  const counts = await query(
    `SELECT p.template_id,
            COUNT(*) FILTER (WHERE p.status='active')                       AS active,
            COUNT(*) FILTER (WHERE p.status='done')                         AS completed,
            COUNT(*) FILTER (WHERE p.status='abandoned')                    AS exited,
            COUNT(*)                                                        AS ever
       FROM cultivation_plans p WHERE p.org_id=? AND p.template_id IS NOT NULL
      GROUP BY p.template_id`, [req.user.orgId]);
  const byTpl = new Map(counts.map(c => [c.template_id, c]));
  // FIX-4 1c — the stages and tags this org actually uses, so the audience
  // controls offer what is on file rather than a list somebody has to type
  // from memory. Read here, once, beside the filters they belong to.
  const stageRows = await query(
    `SELECT DISTINCT stage FROM donors WHERE org_id=? AND deleted_at IS NULL AND stage IS NOT NULL AND stage <> '' ORDER BY stage`,
    [req.user.orgId]).catch(() => []);
  const tagRows = await query(
    `SELECT DISTINCT btrim(tg) AS tag FROM donors d,
       LATERAL jsonb_array_elements_text(
         CASE WHEN coalesce(d.tags,'') ~ '^\\s*\\[' THEN d.tags::jsonb ELSE '[]'::jsonb END) AS tg
      WHERE d.org_id=? AND d.deleted_at IS NULL AND btrim(tg) <> '' ORDER BY 1 LIMIT 200`,
    [req.user.orgId]).catch(() => []);
  // FIX-5 — who a step may name as its owner. The same list Settings shows, so
  // "a named person" means somebody who can actually be handed a step.
  const teamRows = await query(
    `SELECT id, name FROM users WHERE org_id=? AND deactivated_at IS NULL ORDER BY name`,
    [req.user.orgId]).catch(() => []);
  // PARITY-1 Part D — what a trigger or an audience may be narrowed to: this
  // org's groups, funds and campaigns, offered rather than typed.
  const groupOpts = (await GR.listGroups(req.user.orgId).catch(() => [])).map(g => ({ id: g.id, name: g.name, kind: g.kind }));
  const fundOpts = await query(`SELECT id, name FROM fin_funds WHERE org_id=? ORDER BY name`, [req.user.orgId]).catch(() => []);
  const campaignOpts = await query(`SELECT id, name FROM campaigns WHERE org_id=? ORDER BY created_at DESC LIMIT 200`, [req.user.orgId]).catch(() => []);
  res.json({
    triggers: J.TRIGGERS,
    states: J.STATES,
    // JOURNEYS-3 — Journey settings: the touch gap, and the milestones.
    touchGapDays: await journeyTouchGap(req.user.orgId),
    touchGap: { min: J.TOUCH_GAP_MIN, max: J.TOUCH_GAP_MAX, default: J.TOUCH_GAP_DEFAULT },
    hourMilestones: J.HOUR_MILESTONES,
    groups: groupOpts,
    funds: fundOpts.map(f => ({ id: f.id, name: f.name })),
    campaigns: campaignOpts.map(c => ({ id: c.id, name: c.name })),
    audienceFilters: J.AUDIENCE_FILTERS,
    timingUnits: J.TIMING_UNITS,
    timingFrom: J.TIMING_FROM,
    draftKinds: J.DRAFT_KINDS,
    // EMAIL-1 — a step's draft may start from one of the org's email templates.
    emailTemplates: (await query(`SELECT id, name FROM email_templates WHERE org_id=? AND archived_at IS NULL ORDER BY name`,
      [req.user.orgId]).catch(() => [])).map(t => ({ id: t.id, name: t.name })),
    priority: { min: J.PRIORITY_MIN, max: J.PRIORITY_MAX, default: J.PRIORITY_DEFAULT },
    stages: stageRows.map(r => r.stage),
    tags: tagRows.map(r => r.tag),
    presets: J.PRESETS.map(p => ({ ...p, touches: J.touchesSentence(p.steps) })),
    // FIX-5 — the team, so a step can name a person as its owner instead of
    // always falling to the relationship owner.
    team: teamRows.map(u => ({ id: u.id, name: u.name })),
    journeys: rows.map(t => ({
      id: t.id, name: t.name, description: t.description || "", steps: t.steps, trigger: t.trigger_key,
      amountCents: t.trigger_amount_cents, priority: t.priority,
      audience: t.audience || {},
      audienceSentence: J.audienceSentence(t.audience || {}),
      presetKey: t.preset_key, enabled: !!t.journey_enabled,
      touches: J.touchesSentence(t.steps || []),
      // FIX-5 item 2 — arriving on Journeys opens one, and this is how the page
      // knows which: the most recently edited. `updated_at` is set on every
      // PATCH already, so nothing new has to be recorded for it.
      updatedAt: t.updated_at,
      inIt: Number((byTpl.get(t.id) || {}).active) || 0,
      everIn: Number((byTpl.get(t.id) || {}).ever) || 0,
      // PARITY-1 Part D — entered, in it, exited and completed, and the state.
      completed: Number((byTpl.get(t.id) || {}).completed) || 0,
      exited: Number((byTpl.get(t.id) || {}).exited) || 0,
      triggerFilters: t.trigger_filters || {},
      exclusive: !!t.exclusive,
      state: J.journeyState({ enabled: !!t.journey_enabled, everEnabled: !!t.ever_enabled,
        archived: !!t.archived_at, everIn: Number((byTpl.get(t.id) || {}).ever) || 0 }),
    })),
  });
}));

// ── FIX-5 item 6 · WHAT A BIG GIFT IS HERE, FROM THEIR OWN FILE ───────────
// The Major donor journey needs a number and there is no universal one, so the
// old screen refused to save and printed the refusal in terracotta — an error
// for not yet having answered a question nobody had been asked. The question is
// asked up front instead, with a SUGGESTION from this organisation's own gifts:
// the 90th percentile single gift, which is the size the top tenth of their
// gifts start at. Every number opens, so the rows behind it come back with it.
//
// A GET, and it writes nothing.
app.get("/journeys/suggest-big-gift", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [agg] = await query(
    `SELECT COUNT(*)::int n,
            percentile_disc(0.9) WITHIN GROUP (ORDER BY amount)::float p90,
            MAX(amount)::float top
       FROM gifts WHERE org_id=? AND amount > 0`, [orgId]);
  const n = Number(agg?.n) || 0;
  // A file with almost nothing in it cannot suggest anything honestly. $1,000
  // is offered as a STARTING POINT and said to be one, rather than dressed up
  // as something read out of their data.
  if (n < 20) {
    return res.json({
      cents: 100000, fromTheirData: false, gifts: 0,
      sentence: "There are not enough gifts on file yet to read a number out of them, so this is a common starting point. Change it to whatever a big gift is for you.",
      rows: [],
    });
  }
  // Rounded to a number a person would say out loud. $2,647 is arithmetic;
  // $2,500 is an answer.
  const p90 = Number(agg.p90) || 0;
  const step = p90 >= 25000 ? 5000 : p90 >= 10000 ? 2500 : p90 >= 2500 ? 500 : p90 >= 500 ? 100 : 25;
  // Rounded on purpose, and it is not a gift: it is a THRESHOLD being offered
  // for her to accept or type over, and it is carried in cents from here on.
  const suggested = Math.max(step, Math.round(p90 / step) * step);
  const rows = await query(
    `SELECT g.id, g.amount::float amount, g.date, d.id AS donor_id, d.name AS donor_name
       FROM gifts g JOIN donors d ON d.id=g.donor_id AND d.org_id=g.org_id
      WHERE g.org_id=? AND g.amount >= ? AND d.deleted_at IS NULL
      ORDER BY g.amount DESC LIMIT 200`, [orgId, suggested]);
  res.json({
    cents: Math.round(suggested * 100), fromTheirData: true, gifts: n,
    sentence: `The top tenth of your ${n.toLocaleString("en-US")} gifts start at about $${suggested.toLocaleString("en-US")}. `
      + `${rows.length} gift${rows.length === 1 ? "" : "s"} on file ${rows.length === 1 ? "is" : "are"} that size or larger.`,
    // sentenceMoney, not Math.round: these are real gifts, and a gift of
    // $4,000.50 shown as $4,001 in the rows behind a number is the whole
    // reason the money seam exists.
    rows: rows.map(r => ({ id: r.donor_id, giftId: r.id, name: r.donor_name,
      reason: `${sentenceMoney(r.amount)} on ${r.date}` })),
  });
}));

// Create one, from a preset or from scratch. `presetKey` fills the steps; the
// body may then override any of them, which is what "pick a preset, adjust"
// means in the onboarding step.
app.post("/journeys", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const J = await journeyMod();
  const b = req.body || {};
  const preset = b.presetKey ? J.presetByKey(String(b.presetKey)) : null;
  if (b.presetKey && !preset) return res.status(400).json({ error: "unknown_preset", message: "There is no preset by that name." });

  // ── FIX-10 Part C · RE-RUNNING ONBOARDING NEVER CLONES A JOURNEY ─────────
  // Onboarding's preset picker POSTs here the first time a preset is tapped
  // and caches the new id in memory. Walk the wizard a second time and that
  // cache is gone, so the same tap made a SECOND row from the same preset:
  // two journeys, same trigger, same steps, and whichever got armed would fire
  // beside its twin. The preset key is the identity. If a live journey already
  // came from this preset, that journey IS the answer, and "Use this one"
  // opens it. The ORIGINAL, by created_at, so a deliberate duplicate (which
  // carries the preset key too) never shadows the one onboarding made.
  //
  // Only the preset path is affected: a hand-built journey has no preset key,
  // so POSTing two of those still makes two, which is what the button says.
  if (preset) {
    const [already] = await query(
      `SELECT * FROM cultivation_templates WHERE org_id=? AND preset_key=? AND archived_at IS NULL
        ORDER BY created_at ASC, id ASC LIMIT 1`, [req.user.orgId, preset.key]);
    if (already) {
      return res.json({
        id: already.id, name: already.name, description: already.description,
        trigger: already.trigger_key, priority: already.priority,
        steps: already.steps, amountCents: already.trigger_amount_cents,
        audience: already.audience || {}, presetKey: already.preset_key,
        enabled: !!already.journey_enabled,
        touches: J.touchesSentence(already.steps || []),
        existing: true,
        sentence: `You already have "${already.name}" from this one. Opening it instead of making a second.`,
      });
    }
  }

  const input = {
    name: b.name || (preset && preset.name),
    description: b.description !== undefined ? b.description : (preset && preset.blurb),
    trigger: b.trigger || (preset && preset.trigger),
    priority: b.priority !== undefined ? b.priority : (preset && preset.priority),
    amountCents: b.amountCents,
    audience: b.audience,
    triggerFilters: b.triggerFilters,
    steps: Array.isArray(b.steps) && b.steps.length ? b.steps : (preset && preset.steps),
    exclusive: b.exclusive !== undefined ? b.exclusive === true : !!(preset && preset.exclusive),
  };
  // JOURNEYS-3 — a ready-made step that names an EMAIL-1 starter drafts from
  // the org's own copy of that email, saved from the starter if it has none.
  if (Array.isArray(input.steps)) {
    input.steps = await Promise.all(input.steps.map(async st => {
      if (!st || !st.starter || st.draft) return st;
      const tid = await require("./emailTemplates").ensureStarterTemplate(req.user.orgId, st.starter, actor(req)).catch(() => null);
      return tid ? { ...st, draft: `template:${tid}` } : st;
    }));
  }
  const v = J.validateJourney(input);
  if (!v.ok) return res.status(400).json({ error: "invalid_journey", errors: v.errors, message: v.errors[0].message });
  // FIX-19: a step owned by a named person names an active user of this org.
  const stepOwners = await OU.orgUsers(req.user.orgId, v.steps.map(st => st.ownerId));
  if (!stepOwners.ok) return OU.refuse(res, "steps.ownerId");

  const refused = await journeyRefsRefused(req.user.orgId, v);
  if (refused) return res.status(404).json(refused);

  const id = "ct_" + uuid().slice(0, 10);
  await run(
    `INSERT INTO cultivation_templates (id,org_id,name,description,steps,trigger_key,trigger_amount_cents,priority,audience,preset_key,journey_enabled,created_by,created_by_name,trigger_filters,ever_enabled,exclusive)
     VALUES (?,?,?,?,?::jsonb,?,?,?,?::jsonb,?,?,?,?,?::jsonb,?,?)`,
    [id, req.user.orgId, v.name, v.description, JSON.stringify(v.steps), v.trigger, v.amountCents, v.priority,
     JSON.stringify(v.audience),
     preset ? preset.key : null,
     // ARMED ONLY IF ASKED. Creating a journey and having it start firing at
     // people in the same breath is not a thing anybody wants by surprise.
     b.enabled === true, actor(req).id, actor(req).name, JSON.stringify(v.triggerFilters || {}), b.enabled === true, v.exclusive]);
  if (b.enabled === true) await baselineJourneyGroup(req.user.orgId, v);
  const [row] = await query("SELECT * FROM cultivation_templates WHERE id=? AND org_id=?", [id, req.user.orgId]);
  res.status(201).json({ id, name: v.name, description: v.description, trigger: v.trigger, priority: v.priority,
    steps: v.steps, audience: v.audience, enabled: !!row.journey_enabled, exclusive: !!row.exclusive, touches: J.touchesSentence(v.steps) });
}));

// ── FIX-5 item 5 · DUPLICATE A WHOLE JOURNEY ─────────────────────────────
// The way an org gets its second journey: copy the one that works and change
// two things. The copy arrives OFF, whatever the original was — two journeys
// firing on the same trigger the moment you press "duplicate" is the surprise
// this build exists to remove.
app.post("/journeys/:id/duplicate", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const J = await journeyMod();
  const [cur] = await query("SELECT * FROM cultivation_templates WHERE id=? AND org_id=? AND archived_at IS NULL",
    [req.params.id, req.user.orgId]);
  if (!cur) return res.status(404).json({ error: "Not found" });
  // "New donor, first year (copy)", then "(copy 2)" — a name nobody has to
  // think about, and never a silent second row with the identical name.
  const existing = (await query(
    `SELECT name FROM cultivation_templates WHERE org_id=? AND archived_at IS NULL`, [req.user.orgId]))
    .map(r => String(r.name || "").toLowerCase());
  let name = `${cur.name} (copy)`;
  for (let n = 2; existing.includes(name.toLowerCase()); n++) name = `${cur.name} (copy ${n})`;

  const v = J.validateJourney({ name, description: cur.description, trigger: cur.trigger_key,
    priority: cur.priority, amountCents: cur.trigger_amount_cents, audience: cur.audience, steps: cur.steps,
    triggerFilters: cur.trigger_filters || {} });
  if (!v.ok) return res.status(400).json({ error: "invalid_journey", errors: v.errors, message: v.errors[0].message });
  const id = "ct_" + uuid().slice(0, 10);
  await run(
    `INSERT INTO cultivation_templates (id,org_id,name,description,steps,trigger_key,trigger_amount_cents,priority,audience,preset_key,journey_enabled,created_by,created_by_name,trigger_filters,exclusive)
     VALUES (?,?,?,?,?::jsonb,?,?,?,?::jsonb,?,false,?,?,?::jsonb,?)`,
    [id, req.user.orgId, v.name, v.description, JSON.stringify(v.steps), v.trigger, v.amountCents, v.priority,
     JSON.stringify(v.audience), cur.preset_key, actor(req).id, actor(req).name, JSON.stringify(v.triggerFilters || {}), !!cur.exclusive]);
  res.status(201).json({ id, name: v.name, copiedFrom: cur.id, enabled: false,
    sentence: `"${v.name}" is a copy of "${cur.name}" and it is off. Nothing starts until you turn it on.` });
}));

// ── FIX-5 item 5 · DELETE, WITH AN UNDO ──────────────────────────────────
// Archived, never deleted: applied plans point at this id and a plan whose
// origin vanished is a record with a hole in it. Archiving also makes the undo
// trivial and exact — it is the same row, put back.
app.delete("/journeys/:id", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const [cur] = await query("SELECT * FROM cultivation_templates WHERE id=? AND org_id=? AND archived_at IS NULL",
    [req.params.id, req.user.orgId]);
  if (!cur) return res.status(404).json({ error: "Not found" });
  const [inIt] = await query(
    `SELECT COUNT(*)::int n FROM cultivation_plans WHERE org_id=? AND template_id=? AND status='active'`,
    [req.user.orgId, req.params.id]);
  // Turned OFF as well as archived, so restoring cannot quietly re-arm it.
  await run(`UPDATE cultivation_templates SET archived_at=NOW(), journey_enabled=false, updated_at=NOW()
              WHERE id=? AND org_id=?`, [req.params.id, req.user.orgId]);
  res.json({ id: req.params.id, name: cur.name, deleted: true, undoable: true, inIt: Number(inIt?.n) || 0,
    sentence: Number(inIt?.n) > 0
      ? `"${cur.name}" is gone from the list. The ${inIt.n} ${Number(inIt.n) === 1 ? "person" : "people"} already in it keep the steps they entered with.`
      : `"${cur.name}" is gone from the list.` });
}));

app.post("/journeys/:id/restore", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const { changes } = await run(
    `UPDATE cultivation_templates SET archived_at=NULL, updated_at=NOW()
      WHERE id=? AND org_id=? AND archived_at IS NOT NULL`, [req.params.id, req.user.orgId]);
  if (!changes) return res.status(404).json({ error: "Not found" });
  const [row] = await query("SELECT * FROM cultivation_templates WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  res.json({ id: row.id, name: row.name, restored: true, enabled: false,
    sentence: `"${row.name}" is back, and it is off.` });
}));

// ── FIX-5 item 5 · WHO A CHANGE REACHES, BEFORE IT IS SAVED ──────────────
// A GET that writes nothing, and it tells the truth rather than the reassuring
// version. Saving a journey does NOT rewrite the people already in it — their
// steps were copied when they entered, on purpose, so somebody three touches
// into seven cannot silently acquire two more. So the honest sentence is "these
// people are in it, and saving leaves them where they are", plus the count that
// WOULD move if she asks for it (`retimeExisting` on the PATCH).
app.get("/journeys/:id/affects", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [t] = await query("SELECT * FROM cultivation_templates WHERE id=? AND org_id=? AND archived_at IS NULL",
    [req.params.id, orgId]);
  if (!t) return res.status(404).json({ error: "Not found" });
  const rows = await query(
    `SELECT d.id, d.name, p.applied_on,
            (SELECT COUNT(*) FROM cultivation_plan_steps s WHERE s.plan_id=p.id AND s.status='pending')::int pending,
            (SELECT MIN(s.due_date) FROM cultivation_plan_steps s WHERE s.plan_id=p.id AND s.status='pending') next_due
       FROM cultivation_plans p JOIN donors d ON d.id=p.donor_id AND d.org_id=p.org_id
      WHERE p.org_id=? AND p.template_id=? AND p.status='active' AND d.deleted_at IS NULL
      ORDER BY d.name LIMIT 500`, [orgId, t.id]);
  const movable = rows.filter(r => Number(r.pending) > 0);
  res.json({
    journeyId: t.id, name: t.name, inIt: rows.length, movable: movable.length,
    enabled: !!t.journey_enabled,
    sentence: rows.length === 0
      ? "Nobody is in this journey yet, so this change only affects people who enter it from now on."
      : `${rows.length} ${rows.length === 1 ? "person is" : "people are"} in this journey. `
        + `Their steps were copied when they entered, so saving leaves them where they are. `
        + `It changes what happens to everybody who enters from now on.`,
    moveSentence: movable.length
      ? `This moves ${movable.length} ${movable.length === 1 ? "person's" : "people's"} next step.`
      : "There is no step still to come on anybody in it, so there is nothing to move.",
    donors: movable.map(r => ({ id: r.id, name: r.name,
      reason: `${r.pending} step${Number(r.pending) === 1 ? "" : "s"} still to come${r.next_due ? `, next on ${r.next_due}` : ""}` })),
  });
}));

app.patch("/journeys/:id", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const J = await journeyMod();
  const [cur] = await query("SELECT * FROM cultivation_templates WHERE id=? AND org_id=? AND archived_at IS NULL",
    [req.params.id, req.user.orgId]);
  if (!cur) return res.status(404).json({ error: "Not found" });
  const b = req.body || {};
  const v = J.validateJourney({
    name: b.name !== undefined ? b.name : cur.name,
    description: b.description !== undefined ? b.description : cur.description,
    trigger: b.trigger !== undefined ? b.trigger : cur.trigger_key,
    priority: b.priority !== undefined ? b.priority : cur.priority,
    amountCents: b.amountCents !== undefined ? b.amountCents : cur.trigger_amount_cents,
    audience: b.audience !== undefined ? b.audience : cur.audience,
    triggerFilters: b.triggerFilters !== undefined ? b.triggerFilters : cur.trigger_filters,
    steps: b.steps !== undefined ? b.steps : cur.steps,
  });
  if (!v.ok) return res.status(400).json({ error: "invalid_journey", errors: v.errors, message: v.errors[0].message });
  // FIX-19: a step owned by a named person names an active user of this org.
  const stepOwners = await OU.orgUsers(req.user.orgId, v.steps.map(st => st.ownerId));
  if (!stepOwners.ok) return OU.refuse(res, "steps.ownerId");
  const refused = await journeyRefsRefused(req.user.orgId, v);
  if (refused) return res.status(404).json(refused);
  const enabledNow = b.enabled !== undefined ? b.enabled === true : !!cur.journey_enabled;
  const exclusiveNow = b.exclusive !== undefined ? b.exclusive === true : !!cur.exclusive;
  await run(
    `UPDATE cultivation_templates SET name=?, description=?, steps=?::jsonb, trigger_key=?, trigger_amount_cents=?,
       priority=?, audience=?::jsonb, journey_enabled=?, trigger_filters=?::jsonb,
       ever_enabled = (ever_enabled OR ?), exclusive=?, updated_at=NOW() WHERE id=? AND org_id=?`,
    [v.name, v.description, JSON.stringify(v.steps), v.trigger, v.amountCents, v.priority,
     JSON.stringify(v.audience),
     enabledNow, JSON.stringify(v.triggerFilters || {}), enabledNow, exclusiveNow,
     req.params.id, req.user.orgId]);
  if (enabledNow) await baselineJourneyGroup(req.user.orgId, v);

  // CHANGING A JOURNEY DOES NOT REWRITE THE PEOPLE ALREADY IN IT. Their steps
  // were copied when they entered, exactly as a plan's are — somebody who has
  // already had three of seven touches must not silently acquire two more.
  //
  // FIX-5 — UNLESS SHE ASKS. `retimeExisting` is the opt-in the confirm dialog
  // offers after showing her exactly who it reaches, and it moves PENDING steps
  // only: a step that is open, done or skipped has already happened to somebody
  // and is not ours to rewrite. The dates are recomputed from each plan's own
  // `applied_on`, so two people who entered in different weeks stay in their own
  // weeks rather than being dragged onto a shared date.
  let moved = 0, movedPeople = 0;
  if (b.retimeExisting === true) {
    const plans = await query(
      `SELECT id, applied_on FROM cultivation_plans
        WHERE org_id=? AND template_id=? AND status='active'`, [req.user.orgId, req.params.id]);
    for (const p of plans) {
      let any = false;
      for (let i = 0; i < v.steps.length; i++) {
        const due = orgTime.addDays(String(p.applied_on).slice(0, 10), Number(v.steps[i].offsetDays) || 0);
        const { changes } = await run(
          `UPDATE cultivation_plan_steps SET due_date=?, label=?, step_type=?
            WHERE plan_id=? AND org_id=? AND seq=? AND status='pending'`,
          [due, v.steps[i].label, v.steps[i].type, p.id, req.user.orgId, i + 1]);
        if (changes) { moved += changes; any = true; }
      }
      if (any) movedPeople++;
    }
  }

  res.json({ id: req.params.id, name: v.name, description: v.description, trigger: v.trigger, priority: v.priority,
    steps: v.steps, audience: v.audience, exclusive: exclusiveNow, touches: J.touchesSentence(v.steps),
    movedPeople, movedSteps: moved,
    note: b.retimeExisting === true
      ? `${movedPeople} ${movedPeople === 1 ? "person's" : "people's"} steps still to come were moved to the new timing. Steps already done were left alone.`
      : "People already in this journey keep the steps they entered with." });
}));

// Who would qualify right now — the count the "apply to people who already
// qualify" offer opens. A GET, and it writes nothing.
//
// JOURNEYS-3 · COUNTED HONESTLY BEFORE THE CLICK. One read of who qualifies,
// one read of the journeys they are already in, and the split is done here:
// who will join, who is already in this one, who is in a journey marked "only
// one of these at a time" that ranks the same or higher (they stay), and who
// is in other journeys (they join too, spaced a week apart, unless she says
// leave them where they are). The apply route uses the same split, so the
// button's number and the result cannot disagree.
async function applySplit(orgId, t, days, audience, joinOthers = true) {
  const ids = (await qualifyingDonors(orgId, t, days, audience)).map(r => r.id);
  const out = { qualify: ids.length, willJoin: [], alreadyIn: [], blocked: [], inOthers: [] };
  if (!ids.length) return out;
  const [people, plans] = await Promise.all([
    query(`SELECT id, name FROM donors WHERE org_id=? AND id = ANY(?::text[]) AND deleted_at IS NULL`, [orgId, ids]),
    query(`SELECT p.donor_id, p.template_id, p.template_name, p.priority, COALESCE(ct.exclusive, false) AS exclusive
             FROM cultivation_plans p LEFT JOIN cultivation_templates ct ON ct.id = p.template_id AND ct.org_id = p.org_id
            WHERE p.org_id=? AND p.status='active' AND p.donor_id = ANY(?::text[])`, [orgId, ids]),
  ]);
  const nameOf = new Map(people.map(d => [d.id, d.name]));
  const byDonor = new Map();
  for (const p of plans) (byDonor.get(p.donor_id) || byDonor.set(p.donor_id, []).get(p.donor_id)).push(p);
  for (const id of ids) {
    if (!nameOf.has(id)) continue;
    const mine = byDonor.get(id) || [];
    const row = { id, name: nameOf.get(id), journeys: mine.map(p => p.template_name) };
    if (mine.some(p => p.template_id === t.id)) { out.alreadyIn.push(row); continue; }
    const higher = t.exclusive && mine.find(p => p.exclusive && Number(p.priority) >= Number(t.priority));
    if (higher) { out.blocked.push({ ...row, journeys: [higher.template_name] }); continue; }
    if (mine.length) { out.inOthers.push(row); if (joinOthers) out.willJoin.push(row); continue; }
    out.willJoin.push(row);
  }
  return out;
}
function applySentence(split, joinOthers) {
  const n = k => `${k} ${k === 1 ? "person" : "people"}`;
  const parts = [`${split.qualify} qualify.`, `${split.willJoin.length} will join.`];
  if (split.alreadyIn.length) parts.push(`${n(split.alreadyIn.length)} ${split.alreadyIn.length === 1 ? "is" : "are"} already in it.`);
  if (split.blocked.length) parts.push(`${split.blocked.length} ${split.blocked.length === 1 ? "is" : "are"} already in a journey that ranks higher.`);
  if (split.inOthers.length) parts.push(joinOthers
    ? `${split.inOthers.length} ${split.inOthers.length === 1 ? "is" : "are"} in another journey and will join too, with touches spaced out.`
    : `${split.inOthers.length} ${split.inOthers.length === 1 ? "is" : "are"} in another journey and will be left where they are.`);
  return parts.join(" ");
}
app.get("/journeys/:id/qualifying", requireAuth, wrap(async (req, res) => {
  const J = await journeyMod();
  const [t] = await query("SELECT * FROM cultivation_templates WHERE id=? AND org_id=? AND archived_at IS NULL",
    [req.params.id, req.user.orgId]);
  if (!t) return res.status(404).json({ error: "Not found" });
  const days = Math.min(365, Math.max(1, Number(req.query.days) || 90));
  // FIX-4 1c — the audience arrives as a JSON query parameter so this stays a
  // GET that writes nothing. A parameter that will not parse is treated as no
  // filter at all, which is the wider set and therefore the honest failure:
  // the count says more people than it should rather than fewer.
  let audience = {};
  try { audience = J.validateAudience(req.query.audience ? JSON.parse(String(req.query.audience)) : {}); }
  catch { audience = {}; }
  const joinOthers = String(req.query.joinOthers || "true") !== "false";
  const split = await applySplit(req.user.orgId, t, days, audience, joinOthers);
  res.json({ journeyId: t.id, name: t.name, days, audience, joinOthers,
    count: split.qualify, willJoin: split.willJoin.length,
    donorIds: split.willJoin.map(r => r.id).slice(0, 2000),
    alreadyIn: split.alreadyIn.slice(0, 200), blocked: split.blocked.slice(0, 200), inOthers: split.inOthers.slice(0, 200),
    audienceSentence: J.audienceSentence(audience),
    filters: J.AUDIENCE_FILTERS,
    sentence: applySentence(split, joinOthers),
    window: `Their trigger happened in the last ${days} days.` });
}));

// ── THREAD-2b 1 · THE LIVE PREVIEW, ON A REAL DONOR ─────────────────────
// The builder shows what this journey would do to somebody who actually
// exists, with the dates it would actually produce. Invented dates on an
// invented person would let a retiming mistake look fine right up until it
// reached a real record.
//
// WHICH DONOR: the most recent one whose trigger genuinely applies — the
// newest first-time giver for a first_gift journey, the newest big gift for
// gift_over. Falling back to "any donor" would be a preview of something
// that would never happen to them.
//
// A GET, and it writes NOTHING. No plan, no steps, no thread. It is
// arithmetic on a date.
app.get("/journeys/:id/preview", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [t] = await query("SELECT * FROM cultivation_templates WHERE id=? AND org_id=? AND archived_at IS NULL",
    [req.params.id, orgId]);
  if (!t) return res.status(404).json({ error: "Not found" });
  const J = await journeyMod();
  const PL = await planMod();

  // The donor, and the DATE THE TRIGGER WOULD HAVE FIRED ON — which is what
  // the offsets count from, not today. A first gift in October means month 3
  // is January, and a preview that said "three months from today" would be
  // showing a different journey from the one that runs.
  let donor = null, basis = null, from = null;
  const newestGift = async (minCents) => (await query(
    `SELECT d.id, d.name, g.date, g.amount FROM donors d
       JOIN gifts g ON g.donor_id=d.id AND g.org_id=d.org_id
      WHERE d.org_id=? AND d.deleted_at IS NULL AND g.date IS NOT NULL AND g.date <> ''
        ${minCents ? "AND ROUND(g.amount*100) >= " + Number(minCents) : ""}
      ORDER BY g.date DESC LIMIT 1`, [orgId]))[0] || null;

  if (t.trigger_key === "first_gift") {
    const [r] = await query(
      `SELECT d.id, d.name, MIN(g.date) AS date, MAX(g.amount) AS amount
         FROM donors d JOIN gifts g ON g.donor_id=d.id AND g.org_id=d.org_id
        WHERE d.org_id=? AND d.deleted_at IS NULL AND g.date IS NOT NULL AND g.date <> ''
        GROUP BY d.id, d.name HAVING COUNT(g.id)=1
        ORDER BY MIN(g.date) DESC LIMIT 1`, [orgId]);
    if (r) { donor = r; from = String(r.date).slice(0, 10);
             basis = `First gift $${Number(r.amount).toLocaleString("en-US")} · ${from}`; }
  } else if (t.trigger_key === "gift_over") {
    const r = await newestGift(Number(t.trigger_amount_cents) || 0);
    if (r) { donor = r; from = String(r.date).slice(0, 10);
             basis = `Gift $${Number(r.amount).toLocaleString("en-US")} · ${from}`; }
  }
  if (!donor) {
    const r = await newestGift(0);
    if (r) { donor = r; from = String(r.date).slice(0, 10); basis = `Most recent gift · ${from}`; }
  }
  if (!donor) return res.json({ donor: null, steps: [], why: "Nobody on file yet to preview this on." });

  // ── FIX-5 · THE CHAIN'S STATES COME FROM A REAL PLAN WHEN THERE IS ONE ──
  // The chain shows done, today and still-to-come at a glance, and those words
  // have to MEAN something. So the preview prefers somebody who is ACTUALLY in
  // this journey: their real steps, with the real statuses the Thread engine
  // set. Only when nobody is in it does it fall back to the arithmetic above,
  // and then a step is "past", "today" or "upcoming" by its date, never "done"
  // — because nothing has been done, and the caption says which it is showing.
  const today = orgToday(await orgTz(orgId));                           // ORG_TZ_SEAM_OK
  const [live] = await query(
    `SELECT p.id, p.applied_on, d.id AS donor_id, d.name
       FROM cultivation_plans p JOIN donors d ON d.id=p.donor_id AND d.org_id=p.org_id
      WHERE p.org_id=? AND p.template_id=? AND p.status='active' AND d.deleted_at IS NULL
      ORDER BY p.applied_on DESC LIMIT 1`, [orgId, t.id]);
  if (live) {
    const real = await query(
      `SELECT seq, label, due_date, status FROM cultivation_plan_steps
        WHERE org_id=? AND plan_id=? ORDER BY seq`, [orgId, live.id]);
    if (real.length) {
      return res.json({
        donor: { id: live.donor_id, name: live.name,
                 basis: `In this journey since ${String(live.applied_on).slice(0, 10)}` },
        from: String(live.applied_on).slice(0, 10),
        live: true,
        steps: real.map(s => ({
          seq: s.seq, label: s.label, dueDate: s.due_date,
          // done and skipped both read as behind them; open is what they are on
          // now, and it is the step the emerald ring belongs to.
          state: s.status === "done" || s.status === "skipped" ? "done"
               : s.status === "open" || s.due_date === today ? "today"
               : s.due_date < today ? "past" : "upcoming",
        })),
        legend: "This is somebody really in it. Filled steps are behind them, the ring is where they are now.",
        touches: J.touchesSentence(t.steps || []),
      });
    }
  }

  const v = J.validateJourney({ name: t.name, trigger: t.trigger_key, priority: t.priority,
                                amountCents: t.trigger_amount_cents, steps: t.steps, triggerFilters: t.trigger_filters || {} });
  const steps = PL.planFromTemplate({ steps: v.steps, today: from }, orgTime.addDays);
  res.json({
    donor: { id: donor.id, name: donor.name, basis },
    from,
    live: false,
    steps: steps.map((s, i) => ({ seq: s.seq, label: s.label, dueDate: s.dueDate,
      draft: (v.steps[i] || {}).draft || null,
      state: s.dueDate === today ? "today" : s.dueDate < today ? "past" : "upcoming" })),
    legend: "Nobody is in this journey yet, so these are the dates it would have produced for this person. Change a step and they move.",
    touches: J.touchesSentence(v.steps),
  });
}));

// ── THREAD-2b 6 · HOW A JOURNEY IS GOING, AND WHAT IT DOES NOT CLAIM ─────
//
// Four numbers per journey: how many people are in it, how its steps are
// going (on time / late / skipped), and how many donors gave a SECOND gift
// within twelve months of entering.
//
// THE LAST ONE IS NOT A CLAIM THAT THE JOURNEY CAUSED IT, and the route says
// so in the payload rather than leaving it to a caption somebody might
// delete. Nothing here is a comparison against donors who were not in it,
// because Steward is not running an experiment and a number that looks like
// a lift, without a control, is a lie with a decimal point on it.
//
// ── FIX-4 2 · WHAT THIS JOURNEY WOULD DO TO THIS PERSON ──────────────────
// The rail's "Add to a journey" shows the FIRST STEP AND ITS DATE before
// anybody presses anything, so the confirm is a confirm to something real
// rather than to a name. The dates are the organisation's civil dates, the
// same arithmetic the apply itself will do — computed by planShape from the
// org's own today, never from a UTC instant.
//
// A GET, and it writes nothing: no plan, no step, no thread.
app.get("/donors/:id/journey-preview", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const PL = await planMod();
  const J = await journeyMod();
  const [donor] = await query("SELECT id, name FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL",
    [req.params.id, orgId]);
  if (!donor) return res.status(404).json({ error: "Donor not found" });
  const [t] = await query("SELECT * FROM cultivation_templates WHERE id=? AND org_id=? AND archived_at IS NULL",
    [String(req.query.journeyId || ""), orgId]);
  if (!t) return res.status(404).json({ error: "Not found", message: "That journey no longer exists." });

  const v = PL.validateTemplate({ name: t.name, steps: t.steps });
  if (!v.ok) return res.status(400).json({ error: "invalid_journey", message: v.errors[0].message });
  const today = orgToday(await orgTz(orgId));                 // ORG_TZ_SEAM_OK
  const steps = PL.planFromTemplate({ steps: v.steps, today }, orgTime.addDays);
  const first = steps[0] || null;

  // Somebody already in a plan is the one case where this cannot just say
  // yes, so it says so here rather than at the confirm.
  const inNow = await query(
    "SELECT template_id, template_name FROM cultivation_plans WHERE org_id=? AND donor_id=? AND status='active' ORDER BY priority DESC", [orgId, donor.id]);
  const open = inNow.find(p => p.template_id === t.id) || null;

  res.json({
    journeyId: t.id, name: t.name, donorId: donor.id, donorName: donor.name,
    touches: J.touchesSentence(t.steps || []),
    firstStep: first ? { label: first.label, dueDate: first.dueDate, type: first.type } : null,
    steps: steps.map(s => ({ seq: s.seq, label: s.label, dueDate: s.dueDate })),
    alreadyIn: open ? open.template_name : null,
    // JOURNEYS-3 — the other journeys they are in; they can be in this one too.
    alsoIn: inNow.filter(p => p.template_id !== t.id).map(p => p.template_name),
    sentence: first
      ? `${donor.name} would start with "${first.label}", due ${first.dueDate}. Nothing is sent. Every step waits for you.`
      : "That journey has no steps yet.",
  });
}));

// EVERY NUMBER OPENS. Each figure carries the `rows` key that
// GET /journeys/:id/rows re-fetches, so the number on the screen and the
// donors behind it are one query and cannot drift.
app.get("/journeys/:id/stats", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [t] = await query("SELECT * FROM cultivation_templates WHERE id=? AND org_id=? AND archived_at IS NULL",
    [req.params.id, orgId]);
  if (!t) return res.status(404).json({ error: "Not found" });
  const stats = await journeyStats(orgId, t);
  res.json(stats);
}));

// The rows behind one of those numbers. A GET, and it writes nothing.
app.get("/journeys/:id/rows", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [t] = await query("SELECT * FROM cultivation_templates WHERE id=? AND org_id=? AND archived_at IS NULL",
    [req.params.id, orgId]);
  if (!t) return res.status(404).json({ error: "Not found" });
  const key = String(req.query.rows || "");
  const sql = JOURNEY_ROW_SQL[key];
  if (!sql) return res.status(400).json({ error: "unknown_rows",
    message: `There is no set of rows called "${key}". Ask for one of: ${Object.keys(JOURNEY_ROW_SQL).join(", ")}.` });
  const rows = await query(sql, [orgId, t.id]);
  res.json({ journeyId: t.id, rows: key, count: rows.length, donors: rows.slice(0, 1000) });
}));

// ONE definition per number, written once, used by the figure AND by the
// drill-through. A second copy is how a count stops matching its own rows.
const JOURNEY_ROW_SQL = {
  entered: `SELECT d.id, d.name, p.applied_on AS entered
              FROM cultivation_plans p JOIN donors d ON d.id=p.donor_id AND d.org_id=p.org_id
             WHERE p.org_id=? AND p.template_id=? AND d.deleted_at IS NULL
             ORDER BY p.applied_on DESC`,
  exited: `SELECT d.id, d.name, p.applied_on AS entered, p.replaced_reason AS reason
             FROM cultivation_plans p JOIN donors d ON d.id=p.donor_id AND d.org_id=p.org_id
            WHERE p.org_id=? AND p.template_id=? AND p.status='abandoned' AND d.deleted_at IS NULL
            ORDER BY p.closed_at DESC NULLS LAST`,
  completed: `SELECT d.id, d.name, p.applied_on AS entered
                FROM cultivation_plans p JOIN donors d ON d.id=p.donor_id AND d.org_id=p.org_id
               WHERE p.org_id=? AND p.template_id=? AND p.status='done' AND d.deleted_at IS NULL
               ORDER BY p.closed_at DESC NULLS LAST`,
  inIt: `SELECT d.id, d.name, p.applied_on AS entered
           FROM cultivation_plans p JOIN donors d ON d.id=p.donor_id AND d.org_id=p.org_id
          WHERE p.org_id=? AND p.template_id=? AND p.status='active' AND d.deleted_at IS NULL
          ORDER BY p.applied_on DESC`,
  onTime: `SELECT DISTINCT d.id, d.name
             FROM cultivation_plan_steps st
             JOIN cultivation_plans p ON p.id=st.plan_id
             JOIN donors d ON d.id=p.donor_id AND d.org_id=p.org_id
            WHERE p.org_id=? AND p.template_id=? AND st.status='done'
              AND st.closed_at IS NOT NULL AND st.closed_at::date <= st.due_date::date
            ORDER BY d.name`,
  late: `SELECT DISTINCT d.id, d.name
           FROM cultivation_plan_steps st
           JOIN cultivation_plans p ON p.id=st.plan_id
           JOIN donors d ON d.id=p.donor_id AND d.org_id=p.org_id
          WHERE p.org_id=? AND p.template_id=?
            AND ((st.status='done' AND st.closed_at::date > st.due_date::date)
                 OR (st.status IN ('open','pending') AND st.due_date::date < CURRENT_DATE))
          ORDER BY d.name`,
  skipped: `SELECT DISTINCT d.id, d.name, st.skip_reason AS reason
              FROM cultivation_plan_steps st
              JOIN cultivation_plans p ON p.id=st.plan_id
              JOIN donors d ON d.id=p.donor_id AND d.org_id=p.org_id
             WHERE p.org_id=? AND p.template_id=? AND st.status='skipped'
             ORDER BY d.name`,
  // A SECOND GIFT WITHIN TWELVE MONTHS OF ENTERING. Not "because of" — after.
  secondGift: `SELECT DISTINCT d.id, d.name, p.applied_on AS entered
                 FROM cultivation_plans p
                 JOIN donors d ON d.id=p.donor_id AND d.org_id=p.org_id
                WHERE p.org_id=? AND p.template_id=? AND d.deleted_at IS NULL
                  AND EXISTS (SELECT 1 FROM gifts g
                               WHERE g.donor_id=d.id AND g.org_id=d.org_id
                                 AND g.date IS NOT NULL AND g.date <> ''
                                 AND g.date::date >  p.applied_on::date
                                 AND g.date::date <= (p.applied_on::date + INTERVAL '12 months'))
                ORDER BY d.name`,
};

// The four figures, each with the sentence that defines it (the "every number
// has a sentence" rule) and the `rows` key that opens it.
async function journeyStats(orgId, t) {
  const one = async key => (await query(JOURNEY_ROW_SQL[key], [orgId, t.id])).length;
  const [inIt, onTime, late, skipped, secondGift] = await Promise.all(
    ["inIt", "onTime", "late", "skipped", "secondGift"].map(one));
  const [everRow] = await query(
    `SELECT COUNT(*)::int AS c FROM cultivation_plans WHERE org_id=? AND template_id=?`, [orgId, t.id]);
  const [entered, exited, completed] = await Promise.all(["entered", "exited", "completed"].map(one));
  return {
    journeyId: t.id, name: t.name,
    figures: [
      // PARITY-1 Part D — the four counts every journey shows.
      { key: "entered", label: "Entered", value: entered, rows: "entered",
        sentence: "Everyone who has ever gone into this journey, however it ended." },
      { key: "exited", label: "Exited", value: exited, rows: "exited",
        sentence: "People who left before the end: stopped by a person, or moved to a journey that outranks it." },
      { key: "completed", label: "Completed", value: completed, rows: "completed",
        sentence: "People who reached the end, every step done or skipped." },
      { key: "inIt", label: "In it now", value: inIt, rows: "inIt",
        sentence: "People whose journey is still running. Someone who finished, or was moved to another journey, is not counted here." },
      { key: "onTime", label: "Steps on time", value: onTime, rows: "onTime",
        sentence: "People who have completed at least one step on or before the day it was due." },
      { key: "late", label: "Steps late", value: late, rows: "late",
        sentence: "People with a step completed after its due date, or still waiting past it. Late is brass, not a failure." },
      { key: "skipped", label: "Steps skipped", value: skipped, rows: "skipped",
        sentence: "People where somebody decided not to do a step and said why. The reason is on each row." },
      { key: "secondGift", label: "Gave again within a year", value: secondGift, rows: "secondGift",
        sentence: "People who gave another gift within twelve months of entering this journey." },
    ],
    everIn: Number(everRow && everRow.c) || 0,
    // SAID BY THE ROUTE, not by a caption a redesign could drop.
    caveat: "These are counts of what happened, not a measure of what the journey caused. "
          + "Steward is not running an experiment: there is no comparison group, so none of "
          + "these numbers can tell you what would have happened without the journey.",
  };
}

// ── FIX-4 1c · THE AUDIENCE, AS SQL ───────────────────────────────────────
// The one place a filter from shared/journeyShape.js becomes a WHERE clause.
// Every one of them is an EXISTS against a table Steward already keeps, so a
// filter can narrow the set and can never invent a person.
//
// Returned as fragments + params rather than interpolated, because two of
// them (tag, stage) carry text somebody typed.
function audienceClauses(audience = {}, alias = "d") {
  const sql = [], params = [];
  if (audience.volunteers) {
    sql.push(`EXISTS (SELECT 1 FROM volunteers v WHERE v.person_id=${alias}.id AND v.org_id=${alias}.org_id)`);
  }
  if (audience.attendedEvent) {
    sql.push(`EXISTS (SELECT 1 FROM event_attendees ea WHERE ea.donor_id=${alias}.id AND ea.org_id=${alias}.org_id
                        AND lower(coalesce(ea.status,'')) = 'attended')`);
  }
  if (audience.members) {
    sql.push(`EXISTS (SELECT 1 FROM memberships m WHERE m.donor_id=${alias}.id AND m.org_id=${alias}.org_id
                        AND m.status IN ('active','grace'))`);
  }
  if (audience.recurring) {
    // WIRE-1: the same running states the Group rules read (groups.js).
    sql.push(`EXISTS (SELECT 1 FROM recurring_subscriptions rs WHERE rs.donor_id=${alias}.id AND rs.org_id=${alias}.org_id
                        AND rs.status = ANY(?::text[]))`);
    params.push(GR.ACTIVE_RECURRING_STATUSES);
  }
  if (audience.stage) {
    sql.push(`lower(coalesce(${alias}.stage,'')) = lower(?)`);
    params.push(String(audience.stage));
  }
  if (audience.tag) {
    // donors.tags is a JSON array kept as TEXT. Matched case-insensitively on
    // the whole element, so "major" does not pull in "major-prospect".
    sql.push(`EXISTS (SELECT 1 FROM jsonb_array_elements_text(
                        CASE WHEN coalesce(${alias}.tags,'') ~ '^\\s*\\[' THEN ${alias}.tags::jsonb ELSE '[]'::jsonb END) AS tg
                      WHERE lower(btrim(tg)) = lower(btrim(?)))`);
    params.push(String(audience.tag));
  }
  if (audience.giftSize) {
    const { minCents, maxCents } = audience.giftSize;
    // THE LARGEST SINGLE GIFT, not the lifetime total: "gift size" is a
    // sentence about one gift, and summing a year of $20s into a $1,000
    // major donor is the kind of quiet wrong that reaches a real person.
    if (minCents) {
      sql.push(`(SELECT COALESCE(MAX(ROUND(g.amount*100)),0) FROM gifts g
                  WHERE g.donor_id=${alias}.id AND g.org_id=${alias}.org_id) >= ?`);
      params.push(Number(minCents));
    }
    if (maxCents) {
      sql.push(`(SELECT COALESCE(MAX(ROUND(g.amount*100)),0) FROM gifts g
                  WHERE g.donor_id=${alias}.id AND g.org_id=${alias}.org_id) <= ?`);
      params.push(Number(maxCents));
    }
  }
  return { sql: sql.length ? " AND " + sql.join(" AND ") : "", params };
}

// Who qualifies for a journey's trigger inside a window, narrowed by the
// audience. One place, so the COUNT the offer shows and the rows the apply
// writes cannot disagree.
// PARITY-1 Part D · a Group in the audience narrows the same set: only the
// people in it now.
async function qualifyingDonors(orgId, t, days, audience = {}) {
  const rows = await qualifyingDonorsByTrigger(orgId, t, days, audience);
  if (!audience.groupId || !rows.length) return rows;
  const g = await GR.groupById(orgId, audience.groupId);
  const inGroup = new Set(g ? await GR.memberIds(orgId, g) : []);
  return rows.filter(r => inGroup.has(r.id));
}
async function qualifyingDonorsByTrigger(orgId, t, days, audience = {}) {
  const trigger = t.trigger_key;
  if (trigger === "by_hand") return [];
  const cut = `(CURRENT_DATE - ${Number(days)})`;
  const a = audienceClauses(audience, "d");
  if (trigger === "first_gift") {
    return await query(
      `SELECT d.id FROM donors d
        WHERE d.org_id=? AND d.deleted_at IS NULL
          AND (SELECT COUNT(*) FROM gifts g WHERE g.donor_id=d.id AND g.org_id=d.org_id) = 1
          AND EXISTS (SELECT 1 FROM gifts g WHERE g.donor_id=d.id AND g.org_id=d.org_id
                        AND g.date IS NOT NULL AND g.date <> '' AND g.date::date >= ${cut})${a.sql}`,
      [orgId, ...a.params]);
  }
  if (trigger === "gift_over") {
    const need = Number(t.trigger_amount_cents) || 0;
    if (!need) return [];
    return await query(
      `SELECT DISTINCT d.id FROM donors d JOIN gifts g ON g.donor_id=d.id AND g.org_id=d.org_id
        WHERE d.org_id=? AND d.deleted_at IS NULL
          AND g.date IS NOT NULL AND g.date <> '' AND g.date::date >= ${cut}
          AND ROUND(g.amount*100) >= ?${a.sql}`, [orgId, need, ...a.params]);
  }
  if (trigger === "new_volunteer") {
    return await query(
      `SELECT DISTINCT d.id FROM donors d JOIN volunteers v ON v.person_id=d.id AND v.org_id=d.org_id
        WHERE d.org_id=? AND d.deleted_at IS NULL AND v.created_at >= NOW() - (? || ' days')::interval${a.sql}`,
      [orgId, String(days), ...a.params]).catch(() => []);
  }
  // FIX-4 1c — the two new triggers. Both are states with a DATE on them, so
  // unlike stage_change and lapsed_return they can honestly be looked back at.
  if (trigger === "attended_event") {
    return await query(
      `SELECT DISTINCT d.id FROM donors d
         JOIN event_attendees ea ON ea.donor_id=d.id AND ea.org_id=d.org_id
         JOIN events e ON e.id=ea.event_id
        WHERE d.org_id=? AND d.deleted_at IS NULL
          AND lower(coalesce(ea.status,'')) = 'attended'
          AND COALESCE(e.date::date, ea.created_at::date) >= ${cut}${a.sql}`,
      [orgId, ...a.params]).catch(() => []);
  }
  if (trigger === "became_member") {
    return await query(
      `SELECT DISTINCT d.id FROM donors d
         JOIN memberships m ON m.donor_id=d.id AND m.org_id=d.org_id
        WHERE d.org_id=? AND d.deleted_at IS NULL
          AND m.status IN ('active','grace')
          AND m.joined_on IS NOT NULL AND m.joined_on <> '' AND m.joined_on::date >= ${cut}${a.sql}`,
      [orgId, ...a.params]).catch(() => []);
  }
  // JOURNEYS-3 — the new triggers look back with the sweep's own definition.
  const J = await journeyMod();
  if (J.SWEEP_TRIGGER_KEYS.includes(trigger) || trigger === "first_event") {
    const today = orgToday(await orgTz(orgId));                 // ORG_TZ_SEAM_OK
    const tf = t.trigger_filters || {};
    let ids = [...new Set((await lifecycleRows(orgId, trigger, today, days))
      .filter(r => trigger !== "volunteer_hours" || !tf.hours || (r.crossed || []).includes(Number(tf.hours)))
      .map(r => r.donor_id))];
    if (ids.length && a.sql) {
      const keep = new Set((await query(`SELECT d.id FROM donors d WHERE d.org_id=? AND d.id = ANY(?::text[])${a.sql}`,
        [orgId, ids, ...a.params])).map(r => r.id));
      ids = ids.filter(id => keep.has(id));
    }
    return ids.map(id => ({ id }));
  }
  // stage_change and lapsed_return are events rather than states: there is no
  // honest way to look backwards for them, so the offer says none rather than
  // guessing. They still fire forwards, which is what they are for.
  return [];
}

// Put somebody in a journey by hand. This is the `by_hand` trigger and the
// "apply to everyone who qualifies" button, and it goes through the SAME
// engine as every automatic trigger — one path in.
app.post("/journeys/:id/apply", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const J = await journeyMod();
  const [t] = await query("SELECT * FROM cultivation_templates WHERE id=? AND org_id=? AND archived_at IS NULL",
    [req.params.id, req.user.orgId]);
  if (!t) return res.status(404).json({ error: "Not found" });

  const joinOthers = !(req.body && req.body.joinOthers === false);
  let ids = Array.isArray(req.body && req.body.donorIds) ? req.body.donorIds.map(String) : null;
  if (!ids && req.body && req.body.allQualifying === true) {
    const days = Math.min(365, Math.max(1, Number(req.body.days) || 90));
    // THE SAME AUDIENCE AND THE SAME SPLIT THE COUNT WAS TAKEN WITH. The
    // confirm said a number; this puts in exactly the people behind it.
    const audience = J.validateAudience(req.body.audience || {});
    ids = (await applySplit(req.user.orgId, t, days, audience, joinOthers)).willJoin.map(r => r.id);
  }
  if (!ids || !ids.length) return res.status(400).json({ error: "no_donors", message: "Name who should go in, or ask for everyone who qualifies." });
  if (ids.length > 2000) return res.status(400).json({ error: "too_many", message: "That is more than 2,000 people at once. Narrow it first." });

  const out = { started: [], skipped: [] };
  for (const id of ids) {
    // The engine is told the journey's OWN trigger, so a by-hand apply of a
    // gift_over journey still records the trigger it belongs to. `forceId`
    // pins the journey: this is a person choosing one, not a rule picking.
    const r = await maybeStartJourney(req.user.orgId, id, "by_hand", { forceJourneyId: t.id, joinOthers });
    (r.started ? out.started : out.skipped).push({ donorId: id, ...r });
  }
  const n = out.started.length;
  res.json({ journeyId: t.id, name: t.name, started: n,
    skipped: out.skipped.length, detail: out,
    planIds: out.started.map(r => r.planId),
    sentence: `${n} ${n === 1 ? "person" : "people"} joined ${t.name}.` });
}));

// JOURNEYS-3 · UNDO AN APPLY. Takes the plans that apply made back out: their
// steps, the threads and review drafts their steps opened, their timeline
// lines, and puts back any step another journey moved to make room and any
// exclusive journey they replaced. Then each person's soonest remaining step
// takes their thread again. Only plans of this journey, in this org, still
// running.
app.post("/journeys/:id/apply/undo", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [t] = await query("SELECT id, name FROM cultivation_templates WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!t) return res.status(404).json({ error: "Not found" });
  const want = Array.isArray(req.body && req.body.planIds) ? req.body.planIds.map(String).slice(0, 2000) : [];
  const plans = want.length ? await query(
    `SELECT * FROM cultivation_plans WHERE org_id=? AND template_id=? AND status='active' AND id = ANY(?::text[])`,
    [orgId, t.id, want]) : [];
  if (!plans.length) return res.status(404).json({ error: "nothing_to_undo", sentence: "Those people are no longer in it, so there is nothing to undo." });
  const planIds = plans.map(p => p.id);
  const steps = await query(`SELECT id, thread_id, status FROM cultivation_plan_steps WHERE org_id=? AND plan_id = ANY(?::text[])`, [orgId, planIds]);
  const stepIds = steps.map(s => s.id);
  // Steps of OTHER journeys that moved to make room go back to their dates,
  // and the lines that said they moved come off the timeline.
  const movedIds = (await query(`SELECT id FROM cultivation_plan_steps WHERE org_id=? AND moved_by_plan_id = ANY(?::text[])`,
    [orgId, planIds])).map(r => r.id);
  if (movedIds.length) await run(`DELETE FROM interactions WHERE org_id=? AND created_by=? AND metadata->>'via'='journey_spacing'
                                    AND metadata->>'step_id' = ANY(?::text[])`, [orgId, JOURNEY_ACTOR.id, movedIds]);
  await run(`UPDATE cultivation_plan_steps SET due_date=moved_from, moved_from=NULL, moved_reason=NULL, moved_by_plan_id=NULL
              WHERE org_id=? AND moved_by_plan_id = ANY(?::text[]) AND status='pending' AND moved_from IS NOT NULL`, [orgId, planIds]);
  for (const s of steps.filter(x => x.status === "open" && x.thread_id)) {
    await run(`DELETE FROM threads WHERE id=? AND org_id=? AND closed_at IS NULL`, [s.thread_id, orgId]);
  }
  if (stepIds.length) {
    await run(`DELETE FROM milestone_drafts WHERE org_id=? AND milestone_key = ANY(?::text[]) AND status='pending_review'`,
      [orgId, stepIds.map(id => `journey-step:${id}`)]);
    await run(`DELETE FROM interactions WHERE org_id=? AND created_by=? AND metadata->>'step_id' = ANY(?::text[])`,
      [orgId, JOURNEY_ACTOR.id, stepIds]);
  }
  const lineIds = plans.map(p => p.start_interaction_id).filter(Boolean);
  if (lineIds.length) await run(`DELETE FROM interactions WHERE org_id=? AND id = ANY(?::text[]) AND created_by=?`, [orgId, lineIds, JOURNEY_ACTOR.id]);
  // An exclusive journey these replaced is running again.
  for (const p of plans.filter(x => x.replaced_plan_id)) {
    await run(`UPDATE cultivation_plans SET status='active', closed_at=NULL, replaced_reason=NULL
                WHERE id=? AND org_id=? AND status='abandoned'`, [p.replaced_plan_id, orgId]).catch(() => null);
    await run(`UPDATE cultivation_plan_steps SET status='pending', closed_at=NULL, closed_by=NULL, closed_by_name=NULL, skip_reason=NULL, thread_id=NULL
                WHERE plan_id=? AND org_id=? AND status='skipped' AND closed_by=?`, [p.replaced_plan_id, orgId, JOURNEY_ACTOR.id]);
  }
  await run(`DELETE FROM cultivation_plans WHERE org_id=? AND id = ANY(?::text[])`, [orgId, planIds]);
  for (const donorId of [...new Set(plans.map(p => p.donor_id))]) {
    await advanceCultivationPlan(orgId, donorId, { actorId: actor(req).id, actorName: actor(req).name });
  }
  if (req.audit) req.audit.entity("journey", t.id, t.name);
  res.json({ journeyId: t.id, undone: plans.length,
    sentence: `${plans.length} ${plans.length === 1 ? "person was" : "people were"} taken back out of ${t.name}.` });
}));

// JOURNEYS-3 · JOURNEY SETTINGS: the touch gap. No two steps from different
// journeys land within this many days for one person. 7 by default.
app.put("/journeys/settings", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const J = await journeyMod();
  const n = Number(req.body && req.body.touchGapDays);
  if (!Number.isInteger(n) || n < J.TOUCH_GAP_MIN || n > J.TOUCH_GAP_MAX) {
    return res.status(400).json({ error: "invalid_gap", sentence: `Pick a whole number of days from ${J.TOUCH_GAP_MIN} to ${J.TOUCH_GAP_MAX}.` });
  }
  await run(`UPDATE orgs SET journey_touch_gap_days=? WHERE id=?`, [n, req.user.orgId]);
  res.json({ touchGapDays: n, sentence: `No more than one touch every ${n} ${n === 1 ? "day" : "days"} for anyone, across all their journeys.` });
}));

// JOURNEYS-3 · EVERY JOURNEY A PERSON IS IN, with the next step from each.
// A GET, and it writes nothing.
app.get("/donors/:id/journeys", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  if (!(await orgOwns("donors", req.params.id, orgId))) return res.status(404).json({ error: "Donor not found" });
  const plans = await query(
    `SELECT p.id, p.template_id, p.template_name, p.priority, p.applied_on, COALESCE(ct.exclusive, false) AS exclusive
       FROM cultivation_plans p LEFT JOIN cultivation_templates ct ON ct.id = p.template_id AND ct.org_id = p.org_id
      WHERE p.org_id=? AND p.donor_id=? AND p.status='active' ORDER BY p.priority DESC, p.applied_on`, [orgId, req.params.id]);
  const steps = plans.length ? await query(
    `SELECT id, plan_id, seq, label, due_date, status, moved_reason FROM cultivation_plan_steps
      WHERE org_id=? AND plan_id = ANY(?::text[]) ORDER BY seq`, [orgId, plans.map(p => p.id)]) : [];
  res.json({
    touchGapDays: await journeyTouchGap(orgId),
    journeys: plans.map(p => {
      const mine = steps.filter(s => s.plan_id === p.id);
      const next = mine.find(s => s.status === "open") || mine.find(s => s.status === "pending") || null;
      return { planId: p.id, journeyId: p.template_id, name: p.template_name, priority: p.priority, exclusive: !!p.exclusive,
        enteredOn: p.applied_on, total: mine.length, done: mine.filter(s => s.status === "done" || s.status === "skipped").length,
        next: next ? { id: next.id, seq: next.seq, label: next.label, dueDate: next.due_date,
                       open: next.status === "open", movedReason: next.moved_reason || null } : null };
    }),
  });
}));

// POST /donors/:id/plan — apply a template, dates offset from today.
app.post("/donors/:id/plan", requireAuth, requireCrm, checkWriteAccess, wrap(async (req, res) => {
  const PL = await planMod();
  const orgId = req.user.orgId;
  const [donor] = await query("SELECT id, name, assigned_to, assigned_to_name FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL",
    [req.params.id, orgId]);
  if (!donor) return res.status(404).json({ error: "Donor not found" });
  const [tpl] = await query("SELECT * FROM cultivation_templates WHERE id=? AND org_id=?", [req.body.templateId, orgId]);
  if (!tpl) return res.status(404).json({ error: "Template not found" });
  const v = PL.validateTemplate({ name: tpl.name, steps: tpl.steps });
  if (!v.ok) return res.status(400).json({ error: "That template is no longer valid: " + v.errors[0].message, code: "invalid_template" });

  const org = await orgTz(orgId);
  const today = orgToday(org);                                // ORG_TZ_SEAM_OK
  const steps = PL.planFromTemplate({ steps: v.steps, today }, orgTime.addDays);

  const planId = "cp_" + uuid().slice(0, 10);
  // ONE ACTIVE PLAN PER PERSON, decided by the partial unique index rather than
  // by a read-then-write — two officers applying a plan in the same second
  // cannot both land.
  const ins = await query(
    `INSERT INTO cultivation_plans (id,org_id,donor_id,template_id,template_name,applied_on,status,owner_id,owner_name,created_by,created_by_name)
     SELECT ?::text,?::text,?::text,?::text,?::text,?::text,'active',?::text,?::text,?::text,?::text
      WHERE NOT EXISTS (SELECT 1 FROM cultivation_plans x WHERE x.org_id=?::text AND x.donor_id=?::text AND x.status='active')
     RETURNING id`,
    [planId, orgId, donor.id, tpl.id, tpl.name, today,
     donor.assigned_to || req.user.userId, donor.assigned_to_name || actor(req).name,
     actor(req).id, actor(req).name, orgId, donor.id]);
  if (!ins.length) {
    const [cur] = await query("SELECT id, template_name FROM cultivation_plans WHERE org_id=? AND donor_id=? AND status='active'", [orgId, donor.id]);
    return res.status(409).json({ code: "plan_already_active", planId: cur?.id || null,
      error: `${donor.name} is already working through "${cur?.template_name || "a plan"}". Finish or stop that one first.` });
  }
  for (const s of steps) {
    await run(
      `INSERT INTO cultivation_plan_steps (id,org_id,plan_id,seq,step_type,label,due_date,status)
       VALUES (?,?,?,?,?,?,?,'pending')`,
      ["cs_" + uuid().slice(0, 10), orgId, planId, s.seq, s.type, s.label, s.dueDate]);
  }
  // The first step opens now — or waits, if this person already has an open
  // follow-up of their own. Both are correct; the sentence says which.
  await advanceCultivationPlan(orgId, donor.id, { actorId: actor(req).id, actorName: actor(req).name, today });
  await run(
    `INSERT INTO interactions (id,org_id,donor_id,type,date,note,created_by,logged_by_name)
     VALUES (?,?,?,'note',?,?,?,?)`,
    ["int_" + uuid().slice(0, 10), orgId, donor.id, today,
     `Cultivation plan applied: ${tpl.name} (${steps.length} ${steps.length === 1 ? "step" : "steps"})`,
     actor(req).id, actor(req).name]).catch(e => console.error("[plan] timeline:", e.message));
  res.status(201).json(await readPlan(orgId, planId));
}));

// The one reader, so the screen and the suite see the same shape.
async function readPlan(orgId, planId) {
  const PL = await planMod();
  const [plan] = await query("SELECT * FROM cultivation_plans WHERE id=? AND org_id=?", [planId, orgId]);
  if (!plan) return null;
  const steps = await query("SELECT * FROM cultivation_plan_steps WHERE plan_id=? ORDER BY seq", [planId]);
  const shaped = steps.map(s => ({
    id: s.id, seq: Number(s.seq), type: s.step_type, label: s.label,
    dueDate: s.due_date, status: s.status, threadId: s.thread_id || null,
    closedByName: s.closed_by_name || null, closedAt: s.closed_at || null,
  }));
  const prog = PL.planProgress(shaped);
  return {
    id: plan.id, donorId: plan.donor_id, templateId: plan.template_id, templateName: plan.template_name,
    appliedOn: plan.applied_on, status: plan.status,
    ownerName: plan.owner_name || "", appliedByName: plan.created_by_name || "",
    steps: shaped, progress: prog, sentence: PL.planSentence(prog, plan.template_name),
  };
}

// GET /donors/:id/plan — the plan on this person, active or the last one.
app.get("/donors/:id/plan", requireAuth, wrap(async (req, res) => {
  if (!(await orgOwns("donors", req.params.id, req.user.orgId))) return res.status(404).json({ error: "Donor not found" });
  const [p] = await query(
    `SELECT p.id FROM cultivation_plans p WHERE p.org_id=? AND p.donor_id=?
      ORDER BY (p.status='active') DESC,
               -- JOURNEYS-3: of several, the one whose step holds their thread
               EXISTS (SELECT 1 FROM cultivation_plan_steps s WHERE s.plan_id=p.id AND s.status='open') DESC,
               p.priority DESC, p.created_at DESC LIMIT 1`, [req.user.orgId, req.params.id]);
  if (!p) return res.json({ plan: null });
  res.json({ plan: await readPlan(req.user.orgId, p.id) });
}));

// POST /plan-steps/:id/skip — skipping is RECORDED as skipped, never deleted and
// never quietly marked done. "We decided not to do that" is the fact.
// ── THREAD-2a · MARK DONE ASKS FOR ONE LINE, AND SCHEDULES THE NEXT ──────
// The line is not paperwork: closing a thread has ALWAYS required a reason
// (the BUILD-81 CHECK constraint), because a follow-up that closed with no
// record of what happened is a follow-up nobody can learn from. This route is
// that same close, named for what the officer is actually doing, and it
// advances the plan so the next step opens in the same breath.
//
// IT SENDS NOTHING. It writes a logged interaction and opens the next step.
// That is the entire definition of a journey step completing.
app.post("/plan-steps/:id/done", requireAuth, requireCrm, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [s] = await query(
    `SELECT st.*, p.donor_id, p.status AS plan_status FROM cultivation_plan_steps st
       JOIN cultivation_plans p ON p.id = st.plan_id
      WHERE st.id=? AND st.org_id=?`, [req.params.id, orgId]);
  if (!s) return res.status(404).json({ error: "Step not found" });
  if (s.status === "done" || s.status === "skipped") return res.status(409).json({ error: "That step is already closed." });

  const note = String((req.body && req.body.note) || "").replace(/\s+/g, " ").trim().slice(0, 500);
  if (!note) {
    return res.status(400).json({
      error: "note_required",
      message: `One line about what happened. It goes on ${"their"} record, and it is what makes the next step worth anything.`,
    });
  }
  const today = orgToday(await orgTz(orgId));                 // ORG_TZ_SEAM_OK

  // THE INTERACTION IS WRITTEN FIRST, AND THE THREAD CLOSES ONTO IT.
  //
  // `threads_close_honest` only allows two honest closes: an OUTCOME, which
  // must name the interaction that was its outcome, or a DISMISSAL, which
  // must give a reason. A first cut of this route closed with
  // `close_kind='done'` and the database refused it — correctly. A thread
  // that closed with no logged thing behind it is exactly the hole that
  // constraint exists to keep shut, and "mark done" is the most tempting
  // place in the product to punch through it.
  //
  // So: the line becomes a real interaction on the record, and the thread
  // closes pointing at it. That is also what makes a completed journey step
  // count towards Last contact — a step done that left no trace would leave
  // the record saying nobody had spoken to them.
  const intId = "int_" + uuid().slice(0, 10);
  await run(
    `INSERT INTO interactions (id,org_id,donor_id,type,date,note,created_by,logged_by_name)
     VALUES (?,?,?,?,?,?,?,?)`,
    [intId, orgId, s.donor_id,
     s.step_type === "thank" ? "call" : s.step_type === "send" ? "email" : "note",
     today, `${s.label}: ${note}`, actor(req).id, actor(req).name]);
  if (s.thread_id) {
    await run(`UPDATE threads SET closed_at=NOW(), close_kind='outcome', closing_interaction_id=?
                WHERE id=? AND org_id=? AND closed_at IS NULL`, [intId, s.thread_id, orgId]);
  }
  await run(`UPDATE cultivation_plan_steps SET status='done', closed_at=NOW(), closed_by=?, closed_by_name=?, done_note=?
              WHERE id=? AND org_id=?`, [actor(req).id, actor(req).name, note, req.params.id, orgId]);

  // AND SCHEDULES THE NEXT. Same call the rest of the plan machinery makes.
  await advanceCultivationPlan(orgId, s.donor_id, { actorId: actor(req).id, actorName: actor(req).name, today });
  res.json({ plan: await readPlan(orgId, s.plan_id), done: req.params.id, note, interactionId: intId });
}));

app.post("/plan-steps/:id/skip", requireAuth, requireCrm, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [s] = await query(
    `SELECT st.*, p.donor_id, p.status AS plan_status FROM cultivation_plan_steps st
       JOIN cultivation_plans p ON p.id = st.plan_id
      WHERE st.id=? AND st.org_id=?`, [req.params.id, orgId]);
  if (!s) return res.status(404).json({ error: "Step not found" });
  if (s.status === "done" || s.status === "skipped") return res.status(409).json({ error: "That step is already closed." });
  // Skipping the OPEN step dismisses its thread with a reason — a thread may
  // not close without one (the BUILD-81 CHECK constraint), and "we decided not
  // to" is exactly the kind of reason that rule exists to preserve.
  if (s.status === "open" && s.thread_id) {
    await run("UPDATE threads SET closed_at=NOW(), close_kind='dismissed', close_reason='handled_outside' WHERE id=? AND org_id=? AND closed_at IS NULL",
      [s.thread_id, orgId]);
  }
  // THREAD-2a — SKIP ASKS WHY, IN ONE TAP. The reason is a short phrase, not
  // an essay, and it is stored: six months later "why did nobody send her the
  // impact report?" has an answer. It is optional at the route (an older
  // client, a bulk skip during a replacement) and the screen makes it one tap.
  const why = String((req.body && req.body.reason) || "").replace(/\s+/g, " ").trim().slice(0, 200) || null;
  await run("UPDATE cultivation_plan_steps SET status='skipped', closed_at=NOW(), closed_by=?, closed_by_name=?, skip_reason=? WHERE id=? AND org_id=?",
    [actor(req).id, actor(req).name, why, req.params.id, orgId]);
  if (why) {
    await run(
      `INSERT INTO interactions (id,org_id,donor_id,type,date,note,created_by,logged_by_name)
       VALUES (?,?,?,'note',?,?,?,?)`,
      ["int_" + uuid().slice(0, 10), orgId, s.donor_id, orgToday(await orgTz(orgId)),  // ORG_TZ_SEAM_OK
       `Skipped "${s.label}": ${why}`, actor(req).id, actor(req).name])
      .catch(e => console.error("[journey] skip note:", e.message));
  }
  await advanceCultivationPlan(orgId, s.donor_id, { actorId: actor(req).id, actorName: actor(req).name });
  const out = await readPlan(orgId, s.plan_id);
  res.json({ plan: out, skipped: req.params.id, reason: why });
}));

// POST /plans/:id/stop — the officer decides the plan is over. The steps keep
// what they were, so "we got three steps in and stopped" stays readable.
app.post("/plans/:id/stop", requireAuth, requireCrm, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [p] = await query("SELECT * FROM cultivation_plans WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!p) return res.status(404).json({ error: "Plan not found" });
  if (p.status !== "active") return res.status(409).json({ error: "That plan is not active." });
  const [open] = await query("SELECT id, thread_id FROM cultivation_plan_steps WHERE plan_id=? AND status='open'", [p.id]);
  if (open && open.thread_id) {
    await run("UPDATE threads SET closed_at=NOW(), close_kind='dismissed', close_reason='handled_outside' WHERE id=? AND org_id=? AND closed_at IS NULL",
      [open.thread_id, orgId]);
    await run("UPDATE cultivation_plan_steps SET status='skipped', closed_at=NOW(), closed_by=?, closed_by_name=? WHERE id=?",
      [actor(req).id, actor(req).name, open.id]);
  }
  await run("UPDATE cultivation_plans SET status='abandoned', closed_at=NOW() WHERE id=? AND org_id=?", [p.id, orgId]);
  res.json({ plan: await readPlan(orgId, p.id) });
}));

// ── BUILD-99 (major gifts) Part 4 — THE PROSPECT BRIEF ─────────────────────
// "Brief me" on a person: one page an officer reads in the car, written from the
// organisation's own rows, every sentence citing one.
//
// THE GUARANTEE IS THE SCHEMA, NOT THE PROMPT. shared/briefShape.js has no
// numeric field anywhere in it, so a model that wanted to assert a capacity has
// nowhere to put it; every figure on the finished page is rendered HERE from the
// rows. A prompt is a request; this is the absence of a place to say it.
async function briefShapeMod() { return import("../shared/briefShape.js"); }

// WHAT THE MODEL IS HANDED, AND NOTHING ELSE. Each row goes over as a line with
// a `kind:id` reference, and Steward keeps the same reference set to validate the
// citations against — so a cited row it never saw cannot survive.
async function briefRowsFor(orgId, donorId) {
  const P = await proposalMod();
  const V = await import("../shared/vocabulary.js");
  const [org] = await query("SELECT * FROM orgs WHERE id=?", [orgId]);
  const t = V.makeT(org && org.vocabulary_json);
  const [donor] = await query(
    `SELECT id, name, email, kind, stage, suggested_stage, total_giving, gift_count, first_gift_date,
            last_gift_date, last_gift_amount, notes, assigned_to_name, household_id, deceased, do_not_contact
       FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL`, [donorId, orgId]);
  if (!donor) return null;

  const refs = new Set([`person:${donor.id}`]);
  const lines = [];
  const money = require("../money");
  const givingWord = t("giver_singular") || "donor";

  lines.push(`person:${donor.id} — ${donor.name}${donor.kind === "organisation" ? " (an organisation)" : ""}, `
    + `${money.formatCentsPlain(toCents(donor.total_giving) || 0)} given in total across ${Number(donor.gift_count) || 0} gifts, `
    + `first on ${donor.first_gift_date || "no recorded date"}, most recently on ${donor.last_gift_date || "no recorded date"}`
    + `${donor.stage ? `, at the stage "${donor.stage}"` : ""}. This organisation calls somebody like this a ${givingWord}.`);

  // GIFTS — the last twelve, each its own row, with its fund and how it came in.
  const gifts = await query(
    `SELECT g.id, g.amount, g.date, g.type, g.payment_method, g.campaign, f.name AS fund_name
       FROM gifts g LEFT JOIN fin_funds f ON f.id = g.fund_id AND f.org_id = g.org_id
      WHERE g.org_id=? AND g.donor_id=? AND g.is_sample IS NOT TRUE
      ORDER BY g.date DESC, g.id LIMIT 12`, [orgId, donorId]);
  for (const g of gifts) {
    refs.add(`gift:${g.id}`);
    lines.push(`gift:${g.id} — ${money.formatCentsPlain(toCents(g.amount) || 0)} on ${g.date}`
      + `${g.fund_name ? ` to ${t("fund_singular") || "fund"} "${g.fund_name}"` : ""}`
      + `${g.campaign ? `, appeal "${g.campaign}"` : ""}${g.payment_method ? `, by ${g.payment_method}` : ""}.`);
  }

  // PLEDGES — a promise is not money, and the brief must not read it as one.
  for (const p of await query(
    `SELECT id, amount, due_date, status FROM pledges WHERE org_id=? AND donor_id=? ORDER BY due_date DESC LIMIT 6`, [orgId, donorId])) {
    refs.add(`pledge:${p.id}`);
    lines.push(`pledge:${p.id} — a pledge of ${money.formatCentsPlain(toCents(p.amount) || 0)} due ${p.due_date}, currently ${p.status}. A pledge is a promise, not money received.`);
  }

  // HOUSEHOLD AND RELATED PEOPLE.
  if (donor.household_id) {
    const [h] = await query("SELECT id, name FROM households WHERE id=? AND org_id=?", [donor.household_id, orgId]);
    if (h) {
      refs.add(`household:${h.id}`);
      const members = await query("SELECT name FROM donors WHERE org_id=? AND household_id=? AND id<>? AND deleted_at IS NULL", [orgId, h.id, donorId]);
      lines.push(`household:${h.id} — in the household "${h.name}"${members.length ? `, with ${members.map(m => m.name).join(" and ")}` : ""}.`);
    }
  }
  // SOFT CREDITS (BUILD-98 Part 1) — gifts that were somebody else's money.
  for (const sc of await query(
    `SELECT sc.id, sc.role, g.id AS gift_id, g.amount, g.date, d.name AS giver
       FROM gift_soft_credits sc
       JOIN gifts g ON g.id = sc.gift_id AND g.org_id = sc.org_id
       JOIN donors d ON d.id = g.donor_id AND d.org_id = g.org_id
      WHERE sc.org_id=? AND sc.donor_id=? ORDER BY g.date DESC LIMIT 6`, [orgId, donorId]).catch(() => [])) {
    refs.add(`softcredit:${sc.id}`);
    lines.push(`softcredit:${sc.id} — soft-credited for ${money.formatCentsPlain(toCents(sc.amount) || 0)} given by ${sc.giver} on ${sc.date}`
      + `${sc.role ? ` as ${sc.role}` : ""}. The money was ${sc.giver}'s; this is recognition, not their own giving.`);
  }

  // THE OPEN PROPOSAL.
  for (const o of await query(
    `SELECT o.id, o.name, o.target_amount, o.proposal_stage, o.probability, o.notes, f.name AS fund_name,
            to_char(o.expected_close,'YYYY-MM-DD') AS expected_close_civil
       FROM opportunities o LEFT JOIN fin_funds f ON f.id = o.fund_id AND f.org_id = o.org_id
      WHERE o.org_id=? AND o.donor_id=? AND o.proposal_stage = ANY(?::text[])
      ORDER BY o.expected_close NULLS LAST LIMIT 3`, [orgId, donorId, P.OPEN_STAGE_KEYS])) {
    refs.add(`proposal:${o.id}`);
    lines.push(`proposal:${o.id} — an open ask of ${money.formatCentsPlain(toCents(o.target_amount) || 0)} for "${o.name}"`
      + `${o.fund_name ? ` (${o.fund_name})` : ""}, at stage "${P.stageLabel(o.proposal_stage)}"`
      + `${o.probability != null ? `, which the officer put at ${o.probability} per cent` : ", with no probability set"}`
      + `${o.expected_close_civil ? `, expected to close ${o.expected_close_civil}` : ""}`
      + `${o.notes ? `. The officer's note on it: "${String(o.notes).slice(0, 400)}"` : "."}`);
  }

  // THE LAST FIVE CONVERSATIONS, QUOTED.
  for (const i of await query(
    `SELECT id, type, date, note, logged_by_name FROM interactions
      WHERE org_id=? AND donor_id=? AND type = ANY(ARRAY['call','meeting','email','ask','note','stewardship'])
        AND COALESCE(note,'') <> '' ORDER BY date DESC, created_at DESC LIMIT 5`, [orgId, donorId])) {
    refs.add(`conversation:${i.id}`);
    lines.push(`conversation:${i.id} — ${i.type} on ${i.date}${i.logged_by_name ? ` logged by ${i.logged_by_name}` : ""}: "${String(i.note).slice(0, 500)}"`);
  }

  // THE PLAN'S NEXT STEP.
  const [plan] = await query("SELECT id, template_name FROM cultivation_plans WHERE org_id=? AND donor_id=? AND status='active'", [orgId, donorId]);
  if (plan) {
    refs.add(`plan:${plan.id}`);
    const [openStep] = await query("SELECT seq, label, due_date FROM cultivation_plan_steps WHERE plan_id=? AND status='open'", [plan.id]);
    const [nextStep] = await query("SELECT seq, label, due_date FROM cultivation_plan_steps WHERE plan_id=? AND status='pending' ORDER BY seq LIMIT 1", [plan.id]);
    const s = openStep || nextStep;
    lines.push(`plan:${plan.id} — on the cultivation plan "${plan.template_name}"`
      + (s ? `; ${openStep ? "the open step" : "the next step"} is "${s.label}", due ${s.due_date}.` : "; every step is closed."));
  }

  // WHAT THE OFFICER WROTE.
  if (String(donor.notes || "").trim()) {
    refs.add(`note:${donor.id}`);
    lines.push(`note:${donor.id} — the note on their record reads: "${String(donor.notes).slice(0, 1200)}"`);
  }

  // The grounded numeric set: every figure that genuinely appears in the rows,
  // so `ungroundedClaims` can tell a fact from an invented rule.
  // THE MONEY SEAM, not Math.round — `tests/money-cents.test.js` is right that a
  // bare `Math.round(Number(x))` on a dollars value is the banned shape wherever
  // it appears, and "it is only feeding a text check" is not an exemption: the
  // next person to copy this line will not be feeding a text check.
  const grounded = [];
  for (const g of gifts) { const c = toCents(g.amount); if (c != null) grounded.push(toDollars(c), c); }
  grounded.push(Number(donor.gift_count) || 0);
  { const c = toCents(donor.total_giving); if (c != null) grounded.push(toDollars(c), c); }
  for (const l of lines) for (const m of String(l).matchAll(/\d+(?:\.\d+)?/g)) grounded.push(Number(m[0]));

  return { donor, org, t, refs, lines, grounded: [...new Set(grounded)], giftCount: gifts.length };
}

// GET /donors/:id/brief-rows — EXACTLY what the model would be handed, and
// nothing else. This is not a test seam: the brief's promise is that every line
// rests on a row you can open, and this is that list. It also means the row
// gathering — which is Steward's code, not a model's — is provable with no key
// configured at all.
app.get("/donors/:id/brief-rows", requireAuth, requireCrm, wrap(async (req, res) => {
  const ctx = await briefRowsFor(req.user.orgId, req.params.id);
  if (!ctx) return res.status(404).json({ error: "Donor not found" });
  res.json({
    donorId: ctx.donor.id, donorName: ctx.donor.name,
    refs: [...ctx.refs], lines: ctx.lines, groundedValues: ctx.grounded,
  });
}));

// POST /donors/:id/brief — write it, validate it, log it as an agent run.
app.post("/donors/:id/brief", requireAuth, requireCrm, checkWriteAccess, wrap(async (req, res) => {
  const B = await briefShapeMod();
  const TH = await thresholdsMod();
  const orgId = req.user.orgId;
  // THE DONOR IS CHECKED FIRST, AND THAT ORDER IS THE POINT. The gate below
  // answers 503 when no key is configured, and running it first meant a probe
  // with ANOTHER ORG's donor id got 503 instead of 404 — breaking "404 is the one
  // answer" for a cross-tenant read and telling the caller both that the route
  // exists and what Steward's key state is. Found by tenant-matrix §3.
  const ctx = await briefRowsFor(orgId, req.params.id);
  if (!ctx) return res.status(404).json({ error: "Donor not found" });

  const gate = await agentGate(orgId);
  // THE ABSENCE HAS A NAME. No key configured is Steward's state, not the org's,
  // and the honest answer is that the control is unavailable — never a 500 and
  // never an invented brief.
  if (!gate.ok) return res.status(503).json({ error: "brief_unavailable", reason: gate.reason,
    message: gate.reason === "ai_disabled" ? AI_OFF_MESSAGE : undefined });

  const runId = "arun_" + uuid().slice(0, 10);
  await run(`INSERT INTO agent_runs (id,org_id,status,plan,read_summary) VALUES (?,?,?,?,?)`,
    [runId, orgId, "running", JSON.stringify({ kind: "prospect_brief", donorId: ctx.donor.id }),
     `${ctx.refs.size} rows on ${ctx.donor.name}`]);

  const system = [
    "You are writing a one-page brief for a fundraiser who is about to go and see somebody.",
    "",
    "You are given ROWS from this organisation's own records. Each row starts with a reference of the form kind:id.",
    "Write short, plain sentences about what those rows say. Every sentence must cite the references it rests on, exactly as given.",
    "",
    "RULES, and the first one is the whole job:",
    "- You may say NOTHING about this person that is not in the rows. No capacity, no wealth, no means, no guess about what they could give.",
    "- Use no figure that is not in the rows you were handed. Never state a rule about how giving works (no 'donors who give twice usually…').",
    "- A pledge is a promise, not money received. A soft credit is recognition, not their own giving. Say so if you mention them.",
    "- Quote a conversation rather than summarising away the words the officer chose.",
    "- Leave a section out if the rows say nothing about it. Do not pad.",
    "- Use this organisation's own vocabulary where the rows give it.",
    "- The headline names who this is and why she is reading it, and contains no figure.",
  ].join("\n");
  const user = [`The rows, on ${ctx.donor.name}:`, "", ...ctx.lines, "", "Write the brief."].join("\n");

  let raw = null, err = null;
  try {
    const client = anthropicFor(orgId);
    const msg = await client.messages.create({
      model: AGENT_MODEL, max_tokens: 2000, system,
      tools: [{ name: "brief", description: "The one-page brief she reads in the car.", strict: true, input_schema: B.BRIEF_SCHEMA }],
      tool_choice: { type: "tool", name: "brief" },
      messages: [{ role: "user", content: user }],
    });
    raw = (msg.content || []).find(b => b.type === "tool_use" && b.name === "brief")?.input || null;
  } catch (e) { err = e.message || String(e); }

  if (!raw) {
    await run("UPDATE agent_runs SET status='failed', finished_at=NOW(), error=? WHERE id=?", [err || "no brief returned", runId]);
    return res.status(502).json({ error: "The brief could not be written just now.", runId });
  }

  const checked = B.validateBrief(raw, {
    rows: ctx.refs,
    ungrounded: (text, opts) => TH.ungroundedClaims(text, opts),
    groundedValues: ctx.grounded,
  });
  await run(
    `UPDATE agent_runs SET status='done', finished_at=NOW(), actions=?, declined=?, withheld=?, withheld_reason=? WHERE id=?`,
    [JSON.stringify({ brief: checked, donorId: ctx.donor.id }), checked.dropped.length, checked.dropped.length,
     checked.dropped.length ? B.droppedSentence(checked.dropped) : null, runId]);

  res.json({
    runId, donorId: ctx.donor.id, donorName: ctx.donor.name,
    headline: checked.headline, sections: checked.sections,
    dropped: checked.dropped, droppedSentence: B.droppedSentence(checked.dropped),
    rowsRead: ctx.refs.size, footer: B.BRIEF_FOOTER,
  });
}));

// GET /briefs/:runId — read one back. It is an agent run, so it is on the
// Activity screen with everything else the agent did.
app.get("/briefs/:runId", requireAuth, wrap(async (req, res) => {
  const B = await briefShapeMod();
  const [r] = await query("SELECT * FROM agent_runs WHERE id=? AND org_id=?", [req.params.runId, req.user.orgId]);
  if (!r || !r.actions || !r.actions.brief) return res.status(404).json({ error: "Brief not found" });
  const [d] = await query("SELECT id, name FROM donors WHERE id=? AND org_id=?", [r.actions.donorId, req.user.orgId]);
  res.json({
    runId: r.id, donorId: r.actions.donorId, donorName: d ? d.name : "",
    ...r.actions.brief, droppedSentence: B.droppedSentence(r.actions.brief.dropped || []),
    writtenAt: r.finished_at, rowsRead: r.read_summary, footer: B.BRIEF_FOOTER,
  });
}));

// GET /briefs/:runId/pdf — the page she prints for the car, on the org's
// letterhead, through the same renderer discipline the acknowledgment letters use.
app.get("/briefs/:runId/pdf", requireAuth, wrap(async (req, res) => {
  const B = await briefShapeMod();
  const [r] = await query("SELECT * FROM agent_runs WHERE id=? AND org_id=?", [req.params.runId, req.user.orgId]);
  if (!r || !r.actions || !r.actions.brief) return res.status(404).json({ error: "Brief not found" });
  const [org] = await query("SELECT name, legal_name, receipt_address, brand_accent, logo_data FROM orgs WHERE id=?", [req.user.orgId]);
  const [d] = await query("SELECT name FROM donors WHERE id=? AND org_id=?", [r.actions.donorId, req.user.orgId]);
  const pdf = await renderBriefPdf({
    org: { display: org.legal_name || org.name, receipt_address: org.receipt_address,
           brand_accent: org.brand_accent, logo_data: org.logo_data },
    donorName: d ? d.name : "",
    brief: r.actions.brief,
    footer: B.BRIEF_FOOTER,
    droppedSentence: B.droppedSentence(r.actions.brief.dropped || []),
    sectionTitle: B.sectionTitle,
  });
  res.setHeader("Content-Type", "application/pdf");
  res.setHeader("Content-Disposition", `attachment; filename="brief-${(d ? d.name : "prospect").replace(/[^A-Za-z0-9]+/g, "-").toLowerCase()}.pdf"`);
  res.send(pdf);
}));

// ONE page, the org's letterhead, and the footer that says what this is. The
// letterhead block is deliberately the same shape as renderLettersPdf's (BUILD-98
// Part 2) rather than a second idea about where an org's name goes.
function renderBriefPdf({ org, donorName, brief, footer, droppedSentence, sectionTitle }) {
  const PDFDocument = require("pdfkit");
  const doc = new PDFDocument({ size: "LETTER", margins: { top: 50, bottom: 46, left: 72, right: 72 }, autoFirstPage: false });
  return new Promise((resolve, reject) => {
    const chunks = [];
    doc.on("data", c => chunks.push(c));
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);
    const INK = "#0f1a12", SUB = "#5a554f";
    const accent = org.brand_accent || "#0d5c3a";
    let logo = null;
    if (org.logo_data && /^data:image\/(png|jpe?g);base64,/.test(org.logo_data)) {
      try { logo = Buffer.from(org.logo_data.split(",")[1], "base64"); } catch { logo = null; }
    }
    doc.addPage();
    const PW = doc.page.width;
    doc.rect(0, 0, PW, 6).fill(accent);
    if (logo) { try { doc.image(logo, PW - 72 - 60, 22, { fit: [60, 44] }); } catch { /* a logo that will not draw costs the logo, not the page */ } }
    doc.font("Helvetica-Bold").fontSize(13).fillColor(INK).text(org.display || "", 72, 26, { width: PW - 220, lineBreak: false });
    if (org.receipt_address) doc.font("Helvetica").fontSize(8.5).fillColor(SUB).text(org.receipt_address, 72, 44, { width: PW - 220 });

    let y = 92;
    doc.font("Times-Bold").fontSize(19).fillColor(INK).text(donorName || "Prospect brief", 72, y, { width: PW - 144 });
    y = doc.y + 4;
    if (brief.headline) {
      doc.font("Times-Italic").fontSize(11.5).fillColor(SUB).text(brief.headline, 72, y, { width: PW - 144 });
      y = doc.y + 10;
    }
    const bottom = doc.page.height - 84;
    for (const sec of (brief.sections || [])) {
      if (y > bottom - 40) break;                 // held to ONE page, never spilled
      doc.font("Helvetica-Bold").fontSize(9).fillColor(accent)
        .text(String(sectionTitle(sec.key) || sec.key).toUpperCase(), 72, y, { width: PW - 144, characterSpacing: 0.8 });
      y = doc.y + 4;
      for (const s of sec.sentences) {
        if (y > bottom - 14) break;
        doc.font("Times-Roman").fontSize(10.5).fillColor(INK)
          .text(s.text, 72, y, { width: PW - 144, lineGap: 2, height: bottom - y, ellipsis: true });
        y = doc.y + 3;
      }
      y += 7;
    }
    let fy = doc.page.height - 74;
    if (droppedSentence) {
      doc.font("Helvetica").fontSize(8).fillColor(SUB).text(droppedSentence, 72, fy, { width: PW - 144, height: 12 });
      fy += 12;
    }
    doc.font("Helvetica").fontSize(8).fillColor(SUB).text(footer, 72, fy, { width: PW - 144, height: 26 });
    doc.end();
  });
}

// ── BUILD-99 (major gifts) Part 5 — THE MAJOR-GIFTS DASHBOARD ──────────────
// Five things a development director asks. shared/majorGiftsDash.js holds the
// definitions, ONE STRING each, and nothing on this screen may appear without
// one — the BUILD-86 C.3 rule, applied again because the reason has not changed.
//
// NO GOAL IS INVENTED. The only target here is the one she typed in Part 2.
async function mgDashMod() { return import("../shared/majorGiftsDash.js"); }

app.get("/major-gifts/dashboard", requireAuth, wrap(async (req, res) => {
  const MG = await mgDashMod();
  const P = await proposalMod();
  const orgId = req.user.orgId;
  const [org] = await query("SELECT * FROM orgs WHERE id=?", [orgId]);
  const fy = orgPeriodBounds(org, "fiscal_year", 0);
  const fyYear = Number(String(fy.key).replace("fy:", ""));
  const qtr = orgPeriodBounds(org, "quarter", 0);
  const mon = orgPeriodBounds(org, "month", 0);
  const today = orgToday(org);

  // ONE BATCH OF READS, not a query per tile (the BUILD-54 §1 pattern). Every
  // figure below is summed in the database over exactly the rows it names.
  const [pipeline, dueQ, askedY, committedY, convs, backlog, officers, counts] = await Promise.all([
    // Pipeline by stage, over the whole org's open proposals.
    query(`SELECT o.proposal_stage AS stage, COUNT(*)::int AS n, COALESCE(SUM(o.target_amount),0) AS amt,
                  COALESCE(SUM(CASE WHEN o.probability IS NOT NULL
                                    THEN round(o.target_amount::numeric * 100) * o.probability / 100 END),0) AS weighted_cents,
                  COUNT(o.probability)::int AS with_prob
             FROM opportunities o JOIN donors d ON d.id = o.donor_id AND d.org_id = o.org_id
            WHERE o.org_id=? AND d.deleted_at IS NULL
            GROUP BY o.proposal_stage`, [orgId]),
    query(`SELECT COUNT(*)::int AS n, COALESCE(SUM(o.target_amount),0) AS amt
             FROM opportunities o JOIN donors d ON d.id = o.donor_id AND d.org_id = o.org_id
            WHERE o.org_id=? AND d.deleted_at IS NULL AND o.proposal_stage = ANY(?::text[])
              AND o.expected_close >= ?::date AND o.expected_close <= ?::date`,
      [orgId, P.OPEN_STAGE_KEYS, qtr.start, qtr.end]),
    // ASKED THIS YEAR is about reaching the stage, so it reads the stage-change
    // line the proposal routes write — `created_at` would count a proposal
    // opened in July as an ask made in July, which it is not.
    query(`SELECT COUNT(DISTINCT o.id)::int AS n, COALESCE(SUM(o.target_amount),0) AS amt
             FROM opportunities o JOIN donors d ON d.id = o.donor_id AND d.org_id = o.org_id
            WHERE o.org_id=? AND d.deleted_at IS NULL
              AND o.proposal_stage IN ('asked','committed','declined','stewarding')
              AND COALESCE(o.updated_at, o.created_at) >= ?::date
              AND COALESCE(o.updated_at, o.created_at) < (?::date + 1)`, [orgId, fy.start, fy.end]),
    query(`SELECT COUNT(*)::int AS n, COALESCE(SUM(COALESCE(o.gift_amount, o.target_amount)),0) AS amt
             FROM opportunities o JOIN donors d ON d.id = o.donor_id AND d.org_id = o.org_id
            WHERE o.org_id=? AND d.deleted_at IS NULL AND o.status='won'
              AND o.closed_at >= ?::date AND o.closed_at < (?::date + 1)`, [orgId, fy.start, fy.end]),
    // Conversations logged THIS MONTH, per officer, from who logged them.
    query(`SELECT COALESCE(NULLIF(i.logged_by_name,''),'(not recorded)') AS who, COUNT(*)::int AS n
             FROM interactions i JOIN donors d ON d.id = i.donor_id AND d.org_id = i.org_id
            WHERE i.org_id=? AND d.deleted_at IS NULL AND i.is_sample IS NOT TRUE
              AND i.type = ANY(ARRAY['call','meeting','email','ask','stewardship'])
              AND i.date >= ? AND i.date <= ?
            GROUP BY 1 ORDER BY 2 DESC`, [orgId, mon.start, mon.end]),
    // Thread backlog per officer — open follow-ups on their own people, with the
    // overdue ones counted separately. A snoozed thread is not backlog.
    query(`SELECT COALESCE(NULLIF(t.owner_name,''), COALESCE(NULLIF(d.assigned_to_name,''),'(nobody)')) AS who,
                  COUNT(*)::int AS open_n,
                  COUNT(*) FILTER (WHERE t.due_date < ?)::int AS overdue_n
             FROM threads t JOIN donors d ON d.id = t.donor_id AND d.org_id = t.org_id
            WHERE t.org_id=? AND t.closed_at IS NULL AND d.deleted_at IS NULL
              AND (t.snoozed_until IS NULL OR t.snoozed_until <= ?)
            GROUP BY 1 ORDER BY 2 DESC`, [today, orgId, today]),
    query("SELECT COUNT(*)::int AS n FROM users WHERE org_id=?", [orgId]),
    query(`SELECT COUNT(*)::int AS n FROM opportunities o JOIN donors d ON d.id = o.donor_id AND d.org_id = o.org_id
            WHERE o.org_id=? AND d.deleted_at IS NULL`, [orgId]),
  ]);

  const byStage = P.PROPOSAL_STAGES.map(s => {
    const r = pipeline.find(x => x.stage === s.key);
    const askCents = r ? (toCents(r.amt) || 0) : 0;
    return { stage: s.key, label: s.label, kind: s.kind, count: r ? r.n : 0,
             askCents, amount: toDollars(askCents),
             sentence: P.stageTileSentence({ stage: s.key, label: s.label, count: r ? r.n : 0, askCents }, money.formatCentsPlain) };
  });
  const openRows = pipeline.filter(r => P.OPEN_STAGE_KEYS.includes(r.stage));
  const openCents = openRows.reduce((s, r) => s + (toCents(r.amt) || 0), 0);
  const weightedCents = openRows.reduce((s, r) => s + Math.round(Number(r.weighted_cents) || 0), 0);
  const withProb = openRows.reduce((s, r) => s + (Number(r.with_prob) || 0), 0);
  const openCount = openRows.reduce((s, r) => s + (Number(r.n) || 0), 0);

  const askedCents = toCents(askedY[0].amt) || 0;
  const committedCents = toCents(committedY[0].amt) || 0;

  const tile = (id, value) => ({
    id, label: MG.metric(id).label, value,
    definition: MG.definitionFor(id),
    sentence: MG.tileSentence(id, value, money.formatCentsPlain),
  });

  res.json({
    fiscalYear: fyYear, fiscalLabel: `FY ${fyYear}–${String(fyYear + 1).slice(2)}`,
    quarter: { start: qtr.start, end: qtr.end },
    month: { start: mon.start, end: mon.end },
    proposalCount: counts[0].n,
    empty: MG.emptySentence({ proposalCount: counts[0].n, officerCount: officers[0].n }),
    byStage,
    tiles: {
      pipeline: { ...tile("pipeline", openCents), amount: toDollars(openCents), count: openCount },
      weighted: { ...tile("weighted", weightedCents), amount: toDollars(weightedCents), counted: withProb,
                  unset: openCount - withProb,
                  sentence: P.weightedSentence({ cents: weightedCents, counted: withProb, unset: openCount - withProb,
                                                 openCount, askCents: openCents }, money.formatCentsPlain) },
      dueThisQuarter: { ...tile("dueThisQuarter", dueQ[0].n), amount: toDollars(toCents(dueQ[0].amt) || 0) },
      askedThisYear: { ...tile("askedThisYear", askedCents), amount: toDollars(askedCents), count: askedY[0].n },
      committedThisYear: { ...tile("committedThisYear", committedCents), amount: toDollars(committedCents), count: committedY[0].n },
    },
    askedVsCommitted: MG.askedVsCommitted({ askedCents, committedCents }, money.formatCentsPlain),
    officerActivity: {
      definition: MG.definitionFor("conversationsThisMonth"),
      rows: convs.map(r => ({ officerName: r.who, conversations: r.n })),
    },
    threadBacklog: {
      definition: MG.definitionFor("threadBacklog"),
      rows: backlog.map(r => ({ officerName: r.who, open: r.open_n, overdue: r.overdue_n })),
    },
    metrics: MG.METRICS,
  });
}));

// GET /pipeline/officer-activity — per-officer moves/asks/gifts over a period.
// The raw data BUILD-17's per-officer reports read; just recorded cleanly here.
app.get("/pipeline/officer-activity", requireAuth, wrap(async (req, res) => {
  const { orgId } = req.user;
  const from = req.query.from || new Date(Date.now() - 90 * 86400000).toISOString().slice(0, 10);
  const to = req.query.to || orgToday(await orgTz(orgId));   // ORG_TZ_SEAM_OK (FIX-14 Part 2b)
  const officers = await query("SELECT id, name, portfolio_color FROM users WHERE org_id=? ORDER BY name", [orgId]);
  const moves = await query(
    "SELECT officer_id, COUNT(*)::int AS cnt FROM moves WHERE org_id=? AND created_at >= ? AND created_at < (?::date + 1) GROUP BY officer_id", [orgId, from, to]);
  const asks = await query(
    "SELECT officer_id, COUNT(*)::int AS cnt, COALESCE(SUM(target_amount),0) AS amt FROM opportunities WHERE org_id=? AND created_at >= ? AND created_at < (?::date + 1) GROUP BY officer_id", [orgId, from, to]);
  const won = await query(
    "SELECT officer_id, COUNT(*)::int AS cnt, COALESCE(SUM(gift_amount),0) AS amt FROM opportunities WHERE org_id=? AND status='won' AND closed_at >= ? AND closed_at < (?::date + 1) GROUP BY officer_id", [orgId, from, to]);
  const mv = Object.fromEntries(moves.map(r => [r.officer_id, r.cnt]));
  const ak = Object.fromEntries(asks.map(r => [r.officer_id, r]));
  const wn = Object.fromEntries(won.map(r => [r.officer_id, r]));
  res.json({
    from, to,
    officers: officers.map(o => ({
      officerId: o.id, name: o.name, color: o.portfolio_color,
      movesMade: mv[o.id] || 0,
      asksMade: ak[o.id]?.cnt || 0, asksAmount: parseFloat(ak[o.id]?.amt) || 0,
      giftsClosed: wn[o.id]?.cnt || 0, giftsAmount: parseFloat(wn[o.id]?.amt) || 0,
    })),
  });
}));

// ── Donor-to-donor relationships (household/spouse/family/employer_match) ──
// Manual linking only — no auto-detection (matching last name, address,
// etc.) in this pass, see CLAUDE.md. One row per pair regardless of which
// donor is A vs B; both directions are queried here so either donor's
// profile shows the same link.
const DONOR_RELATIONSHIP_TYPES = ["spouse", "household", "family", "employer_match"];
// Only these two types pool into a shared "household total" — family and
// employer_match are relationship context, not a shared giving pool.
const HOUSEHOLD_RELATIONSHIP_TYPES = ["spouse", "household"];

app.get("/donors/:id/relationships", requireAuth, wrap(async (req, res) => {
  if (!(await orgOwns("donors", req.params.id, req.user.orgId))) return res.status(404).json({ error: "Donor not found" }); // BUILD-75 B: the parent must be YOURS before children are answered — even an empty list confirms nothing about another tenant
  const { orgId } = req.user;
  const donorId = req.params.id;
  const rows = await query(
    `SELECT dr.id, dr.relationship_type, dr.notes, dr.created_at,
            CASE WHEN dr.donor_id_a = ? THEN dr.donor_id_b ELSE dr.donor_id_a END AS related_donor_id
     FROM donor_relationships dr
     WHERE dr.org_id = ? AND (dr.donor_id_a = ? OR dr.donor_id_b = ?)
     ORDER BY dr.created_at ASC`,
    [donorId, orgId, donorId, donorId]
  );
  if (!rows.length) return res.json({ relationships: [], householdTotal: null });

  const relatedIds = rows.map(r => r.related_donor_id);
  const relatedDonors = await query(
    `SELECT id, name, total_giving FROM donors WHERE org_id = ? AND id = ANY(?)`,
    [orgId, relatedIds]
  );
  const donorMap = Object.fromEntries(relatedDonors.map(d => [d.id, d]));

  const relationships = rows.map(r => ({
    id: r.id,
    relationshipType: r.relationship_type,
    notes: r.notes,
    relatedDonorId: r.related_donor_id,
    relatedDonorName: donorMap[r.related_donor_id]?.name || "(deleted donor)",
    relatedDonorTotalGiving: Number(donorMap[r.related_donor_id]?.total_giving) || 0,
  }));

  // REPORTS-4: the household total is the `linked-household-giving` source's
  // value, so it opens onto the people it adds up. It used to be added here,
  // in floating point, with a deleted spouse's giving counted in.
  let householdTotal = null, householdTotalSource = null;
  const householdLinks = relationships.filter(r => HOUSEHOLD_RELATIONSHIP_TYPES.includes(r.relationshipType));
  if (householdLinks.length) {
    householdTotalSource = { key: "linked-household-giving", params: { donor: donorId } };
    householdTotal = (await figureSources.figureValue(orgId, householdTotalSource)).value;
  }

  res.json({ relationships, householdTotal, householdTotalSource });
}));

app.post("/donors/:id/relationships", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { orgId } = req.user;
  const donorId = req.params.id;
  const { relatedDonorId, relationshipType, notes } = req.body;
  if (!relatedDonorId || !DONOR_RELATIONSHIP_TYPES.includes(relationshipType)) {
    return res.status(400).json({ error: "relatedDonorId and a valid relationshipType are required" });
  }
  if (relatedDonorId === donorId) return res.status(400).json({ error: "A donor can't be linked to themselves" });

  const bothRows = await query(
    "SELECT id FROM donors WHERE org_id = ? AND id IN (?, ?) AND deleted_at IS NULL",
    [orgId, donorId, relatedDonorId]
  );
  if (bothRows.length < 2) return res.status(404).json({ error: "Donor not found" });

  // Order-agnostic dedup — a link already stored as (B,A) shouldn't allow a
  // second (A,B) row for the same pair.
  const existing = await query(
    `SELECT id FROM donor_relationships WHERE org_id = ?
       AND ((donor_id_a = ? AND donor_id_b = ?) OR (donor_id_a = ? AND donor_id_b = ?))`,
    [orgId, donorId, relatedDonorId, relatedDonorId, donorId]
  );
  if (existing.length) return res.status(409).json({ error: "These donors are already linked" });

  const id = "drel_" + uuid().slice(0, 8);
  await run(
    "INSERT INTO donor_relationships (id, org_id, donor_id_a, donor_id_b, relationship_type, notes, created_by, created_by_name) VALUES (?,?,?,?,?,?,?,?)",
    [id, orgId, donorId, relatedDonorId, relationshipType, notes || null, actor(req).id, actor(req).name]
  );
  if (req.audit) {
    const [r] = await query("SELECT * FROM donor_relationships WHERE id = ?", [id]);
    req.audit.after(await auditShape("donor_relationships", r, orgId));
  }
  res.status(201).json({ id });
}));

// FIX-15 Part 4 — a relationship from BEFORE FIX-14, or one an import or the
// system made, has no person who "linked them" to defer to. Those belong to
// whoever can edit the donor (the same gate as PUT /donors/:id: signed in, with
// write access). One made since FIX-14 by a person stays theirs, or an admin's.
const FIX14_SHIPPED = "2026-10-02T05:09:42Z";
async function mayEditRelationship(req, r) {
  const humanMade = r.created_by && !String(r.created_by).startsWith("system:");
  const legacy = !humanMade || (r.created_at && new Date(r.created_at) < new Date(FIX14_SHIPPED));
  if (legacy) return true;
  return mayEditLogged(req, r);
}

// FIX-14 Part 2b — edit a relationship's kind and its note. Whoever linked
// the two, or an admin (FIX-15: or anyone who can edit the donor, for a legacy one).
app.put("/donor-relationships/:id", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { orgId } = req.user;
  const [r] = await query("SELECT * FROM donor_relationships WHERE id = ? AND org_id = ?", [req.params.id, orgId]);
  if (!r) return res.status(404).json({ error: "Not found" });
  if (!(await mayEditRelationship(req, r))) return res.status(403).json(NOT_YOURS);
  const b = req.body || {};
  const sets = [], vals = [];
  if (b.relationshipType !== undefined && b.relationshipType !== r.relationship_type) {
    if (!DONOR_RELATIONSHIP_TYPES.includes(b.relationshipType)) return res.status(400).json({ error: "A valid relationshipType is required" });
    sets.push("relationship_type=?"); vals.push(b.relationshipType);
  }
  if (b.notes !== undefined && String(b.notes || "") !== String(r.notes || "")) {
    sets.push("notes=?"); vals.push(String(b.notes || "").slice(0, 2000) || null);
  }
  if (!sets.length) return res.json({ ...r, unchanged: true });
  sets.push("edited_at=NOW()", "edited_by=?", "edited_by_name=?");
  vals.push(...(await editStamp(req)));
  await run(`UPDATE donor_relationships SET ${sets.join(", ")} WHERE id = ? AND org_id = ?`, [...vals, req.params.id, orgId]);
  const [out] = await query("SELECT * FROM donor_relationships WHERE id = ?", [req.params.id]);
  if (req.audit) { req.audit.before(await auditShape("donor_relationships", r, orgId)); req.audit.after(await auditShape("donor_relationships", out, orgId)); }
  res.json(out);
}));

// FIX-14 Part 2b: whoever linked them, or an admin; to the trash, so Undo works.
app.delete("/donor-relationships/:id", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const [r] = await query("SELECT * FROM donor_relationships WHERE id = ? AND org_id = ?", [req.params.id, req.user.orgId]);
  if (!r) return res.status(404).json({ error: "Not found" }); // BUILD-75 B: a foreign/unknown id answers 404, never a false success — one answer everywhere
  if (!(await mayEditRelationship(req, r))) return res.status(403).json(NOT_YOURS);
  if (req.audit) req.audit.before(await auditShape("donor_relationships", r, req.user.orgId));
  const undoId = await trashRow("donor_relationships", req.params.id, req);
  if (!undoId) return res.status(404).json({ error: "Not found" });
  res.json({ success: true, deleted: 1, undoId, undoSeconds: UNDO_SECONDS });
}));

// ── ENGAGE-1 — A DONOR'S TWO SCORES ────────────────────────────────────────
// What the profile rail shows: engagement with its band and reason, generosity,
// every part with its points (they add to the score), the explanation from the
// one weights file, and the suggested ask from their own gifts. A donor the
// compute has not reached yet (added a second ago) gets the org computed now.
app.get("/donors/:id/scores", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [d] = await query("SELECT id, name FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL", [req.params.id, orgId]);
  if (!d) return res.status(404).json({ error: "Not found" });
  let [row] = await query("SELECT * FROM donor_scores WHERE org_id=? AND donor_id=?", [orgId, d.id]);
  if (!row) { await recomputeScoresForOrg(orgId); [row] = await query("SELECT * FROM donor_scores WHERE org_id=? AND donor_id=?", [orgId, d.id]); }
  const W = await engagementMod.weights();
  const parts = (typeof row?.parts === "string" ? JSON.parse(row.parts) : row?.parts) || { engagement: [], generosity: [] };
  const band0 = W.bandFor(row ? row.engagement : 0);
  // FIX-34 · ONE STATUS. A Distant score beside a green "On track" line was two
  // answers on one profile; the band word is the closeness word (PARITY-1:
  // "the band in words"), read on the gifts as they are now.
  const today = orgToday(await orgTz(orgId));   // ORG_TZ_SEAM_OK
  const cl = await engagementMod.closenessNow(query, orgId, d.id, today, band0.key);
  const band = cl.key === band0.key ? band0 : { key: cl.key, label: W.CLOSENESS.find(c => c.key === cl.key).label };
  res.json({
    donorId: d.id,
    engagement: row ? row.engagement : 0, generosity: row ? row.generosity : 0,
    // FIX-24 2b: "the most recent touch N days ago" said for today, not for the day the scores ran.
    band: band.key, bandLabel: band.label, reason: row ? engagementMod.reasonFor(row, orgToday(await orgTz(orgId))) : null,   // ORG_TZ_SEAM_OK
    computedFor: row ? row.computed_for : null, computedAt: row ? row.computed_at : null,
    parts: {
      engagement: parts.engagement.map(x => ({ ...x, label: W.TOUCH_POINTS[x.key].label, how: W.TOUCH_POINTS[x.key].how, one: W.TOUCH_POINTS[x.key].one, many: W.TOUCH_POINTS[x.key].many,
        source: { key: "donor-engagement-part", params: { donor: d.id, part: x.key } } })),
      generosity: parts.generosity.map(x => ({ ...x, label: W.GENEROSITY_PARTS[x.key].label, how: W.GENEROSITY_PARTS[x.key].how,
        weight: W.GENEROSITY_PARTS[x.key].weight,
        source: { key: "donor-generosity-part", params: { donor: d.id, part: x.key } } })),
    },
    explanation: W.EXPLANATION,
    bands: W.BANDS,
    // PROSPECT-1 — screening results move the ask only for someone who may see them.
    suggestedAsk: await engagementMod.suggestedAsk(query, orgId, d.id,
      (await require("../prospect").canSee(req.user.userId)) ? { screening: (await require("../prospect").latestScreening(orgId, [d.id])).get(d.id) || null } : {}),
  });
}));

// ── ENGAGE-1 §4 — APPEAL-WHY: "How did it do?" ─────────────────────────────
// This campaign against the comparable one a year earlier: the totals, the
// ranked reasons (each a number that opens its rows, figure source appeal-why)
// and who to call. Planning a follow-up is the existing POST
// /donors/:id/threads: it opens a step, it sends nothing.
app.get("/campaigns/:id/how-did-it-do", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const AW = require("../appealWhy");
  const c = await AW.campaignRow(orgId, req.params.id);
  if (!c) return res.status(404).json({ error: "Not found" });
  const { compare, how, candidates } = await AW.comparableFor(orgId, c);
  if (!compare) return res.json({ campaign: { id: c.id, name: c.name }, compare: null, candidates,
    sentence: "There is no campaign from a year earlier to compare this with. Choose one and the comparison appears." });
  const P = await AW.parts(orgId, c.id, compare.id);
  const src = part => ({ key: "appeal-why", params: { campaign: c.id, compare: compare.id, part } });
  const side = (gifts, newcomers, returning, lapsed) => ({ ...AW.summary(gifts), newDonors: newcomers, returning, lapsed });
  const thisSide = side(P.this, P.newcomers.length, P.returning.length, P.notYet.length);
  const lastSide = { ...AW.summary(P.last) };
  const reasons = [
    { key: "notYet", label: "Last year's donors who have not given yet", people: P.notYet.length, cents: AW.sumC(P.notYet), words: "gave last time" },
    { key: "less", label: "Gave less than last year", people: P.less.length, cents: AW.sumC(P.less), words: "against last time" },
    { key: "more", label: "Gave more than last year", people: P.more.length, cents: AW.sumC(P.more), words: "more than last time" },
    { key: "newcomers", label: "New donors", people: P.newcomers.length, cents: AW.sumC(P.newcomers), words: "from people new to you" },
  ].map(r => ({ ...r, source: src(r.key) }))
   // RANKED by how much money each reason moved, either way.
   .sort((a, b) => Math.abs(b.cents) - Math.abs(a.cents));
  // WHO TO CALL: last year's donors not back yet, ranked half by what they gave
  // last time (where it stands among them) and half by engagement.
  const pool = P.notYet;
  const sortedGift = pool.map(x => x.lastCents).sort((a, b) => a - b);
  const giftPct = v => sortedGift.length ? (100 * (sortedGift.filter(y => y < v).length + sortedGift.filter(y => y === v).length / 2)) / sortedGift.length : 0;
  const whoToCall = pool.map(x => ({ donorId: x.donor_id, name: x.name, lastGiftCents: x.lastCents, engagement: x.engagement, lastTouch: x.date,
      rank: Math.round(giftPct(x.lastCents) / 2 + x.engagement / 2) }))
    .sort((a, b) => b.rank - a.rank || b.lastGiftCents - a.lastGiftCents).slice(0, 25);
  res.json({
    campaign: { id: c.id, name: c.name }, compare: { id: compare.id, name: compare.name, how }, candidates,
    this: { ...thisSide, source: src("this") }, last: { ...lastSide, source: src("last") },
    reasons, whoToCall,
    whoToCallSentence: "Last year's donors who have not given to this campaign yet, ranked half by what they gave last time and half by engagement. Planning a follow-up opens a step on their Thread; nothing is sent.",
  });
}));
app.put("/campaigns/:id/compare", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [c] = await query("SELECT * FROM campaigns WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!c) return res.status(404).json({ error: "Not found" });
  const want = req.body?.compareId ? String(req.body.compareId) : null;
  if (want) {
    const [o] = await query("SELECT id FROM campaigns WHERE id=? AND org_id=? AND id<>?", [want, orgId, c.id]);
    if (!o) return res.status(400).json({ error: "Choose another of your campaigns." });
  }
  if (req.audit) req.audit.before({ compare_campaign_id: c.compare_campaign_id || null });
  await run("UPDATE campaigns SET compare_campaign_id=? WHERE id=? AND org_id=?", [want, c.id, orgId]);
  if (req.audit) req.audit.after({ compare_campaign_id: want });
  res.json({ ok: true, compareId: want });
}));

