// The vendor's wealth-screen figures off an import row, trimmed and capped.
// Hoisted (a function declaration) because the import route above calls it.
function wealthScreenParams(d) {
  const w = d && d.wealthScreen;
  if (!w || typeof w !== "object") return null;
  const t = (v, n) => (v == null ? null : (String(v).trim().slice(0, n) || null));
  const o = { source: t(w.source, 40) || "Wealth screening", rating: t(w.rating, 64), capacity: t(w.capacity, 64), date: t(w.date, 32) };
  return o.rating || o.capacity || o.date ? o : null;
}
// ── INT-5 · THE KEY WALL, THE RATE LIMIT AND THE CALL LOG ─────────────────
// One place, because all three are about the same request and separating them
// is how a call gets rate-limited but not logged, or logged but not scoped.
const apiScopesMod = () => import("../shared/apiScopes.js");
// Per-key, in memory, one minute wide. Per KEY rather than per org so one noisy
// integration cannot starve another, and deliberately not in the database: a
// rate limiter that writes a row per request is its own denial of service.
const apiKeyHits = new Map();
function apiRateHit(keyId, perMinute) {
  const now = Date.now();
  const w = apiKeyHits.get(keyId);
  if (!w || now - w.start >= 60000) { apiKeyHits.set(keyId, { start: now, n: 1 }); return { ok: true }; }
  w.n++;
  if (w.n > perMinute) return { ok: false, retryAfter: Math.ceil((w.start + 60000 - now) / 1000) };
  return { ok: true };
}

/**
 * THE CALL LOG WRITES ON THE WAY OUT, WHATEVER HAPPENED.
 *
 * Hooked to the response rather than called at each return, because a log that
 * has to be remembered at twenty return statements is a log that is missing the
 * twenty-first — and the refusals are the rows somebody debugging most needs.
 */
function logApiCall(req, res, { keyId, orgId, scope }) {
  const started = Date.now();
  res.on("finish", () => {
    run(`INSERT INTO api_call_log (id,org_id,key_id,method,path,status,scope_required,entity_id,ms)
         VALUES (?,?,?,?,?,?,?,?,?)`,
      ["acl_" + uuid().slice(0, 12), orgId, keyId || null, req.method,
       // The ROUTE, not the filled path: a log of "/api/v1/people/d_abc123"
       // is a list of donor ids in a table nobody guards. The id, when it
       // matters, is its own column.
       String(req.route?.path || req.path || "").slice(0, 200),
       res.statusCode, scope || null,
       String(req.params?.id || "").slice(0, 64) || null,
       Date.now() - started]).catch(() => {});
  });
}

async function requireApiKey(req, res, next) {
  try {
    const raw = String(req.headers["x-api-key"] || (req.headers.authorization || "").replace(/^Bearer\s+/i, "")).trim();
    const refuse = () => res.status(401).json({ error: "invalid_api_key", message: "That API key is not valid." });
    if (!raw.startsWith(API_KEY_PREFIX) || raw.length < 20) return refuse();
    const [k] = await query(`SELECT id, org_id, name, scopes, last_used_at FROM api_keys WHERE key_hash=? AND revoked_at IS NULL`, [hashApiKey(raw)]);
    if (!k) return refuse();
    const S = await apiScopesMod();
    const stored = Array.isArray(k.scopes) ? k.scopes : ["read"];
    req.apiKey = { id: k.id, orgId: k.org_id, name: k.name,
                   scopes: S.effectiveScopes(stored), stored };
    logApiCall(req, res, { keyId: k.id, orgId: k.org_id, scope: req.requiredScope });
    const hit = apiRateHit(k.id, S.RATE_LIMIT_PER_MINUTE);
    if (!hit.ok) {
      res.set("Retry-After", String(hit.retryAfter));
      return res.status(429).json(S.rateLimitBody(hit.retryAfter));
    }
    // Stamp use at most once a minute — a busy integration must not turn
    // every read into a write.
    if (!k.last_used_at || Date.now() - new Date(k.last_used_at).getTime() > 60000)
      run(`UPDATE api_keys SET last_used_at=NOW() WHERE id=?`, [k.id]).catch(() => {});
    next();
  } catch (e) { next(e); }
}

/**
 * THE SCOPE WALL. `requireScope("write:gifts")` after `requireApiKey`.
 *
 * It fails CLOSED on an unknown scope name, so a typo in a route definition
 * refuses every call rather than allowing every call, which is the direction a
 * mistake here has to fail in.
 */
function requireScope(needed) {
  return async function (req, res, next) {
    req.requiredScope = needed;
    const S = await apiScopesMod();
    if (!req.apiKey) return res.status(401).json({ error: "invalid_api_key", message: "That API key is not valid." });
    if (!S.allows(req.apiKey.stored, needed)) return res.status(403).json(S.refusalFor(needed));
    next();
  };
}

// ── Staff side: make, list and revoke keys (admin only) ────────────────────
app.get("/api-keys", requireAuth, requireAdmin, wrap(async (req, res) => {
  const rows = await query(`SELECT id, name, prefix, scopes, created_by_name, created_at, last_used_at, revoked_at
                              FROM api_keys WHERE org_id=? ORDER BY created_at DESC`, [req.user.orgId]);
  res.json({ keys: rows.map(r => ({ id: r.id, name: r.name, prefix: r.prefix, scopes: r.scopes, createdBy: r.created_by_name,
    createdAt: r.created_at, lastUsedAt: r.last_used_at, revokedAt: r.revoked_at })) });
}));
app.post("/api-keys", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const S = await apiScopesMod();
  const name = String(req.body?.name || "").trim().slice(0, 80);
  if (!name) return res.status(400).json({ error: "Give the key a name, so you can tell it apart later (for example, Zapier)." });
  // INT-5 — SCOPES ARE CHOSEN, NEVER DEFAULTED TO EVERYTHING. A caller that
  // sends none gets the read set, which is what every key issued before this
  // build already had: the default may narrow over time, never widen.
  const asked = req.body?.scopes === undefined ? S.READ_SCOPES : req.body.scopes;
  const v = S.validateScopes(asked);
  if (!v.ok) return res.status(400).json({ error: v.error });
  const secret = API_KEY_PREFIX + crypto.randomBytes(24).toString("base64url");
  const prefix = secret.slice(0, 10);
  const who = actor(req);
  const [me] = await query(`SELECT name FROM users WHERE id=? AND org_id=?`, [req.user.userId, req.user.orgId]);
  const id = "ak_" + uuid().slice(0, 12);
  await run(`INSERT INTO api_keys (id,org_id,name,prefix,key_hash,scopes,created_by,created_by_name) VALUES (?,?,?,?,?,?::jsonb,?,?)`,
    [id, req.user.orgId, name, prefix, hashApiKey(secret), JSON.stringify(v.value), who.id, me?.name || who.name]);
  await writeAuditLog(req.user.orgId, who.id, me?.name || who.name, "api_key_created", "api_key", id,
    { scopes: v.value }).catch(() => {});
  res.json({ id, name, prefix, scopes: v.value, key: secret,
    sentence: "This is the only time the whole key is shown. Copy it now; Steward keeps only a fingerprint of it." });
}));

// WHAT A KEY MAY BE GIVEN, for the screen that makes one.
app.get("/api-keys/scopes", requireAuth, requireAdmin, wrap(async (req, res) => {
  const S = await apiScopesMod();
  res.json({
    scopes: S.SCOPE_KEYS.map(k => S.SCOPES[k]),
    defaults: S.READ_SCOPES,
    rateLimitSentence: S.RATE_LIMIT_SENTENCE,
    callLogSentence: S.CALL_LOG_SENTENCE,
    legacySentence: "A key made before permissions existed can read everything it always could, and cannot write. Make a new key to grant writing.",
  });
}));

// THE CALL LOG FOR ONE KEY. Thirty days, ids only.
app.get("/api-keys/:id/calls", requireAuth, requireAdmin, wrap(async (req, res) => {
  const S = await apiScopesMod();
  const [k] = await query(`SELECT id, name FROM api_keys WHERE id=? AND org_id=?`, [req.params.id, req.user.orgId]);
  if (!k) return res.status(404).json({ error: "Not found" });
  const rows = await query(
    `SELECT method, path, status, scope_required, entity_id, ms, created_at
       FROM api_call_log WHERE key_id=? AND org_id=? AND created_at > NOW() - INTERVAL '${S.CALL_LOG_DAYS} days'
      ORDER BY created_at DESC LIMIT 200`, [req.params.id, req.user.orgId]);
  res.json({
    key: { id: k.id, name: k.name },
    calls: rows.map(r => ({
      method: r.method, path: r.path, status: r.status, at: r.created_at, ms: r.ms,
      entityId: r.entity_id || null,
      sentence: S.statusSentence(r.status, r.scope_required),
    })),
    definition: S.CALL_LOG_SENTENCE,
  });
}));
// Revoking is never write-gated: a lapsed org must always be able to shut a door.
app.delete("/api-keys/:id", requireAuth, requireAdmin, wrap(async (req, res) => {
  const r = await query(`UPDATE api_keys SET revoked_at=COALESCE(revoked_at, NOW()) WHERE id=? AND org_id=? RETURNING id`, [req.params.id, req.user.orgId]);
  if (!r.length) return res.status(404).json({ error: "Not found" });
  res.json({ ok: true });
}));

// ── FIX-11 Part 1 — THE AUDIT LOG SCREEN'S ROUTES ─────────────────────────
// One read for the whole organisation's history, newest first, and one CSV of
// the same rows. The old /finance/audit-log stays where it is and keeps the
// Finance tab working; it is the same table, filtered to nothing in
// particular, and this is the screen that covers everything.
//
// OWNERS AND ADMINS ONLY, and that is a boundary rather than a preference: the
// log names who signed in, whose role changed and who downloaded a donor file.
// Showing it to everybody would turn an accountability record into a
// surveillance feed.
const AUDIT_COLS = `id, created_at, user_id, user_name, actor_kind, action, entity_type, entity_id,
  entity_label, summary, record_count, request_method, request_path, status_code, changes,
  before_fields, after_fields`;

// What the log covers, in one sentence, at the top of the screen. It lives
// here so the screen, the CSV header and anything printed later say the same
// thing: every number has a sentence, and so does a history.
const AUDIT_COVERAGE = "Every change anyone makes in Steward: gifts, pledges and refunds; donors, "
  + "people and merges; receipts and emails sent; funds, campaigns and pages; events, volunteers and "
  + "shifts; imports and undos; downloads of donor data; users, roles and sign-ins; connections, API "
  + "keys and settings; and every action an agent took and who approved it. Rows cannot be edited or "
  + "removed, and they are kept for at least seven years.";

async function auditQuery(req, q0 = req.query) {
  const { actor, entityType, action, from, to, q: search } = q0;
  const limit = Math.max(1, Math.min(2000, parseInt(q0.limit, 10) || 200));
  const offset = Math.max(0, parseInt(q0.offset, 10) || 0);
  let sql = `SELECT ${AUDIT_COLS} FROM fin_audit_log WHERE org_id = ?`;
  const params = [req.user.orgId];
  // FIX-12 Part 4: rows from FIX-12 on carry the actor's id, not a name, so a
  // name chosen in the filter also matches the ids of the people it names.
  if (actor) {
    sql += " AND (user_id = ? OR user_name = ? OR user_id IN (SELECT id FROM users WHERE org_id = ? AND (name = ? OR email = ?)))";
    params.push(actor, actor, req.user.orgId, actor, actor);
  }
  if (entityType) { sql += " AND entity_type = ?"; params.push(entityType); }
  if (action) { sql += " AND action = ?"; params.push(action); }
  // FIX-14 Part 2 — BY PERSON OR BY RECORD. A person is everything about
  // them: their own record, and every conversation, step, task and gift that
  // carries their id. A record is one entity id exactly.
  if (q0.person) {
    sql += ` AND (entity_id = ? OR after_fields->>'donor_id' = ? OR before_fields->>'donor_id' = ?
                  OR changes->'record'->>'donor_id' = ?)`;
    const pid = String(q0.person);
    params.push(pid, pid, pid, pid);
  }
  if (q0.record) { sql += " AND entity_id = ?"; params.push(String(q0.record)); }
  if (from) { sql += " AND created_at >= ?::date"; params.push(from); }
  // `to` is inclusive of the whole day somebody typed, which is what a person
  // filtering "up to the 30th" means. An exclusive bound silently drops that
  // day's rows and reads as a missing record.
  if (to) { sql += " AND created_at < (?::date + INTERVAL '1 day')"; params.push(to); }
  // SEARCH BY DONOR NAME is the one a fundraiser actually needs, so it matches
  // the label the row carries (the donor's name) as well as the person who
  // acted and the record id, rather than making her know which field it is in.
  if (search && String(search).trim()) {
    sql += ` AND (entity_label ILIKE ? OR user_name ILIKE ? OR entity_id = ? OR summary ILIKE ?
                  OR after_fields::text ILIKE ? OR before_fields::text ILIKE ?
                  OR entity_id IN (SELECT id FROM donors WHERE org_id = ? AND erased_at IS NULL AND name ILIKE ?)
                  OR user_id IN (SELECT id FROM users WHERE org_id = ? AND (name ILIKE ? OR email ILIKE ?)))`;
    const like = "%" + String(search).trim() + "%";
    params.push(like, like, String(search).trim(), like, like, like, req.user.orgId, like, req.user.orgId, like, like);
  }
  sql += " ORDER BY created_at DESC, id DESC LIMIT ? OFFSET ?";
  params.push(limit, offset);
  return auditMw.resolveAuditNames(await query(sql, params), req.user.orgId);
}

// Which record a row opens. A voided gift and a deleted donor still open,
// read-only, because the row whose history this is may well be the one
// somebody is trying to account for.
function auditRecordLink(r) {
  const t = String(r.entity_type || "");
  const id = r.entity_id;
  if (!id) return null;
  // FIX-14 Part 2: a conversation, next step or task opens the person it is about.
  const donorId = auditTrailMod.auditDonorId({ ...r, changes: auditJson(r.changes, {}),
    before: auditJson(r.before_fields, null), after: auditJson(r.after_fields, null) });
  if (/^(interaction|conversation|touchpoint|thread|next step|task|relationship|donor relationship|pledge|proposal)$/.test(t) && donorId) {
    return { tab: "donors", donorId };
  }
  if (/^user_/.test(String(id))) return { tab: "settings", section: "team" };
  if (/^(donor|person|people|organisation|organization|stage)$/.test(t)) return { tab: "donors", donorId: id };
  if (/^(gift|pledge|receipt|refund|soft credit)$/.test(t)) return { tab: "donors", giftId: id };
  if (/^(user|invite|role)$/.test(t)) return { tab: "settings", section: "team" };
  if (/^(fund|account|transaction|budget)$/.test(t)) return { tab: "finance", recordId: id };
  if (/^(campaign|appeal|giving page|form|widget)$/.test(t)) return { tab: "fundraising", recordId: id };
  if (/^(event|ticket|guest|table|seat)$/.test(t)) return { tab: "events", recordId: id };
  if (/^(volunteer|shift|hour|waiver)$/.test(t)) return { tab: "volunteers", recordId: id };
  if (/^(grant|funder|milestone)$/.test(t)) return { tab: "grants", recordId: id };
  if (/^(import|export)$/.test(t)) return { tab: "settings", section: "imports" };
  if (/^(connection|api key|webhook|mailbox)$/.test(t)) return { tab: "settings", section: "connections" };
  return { tab: "settings", section: "audit", recordId: id };
}

function auditJson(v, dflt) {
  if (typeof v === "string") { try { return JSON.parse(v || "null") ?? dflt; } catch { return dflt; } }
  return v || dflt;
}
const auditRowOut = (r, people) => {
  const o = {
    ...r,
    changes: auditJson(r.changes, {}),
    before: auditJson(r.before_fields, null),
    after: auditJson(r.after_fields, null),
    sentence: auditTrailMod.rowSentence(r),
    link: auditRecordLink(r),
  };
  // FIX-14 Part 2: the Description, in a plain sentence. Never a dash.
  o.description = auditTrailMod.describeAuditRow(o, { people: people || new Map() });
  o.record_name = auditTrailMod.auditRecordName(o, { people: people || new Map() });
  return o;
};
// The names the sentences need, read live (FIX-12: the row holds ids). An
// erased person reads "Erased person", as everywhere else in the log.
async function auditPeople(rows, orgId) {
  const ids = new Set();
  for (const r of rows) {
    // FIX-14 Part 2b: both sides of a relationship and a household's members too.
    for (const id of auditTrailMod.auditPeopleIds({ ...r, changes: auditJson(r.changes, {}),
      before: auditJson(r.before_fields, null), after: auditJson(r.after_fields, null) })) ids.add(String(id));
  }
  const people = new Map();
  if (ids.size) {
    const ds = await query("SELECT id, name, erased_at FROM donors WHERE org_id=? AND id = ANY(?)", [orgId, [...ids]]).catch(() => []);
    for (const d of ds) people.set(d.id, d.erased_at ? "Erased person" : (d.name || "a person with no name"));
  }
  // FIX-14 Part 2b: a household's name, live, or as it was when it was deleted.
  const hhIds = [...new Set(rows.filter(r => r.entity_type === "household" && r.entity_id).map(r => String(r.entity_id)))];
  if (hhIds.length) {
    const hs = await query(
      `SELECT id, name FROM households WHERE org_id=? AND id = ANY(?)
       UNION ALL SELECT record_id, row_data->>'name' FROM deleted_records WHERE org_id=? AND table_name='households' AND record_id = ANY(?)`,
      [orgId, hhIds, orgId, hhIds]).catch(() => []);
    for (const h of hs) if (h.name && !people.has("hh:" + h.id)) people.set("hh:" + h.id, h.name);
  }
  return people;
}
async function auditDescribe(rows, orgId) {
  const people = await auditPeople(rows, orgId);
  return rows.map(r => auditRowOut(r, people));
}

app.get("/audit/log", requireAuth, requireAdmin, wrap(async (req, res) => {
  const rows = await auditQuery(req);
  // The filter choices come from the rows that exist, so a dropdown never
  // offers a type this organisation has never produced.
  const [facets] = await query(
    `SELECT
       (SELECT COALESCE(JSON_AGG(DISTINCT entity_type), '[]') FROM fin_audit_log WHERE org_id=? AND entity_type IS NOT NULL) AS types,
       (SELECT COALESCE(JSON_AGG(DISTINCT action),      '[]') FROM fin_audit_log WHERE org_id=? AND action IS NOT NULL) AS actions,
       (SELECT COALESCE(JSON_AGG(DISTINCT n), '[]') FROM (
          SELECT user_name AS n FROM fin_audit_log WHERE org_id=? AND user_name IS NOT NULL
          UNION SELECT COALESCE(u.name, u.email) FROM users u
           WHERE u.org_id=? AND u.id IN (SELECT user_id FROM fin_audit_log WHERE org_id=? AND user_name IS NULL)) x) AS actors`,
    [req.user.orgId, req.user.orgId, req.user.orgId, req.user.orgId, req.user.orgId]);
  res.json({
    coverage: AUDIT_COVERAGE,
    // Times are shown in the organisation's zone, and the zone is named.
    timezone: await orgTzName(req.user.orgId),
    rows: await auditDescribe(rows, req.user.orgId),
    facets: {
      entityTypes: (facets?.types || []).filter(Boolean).sort(),
      actions: (facets?.actions || []).filter(Boolean).sort(),
      actors: (facets?.actors || []).filter(Boolean).sort(),
    },
  });
}));

// ONE ROW of history, for the "what changed?" panel. Scoped to the org like
// everything else.
app.get("/audit/log/:id", requireAuth, requireAdmin, wrap(async (req, res) => {
  const rows = await auditMw.resolveAuditNames(await query(`SELECT ${AUDIT_COLS} FROM fin_audit_log WHERE id=? AND org_id=?`,
    [req.params.id, req.user.orgId]), req.user.orgId);
  if (!rows.length) return res.status(404).json({ error: "Not found" });
  res.json((await auditDescribe(rows, req.user.orgId))[0]);
}));

// FIX-14 Part 2 — ONE PERSON'S HISTORY, on their profile: every audit row
// about them (their record, and every conversation, step, task and gift that
// carries their id), newest first. Open to anyone who can open the profile,
// because it shows only what happened to this one record.
app.get("/donors/:id/history", requireAuth, wrap(async (req, res) => {
  if (!(await orgOwns("donors", req.params.id, req.user.orgId))) return res.status(404).json({ error: "Donor not found" });
  const rows = await auditQuery(req, { person: req.params.id, limit: req.query.limit || 200 });
  res.json({ timezone: await orgTzName(req.user.orgId), rows: await auditDescribe(rows, req.user.orgId) });
}));

// The export of the log is itself a download of who-did-what, so it is logged
// like any other download: the middleware sees Content-Disposition and writes
// the row. Nothing here calls the audit layer by hand.
app.get("/audit/log.csv", requireAuth, requireAdmin, wrap(async (req, res) => {
  const rows = await auditQuery(req);
  const cell = v => {
    const s = v === null || v === undefined ? ""
      : typeof v === "object" ? JSON.stringify(v) : String(v);
    return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  };
  const people = await auditPeople(rows, req.user.orgId);
  const head = ["When", "Who", "In what capacity", "Description", "Action", "Record type", "Record",
                "Record id", "What changed (before)", "What changed (after)", "Summary",
                "Records touched", "Request", "Result"];
  const lines = [head.join(",")];
  for (const r of rows) {
    const o = auditRowOut(r, people);
    lines.push([
      new Date(r.created_at).toISOString(), r.user_name || "System", r.actor_kind || "", o.description,
      r.action || "", r.entity_type || "", r.entity_label || "", r.entity_id || "",
      o.before, o.after, r.summary || "", r.record_count == null ? "" : r.record_count,
      `${r.request_method || ""} ${r.request_path || ""}`.trim(), r.status_code == null ? "" : r.status_code,
    ].map(cell).join(","));
  }
  const name = `audit-log-${new Date().toISOString().slice(0, 10)}.csv`;
  res.setHeader("Content-Type", "text/csv; charset=utf-8");
  res.setHeader("Content-Disposition", `attachment; filename="${name}"`);
  res.send("﻿" + lines.join("\n") + "\n");
}));

// ── Key side: /api/v1, read only ───────────────────────────────────────────
const apiPage = q => ({ limit: Math.max(1, Math.min(100, parseInt(q.limit, 10) || 50)), offset: Math.max(0, parseInt(q.offset, 10) || 0) });
const apiPerson = d => ({
  id: d.id, name: d.name, email: d.email || null, phone: d.phone || null,
  city: d.city || null, state: d.state || null, zip: d.zip || null,
  types: Array.isArray(d.person_types) ? d.person_types : ["donor"],
  lifetimeGiving: Number(d.total_giving || 0), giftCount: Number(d.gift_count || 0),
  lastGiftDate: d.last_gift_date || null, stage: d.stage || null,
  wealthScreen: d.wealth_screen_source ? { source: d.wealth_screen_source, rating: d.wealth_screen_rating || null,
    capacity: d.wealth_screen_capacity || null, date: d.wealth_screen_date || null } : null,
  sample: !!d.is_sample, createdAt: d.created_at,
});
const API_PERSON_COLS = `id,name,email,phone,city,state,zip,person_types,total_giving,gift_count,last_gift_date,stage,
  wealth_screen_source,wealth_screen_rating,wealth_screen_capacity,wealth_screen_date,is_sample,created_at`;
// `/me` needs no scope: it is how a caller finds out what their key may do,
// and a key that cannot ask that has no way to discover it has been narrowed.
app.get("/api/v1/me", apiLimiter, requireApiKey, wrap(async (req, res) => {
  const [o] = await query(`SELECT name FROM orgs WHERE id=?`, [req.apiKey.orgId]);
  res.json({ organization: o?.name || null, key: req.apiKey.name, scopes: req.apiKey.scopes });
}));
app.get("/api/v1/people", apiLimiter, requireApiKey, requireScope("read:people"), wrap(async (req, res) => {
  const { limit, offset } = apiPage(req.query);
  const rows = await query(`SELECT ${API_PERSON_COLS} FROM donors WHERE org_id=? AND deleted_at IS NULL
                             ORDER BY created_at DESC, id DESC LIMIT ? OFFSET ?`, [req.apiKey.orgId, limit, offset]);
  res.json({ data: rows.map(apiPerson), limit, offset });
}));
app.get("/api/v1/people/:id", apiLimiter, requireApiKey, requireScope("read:people"), wrap(async (req, res) => {
  const [d] = await query(`SELECT ${API_PERSON_COLS} FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL`, [req.params.id, req.apiKey.orgId]);
  if (!d) return res.status(404).json({ error: "Not found" });
  res.json({ data: apiPerson(d) });
}));
app.get("/api/v1/gifts", apiLimiter, requireApiKey, requireScope("read:gifts"), wrap(async (req, res) => {
  const { limit, offset } = apiPage(req.query);
  const rows = await query(
    `SELECT g.id, g.donor_id, g.amount, g.date, g.type, g.payment_method, g.created_at, g.is_sample,
            f.name AS fund_name, COALESCE(c.name, g.campaign) AS campaign_name
       FROM gifts g JOIN donors d ON d.id=g.donor_id AND d.deleted_at IS NULL
       LEFT JOIN fin_funds f ON f.id=g.fund_id AND f.org_id=g.org_id
       LEFT JOIN campaigns c ON c.id=g.campaign_id AND c.org_id=g.org_id
      WHERE g.org_id=? ORDER BY g.created_at DESC, g.id DESC LIMIT ? OFFSET ?`, [req.apiKey.orgId, limit, offset]);
  res.json({ data: rows.map(g => ({ id: g.id, personId: g.donor_id, amount: Number(g.amount), date: g.date, type: g.type || null,
    paymentMethod: g.payment_method || null, fund: g.fund_name || null, campaign: g.campaign_name || null,
    sample: !!g.is_sample, createdAt: g.created_at })), limit, offset });
}));
// FIX-13: THE FUNDS A GIFT CAN GO TO, so an integration can offer a list of
// names instead of asking for an id somebody has to go and find (the Zapier
// fund dropdown). Id and name only, this org only, behind its own read scope.
app.get("/api/v1/funds", apiLimiter, requireApiKey, requireScope("read:funds"), wrap(async (req, res) => {
  const { limit, offset } = apiPage(req.query);
  const rows = await query(`SELECT id, name FROM fin_funds WHERE org_id=? ORDER BY name ASC, id ASC LIMIT ? OFFSET ?`,
    [req.apiKey.orgId, limit, offset]);
  res.json({ data: rows.map(f => ({ id: f.id, name: f.name })), limit, offset });
}));

// ── INT-5 · WEBHOOKS OUT ──────────────────────────────────────────────────
//
// Steward telling somebody else that something happened. Signed with a
// per-endpoint secret and a timestamp, retried with backoff for a day, and
// every ATTEMPT kept so "it failed four times and then worked" is visible.
const webhookMod = () => import("../shared/webhookOut.js");

app.get("/webhooks", requireAuth, requireAdmin, wrap(async (req, res) => {
  const W = await webhookMod();
  const rows = await query(
    `SELECT id,url,description,events,paused_at,consecutive_failures,last_delivered_at,last_status,created_at
       FROM webhook_endpoints WHERE org_id=? ORDER BY created_at DESC`, [req.user.orgId]);
  res.json({
    endpoints: rows.map(r => ({
      id: r.id, url: r.url, description: r.description,
      events: Array.isArray(r.events) ? r.events : [],
      paused: !!r.paused_at, consecutiveFailures: r.consecutive_failures || 0,
      lastDeliveredAt: r.last_delivered_at, lastStatus: r.last_status, createdAt: r.created_at,
      sentence: r.paused_at
        ? W.pauseSentence(r.url, r.consecutive_failures || 0)
        : r.last_delivered_at ? `Delivering. Last answered ${r.last_status}.`
        : "Added. Nothing has been sent to it yet.",
    })),
    // The secret is NEVER returned after creation, not even to an admin: it is
    // shown once, exactly like an API key, because a secret a screen can
    // re-display is a secret in every screenshot and support ticket.
    events: W.EVENT_KEYS.map(k => W.EVENTS[k]),
    verifySnippet: W.VERIFY_SNIPPET,
    signatureHeader: W.SIGNATURE_HEADER,
    definition: "Where Steward should post when something happens here. Each delivery is signed with that endpoint's own secret and a timestamp, and retried for a day if it fails.",
  });
}));

app.post("/webhooks", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const W = await webhookMod();
  const v = W.validateEndpoint(req.body || {});
  if (!v.ok) return res.status(400).json({ error: v.errors[0], errors: v.errors });
  const id = "whe_" + uuid().slice(0, 12);
  const secret = "whsec_" + crypto.randomBytes(24).toString("base64url");
  const who = actor(req);
  await run(
    `INSERT INTO webhook_endpoints (id,org_id,url,description,events,secret,created_by,created_by_name)
     VALUES (?,?,?,?,?::jsonb,?,?,?)`,
    [id, req.user.orgId, v.value.url, v.value.description, JSON.stringify(v.value.events), secret, who.id, who.name]);
  await writeAuditLog(req.user.orgId, who.id, who.name, "webhook_endpoint_created", "webhook", id,
    { url: v.value.url, events: v.value.events }).catch(() => {});
  res.status(201).json({ id, url: v.value.url, events: v.value.events, secret,
    sentence: "This is the only time the signing secret is shown. Copy it now: Steward signs every delivery with it, and cannot show it again." });
}));

app.delete("/webhooks/:id", requireAuth, requireAdmin, wrap(async (req, res) => {
  const r = await run(`DELETE FROM webhook_endpoints WHERE id=? AND org_id=?`, [req.params.id, req.user.orgId]);
  if (!r.changes) return res.status(404).json({ error: "Not found" });
  res.json({ ok: true, sentence: "Removed. Steward will not post there again, and its delivery history has gone with it." });
}));

// Turning a paused endpoint back on, and resending what is still waiting.
app.post("/webhooks/:id/resume", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const [e] = await query(`SELECT id FROM webhook_endpoints WHERE id=? AND org_id=?`, [req.params.id, req.user.orgId]);
  if (!e) return res.status(404).json({ error: "Not found" });
  await run(`UPDATE webhook_endpoints SET paused_at=NULL, consecutive_failures=0, updated_at=NOW() WHERE id=?`, [e.id]);
  const r = await run(
    `UPDATE webhook_deliveries SET next_attempt_at=NOW(), gave_up_at=NULL
      WHERE endpoint_id=? AND delivered_at IS NULL`, [e.id]);
  res.json({ ok: true, requeued: (r && r.changes) || 0,
    sentence: "Back on. Anything that was still waiting will be tried again within the minute." });
}));

// THE DELIVERY LOG, every attempt.
app.get("/webhooks/:id/deliveries", requireAuth, requireAdmin, wrap(async (req, res) => {
  const [e] = await query(`SELECT id, url FROM webhook_endpoints WHERE id=? AND org_id=?`, [req.params.id, req.user.orgId]);
  if (!e) return res.status(404).json({ error: "Not found" });
  const rows = await query(
    `SELECT id,event,attempt,status,outcome,error,created_at,delivered_at,gave_up_at,next_attempt_at
       FROM webhook_deliveries WHERE endpoint_id=? AND org_id=? ORDER BY created_at DESC LIMIT 200`,
    [e.id, req.user.orgId]);
  res.json({
    endpoint: { id: e.id, url: e.url },
    deliveries: rows.map(r => ({
      id: r.id, event: r.event, attempt: r.attempt, status: r.status, outcome: r.outcome,
      error: r.error, at: r.created_at, deliveredAt: r.delivered_at,
      gaveUpAt: r.gave_up_at, nextAttemptAt: r.next_attempt_at,
      sentence: r.delivered_at ? `Delivered on attempt ${r.attempt}.`
        : r.gave_up_at ? `Gave up after ${r.attempt} attempts.`
        : `Attempt ${r.attempt} answered ${r.status || "nothing"}. Trying again.`,
    })),
  });
}));

// RESEND ONE, by hand.
app.post("/webhooks/deliveries/:id/resend", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const [d] = await query(
    `SELECT id, endpoint_id, event, payload FROM webhook_deliveries WHERE id=? AND org_id=?`,
    [req.params.id, req.user.orgId]);
  if (!d) return res.status(404).json({ error: "Not found" });
  const id = "whd_" + uuid().slice(0, 12);
  await run(
    `INSERT INTO webhook_deliveries (id,org_id,endpoint_id,event,payload,attempt,next_attempt_at)
     VALUES (?,?,?,?,?::jsonb,0,NOW())`,
    [id, req.user.orgId, d.endpoint_id, d.event, JSON.stringify(d.payload)]);
  res.status(201).json({ ok: true, id, sentence: "Queued. Steward will try it again within the minute." });
}));

// ── INT-5 · THE WRITE HALF OF THE PUBLIC API ──────────────────────────────
//
// EVERY WRITE GOES THROUGH THE FUNCTION THE APP USES. Not "similar code": the
// same `recordGift`, the same person rules. A second writer would eventually
// disagree with the first about a fund, a rollup, a receipt or a duplicate,
// and the half that lost would be the one nobody was watching.
//
// A key is scoped per verb and per thing, so "record gifts" does not carry
// "add people" with it.
app.post("/api/v1/people", apiLimiter, requireApiKey, requireScope("write:people"), wrap(async (req, res) => {
  const orgId = req.apiKey.orgId;
  const name = String(req.body?.name || "").trim().slice(0, 200);
  const email = String(req.body?.email || "").trim().toLowerCase().slice(0, 200) || null;
  if (!name) return res.status(422).json({ error: "invalid_request", message: "A person needs a name." });
  if (email && !email.includes("@")) return res.status(422).json({ error: "invalid_request", message: "That email address is not usable." });

  // AN EXISTING PERSON IS UPDATED, NOT DUPLICATED. An integration posting the
  // same supporter every night must not build a thousand records, so the match
  // is on email within this org, which is the same rule the importer uses.
  if (email) {
    const [existing] = await query(
      `SELECT id FROM donors WHERE org_id=? AND LOWER(email)=? AND deleted_at IS NULL LIMIT 1`, [orgId, email]);
    if (existing) {
      await run(`UPDATE donors SET name=COALESCE(NULLIF(?, ''), name), phone=COALESCE(?, phone),
                        city=COALESCE(?, city), state=COALESCE(?, state), zip=COALESCE(?, zip)
                  WHERE id=? AND org_id=?`,
        [name, req.body?.phone || null, req.body?.city || null, req.body?.state || null,
         req.body?.zip || null, existing.id, orgId]);
      await emitWebhook(orgId, "person.updated", { personId: existing.id, email }).catch(() => {});
      const [row] = await query(`SELECT ${API_PERSON_COLS} FROM donors WHERE id=?`, [existing.id]);
      return res.status(200).json({ data: apiPerson(row), created: false });
    }
  }
  const id = "d_" + uuid().slice(0, 12);
  await run(
    `INSERT INTO donors (id,org_id,name,email,phone,city,state,zip,stage,person_types,created_by,created_by_name)
     VALUES (?,?,?,?,?,?,?,?, 'prospect', '["donor"]'::jsonb, ?, ?)`,
    [id, orgId, name, email, req.body?.phone || null, req.body?.city || null,
     req.body?.state || null, req.body?.zip || null,
     // THE ACTOR STAMP, and it names the KEY: "which integration created this
     // person" is the first question anybody asks of a record they did not
     // expect, and `system:api` alone cannot answer it.
     `system:api/${req.apiKey.id}`, `API key: ${req.apiKey.name}`]);
  await emitWebhook(orgId, "person.created", { personId: id, email }).catch(() => {});
  const [row] = await query(`SELECT ${API_PERSON_COLS} FROM donors WHERE id=?`, [id]);
  res.status(201).json({ data: apiPerson(row), created: true });
}));

app.post("/api/v1/gifts", apiLimiter, requireApiKey, requireScope("write:gifts"), wrap(async (req, res) => {
  const orgId = req.apiKey.orgId;
  const personId = String(req.body?.personId || "").trim();
  const amount = Number(req.body?.amount);
  const date = String(req.body?.date || "").slice(0, 10);
  if (!personId) return res.status(422).json({ error: "invalid_request", message: "A gift needs a personId." });
  if (!Number.isFinite(amount) || amount <= 0) return res.status(422).json({ error: "invalid_request", message: "A gift needs a positive amount." });
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return res.status(422).json({ error: "invalid_request", message: "A gift needs a date as YYYY-MM-DD." });
  const [d] = await query(`SELECT id FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL`, [personId, orgId]);
  if (!d) return res.status(404).json({ error: "not_found", message: "Steward has no such person for this organisation." });

  // IDEMPOTENT BY THE CALLER'S OWN KEY. An integration that retries after a
  // timeout must not record the gift twice, and the caller is the only party
  // who knows the two requests were the same intent.
  const idemKey = String(req.body?.idempotencyKey || "").trim().slice(0, 120) || null;
  const written = await recordGift({
    orgId, donorId: personId, amount, date,
    type: String(req.body?.type || "cash").slice(0, 40),
    campaign: String(req.body?.campaign || "").slice(0, 120),
    notes: String(req.body?.notes || "").slice(0, 2000),
    fundId: req.body?.fundId || null,
    paymentMethod: req.body?.paymentMethod || null,
    idempotencyKey: idemKey, conflict: idemKey ? "idempotency" : undefined,
    actorId: `system:api/${req.apiKey.id}`, actorName: `API key: ${req.apiKey.name}`,
    source: "public_api",
  });
  if (written.duplicate) {
    const [dup] = await query(`SELECT id, amount, date FROM gifts WHERE org_id=? AND idempotency_key=?`, [orgId, idemKey]);
    return res.status(200).json({ data: dup ? { id: dup.id, personId, amount: Number(dup.amount), date: dup.date } : null, duplicate: true });
  }
  const g = written.gift;
  await emitWebhook(orgId, "gift.created", { giftId: g.id, personId, amount: Number(g.amount), date: g.date }).catch(() => {});
  res.status(201).json({ data: { id: g.id, personId, amount: Number(g.amount), date: g.date } });
}));

app.post("/api/v1/notes", apiLimiter, requireApiKey, requireScope("write:notes"), wrap(async (req, res) => {
  const orgId = req.apiKey.orgId;
  const personId = String(req.body?.personId || "").trim();
  const note = String(req.body?.note || "").trim().slice(0, 4000);
  if (!personId || !note) return res.status(422).json({ error: "invalid_request", message: "A note needs a personId and a note." });
  const [d] = await query(`SELECT id FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL`, [personId, orgId]);
  if (!d) return res.status(404).json({ error: "not_found", message: "Steward has no such person for this organisation." });
  const type = ["call", "meeting", "email", "note"].includes(String(req.body?.type)) ? req.body.type : "note";
  const id = "int_" + uuid().slice(0, 8);
  await run(`INSERT INTO interactions (id,org_id,donor_id,type,note,date,created_by) VALUES (?,?,?,?,?,?,?)`,
    [id, orgId, personId, type, note,
     String(req.body?.date || "").slice(0, 10) || orgToday(await orgTz(orgId)),   // ORG_TZ_SEAM_OK
     `system:api/${req.apiKey.id}`]);
  res.status(201).json({ data: { id, personId, type } });
}));

// ── FIX-31 · A LINKED TASK CHANGES THROUGH ITS RECORD ──────────────────────
// Returns null for an ordinary task (the caller writes it), { refused } when
// the change cannot be made, or { ok } once the thread or deadline changed and
// its trigger brought the task along. Ticking a next step's task logs a line
// "<label>: done" and closes the thread on it (a thread may only close on a
// line or a reason, BUILD-81); Undo takes that line back and reopens it.
async function linkedTaskChange(req, taskId, { done, due }) {
  const orgId = req.user.orgId;
  const [t] = await query("SELECT * FROM tasks WHERE id=? AND org_id=? AND link_kind IN ('next_step','deadline')", [taskId, orgId]);
  if (!t) return null;
  const who = actor(req);
  if (t.link_kind === "deadline") {
    const [ms] = await query("SELECT * FROM grant_milestones WHERE id=? AND org_id=?", [t.milestone_id, orgId]);
    if (!ms) return { refused: { error: "deadline_gone", sentence: "That deadline is no longer on the grant." } };
    if (due !== undefined && due && due !== String(ms.due_date).slice(0, 10)) {
      if (!/^\d{4}-\d{2}-\d{2}$/.test(due)) return { refused: { error: "bad_due_date", sentence: "The date must be a day." } };
      await run("UPDATE grant_milestones SET due_date=?, updated_at=NOW() WHERE id=? AND org_id=?", [due, ms.id, orgId]);
      if (ms.thread_id) await run(`UPDATE threads SET due_date=?, original_due_date=COALESCE(original_due_date, due_date)
                                    WHERE id=? AND org_id=? AND closed_at IS NULL`, [due, ms.thread_id, orgId]);
    }
    if (done === 1 && ms.state !== "done") await markMilestoneDone(orgId, ms.id, who);
    if (done === 0 && ms.state === "done") await reopenMilestone(orgId, ms);
    return { ok: true };
  }
  const [th] = await query("SELECT * FROM threads WHERE id=? AND org_id=?", [t.thread_id, orgId]);
  if (!th) return { refused: { error: "step_gone", sentence: "That next step is no longer on the Thread." } };
  if (due !== undefined && due && due !== String(th.due_date).slice(0, 10) && !th.closed_at) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(due)) return { refused: { error: "bad_due_date", sentence: "The date must be a day." } };
    await run(`UPDATE threads SET due_date=?, original_due_date=COALESCE(original_due_date, due_date) WHERE id=? AND org_id=?`, [due, th.id, orgId]);
  }
  if (done === 1 && !th.closed_at) {
    const intId = "int_" + uuid().slice(0, 10);
    const today = orgToday(await orgTz(orgId));                   // ORG_TZ_SEAM_OK
    await withTransaction(async client => {
      await runTx(client, `INSERT INTO interactions (id,org_id,donor_id,type,date,note,created_by,logged_by_name,metadata)
                           VALUES (?,?,?,?,?,?,?,?,?)`,
        [intId, orgId, th.donor_id, "note", today, `${th.next_step_label}: done.`, who.id, who.name, JSON.stringify({ via: "task_done", threadId: th.id })]);
      await runTx(client, `UPDATE threads SET closed_at=NOW(), close_kind='outcome', closing_interaction_id=? WHERE id=? AND org_id=? AND closed_at IS NULL`,
        [intId, th.id, orgId]);
    });
  }
  if (done === 0 && th.closed_at) {
    const [busy] = await query("SELECT id FROM threads WHERE org_id=? AND donor_id=? AND closed_at IS NULL AND id<>?", [orgId, th.donor_id, th.id]);
    if (busy) return { refused: { error: "step_replaced", sentence: "A newer next step is already open for this person, so this one stays done." } };
    await withTransaction(async client => {
      await runTx(client, `UPDATE threads SET closed_at=NULL, close_kind=NULL, close_reason=NULL, closing_interaction_id=NULL WHERE id=? AND org_id=?`, [th.id, orgId]);
      if (th.closing_interaction_id) await runTx(client, `DELETE FROM interactions WHERE id=? AND org_id=? AND metadata->>'via' = 'task_done'`, [th.closing_interaction_id, orgId]);
    });
  }
  return { ok: true };
}

// ── Tasks ──────────────────────────────────────────────────────────────────
// Tasks — the daily-driver follow-up surface (BUILD-13). A task links an
// optional donor; the linked donor is now RENDERED in the UI, so donorId must
// be org-verified (orgOwns) — a foreign id would otherwise leak a donor
// name/link across tenants (the §1 resurfacing threat model note).
// ── TASKS-2 · ONE RULE FOR WHICH VIEW A TASK IS IN ───────────────────────
// The list, the counts on every view, Home's numbers and the profile all read
// taskViewSql. It is shared/taskShape.js viewOf, in SQL; the tasks2-thread
// suite checks the two agree row by row. Done means done in the last 30 days.
let _taskShape = null;
const taskShapeMod = async () => _taskShape || (_taskShape = await import("../shared/taskShape.js"));
const taskViewSql = `CASE
    WHEN t.done = 1 THEN 'done'
    WHEN COALESCE(t.due, '') !~ '^\\d{4}-\\d{2}-\\d{2}' THEN 'nodate'
    WHEN LEFT(t.due, 10) < ? THEN 'overdue'
    WHEN LEFT(t.due, 10) = ? THEN 'today'
    WHEN LEFT(t.due, 10) <= ? THEN 'upcoming'
    ELSE 'later' END`;
const TASK_SELECT = `t.*, d.name AS donor_name, g.funder AS grant_funder, g.program AS grant_program,
    ev.name AS event_name, cp.name AS campaign_name, hh.name AS household_name`;
const TASK_JOINS = `LEFT JOIN donors d ON d.id = t.donor_id AND d.org_id = t.org_id
    LEFT JOIN grants g ON g.id = t.grant_id AND g.org_id = t.org_id
    LEFT JOIN events ev ON ev.id = t.event_id AND ev.org_id = t.org_id
    LEFT JOIN campaigns cp ON cp.id = t.campaign_id AND cp.org_id = t.org_id
    LEFT JOIN households hh ON hh.id = t.household_id AND hh.org_id = t.org_id`;
// Whose tasks. "mine" for an admin also holds the unowned ones, the Thread's
// own rule (composeThreads), so Home's Thread and Home's numbers agree.
async function taskScope(req) {
  const { orgId, userId } = req.user;
  const isAdmin = req.user.role === "admin";
  const staff = req.query.staff ? String(req.query.staff) : null;
  if (staff && isAdmin) {
    if (!(await OU.orgUser(orgId, staff, { allowInactive: true })).ok) return { refused: true };
    return { sql: "AND t.assigned_to = ?", params: [staff] };
  }
  if (req.query.scope === "all") return { sql: "", params: [] };
  if (req.query.scope === "mine" || req.query.scope === undefined && req.query.view)
    return isAdmin ? { sql: "AND (t.assigned_to = ? OR t.assigned_to IS NULL)", params: [userId] } : { sql: "AND t.assigned_to = ?", params: [userId] };
  return { sql: "", params: [] };
}
async function taskDays(orgId) {
  const today = orgToday(await orgTz(orgId));                        // ORG_TZ_SEAM_OK
  const ts = await taskShapeMod();
  return { today, week: ts.addDays(today, 7), monthAgo: ts.addDays(today, -30) };
}
// What a task is about, as one chip: the most specific record wins.
function taskAbout(t) {
  if (t.grant_id && (t.grant_funder || t.grant_program)) return { kind: "grant", id: t.grant_id, name: [t.grant_funder, t.grant_program].filter(Boolean).join(" · ") };
  if (t.event_id && t.event_name) return { kind: "event", id: t.event_id, name: t.event_name };
  if (t.campaign_id && t.campaign_name) return { kind: "campaign", id: t.campaign_id, name: t.campaign_name };
  if (t.household_id && t.household_name) return { kind: "household", id: t.household_id, name: t.household_name };
  if (t.donor_id && t.donor_name) return { kind: "person", id: t.donor_id, name: t.donor_name };
  return null;
}
async function readTasks(orgId, { where = "", params = [], days }) {
  const ts = await taskShapeMod();
  const rows = await query(
    `SELECT ${TASK_SELECT}, ${taskViewSql} AS view
       FROM tasks t ${TASK_JOINS}
      WHERE t.org_id = ? AND t.voided_at IS NULL
        -- WIRE-1: a deleted person's tasks go with them (and come back on Undo).
        AND (t.donor_id IS NULL OR d.deleted_at IS NULL) ${where}
      ORDER BY CASE t.priority WHEN 'high' THEN 0 ELSE 1 END, t.due ASC NULLS LAST, t.due_time ASC NULLS LAST, t.created_at DESC`,
    [days.today, days.today, days.week, orgId, ...params]);
  return rows.map(t => ({ ...t, kind: ts.kindOf(t), kindChosen: t.kind || null, about: taskAbout(t) }));
}
const readTask = async (orgId, id) => {
  const days = await taskDays(orgId);
  const [row] = await readTasks(orgId, { where: "AND t.id = ?", params: [id], days });
  return row || null;
};

app.get("/tasks", requireAuth, wrap(async (req, res) => {
  // scope=mine → the caller's own; all (or none) → the whole org; staff=<id>
  // (admins) → one person's. view=<today|upcoming|overdue|later|nodate|done>
  // narrows to one view with the same rule the counts use.
  const scope = await taskScope(req);
  if (scope.refused) return OU.refuse(res, "staff");
  const days = await taskDays(req.user.orgId);
  const view = String(req.query.view || "");
  const viewWhere = ["today", "upcoming", "overdue", "later", "nodate", "done"].includes(view) ? `AND ${taskViewSql} = ?` : "";
  const viewParams = viewWhere ? [days.today, days.today, days.week, view] : [];
  const doneWindow = view === "done" ? "AND COALESCE(t.completed_at, t.updated_at, t.created_at) >= ?::date" : "";
  const rows = await readTasks(req.user.orgId, {
    where: `${scope.sql} ${viewWhere} ${doneWindow}`,
    params: [...scope.params, ...viewParams, ...(doneWindow ? [days.monthAgo] : [])], days });
  res.json(rows);
}));

// The count on every view, from the same rule as the list. Home reads this.
async function taskCounts(orgId, scope) {
  const days = await taskDays(orgId);
  const rows = await query(
    `SELECT v, COUNT(*)::int AS n FROM (
       SELECT ${taskViewSql} AS v, t.done, COALESCE(t.completed_at, t.updated_at, t.created_at) AS fin
         FROM tasks t LEFT JOIN donors d ON d.id = t.donor_id AND d.org_id = t.org_id
        WHERE t.org_id = ? AND t.voided_at IS NULL AND (t.donor_id IS NULL OR d.deleted_at IS NULL) ${scope.sql}) x
      WHERE v <> 'done' OR fin >= ?::date
      GROUP BY v`,
    [days.today, days.today, days.week, orgId, ...scope.params, days.monthAgo]);
  const out = { today: 0, upcoming: 0, overdue: 0, later: 0, nodate: 0, done: 0 };
  for (const r of rows) out[r.v] = r.n;
  out.open = out.today + out.upcoming + out.overdue + out.later + out.nodate;
  return { ...out, asOf: days.today };
}
app.get("/tasks/counts", requireAuth, wrap(async (req, res) => {
  const scope = await taskScope({ ...req, query: { ...req.query, view: req.query.view || "count" } });
  if (scope.refused) return OU.refuse(res, "staff");
  res.json(await taskCounts(req.user.orgId, scope));
}));

// Quick add: read the words, find the person, change nothing. The person
// confirms on the screen before anything is saved.
app.post("/tasks/parse", requireAuth, wrap(async (req, res) => {
  if (req.audit) req.audit.skip("reads a sentence and writes nothing");
  const text = String((req.body && req.body.text) || "").slice(0, 300);
  if (!text.trim()) return res.status(400).json({ error: "text_required", sentence: "Type what needs doing." });
  const ts = await taskShapeMod();
  const { today } = await taskDays(req.user.orgId);
  const p = ts.parseQuickAdd(text, today);
  let person = null, span = null, candidates = [];
  // Each capitalised run, and its tail without a title ("Rev. Ana Ortiz").
  const tries = [];
  for (const sp of p.nameSpans) { const w = sp.split(" "); for (let i = 0; i < w.length && w.length - i >= 1; i++) tries.push([sp, w.slice(i).join(" ")]); }
  for (const [sp, name] of tries) {
    if (name.length < 3) continue;
    const rows = await query(
      `SELECT id, name FROM donors WHERE org_id = ? AND deleted_at IS NULL
          AND (LOWER(name) = LOWER(?) OR LOWER(name) LIKE LOWER(?) OR LOWER(name) LIKE LOWER(?))
        ORDER BY (LOWER(name) = LOWER(?)) DESC, name LIMIT 5`,
      [req.user.orgId, name, name + " %", "% " + name, name]);
    const exact = rows.filter(r => r.name.toLowerCase() === name.toLowerCase());
    if (exact.length === 1 || rows.length === 1) { person = exact[0] || rows[0]; span = name; break; }
    if (rows.length > 1 && !candidates.length) { candidates = rows; span = name; }
  }
  const title = ts.titleWithout(p.rest, person ? span : null);
  res.json({ title, kind: p.kind, due: p.due, time: p.time, recur: p.recur, recurPhrase: ts.recurPhrase(p.recur),
             priority: p.priority, person, candidates: person ? [] : candidates, heard: p.matched, today });
}));

// A donor's own open tasks — surfaced on the donor profile.
app.get("/donors/:id/tasks", requireAuth, wrap(async (req, res) => {
  if (!(await orgOwns("donors", req.params.id, req.user.orgId)))
    return res.status(404).json({ error: "Donor not found" });
  const tasks = await query(
    `SELECT * FROM tasks WHERE org_id = ? AND donor_id = ? AND voided_at IS NULL
      ORDER BY done ASC, due ASC NULLS LAST, created_at DESC`,
    [req.user.orgId, req.params.id]
  );
  res.json(tasks);
}));

app.post("/tasks", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { title, due, priority, type, donorId, assignedTo, assignedToName } = req.body;
  if (!title || !String(title).trim()) return res.status(400).json({ error: "Title required" });
  // Tenant guard: a linked donor must belong to the caller's org.
  if (!(await orgOwns("donors", donorId, req.user.orgId)))
    return res.status(404).json({ error: "Donor not found" });

  // Owner defaults to the creator; may target a teammate (validated to the org).
  if (!(await OU.orgUser(req.user.orgId, assignedTo)).ok) return OU.refuse(res, "assignedTo");
  const ownerTargetId = assignedTo || req.user.userId;
  const u = await query("SELECT id, name FROM users WHERE id=? AND org_id=?", [ownerTargetId, req.user.orgId]);
  const ownerId = u.length ? u[0].id : req.user.userId;
  const ownerName = (u.length && u[0].name) || assignedToName || "";

  // ── BUILD-88a A.2 — NO LABEL BEGINS "FOLLOW UP:" ─────────────────────────
  // A follow-up list every row of which starts with the words "Follow up" is a
  // list you cannot read: the only part that differs is at the end, and the
  // thing that tells you what to DO has been replaced by the fact that there is
  // something to do. The label is the STEP — read out of the note by the same
  // extractor the conversation flow uses (shared/threadShape.js stepFromNote),
  // or the type's own default. The user's own sentence is never touched; only
  // the prefix that says nothing is.
  const taskTitle = await (async () => {
    const raw = String(title).trim();
    const m = /^follow\s*up\s*:\s*(.*)$/i.exec(raw);
    if (!m) return raw;
    const shape = await threadShapeMod();
    const rest = m[1].trim();
    const fromNote = shape.stepFromNote(req.body.note || rest);
    if (fromNote && fromNote.label) return fromNote.label;
    return shape.nextStepLabelFor("follow_up") || "Follow up";
  })();

  // TASKS-2 — the rest of a task: its kind, time, notes, checklist, repeat,
  // and the record it is about (each checked to belong to this org).
  const x = await taskExtras(req.user.orgId, req.body || {});
  if (x.refused) return res.status(x.status || 400).json(x.refused);
  if (due && !/^\d{4}-\d{2}-\d{2}$/.test(String(due))) return res.status(400).json({ error: "bad_due_date", sentence: "The date must be a day." });
  const id = "t_" + uuid().slice(0, 8);
  await run(
    `INSERT INTO tasks (id,org_id,title,due,priority,type,done,donor_id,assigned_to,assigned_to_name,updated_at,created_by,created_by_name,
                        kind,due_time,notes,checklist,recur,household_id,grant_id,event_id,campaign_id,recur_parent_id)
     VALUES (?,?,?,?,?,?,0,?,?,?,NOW(),?,?,?,?,?,?::jsonb,?::jsonb,?,?,?,?,?)`,
    [id, req.user.orgId, taskTitle, due || "", priority === "high" ? "high" : "medium", type || "donor",
     donorId || null, ownerId, ownerName, actor(req).id, actor(req).name,
     x.fields.kind ?? null, x.fields.due_time ?? null, x.fields.notes ?? null, JSON.stringify(x.fields.checklist || []),
     x.fields.recur ? JSON.stringify(x.fields.recur) : null, x.fields.household_id ?? null, x.fields.grant_id ?? null,
     x.fields.event_id ?? null, x.fields.campaign_id ?? null, req.body.recurParentId && /^t_/.test(String(req.body.recurParentId)) ? String(req.body.recurParentId) : null]
  );
  const rows = [await readTask(req.user.orgId, id)];
  // BUILD-36 A2: if this task was assigned to someone OTHER than the creator,
  // email the assignee (no email for a self-assigned task). Fire-and-forget.
  if (rows[0]?.assigned_to && rows[0].assigned_to !== req.user.userId) {
    queueTaskAssignmentEmail(rows[0], req.user.userId).catch(e => console.error("[task] assign email:", e.message));
  }
  res.status(201).json(rows[0]);
}));

// TASKS-2 — the optional fields of a task, validated once for create, edit
// and bulk. Returns { fields } (only the keys that were sent) or { refused }.
async function taskExtras(orgId, b) {
  const ts = await taskShapeMod();
  const f = {};
  if (b.kind !== undefined) f.kind = b.kind ? ts.normalizeKind(b.kind) : null;
  if (b.kind && !f.kind) return { refused: { error: "bad_kind", sentence: "That kind of task is not one Steward knows." } };
  if (b.dueTime !== undefined) {
    if (b.dueTime && !/^([01]\d|2[0-3]):[0-5]\d$/.test(String(b.dueTime))) return { refused: { error: "bad_time", sentence: "The time must be like 14:00." } };
    f.due_time = b.dueTime || null;
  }
  if (b.notes !== undefined) f.notes = String(b.notes || "").slice(0, 8000) || null;
  if (b.checklist !== undefined) {
    if (!Array.isArray(b.checklist)) return { refused: { error: "bad_checklist", sentence: "A checklist is a list of items." } };
    f.checklist = b.checklist.slice(0, 50).map(i => ({ text: String((i && i.text) || "").slice(0, 300), done: !!(i && i.done) })).filter(i => i.text.trim());
  }
  if (b.recur !== undefined) {
    f.recur = b.recur ? ts.normalizeRecur(b.recur) : null;
    if (b.recur && !f.recur) return { refused: { error: "bad_recur", sentence: "A repeat is weekly, monthly or quarterly." } };
  }
  for (const [key, table, col] of [["householdId", "households", "household_id"], ["grantId", "grants", "grant_id"],
                                   ["eventId", "events", "event_id"], ["campaignId", "campaigns", "campaign_id"]]) {
    if (b[key] === undefined) continue;
    if (b[key] && !(await orgOwns(table, b[key], orgId))) return { refused: { error: "not_found", sentence: "That record is not in this organization." }, status: 404 };
    f[col] = b[key] || null;
  }
  return { fields: f };
}

// TASKS-2 — change some of a task and leave the rest alone (the full PUT
// replaces every column, which an inline edit must never do). A linked
// task's day goes through its next step or deadline, like everywhere else.
app.patch("/tasks/:id", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [t] = await query("SELECT * FROM tasks WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!t) return res.status(404).json({ error: "Task not found" });
  const b = req.body || {};
  const x = await taskExtras(orgId, b);
  if (x.refused) return res.status(x.status || 400).json(x.refused);
  const sets = [], params = [];
  const add = (col, v, cast = "") => { sets.push(`${col}=?${cast}`); params.push(v); };
  for (const [col, v] of Object.entries(x.fields)) add(col, col === "checklist" || col === "recur" ? (v == null ? null : JSON.stringify(v)) : v, col === "checklist" || col === "recur" ? "::jsonb" : "");
  if (b.title !== undefined && !t.link_kind) { if (!String(b.title).trim()) return res.status(400).json({ error: "Title required" }); add("title", String(b.title).trim().slice(0, 300)); }
  if (b.priority !== undefined) add("priority", b.priority === "high" ? "high" : "medium");
  if (b.donorId !== undefined && !t.link_kind) {
    if (!(await orgOwns("donors", b.donorId, orgId))) return res.status(404).json({ error: "Donor not found" });
    add("donor_id", b.donorId || null);
  }
  let reassigned = null;
  if (b.assignedTo !== undefined) {
    if (b.assignedTo) {
      const { ok, user: u } = await OU.orgUser(orgId, b.assignedTo);
      if (!ok) return OU.refuse(res, "assignedTo");
      add("assigned_to", u.id); add("assigned_to_name", u.name || "");
      if (u.id !== t.assigned_to) reassigned = u.id;
    } else { add("assigned_to", null); add("assigned_to_name", null); }
    add("reassign_note", String(b.reassignNote || "").slice(0, 500) || null);
  }
  if (b.due !== undefined) {
    const due = String(b.due || "");
    if (due && !/^\d{4}-\d{2}-\d{2}$/.test(due)) return res.status(400).json({ error: "bad_due_date", sentence: "The date must be a day." });
    const linked = await linkedTaskChange(req, t.id, { due });
    if (linked && linked.refused) return res.status(409).json(linked.refused);
    if (!linked) add("due", due);
  }
  if (sets.length) {
    sets.push("updated_at=NOW()");
    await run(`UPDATE tasks SET ${sets.join(",")} WHERE id=? AND org_id=?`, [...params, t.id, orgId]);
  }
  // FIX-31: a next step's owner is the thread's; reassigning its task moves the thread.
  if (reassigned && t.link_kind === "next_step" && t.thread_id) {
    const [u] = await query("SELECT name FROM users WHERE id=? AND org_id=?", [reassigned, orgId]);
    await run("UPDATE threads SET owner_id=?, owner_name=? WHERE id=? AND org_id=? AND closed_at IS NULL", [reassigned, u ? u.name : null, t.thread_id, orgId]);
  }
  const row = await readTask(orgId, t.id);
  if (reassigned && reassigned !== req.user.userId) queueTaskAssignmentEmail(row, req.user.userId).catch(e => console.error("[task] reassign email:", e.message));
  res.json(row);
}));

// TASKS-2 — Snooze: the task moves to a later day and remembers why and from
// when. Undo is a PATCH of the day back (the screen holds `snoozedFrom`).
app.post("/tasks/:id/snooze", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const until = String((req.body && req.body.until) || "");
  if (!/^\d{4}-\d{2}-\d{2}$/.test(until)) return res.status(400).json({ error: "bad_due_date", sentence: "Pick the day to bring it back." });
  const { today } = await taskDays(orgId);
  if (until <= today) return res.status(400).json({ error: "not_later", sentence: "Snooze to a day after today." });
  const [t] = await query("SELECT id, due FROM tasks WHERE id=? AND org_id=? AND done=0", [req.params.id, orgId]);
  if (!t) return res.status(404).json({ error: "Task not found" });
  const linked = await linkedTaskChange(req, t.id, { due: until });
  if (linked && linked.refused) return res.status(409).json(linked.refused);
  await run(`UPDATE tasks SET ${linked ? "" : "due=?, "}snooze_reason=?, snoozed_from=?, snoozed_at=NOW(), updated_at=NOW() WHERE id=? AND org_id=?`,
    [...(linked ? [] : [until]), String((req.body && req.body.reason) || "").slice(0, 300) || null, t.due || "", t.id, orgId]);
  res.json({ ...(await readTask(orgId, t.id)), previousDue: t.due || "" });
}));

// TASKS-2 — Bulk: reassign, move a day, mark done, or delete, many at once.
// A next step or a grant deadline changes through its own record (FIX-31);
// one that cannot is SKIPPED and named, never half-done. The answer carries
// what each row was before, so the screen's Undo can put every one back.
app.post("/tasks/bulk", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const b = req.body || {};
  const ids = Array.isArray(b.ids) ? [...new Set(b.ids.map(String))].slice(0, 200) : [];
  const action = String(b.action || "");
  if (!ids.length || !["reassign", "move", "done", "undone", "delete", "restore"].includes(action))
    return res.status(400).json({ error: "bad_bulk", sentence: "Pick some tasks and one thing to do to them." });
  const rows = await query(`SELECT id, title, due, done, assigned_to, assigned_to_name, link_kind, thread_id FROM tasks WHERE org_id=? AND id IN (${ids.map(() => "?").join(",")})`, [orgId, ...ids]);
  let owner = null;
  if (action === "reassign") {
    const { ok, user: u } = await OU.orgUser(orgId, b.assignedTo);
    if (!ok || !b.assignedTo) return OU.refuse(res, "assignedTo");
    owner = u;
  }
  if (action === "move" && !/^\d{4}-\d{2}-\d{2}$/.test(String(b.due || ""))) return res.status(400).json({ error: "bad_due_date", sentence: "The date must be a day." });
  const before = [], changed = [], skipped = [], undoIds = [];
  for (const t of rows) {
    const prior = { id: t.id, due: t.due || "", done: t.done, assignedTo: t.assigned_to || null };
    if (action === "reassign") {
      await run("UPDATE tasks SET assigned_to=?, assigned_to_name=?, reassign_note=?, updated_at=NOW() WHERE id=? AND org_id=?",
        [owner.id, owner.name || "", String(b.note || "").slice(0, 500) || null, t.id, orgId]);
      if (t.link_kind === "next_step" && t.thread_id)
        await run("UPDATE threads SET owner_id=?, owner_name=? WHERE id=? AND org_id=? AND closed_at IS NULL", [owner.id, owner.name, t.thread_id, orgId]);
    } else if (action === "move") {
      const linked = await linkedTaskChange(req, t.id, { due: b.due });
      if (linked && linked.refused) { skipped.push({ id: t.id, title: t.title, sentence: linked.refused.sentence }); continue; }
      if (!linked) await run("UPDATE tasks SET due=?, updated_at=NOW() WHERE id=? AND org_id=?", [b.due, t.id, orgId]);
    } else if (action === "done" || action === "undone") {
      const done = action === "done" ? 1 : 0;
      if (t.done === done) continue;
      const linked = await linkedTaskChange(req, t.id, { done });
      if (linked && linked.refused) { skipped.push({ id: t.id, title: t.title, sentence: linked.refused.sentence }); continue; }
      if (!linked) await run(`UPDATE tasks SET done=?, completed_at=${done ? "NOW()" : "NULL"}, completed_by_name=?, updated_at=NOW() WHERE id=? AND org_id=?`,
        [done, done ? actor(req).name : null, t.id, orgId]);
    } else if (action === "delete") {
      if (t.link_kind === "next_step" || t.link_kind === "deadline") {
        skipped.push({ id: t.id, title: t.title, sentence: t.link_kind === "deadline" ? "A grant deadline goes when it is taken off the grant." : "A next step goes when it is dismissed on the Thread." });
        continue;
      }
      const undoId = await trashRow("tasks", t.id, req);
      if (undoId) undoIds.push(undoId);
    } else if (action === "restore") {
      // Undo of a reassign or a move: each row back as it was.
      const want = (Array.isArray(b.before) ? b.before : []).find(x => x && x.id === t.id);
      if (!want) continue;
      if (want.assignedTo !== undefined && want.assignedTo !== t.assigned_to) {
        const [u] = want.assignedTo ? await query("SELECT id, name FROM users WHERE id=? AND org_id=?", [want.assignedTo, orgId]) : [null];
        await run("UPDATE tasks SET assigned_to=?, assigned_to_name=?, updated_at=NOW() WHERE id=? AND org_id=?", [u ? u.id : null, u ? u.name : null, t.id, orgId]);
        if (t.link_kind === "next_step" && t.thread_id && u)
          await run("UPDATE threads SET owner_id=?, owner_name=? WHERE id=? AND org_id=? AND closed_at IS NULL", [u.id, u.name, t.thread_id, orgId]);
      }
      if (want.due !== undefined && String(want.due) !== String(t.due || "")) {
        const linked = await linkedTaskChange(req, t.id, { due: want.due });
        if (!linked && /^(\d{4}-\d{2}-\d{2})?$/.test(String(want.due))) await run("UPDATE tasks SET due=?, updated_at=NOW() WHERE id=? AND org_id=?", [want.due, t.id, orgId]);
      }
    }
    before.push(prior); changed.push(t.id);
  }
  if (req.audit) req.audit.after({ action, changed, skipped: skipped.map(x => x.id) });
  res.json({ action, changed, skipped, before, undoIds, undoSeconds: UNDO_SECONDS });
}));

app.put("/tasks/:id", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { title, due, priority, type, done, donorId, assignedTo } = req.body;
  if (!title || !String(title).trim()) return res.status(400).json({ error: "Title required" });
  if (donorId !== undefined && !(await orgOwns("donors", donorId, req.user.orgId)))
    return res.status(404).json({ error: "Donor not found" });

  // Reassignment (BUILD-36 A2): validate a new assignee to the org, capture the
  // prior owner so we only notify on a genuine change to a NEW person.
  const priorRows = await query("SELECT assigned_to FROM tasks WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!priorRows.length) return res.status(404).json({ error: "Task not found" });
  const priorAssignee = priorRows[0].assigned_to;
  let newAssignee, newAssigneeName;
  if (assignedTo !== undefined) {
    if (assignedTo) {
      const { ok, user: u } = await OU.orgUser(req.user.orgId, assignedTo);
      if (!ok) return OU.refuse(res, "assignedTo");
      newAssignee = u.id; newAssigneeName = u.name || "";
    } else { newAssignee = null; newAssigneeName = null; }
  }

  // FIX-31: a linked task's date and done state belong to its next step or
  // deadline; change them there and the trigger brings the task along.
  const linked = await linkedTaskChange(req, req.params.id, { done: done ? 1 : 0, due: due || "" });
  if (linked && linked.refused) return res.status(409).json(linked.refused);
  const sets = linked ? ["priority=?", "updated_at=NOW()"] : ["title=?", "due=?", "priority=?", "type=?", "done=?", "updated_at=NOW()"];
  const params = linked ? [priority || "medium"] : [String(title).trim(), due || "", priority || "medium", type || "donor", done ? 1 : 0];
  if (donorId !== undefined) { sets.push("donor_id=?"); params.push(donorId || null); }
  if (assignedTo !== undefined) { sets.push("assigned_to=?", "assigned_to_name=?"); params.push(newAssignee, newAssigneeName); }
  params.push(req.params.id, req.user.orgId);

  const affected = await run(
    `UPDATE tasks SET ${sets.join(",")} WHERE id=? AND org_id=?`, params);
  if (!affected.changes) return res.status(404).json({ error: "Task not found" });
  const rows = await query(
    `SELECT t.*, d.name AS donor_name FROM tasks t
       LEFT JOIN donors d ON d.id = t.donor_id AND d.org_id = t.org_id WHERE t.id = ?`, [req.params.id]);
  // Notify only on a genuine reassignment to a NEW person who isn't the actor.
  if (assignedTo !== undefined && newAssignee && newAssignee !== priorAssignee && newAssignee !== req.user.userId) {
    queueTaskAssignmentEmail(rows[0], req.user.userId).catch(e => console.error("[task] reassign email:", e.message));
  }
  res.json(rows[0]);
}));

// One-click complete/reopen — the primary Tasks action (write-gated).
app.post("/tasks/:id/complete", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const done = req.body.done === false ? 0 : 1;
  const orgId = req.user.orgId;
  const ts = await taskShapeMod();
  const [t] = await query("SELECT * FROM tasks WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!t) return res.status(404).json({ error: "Task not found" });
  // TASKS-2 · DONE PROPERLY. A call or a meeting with a person is finished by
  // saying how it went and what is next: the conversation is logged through
  // POST /donors/:id/conversations (which requires a next step or an explicit
  // "No next step") and its id comes here. A bare tick is refused, so the
  // thread never ends without a decision.
  // FIX-34 · AN EMAIL SENT FROM ITS TASK asks for the next step the way a
  // call does: the email's own timeline line (sent through /tasks/:id/email)
  // carries the decision, and a next step opens a thread on it.
  if (done === 1 && !t.done && t.donor_id && req.body.interactionId && req.body.nextStep) {
    const [ei] = await query(
      `SELECT id, date FROM interactions WHERE id=? AND org_id=? AND donor_id=? AND metadata->>'via'='task_email' AND metadata->>'taskId'=?
          AND metadata->>'next_step' IS NULL`, [String(req.body.interactionId), orgId, t.donor_id, t.id]);
    if (ei) {
      const shape = await threadShapeMod();
      const ns = req.body.nextStep;
      const skipped = ns.skipped === true;
      let step = null;
      if (!skipped) {
        const typeLabel = shape.nextStepLabelFor(ns.type);
        if (!typeLabel || !/^\d{4}-\d{2}-\d{2}$/.test(String(ns.due || ""))) return res.status(400).json({ error: "nextStep must be {type, due} from the offered set, or {skipped:true}" });
        step = { type: ns.type, label: shape.sanitizeStepLabel(ns.label) || typeLabel, due: ns.due, time: null };
      }
      const [donor] = await query("SELECT assigned_to, assigned_to_name FROM donors WHERE id=? AND org_id=?", [t.donor_id, orgId]);
      const [me] = await query("SELECT name FROM users WHERE id=?", [req.user.userId]);
      const userName = me?.name || "";
      const { today } = await taskDays(orgId);
      await withTransaction(async client => {
        await runTx(client, `UPDATE interactions SET metadata = COALESCE(metadata,'{}'::jsonb) || ?::jsonb WHERE id=? AND org_id=?`,
          [JSON.stringify({ next_step: skipped ? "skipped" : "set", ...(step ? { next_step_label: step.label } : {}) }), ei.id, orgId]);
        await queryTx(client, `UPDATE threads SET closed_at = NOW(), close_kind = 'outcome', closing_interaction_id = ?
            WHERE org_id = ? AND donor_id = ? AND closed_at IS NULL RETURNING id`, [ei.id, orgId, t.donor_id]);
        if (step) await openThreadTx(client, { orgId, donorId: t.donor_id, step, openedOn: today,
          ownerId: donor?.assigned_to || req.user.userId, ownerName: donor?.assigned_to ? donor.assigned_to_name : userName,
          actorId: req.user.userId, actorName: userName, openingInteractionId: ei.id, followon: null });
      });
    }
  }
  // FIX-34: a next step's own task (link_kind next_step) that is a call or a
  // meeting is finished the same way: the Calendar's Mark done used to close
  // it with no "How did it go?" and no "What's next?". A deadline's task keeps
  // its plain tick.
  let viaConversation = false;
  let outcomeKind = !t.link_kind ? ts.kindOf(t) : null;
  if (t.link_kind === "next_step" && t.thread_id) {
    const [th] = await query("SELECT next_step_type FROM threads WHERE id=? AND org_id=?", [t.thread_id, orgId]);
    outcomeKind = th && ts.NEEDS_OUTCOME.has(th.next_step_type) ? th.next_step_type : ts.kindOf(t);
  }
  if (done === 1 && !t.done && t.donor_id && outcomeKind && ts.NEEDS_OUTCOME.has(outcomeKind)) {
    const iid = String(req.body.interactionId || "");
    const [i] = iid ? await query(
      `SELECT id FROM interactions WHERE id=? AND org_id=? AND donor_id=? AND metadata->>'next_step' IN ('set','skipped')`,
      [iid, orgId, t.donor_id]) : [];
    if (!i) return res.status(422).json({ error: "needs_outcome",
      kind: outcomeKind,
      sentence: `Say how the ${outcomeKind === "call" ? "call" : "meeting"} went and what's next (or "No next step") to finish it.` });
    viaConversation = true;
  }
  // FIX-31: a next step's or a deadline's task is ticked through that record,
  // and the record's trigger ticks the task: one record, every view. When the
  // conversation already closed the next step, there is nothing left to tick.
  const fresh = viaConversation ? (await query("SELECT done FROM tasks WHERE id=? AND org_id=?", [t.id, orgId]))[0] : null;
  const linked = fresh && fresh.done === 1 ? { ok: true } : await linkedTaskChange(req, t.id, { done });
  if (linked && linked.refused) return res.status(409).json(linked.refused);
  if (!linked) await run("UPDATE tasks SET done=?, updated_at=NOW() WHERE id=? AND org_id=?", [done, t.id, orgId]);
  await run(`UPDATE tasks SET completed_at=${done ? "COALESCE(completed_at, NOW())" : "NULL"}, completed_by_name=? WHERE id=? AND org_id=?`,
    [done ? actor(req).name : null, t.id, orgId]);
  // TASKS-2 · A REPEAT. Finishing a repeating task makes the next one, once;
  // taking the tick back takes the untouched next one away again.
  let next = null;
  const recur = ts.normalizeRecur(t.recur);
  if (recur && done === 1) {
    const [have] = await query("SELECT id FROM tasks WHERE recur_parent_id=? AND org_id=?", [t.id, orgId]);
    if (!have) {
      const { today } = await taskDays(orgId);
      const nid = "t_" + uuid().slice(0, 8);
      await run(
        `INSERT INTO tasks (id,org_id,title,due,priority,type,done,donor_id,assigned_to,assigned_to_name,updated_at,created_by,created_by_name,
                            kind,due_time,notes,checklist,recur,household_id,grant_id,event_id,campaign_id,recur_parent_id)
         SELECT ?,org_id,title,?,priority,type,0,donor_id,assigned_to,assigned_to_name,NOW(),?,?,
                kind,due_time,notes,(SELECT COALESCE(jsonb_agg(jsonb_set(e,'{done}','false'::jsonb)),'[]'::jsonb) FROM jsonb_array_elements(COALESCE(checklist,'[]'::jsonb)) e),
                recur,household_id,grant_id,event_id,campaign_id,id
           FROM tasks WHERE id=? AND org_id=?`,
        [nid, ts.nextDue(recur, t.due, today), "system:task-repeat", "Steward", t.id, orgId]);
      next = await readTask(orgId, nid);
    }
  }
  if (recur && done === 0) await run("DELETE FROM tasks WHERE recur_parent_id=? AND org_id=? AND done=0 AND link_kind IS NULL", [t.id, orgId]);
  res.json({ ...(await readTask(orgId, t.id)), next });
}));

// FIX-34 · A THANK-YOU TASK DOES THE THANKING. The task's Thank-you button
// opens the draft for THAT gift (the task's source gift, else the person's
// latest gift not yet thanked). Sending it, or marking it sent, is one write:
// the gift is thanked the way /acknowledgments/mark thanks it, its drafted
// thank-you leaves the queue, and the task closes. She pressed Send; Steward
// did not send anything on its own. Undo (POST /tasks/:id/thank/undo) puts
// all three back.
async function taskGiftToThank(orgId, t, giftId) {
  if (giftId) { const [g] = await query("SELECT * FROM gifts WHERE id=? AND org_id=? AND donor_id=?", [String(giftId), orgId, t.donor_id]); if (g) return g; }
  if (t.source_gift_id) { const [g] = await query("SELECT * FROM gifts WHERE id=? AND org_id=?", [t.source_gift_id, orgId]); if (g) return g; }
  const [g] = await query(
    `SELECT * FROM gifts WHERE org_id=? AND donor_id=? AND amount > 0 AND acknowledgement_sent IS NOT TRUE
      ORDER BY date DESC, id DESC LIMIT 1`, [orgId, t.donor_id]);
  return g || null;
}
app.get("/tasks/:id/thank", requireAuth, wrap(async (req, res) => {
  const [t] = await query("SELECT * FROM tasks WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!t || !t.donor_id) return res.status(404).json({ error: "Task not found" });
  const g = await taskGiftToThank(req.user.orgId, t, req.query.giftId);
  const [d] = await query("SELECT id, name, email FROM donors WHERE id=? AND org_id=?", [t.donor_id, req.user.orgId]);
  const [gc] = await query("SELECT COUNT(*)::int AS n FROM gifts WHERE org_id=? AND donor_id=? AND amount > 0", [req.user.orgId, t.donor_id]);
  res.json({ giftCount: gc ? gc.n : 0, gift: g ? { id: g.id, amount: Number(g.amount), date: String(g.date || "").slice(0, 10), thanked: g.acknowledgement_sent === true } : null,
             donor: d ? { id: d.id, name: d.name, email: d.email || null } : null });
}));
app.post("/tasks/:id/thank", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  await ACK_READY;
  const orgId = req.user.orgId;
  const [t] = await query("SELECT * FROM tasks WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!t || !t.donor_id) return res.status(404).json({ error: "Task not found" });
  const g = await taskGiftToThank(orgId, t, req.body && req.body.giftId);
  if (!g) return res.status(409).json({ error: "no_gift", sentence: "There is no gift on file to thank this person for yet." });
  const mode = req.body && req.body.mode === "send" ? "send" : "mark";
  if (mode === "send") {
    const subject = String((req.body && req.body.subject) || "").trim().slice(0, 200);
    const body = String((req.body && req.body.body) || "").trim().slice(0, 8000);
    if (!subject || !body) return res.status(400).json({ error: "A thank-you needs a subject and words." });
    const who = actor(req), mdId = "md_" + uuid().slice(0, 12);
    await run(`INSERT INTO milestone_drafts (id,org_id,donor_id,milestone_key,subject,body,status,source,created_by,created_by_name)
               VALUES (?,?,?,?,?,?,'pending_review','task',?,?)`,
      [mdId, orgId, t.donor_id, `task-thanks:${t.id}:${Date.now()}`, subject, body, who.id, who.name]);
    const [draft] = await query("SELECT * FROM milestone_drafts WHERE id=?", [mdId]);
    const r = await sendMilestoneDraft(req, draft);
    if (r.status !== 200) { await run("DELETE FROM milestone_drafts WHERE id=? AND org_id=?", [mdId, orgId]); return res.status(r.status).json({ error: r.error, sentence: r.error }); }
  }
  const before = { acknowledgement_sent: g.acknowledgement_sent === true, acknowledgement_sent_at: g.acknowledgement_sent_at || null,
    acknowledged_by: g.acknowledged_by || null, acknowledged_by_name: g.acknowledged_by_name || null, acknowledged_via: g.acknowledged_via || null };
  const [u] = await query("SELECT name FROM users WHERE id=?", [req.user.userId]);
  const whoName = u?.name || actor(req).name;
  await run(
    `UPDATE gifts SET acknowledgement_sent=true, acknowledgement_sent_at=COALESCE(acknowledgement_sent_at, NOW()),
                      acknowledged_by=COALESCE(acknowledged_by, ?), acknowledged_by_name=COALESCE(acknowledged_by_name, ?),
                      acknowledged_via=COALESCE(acknowledged_via, 'email')
      WHERE org_id=? AND id=?`, [actor(req).id, whoName, orgId, g.id]);
  const drafts = await query("UPDATE thank_you_drafts SET sent_at=NOW() WHERE org_id=? AND gift_id=? AND sent_at IS NULL AND skipped_at IS NULL RETURNING id", [orgId, g.id]).catch(() => []);
  const linked = await linkedTaskChange(req, t.id, { done: 1 });
  if (linked && linked.refused) return res.status(409).json(linked.refused);
  if (!linked) await run("UPDATE tasks SET done=1, updated_at=NOW() WHERE id=? AND org_id=?", [t.id, orgId]);
  await run("UPDATE tasks SET completed_at=COALESCE(completed_at, NOW()), completed_by_name=? WHERE id=? AND org_id=?", [actor(req).name, t.id, orgId]);
  if (req.audit) { req.audit.entity("gift", g.id); req.audit.before(before); req.audit.after({ acknowledgement_sent: true, task_done: true, mode }); }
  res.json({ ok: true, mode, giftId: g.id, before, draftIds: drafts.map(d => d.id), task: await readTask(orgId, t.id) });
}));
app.post("/tasks/:id/thank/undo", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [t] = await query("SELECT * FROM tasks WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!t) return res.status(404).json({ error: "Task not found" });
  const b = (req.body && req.body.before) || {};
  const giftId = String((req.body && req.body.giftId) || "");
  if (giftId && !b.acknowledgement_sent) {
    await run(`UPDATE gifts SET acknowledgement_sent=false, acknowledgement_sent_at=NULL, acknowledged_by=NULL, acknowledged_by_name=NULL, acknowledged_via=NULL
                WHERE org_id=? AND id=?`, [orgId, giftId]);
  }
  const ids = Array.isArray(req.body && req.body.draftIds) ? req.body.draftIds.map(String) : [];
  if (ids.length) await run("UPDATE thank_you_drafts SET sent_at=NULL WHERE org_id=? AND id = ANY(?)", [orgId, ids]);
  const linked = await linkedTaskChange(req, t.id, { done: 0 });
  if (!linked) await run("UPDATE tasks SET done=0, completed_at=NULL, completed_by_name=NULL, updated_at=NOW() WHERE id=? AND org_id=?", [t.id, orgId]);
  res.json({ ok: true, task: await readTask(orgId, t.id) });
}));

// FIX-34 · AN EMAIL TASK OPENS A DRAFT. Send goes through the one draft sender
// (sendMilestoneDraft: donorMailDecision, the footer, the timeline line). The
// task stays open: it is finished through /tasks/:id/complete with the email's
// interactionId and a next step (or "No next step"), the way a call is.
app.post("/tasks/:id/email", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [t] = await query("SELECT * FROM tasks WHERE id=? AND org_id=?", [req.params.id, orgId]);
  if (!t || !t.donor_id) return res.status(404).json({ error: "Task not found" });
  const subject = String((req.body && req.body.subject) || "").trim().slice(0, 200);
  const body = String((req.body && req.body.body) || "").trim().slice(0, 8000);
  if (!subject || !body) return res.status(400).json({ error: "An email needs a subject and words." });
  const who = actor(req), mdId = "md_" + uuid().slice(0, 12);
  await run(`INSERT INTO milestone_drafts (id,org_id,donor_id,milestone_key,subject,body,status,source,created_by,created_by_name)
             VALUES (?,?,?,?,?,?,'pending_review','task',?,?)`,
    [mdId, orgId, t.donor_id, `task-email:${t.id}:${Date.now()}`, subject, body, who.id, who.name]);
  const [draft] = await query("SELECT * FROM milestone_drafts WHERE id=?", [mdId]);
  const r = await sendMilestoneDraft(req, draft, { taskId: t.id });
  if (r.status !== 200) { await run("DELETE FROM milestone_drafts WHERE id=? AND org_id=?", [mdId, orgId]); return res.status(r.status).json({ error: r.error, sentence: r.error }); }
  res.json({ ok: true, interactionId: r.interactionId, needsNextStep: true });
}));

// FIX-31: a task's day on its own (a Calendar drag, "Give it a day"). The full
// PUT replaces every column, which a drag must never do. A linked task's day
// moves its next step or deadline, and the trigger brings the task along.
app.patch("/tasks/:id/due", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const due = String((req.body && req.body.due) || "");
  if (due && !/^\d{4}-\d{2}-\d{2}$/.test(due)) return res.status(400).json({ error: "bad_due_date", sentence: "The date must be a day." });
  const [t] = await query("SELECT id, due FROM tasks WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!t) return res.status(404).json({ error: "Task not found" });
  req.audit = { ...(req.audit || {}), before: { due: t.due || "" }, after: { due } };
  const linked = await linkedTaskChange(req, t.id, { due });
  if (linked && linked.refused) return res.status(409).json(linked.refused);
  if (!linked) await run("UPDATE tasks SET due=?, updated_at=NOW() WHERE id=? AND org_id=?", [due, t.id, req.user.orgId]);
  const [row] = await query(`SELECT t.*, d.name AS donor_name FROM tasks t
       LEFT JOIN donors d ON d.id = t.donor_id AND d.org_id = t.org_id WHERE t.id = ? AND t.org_id = ?`, [t.id, req.user.orgId]);
  res.json({ ...row, previousDue: t.due || "" });
}));

app.delete("/tasks/:id", requireAuth, wrap(async (req, res) => {
  // FIX-31: a linked task goes when its next step or deadline goes, never alone.
  const [lk] = await query("SELECT link_kind FROM tasks WHERE id=? AND org_id=? AND link_kind IN ('next_step','deadline')", [req.params.id, req.user.orgId]);
  if (lk) return res.status(409).json({ error: "linked_task", sentence: lk.link_kind === "deadline"
    ? "This task is the grant deadline itself. Take the deadline off the grant and the task goes with it."
    : "This task is a next step. Dismiss it on the Thread and the task goes with it." });
  // FIX-14 Part 2: moved, not destroyed, so the screen can offer Undo.
  const undoId = await trashRow("tasks", req.params.id, req);
  if (!undoId) return res.status(404).json({ error: "Not found" }); // BUILD-75 B: a foreign/unknown id answers 404, never a false success — one answer everywhere
  res.json({ success: true, undoId, undoSeconds: UNDO_SECONDS });
}));

// ── Board ──────────────────────────────────────────────────────────────────
app.get("/board", requireAuth, wrap(async (req, res) => {
  const members = await query("SELECT * FROM board_members WHERE org_id = ?", [req.user.orgId]);
  res.json(members.map(m => ({ ...m, committees: JSON.parse(m.committees || "[]") })));
}));

app.post("/board", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { name, role, employer, term, givingLevel, committees, attendance } = req.body;
  if (!name) return res.status(400).json({ error: "Name required" });

  const id = "b_" + uuid().slice(0, 8);
  await run(
    "INSERT INTO board_members (id,org_id,name,role,employer,term,giving_level,committees,attendance,created_by,created_by_name) VALUES (?,?,?,?,?,?,?,?,?,?,?)",
    [id, req.user.orgId, name, role || "Member", employer || "", term || "",
     givingLevel || "$0", JSON.stringify(committees || []), attendance ?? 100, actor(req).id, actor(req).name]
  );
  const rows = await query("SELECT * FROM board_members WHERE id = ?", [id]);
  res.status(201).json(rows[0]);
}));

// ── Dashboard ──────────────────────────────────────────────────────────────
// GET /donors (the list route App.jsx's loadData() uses) never embeds
// interactions — only GET /donors/:id does, joined lazily when a profile
// opens. adaptData() hardcodes donors[].interactions to [], so the
// Dashboard's Recent Activity feed had no real data source. This gives it
// one directly, org-wide, instead of relying on the per-donor shape.
// (route deleted, BUILD-75 B.4 — zero references anywhere: client, tests, scripts, docs. See audit/BUILD-75-FINDINGS.md B.1 orphan verdicts.)

app.get("/dashboard/my-stats", requireAuth, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  const now = new Date();
  const fyStart = orgFiscalYearStart(await orgTz(orgId));   // ORG_TZ_SEAM_OK
  // FIX-14 Part 1 — the org's civil today (this was the UTC date), and Visits
  // YTD is the one meetings source (meetings.js) for this staff member.
  const today = orgToday(await orgTz(orgId));                // ORG_TZ_SEAM_OK

  const [portfolioRows, visitsRows, movesRows, giftsRows, pipelineRows, lapsedRows, orgInteractionRows, orgGiftHistoryRows] = await Promise.all([
    query("SELECT COUNT(*) as cnt FROM donors WHERE org_id=? AND assigned_to=? AND deleted_at IS NULL", [orgId, userId]),
    figureSources.figureValue(orgId, { key: "meetings", params: { from: fyStart, to: today, staff: userId } }, {}).then(f => [{ cnt: f.value || 0 }]),
    // "Moves Made" = every meaningful-contact interaction (call/meeting/
    // email/stewardship — the same MEANINGFUL_CONTACT_TYPES used by
    // Stewardship Debt/First-Touch Delay), NOT literally every interactions
    // row with created_by=userId. Previously unfiltered by type, which
    // silently counted 'gift' rows (auto-logged by /donors/:id/gifts and the
    // bulk history importer) and 'stage_change' rows (auto-logged by a
    // Kanban drag) as if they were outreach — a bulk gift import or a stage
    // drag inflated a fundraiser's own activity count without them actually
    // contacting anyone. This makes Visits YTD a true subset of Moves Made
    // (meeting ⊂ meaningful contact) instead of two counts with an unclear
    // relationship, and lets GET /dashboard/my-stats/moves/breakdown below
    // return a list that actually matches what's being counted.
    query(`SELECT COUNT(*) as cnt FROM interactions WHERE org_id=? AND created_by=? AND type IN ${MEANINGFUL_CONTACT_TYPES} AND date>=?`, [orgId, userId, fyStart]),
    query("SELECT COALESCE(SUM(g.amount),0) as total FROM gifts g JOIN donors d ON d.id=g.donor_id WHERE d.org_id=? AND d.assigned_to=? AND g.date>=?", [orgId, userId, fyStart]),
    query("SELECT COALESCE(SUM(total_giving),0) as total FROM donors WHERE org_id=? AND assigned_to=? AND stage NOT IN ('lapsed','closed') AND deleted_at IS NULL", [orgId, userId]),
    query("SELECT COUNT(*) as cnt FROM donors WHERE org_id=? AND assigned_to=? AND stage='lapsed' AND deleted_at IS NULL", [orgId, userId]),
    // Org-wide (not user-scoped) signals for the Home dashboard's empty-state
    // copy: distinguishes "you have real donor/gift history but genuinely
    // haven't logged any outreach yet" (show explanatory first-run copy)
    // from "this org has no donors at all" (a different, existing empty state).
    // Deliberately scoped to MEANINGFUL_CONTACT_TYPES, not any interaction row:
    // a fresh onboarding import creates 'gift' interactions as a side effect
    // of recording each gift (see /donors/import-combined), which is real
    // data but not outreach — counting it here would hide the "log your
    // first call" prompt on Day 1 for every org that imported gift history.
    query(`SELECT COUNT(*) as cnt FROM interactions WHERE org_id=? AND type IN ${MEANINGFUL_CONTACT_TYPES}`, [orgId]),
    query("SELECT COUNT(*) as cnt FROM donors WHERE org_id=? AND deleted_at IS NULL AND gift_count>0", [orgId]),
  ]);

  res.json({
    portfolioCount: parseInt(portfolioRows[0]?.cnt || 0),
    visitsYtd: parseInt(visitsRows[0]?.cnt || 0),
    madeYtd: parseInt(movesRows[0]?.cnt || 0),
    giftsYtd: parseInt(giftsRows[0]?.total || 0),
    pipelineValue: parseInt(pipelineRows[0]?.total || 0),
    lapsedCount: parseInt(lapsedRows[0]?.cnt || 0),
    orgHasInteractions: parseInt(orgInteractionRows[0]?.cnt || 0) > 0,
    orgHasGiftHistory: parseInt(orgGiftHistoryRows[0]?.cnt || 0) > 0,
  });
}));

// BUILD-16 Part 1 — the Home command center. Four headers a fundraiser opens
// the app to see: Portfolio [Team], Tasks [Core], Need to Do [Core], Pipeline
// [Team]. First-touch-delay / stewardship-debt are demoted to secondary chips
// (still served by /metrics/stewardship-summary), never headline cards. Plan-
// graceful: a Core org gets Tasks + a giving snapshot, no broken Team headers.
// The Need-to-do LIST itself is the existing /dashboard/today queue (the client
// already fetches it) — this endpoint returns the four headers' summary data.
app.get("/dashboard/home", requireAuth, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  const scope = req.query.scope === "all" ? "all" : "mine";
  // THE ORG'S CIVIL DATE, NOT THE UTC DAY. These four counts are Home's Today
  // rail. A UTC slice is already tomorrow from ~20:00 Eastern, so every task
  // due today moved into `overdue` and "due today" read 0 - every evening, on
  // the calmest screen in the product, with nothing having changed but the
  // clock. Same seam the gift paths have used since BUILD-75.
  const today = orgToday(await orgTz(orgId));           // ORG_TZ_SEAM_OK

  const orgRows = await query("SELECT plan, subscription_status FROM orgs WHERE id=?", [orgId]);
  const tier = orgRows.length ? orgPlanTier(orgRows[0]) : "core";

  // BUILD-54 §1 — everything after the tier probe is independent: one
  // parallel batch instead of ~7 sequential round trips. The team-only
  // queries only join the batch on team tier (results unchanged).
  const taskScope = scope === "mine" ? "AND assigned_to=?" : "";
  const mMine = tier === "team" ? portfolioMembership({ orgId, userId, scope: "mine", alias: "" }) : null;
  const mScope = tier === "team" ? portfolioMembership({ orgId, userId, scope, alias: "" }) : null;
  const owner = scope === "mine" ? "assigned_to = ?" : "assigned_to IS NOT NULL";
  const oppParams = scope === "mine" ? [orgId, orgId, userId] : [orgId, orgId];
  const nullQ = Promise.resolve(null);
  const [distinctOfficers, taskRows, pRows, cRows, totRows, stageRows, oppRows] = await Promise.all([
    // BUILD-32 Part 4 — the Home "My donors / Whole org" scope toggle is a
    // single-value picker unless 2+ officers actually have assigned donors.
    query(
      `SELECT COUNT(DISTINCT assigned_to)::int AS c FROM donors
         WHERE org_id=? AND assigned_to IS NOT NULL AND deleted_at IS NULL`, [orgId]),
    // Tasks buckets [Core] — open tasks, scoped to the user (mine) or org (all).
    query(
      `SELECT
         COUNT(*) FILTER (WHERE due <> '' AND due IS NOT NULL AND due < ?) AS overdue,
         COUNT(*) FILTER (WHERE due <> '' AND due IS NOT NULL AND left(due,10) = ?) AS today,
         COUNT(*) FILTER (WHERE due <> '' AND due IS NOT NULL AND due > ? AND left(due,10) <> ?) AS upcoming,
         COUNT(*) FILTER (WHERE due = '' OR due IS NULL) AS no_date,
         COUNT(*) AS total
       FROM tasks WHERE org_id=? AND done=0 AND voided_at IS NULL ${taskScope}`,
      scope === "mine" ? [today, today, today, today, orgId, userId] : [today, today, today, today, orgId]),
    mMine ? query(`SELECT COUNT(*) AS cnt, COALESCE(SUM(total_giving),0) AS val FROM donors WHERE ${mMine.where}`, mMine.params) : nullQ,
    mMine ? query("SELECT portfolio_color FROM users WHERE id=? AND org_id=?", [userId, orgId]) : nullQ,
    mScope ? query(`SELECT COUNT(*) AS cnt, COALESCE(SUM(total_giving),0) AS val FROM donors WHERE ${mScope.where}`, mScope.params) : nullQ,
    mScope ? query(`SELECT stage, COUNT(*) AS cnt, COALESCE(SUM(total_giving),0) AS val
             FROM donors WHERE ${mScope.where} GROUP BY stage`, mScope.params) : nullQ,
    mScope ? query(
      `SELECT COALESCE(SUM(target_amount),0) AS ask, COUNT(*) AS cnt
         FROM opportunities WHERE org_id=? AND status='open'
           AND donor_id IN (SELECT id FROM donors WHERE org_id=? AND deleted_at IS NULL AND ${owner})`, oppParams) : nullQ,
  ]);
  const multiOfficer = (distinctOfficers[0]?.c || 0) >= 2;
  const tRow = taskRows[0] || {};
  const tasks = {
    overdue: parseInt(tRow.overdue, 10) || 0,
    today: parseInt(tRow.today, 10) || 0,
    upcoming: parseInt(tRow.upcoming, 10) || 0,
    noDate: parseInt(tRow.no_date, 10) || 0,
    total: parseInt(tRow.total, 10) || 0,
  };

  // Portfolio [Team] — the officer's assigned constituents + their lifetime
  // value + the officer's color. Null on Core (the header is hidden).
  let portfolio = null;
  if (tier === "team") {
    portfolio = {
      count: parseInt(pRows[0]?.cnt, 10) || 0,
      value: parseFloat(pRows[0]?.val) || 0,
      color: cRows[0]?.portfolio_color || null,
    };
  }

  // Pipeline [Team] — SAME membership as the board + Portfolio card (the ONE
  // definition via portfolioMembership), broken out per stage for the compact
  // summary. total/value are computed over the whole portfolio so they equal the
  // Portfolio card and the board exactly; the per-stage rows are the display
  // breakdown. The open-ask forecast is scoped to the SAME portfolio donors the
  // board sums, so Home's forecast and the board's asks agree. Null on Core.
  let pipeline = null;
  if (tier === "team") {
    const byStage = Object.fromEntries(stageRows.map(r => [r.stage, r]));
    const stages = ALL_PIPELINE_STAGES.map(s => ({
      stage: s,
      count: parseInt(byStage[s]?.cnt, 10) || 0,
      value: parseFloat(byStage[s]?.val) || 0,
    }));
    pipeline = {
      total: parseInt(totRows[0]?.cnt, 10) || 0,
      value: parseFloat(totRows[0]?.val) || 0,
      stages,
      forecastOpen: Math.round(parseFloat(oppRows[0]?.ask) || 0),
      openOppCount: parseInt(oppRows[0]?.cnt, 10) || 0,
    };
  }

  // ── BUILD-88b B.2 — LATE PLEDGE INSTALMENTS, for the morning sentence ────
  // A pledge somebody signed and then stopped paying is the quietest kind of
  // bad news: nothing fails, nothing bounces, and the money simply never
  // arrives. A SHELL pledge (BUILD-88a A.7, inferred from payments) is never
  // counted late — it has no schedule anybody wrote down, so it is unfinished
  // rather than overdue, and it is reported separately so it can be finished.
  const orgForPledges = await orgTz(orgId);
  const pledgeToday = orgToday(orgForPledges);                     // ORG_TZ_SEAM_OK
  const { PLEDGE_LATE_DAYS } = await import("../shared/draftNote.js");
  const [lateRow] = await query(
    `SELECT COUNT(*)::int AS late FROM pledge_installments i
       JOIN pledges p ON p.id = i.pledge_id AND p.org_id = i.org_id
       JOIN donors d ON d.id = p.donor_id AND d.org_id = p.org_id
      WHERE i.org_id=? AND i.paid_gift_id IS NULL AND i.due_date <= ?
        AND p.status='open' AND COALESCE(p.is_shell,false) = false AND COALESCE(p.is_match,false) = false
        AND d.deleted_at IS NULL AND d.is_sample IS NOT TRUE`,
    [orgId, orgTime.addDays(pledgeToday, -PLEDGE_LATE_DAYS)]);
  const [shellRow] = await query(
    `SELECT COUNT(*)::int AS n FROM pledges p JOIN donors d ON d.id = p.donor_id AND d.org_id = p.org_id
      WHERE p.org_id=? AND p.status='open' AND d.deleted_at IS NULL
        AND (COALESCE(p.is_shell,false) = true
             OR NOT EXISTS (SELECT 1 FROM pledge_installments i WHERE i.pledge_id = p.id))`,
    [orgId]);

  // BUILD-101 Part 2 — memberships that expire this calendar month and are
  // still held. Home says it in one line, and only when it is not zero.
  const monthStart = pledgeToday.slice(0, 7) + "-01", monthEnd = pledgeToday.slice(0, 7) + "-31";
  const [expRow] = await query(
    `SELECT COUNT(*)::int AS n FROM memberships m JOIN donors d ON d.id=m.donor_id AND d.org_id=m.org_id
      WHERE m.org_id=? AND m.status IN ('active','grace') AND m.expires_on BETWEEN ? AND ? AND d.deleted_at IS NULL`,
    [orgId, monthStart, monthEnd]);
  // BUILD-100 (grants) Part 7 — grant deadlines inside Home's window, counted
  // through grantMilestones' ONE window so this and the Deadlines screen's line
  // cannot disagree. Open milestones only; a sample grant never counts.
  const GM = await grantMsMod();
  const openMs = await query(
    `SELECT m.due_date FROM grant_milestones m JOIN grants g ON g.id=m.grant_id AND g.org_id=m.org_id
      WHERE m.org_id=? AND m.state NOT IN ('done','skipped') AND g.is_sample IS NOT TRUE`, [orgId]);
  const grantDeadlinesSoon = GM.deadlinesInWindow(openMs.map(r => ({ dueDate: r.due_date })), pledgeToday).length;
  res.json({ tier, scope, portfolio, tasks, pipeline, multiOfficer, today: pledgeToday,
             latePledgeInstallments: lateRow?.late || 0,
             membershipsExpiringThisMonth: expRow?.n || 0,
             grantDeadlinesSoon, grantDeadlineWindowDays: GM.HOME_WINDOW_DAYS,
             pledgesNeedingSchedule: shellRow?.n || 0 });
}));

// Per-stat drill-downs behind the My Portfolio bar. Each mirrors the exact
// filter its headline count above uses (same fyStart boundary, same type
// filters), so the number shown and the list you get from clicking it can
// never disagree. Rows are shaped for MetricBreakdownPanel — visits/moves/
// gifts are one row per logged event (a donor can appear more than once, so
// each row carries its own `id`), pipeline/lapsed are one row per donor.
app.get("/dashboard/my-stats/visits/breakdown", requireAuth, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  // fyStart mirrors /dashboard/my-stats exactly: July 1 fiscal year boundary.
  const now = new Date();
  const fyStart = orgFiscalYearStart(await orgTz(orgId));   // ORG_TZ_SEAM_OK
  const PAGE_SIZE = 50;
  // FIX-14 Part 1 — the same source as the count on Home (meetings.js).
  const f = await figureSources.figure(orgId, { key: "meetings", params: { from: fyStart, to: orgToday(await orgTz(orgId)), staff: userId } }, {}, { pageSize: PAGE_SIZE });   // ORG_TZ_SEAM_OK
  const { displayDateShort } = await import("../shared/displayDate.js");
  const names = Object.fromEntries((await query("SELECT id, name FROM donors WHERE org_id=? AND id = ANY(?)",
    [orgId, [...new Set((f.rows || []).map(r => r.donorId || r.donor_id).filter(Boolean))]])).map(r => [r.id, r.name]));
  res.json({
    count: f.totalRows || 0,
    rows: (f.rows || []).map(r => ({
      id: r.id, donorId: r.donorId || r.donor_id, donorName: names[r.donorId || r.donor_id] || "",
      detail: r.type === "meeting" ? "Meeting from a calendar" : "Meeting logged",
      value: displayDateShort(r.date, r.date),
    })),
  });
}));

app.get("/dashboard/my-stats/moves/breakdown", requireAuth, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  // fyStart mirrors /dashboard/my-stats exactly: July 1 fiscal year boundary.
  const now = new Date();
  const fyStart = orgFiscalYearStart(await orgTz(orgId));   // ORG_TZ_SEAM_OK
  const PAGE_SIZE = 50;
  const [rows, countRow] = await Promise.all([
    query(
      `SELECT i.id, i.donor_id, d.name AS donor_name, i.date, i.type FROM interactions i
       JOIN donors d ON d.id = i.donor_id
       WHERE i.org_id=? AND i.created_by=? AND i.type IN ${MEANINGFUL_CONTACT_TYPES} AND i.date>=? AND d.deleted_at IS NULL
       ORDER BY i.date DESC LIMIT ?`,
      [orgId, userId, fyStart, PAGE_SIZE]
    ),
    query(
      `SELECT COUNT(*) as cnt FROM interactions i JOIN donors d ON d.id=i.donor_id
       WHERE i.org_id=? AND i.created_by=? AND i.type IN ${MEANINGFUL_CONTACT_TYPES} AND i.date>=? AND d.deleted_at IS NULL`,
      [orgId, userId, fyStart]
    ),
  ]);
  const TYPE_LABEL = { call: "Call", meeting: "Meeting", email: "Email", stewardship: "Stewardship" };
  res.json({
    count: parseInt(countRow[0]?.cnt || 0),
    rows: rows.map(r => ({
      id: r.id, donorId: r.donor_id, donorName: r.donor_name,
      detail: TYPE_LABEL[r.type] || r.type,
      value: new Date(r.date).toLocaleDateString("en-US", { month: "short", day: "numeric" }),
    })),
  });
}));

app.get("/dashboard/my-stats/gifts/breakdown", requireAuth, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  // fyStart mirrors /dashboard/my-stats exactly: July 1 fiscal year boundary.
  const now = new Date();
  const fyStart = orgFiscalYearStart(await orgTz(orgId));   // ORG_TZ_SEAM_OK
  const PAGE_SIZE = 50;
  const [rows, totalRow] = await Promise.all([
    query(
      `SELECT g.id, g.donor_id, d.name AS donor_name, g.date, g.amount FROM gifts g
       JOIN donors d ON d.id = g.donor_id
       WHERE d.org_id=? AND d.assigned_to=? AND g.date>=? AND d.deleted_at IS NULL
       ORDER BY g.amount DESC LIMIT ?`,
      [orgId, userId, fyStart, PAGE_SIZE]
    ),
    query(
      `SELECT COALESCE(SUM(g.amount),0) as total, COUNT(*) as cnt FROM gifts g
       JOIN donors d ON d.id=g.donor_id
       WHERE d.org_id=? AND d.assigned_to=? AND g.date>=? AND d.deleted_at IS NULL`,
      [orgId, userId, fyStart]
    ),
  ]);
  res.json({
    // BUILD-73 Part 2 — was Math.round(): a drill-down total is money, and
    // rounding it here made the panel disagree with the ledger it drills into.
    total: toDollars(toCents(totalRow[0]?.total) || 0),
    count: parseInt(totalRow[0]?.cnt || 0),
    rows: rows.map(r => ({
      id: r.id, donorId: r.donor_id, donorName: r.donor_name,
      detail: new Date(r.date).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }),
      value: "$" + Number(r.amount).toLocaleString(),
    })),
  });
}));

app.get("/dashboard/my-stats/pipeline/breakdown", requireAuth, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  const PAGE_SIZE = 50;
  const [rows, totalRow] = await Promise.all([
    query(
      `SELECT id, name, stage, total_giving FROM donors
       WHERE org_id=? AND assigned_to=? AND stage NOT IN ('lapsed','closed') AND deleted_at IS NULL
       ORDER BY total_giving DESC LIMIT ?`,
      [orgId, userId, PAGE_SIZE]
    ),
    query(
      `SELECT COALESCE(SUM(total_giving),0) as total, COUNT(*) as cnt FROM donors
       WHERE org_id=? AND assigned_to=? AND stage NOT IN ('lapsed','closed') AND deleted_at IS NULL`,
      [orgId, userId]
    ),
  ]);
  res.json({
    // BUILD-73 Part 2 — was Math.round(); see the sibling drill-down above.
    total: toDollars(toCents(totalRow[0]?.total) || 0),
    count: parseInt(totalRow[0]?.cnt || 0),
    rows: rows.map(d => ({
      donorId: d.id, donorName: d.name,
      detail: d.stage ? d.stage[0].toUpperCase() + d.stage.slice(1) : "",
      value: "$" + Number(d.total_giving || 0).toLocaleString(),
    })),
  });
}));

app.get("/dashboard/my-stats/lapsed/breakdown", requireAuth, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  const PAGE_SIZE = 50;
  const [rows, countRow] = await Promise.all([
    query(
      `SELECT id, name, total_giving, last_gift_date FROM donors
       WHERE org_id=? AND assigned_to=? AND stage='lapsed' AND deleted_at IS NULL
       ORDER BY total_giving DESC LIMIT ?`,
      [orgId, userId, PAGE_SIZE]
    ),
    query(
      "SELECT COUNT(*) as cnt FROM donors WHERE org_id=? AND assigned_to=? AND stage='lapsed' AND deleted_at IS NULL",
      [orgId, userId]
    ),
  ]);
  res.json({
    count: parseInt(countRow[0]?.cnt || 0),
    rows: rows.map(d => ({
      donorId: d.id, donorName: d.name,
      detail: d.last_gift_date ? `Last gave ${new Date(d.last_gift_date).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}` : "No gift date on file",
      value: "$" + Number(d.total_giving || 0).toLocaleString(),
    })),
  });
}));

app.get("/dashboard/today", requireAuth, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  const today = new Date();
  // BUILD-72 Part 4 — the day view is the screen Part 0 captured going wrong:
  // `todayStr` was a UTC calendar date, so at 20:00 EDT it rolled over and a
  // task due today began reading "1 day overdue" with nothing changing but the
  // clock. It is now the civil date IN THE ORG'S TIMEZONE, and every window
  // below is derived from it by calendar arithmetic. ORG_TZ_SEAM_OK
  const org = await orgTz(orgId);
  const todayStr = orgToday(org, today);
  const ninetyDaysAgo = orgTime.addDays(todayStr, -90);
  const items = [];

  // Ownership scoping — defaults to "this is MY job today" (the logged-in
  // user's own assigned donors), matching the existing assigned_to pattern
  // already used by GET /donors/my and /dashboard/my-stats. ?scope=all opts
  // into the previous org-wide behavior for anyone who legitimately needs
  // it (admins/directors) — additive, not a removal of that capability.
  // Every donor-touching bucket below applies the same `scopeClause`/
  // `scopeParams` fragment so the whole unified queue honors one rule.
  const scope = req.query.scope === "all" ? "all" : "mine";
  const scopeClause = scope === "mine" ? "AND d.assigned_to = ?" : "";
  const scopeParams = scope === "mine" ? [userId] : [];
  // Each bucket below can produce a reason for a donor another bucket
  // already claimed. The queue is meant to be one ranked, unified list, so
  // the higher-priority reason should always win regardless of which
  // bucket happened to run first — not whichever bucket got there first.
  const upsertItem = item => {
    const existingIdx = items.findIndex(i => i.donorId === item.donorId);
    if (existingIdx === -1) items.push(item);
    else if (items[existingIdx].priority < item.priority) items[existingIdx] = item;
  };

  // ── BUILD-54 §1 — every bucket below is an independent read, so all of
  // them fire in ONE parallel batch. This endpoint was ~14 sequential
  // Railway↔Supabase round trips (~1.2s TTFB on a small org, the slowest
  // read in the product); the results are byte-identical because bucket
  // APPLICATION order below is unchanged — upsertItem's strict-< tie-break
  // depends on that order, so never reorder the for-loops. The two receipt
  // queries now always run (cheap LIMIT-5 reads) but still only APPLY when
  // the org has receipts enabled.
  const sixtyDaysAgo = orgTime.addDays(todayStr, -60);   // ORG_TZ_SEAM_OK
  const [
    orgReceiptRows, atRiskCandidates, noContact, lapsedDonorRows, unacked,
    needsReceipt, mismatched, dueTasks, milestoneRows, atRiskDraftRows,
    noteReminderRows, atRiskSubs, portalDrift, employerDonorRows,
  ] = await Promise.all([
    query("SELECT receipts_enabled FROM orgs WHERE id=?", [orgId]),
    // Single source of truth for "at risk" — shared with the 'at_risk'
    // auto-enroll trigger (see computeAtRiskCandidates/autoEnroll in
    // server.js) so this display flag and the real-time draft trigger can
    // never drift into two different definitions of the same thing.
    computeAtRiskCandidates(orgId),
    // Donors in active stages with no recent contact
    query(`
    SELECT d.id, d.name, d.total_giving, d.last_gift_date, d.last_gift_amount, d.stage,
           MAX(i.date) AS last_contact
    FROM donors d
    LEFT JOIN interactions i ON i.donor_id = d.id AND i.type != 'email_open'
    WHERE d.org_id = ? AND d.deleted_at IS NULL AND d.stage NOT IN ('prospect','lapsed')
      AND ${solicitableSql("d")} AND ${donorOnly("d")} AND ${namedOrGivingSql("d")} ${scopeClause}
    GROUP BY d.id, d.name, d.total_giving, d.last_gift_date, d.last_gift_amount, d.stage
    HAVING MAX(i.date) < ? OR MAX(i.date) IS NULL
    ORDER BY COALESCE(d.total_giving, 0) DESC
    LIMIT 20
  `, [orgId, ...scopeParams, ninetyDaysAgo]),
    // Lapsed donors
    query(`
    SELECT id, name, total_giving, last_gift_date
    FROM donors d
    WHERE d.org_id = ? AND d.deleted_at IS NULL AND d.stage = 'lapsed'
      AND ${solicitableSql("d")} AND ${donorOnly("d")}
      AND d.imported_sustainer IS NOT TRUE ${scopeClause}
    ORDER BY total_giving DESC
    LIMIT 5
  `, [orgId, ...scopeParams]),
    // Unacknowledged recent gifts (need a thank-you)
    query(`
    SELECT g.id AS gift_id, g.amount, g.date, d.id AS donor_id, d.name AS donor_name, d.total_giving
    FROM gifts g
    JOIN donors d ON d.id = g.donor_id
    WHERE d.org_id = ?
      AND (g.acknowledgement_sent = false OR g.acknowledgement_sent IS NULL)
      AND d.deceased IS NOT TRUE
      AND g.date >= ? ${scopeClause}
    ORDER BY g.amount DESC
    LIMIT 5
  `, [orgId, ninetyDaysAgo, ...scopeParams]),
    // Tax receipts — $250+ gifts with no acknowledgment (applied only when
    // the org has receipts enabled)
    query(`
      SELECT g.id AS gift_id, g.amount, g.date, d.id AS donor_id, d.name AS donor_name, d.total_giving
      FROM gifts g
      JOIN donors d ON d.id = g.donor_id
      WHERE d.org_id = ?
        AND g.amount >= 250
        AND (g.acknowledgement_sent = false OR g.acknowledgement_sent IS NULL)
        AND (g.is_sample IS NOT TRUE)
        AND d.deceased IS NOT TRUE
        AND g.date >= ? ${scopeClause}
      ORDER BY g.amount DESC
      LIMIT 5
    `, [orgId, sixtyDaysAgo, ...scopeParams]),
    // Receipt/gift mismatch (applied only when receipts enabled)
    query(`
      SELECT r.id AS receipt_id, r.receipt_number, r.amount AS receipt_amount,
             g.amount AS gift_amount, d.id AS donor_id, d.name AS donor_name, d.total_giving
      FROM receipts r
      LEFT JOIN gifts g ON g.id = r.gift_id
      JOIN donors d ON d.id = r.donor_id
      WHERE r.org_id = ? AND r.type = 'gift' AND r.voided_at IS NULL
        AND (g.id IS NULL OR r.amount != g.amount OR (r.snapshot->>'giftDateRaw') != g.date)
        ${scopeClause}
      LIMIT 5
    `, [orgId, ...scopeParams]),
    // Overdue donor-linked tasks
    query(`
    SELECT t.id, t.title, t.due, t.priority AS task_priority, t.type AS task_type, t.donor_id, d.name AS donor_name, d.total_giving
    FROM tasks t
    JOIN donors d ON d.id = t.donor_id
    WHERE t.org_id = ? AND done=0 AND t.voided_at IS NULL AND t.due <= ? ${scopeClause}
      AND COALESCE(t.link_kind, '') <> 'next_step'   -- FIX-31: a next step is already in this queue as its thread
    ORDER BY t.due ASC
    LIMIT 5
  `, [orgId, todayStr, ...scopeParams]),
    // Milestone-ready donors — pending AI-drafted stewardship emails
    query(`
    SELECT md.id AS draft_id, md.donor_id, md.subject, md.created_at, d.name AS donor_name, d.total_giving
    FROM milestone_drafts md
    JOIN donors d ON d.id = md.donor_id
    WHERE md.org_id = ? AND md.status = 'pending_review' ${scopeClause}
    ORDER BY md.created_at DESC
    LIMIT 5
  `, [orgId, ...scopeParams]),
    // At-risk re-engagement drafts
    query(`
    SELECT md.id AS draft_id, md.donor_id, d.name AS donor_name, d.total_giving
    FROM milestone_drafts md
    JOIN donors d ON d.id = md.donor_id
    WHERE md.org_id = ? AND md.status = 'pending_review' AND md.milestone_key = 'at_risk' ${scopeClause}
    ORDER BY md.created_at DESC
    LIMIT 10
  `, [orgId, ...scopeParams]),
    // Personal-note reminders
    query(`
    SELECT nr.id AS reminder_id, nr.donor_id, nr.talking_points, nr.created_at, d.name AS donor_name, d.total_giving
    FROM note_reminders nr
    JOIN donors d ON d.id = nr.donor_id
    WHERE nr.org_id = ? AND nr.status = 'pending' ${scopeClause}
    ORDER BY nr.created_at DESC
    LIMIT 5
  `, [orgId, ...scopeParams]),
    // At-risk recurring gifts — failed/retrying donor subscriptions
    query(`
    SELECT rs.donor_id, rs.stripe_subscription_id, rs.amount, rs.interval, d.name AS donor_name, d.total_giving
    FROM recurring_subscriptions rs
    JOIN donors d ON d.id = rs.donor_id
    WHERE rs.org_id = ? AND rs.status IN ('past_due','recovering') ${scopeClause}
    ORDER BY rs.amount DESC NULLS LAST
    LIMIT 5
  `, [orgId, ...scopeParams]),
    // BUILD-45 §6.3 drift wire — portal cancel/pause in the last 7 days
    query(`
    SELECT DISTINCT ON (pal.donor_id) pal.donor_id, pal.action, pal.created_at,
           d.name AS donor_name, d.total_giving,
           rs.amount, rs.interval
    FROM portal_audit_log pal
    JOIN donors d ON d.id = pal.donor_id AND d.org_id = pal.org_id AND d.deleted_at IS NULL
    LEFT JOIN recurring_subscriptions rs ON rs.id = (pal.meta->>'subId') AND rs.org_id = pal.org_id
    WHERE pal.org_id = ? AND pal.action IN ('recurring_cancel','recurring_pause')
      AND pal.created_at > NOW() - INTERVAL '7 days' ${scopeClause}
    ORDER BY pal.donor_id, pal.created_at DESC
    LIMIT 5
  `, [orgId, ...scopeParams]).catch(() => []),
    // Matching-gift opportunities — recent donors with a known employer
    query(`
    SELECT d.id, d.name, d.employer, d.total_giving, d.last_gift_amount, d.last_gift_date
    FROM donors d
    WHERE d.org_id = ? AND d.deleted_at IS NULL AND d.employer IS NOT NULL AND d.employer <> ''
      AND ${solicitableSql("d")} AND ${donorOnly("d")} AND d.last_gift_date >= ? ${scopeClause}
    ORDER BY d.last_gift_date DESC
    LIMIT 30
  `, [orgId, ninetyDaysAgo, ...scopeParams]),
  ]);
  const receiptsEnabled = !!orgReceiptRows[0]?.receipts_enabled;
  const atRiskDonorIds = new Set(atRiskCandidates.map(x => x.id));

  for (const d of noContact) {
    const daysSinceContact = d.last_contact
      ? Math.floor((today - new Date(d.last_contact)) / 86400000) : null;
    const daysSinceGift = d.last_gift_date
      ? Math.floor((today - new Date(d.last_gift_date)) / 86400000) : null;
    const totalGiving = parseFloat(d.total_giving) || 0;
    const lastAmt = parseFloat(d.last_gift_amount) || 0;

    const isLapsing = atRiskDonorIds.has(d.id);
    let reason, action;
    if (isLapsing) {
      reason = `Gave $${lastAmt.toLocaleString()} — last gift ${daysSinceGift} days ago, lapsing risk`;
      action = "call";
    } else if (daysSinceContact) {
      const prefix = totalGiving > 0 ? `Gave $${totalGiving.toLocaleString()} total — ` : "";
      reason = `${prefix}no contact in ${daysSinceContact} days`;
      action = totalGiving >= 5000 ? "call" : "email";
    } else {
      reason = d.stage === "qualify"
        ? "New prospect — no contact yet. First outreach sets the tone."
        : "In your portfolio — no outreach logged yet. Make a strong first impression.";
      action = "call";
    }

    const priority = Math.min(50, totalGiving / 5000)
      + (isLapsing ? 30 : 0)
      + (daysSinceContact && daysSinceContact > 180 ? 20 : 0);

    upsertItem({ donorId: d.id, donorName: d.name, reason, priority, action, totalGiving, isLapsing });
  }

  // Lapsed donors — explicitly excluded from the no-contact bucket above
  // (which only looks at active stages), but the queue is meant to unify
  // lapsed/no-contact/overdue-task/milestone in one ranked list, so they
  // need their own bucket rather than never appearing at all.
  for (const l of lapsedDonorRows) {
    const daysSince = l.last_gift_date ? Math.floor((today - new Date(l.last_gift_date)) / 86400000) : null;
    const totalGiving = parseFloat(l.total_giving) || 0;
    const lapsedItem = {
      donorId: l.id, donorName: l.name,
      reason: `Lapsed — ${daysSince != null ? `last gift ${daysSince} days ago` : "no gift on record"}${totalGiving > 0 ? `, $${totalGiving.toLocaleString()} lifetime value` : ""}`,
      priority: 60 + Math.min(20, totalGiving / 5000), action: "lapsed",
      totalGiving, isLapsing: true,
    };
    upsertItem(lapsedItem);
  }

  // Unacknowledged recent gifts (need a thank-you).
  // BUILD-80 Part 9 — the queue reads the LARGEST-GIFTS panel first: a
  // number that is 10% of the file in one row is a parse error until a
  // human says otherwise, and a $200,000 misparse must never LEAD the
  // thank-you queue. An unconfirmed largest-import gift becomes a
  // confirm-this-amount question, not a thank-you task.
  const { stats: impStats } = await importHealth(orgId);
  const { eitherContainsTokenRun } = await import("../shared/importShape.js");
  const unconfirmedLargest = (impStats?.largestGifts || []).filter(g => !g.confirmed);
  for (const g of unacked) {
    const giftDate = new Date(g.date).toLocaleDateString("en-US", { month: "long", day: "numeric" });
    // BUILD-84 census — matching two donor NAMES respects token boundaries.
    // `g.donor_name.includes(x.name)` matched "Ann Lee" inside "Joann Leewood",
    // which here would put a confirm-this-amount flag on the wrong donor's
    // thank-you. `eitherContainsTokenRun` is the ONE boundary-aware test.
    const flagged = unconfirmedLargest.find(x => Number(x.dollars) === Number(g.amount) && x.name && g.donor_name
      && eitherContainsTokenRun(g.donor_name, x.name));
    if (flagged) {
      upsertItem({
        donorId: g.donor_id, donorName: g.donor_name,
        reason: `Imported gift of $${Number(g.amount).toLocaleString()} on ${giftDate} — one of the file's largest. Confirm the amount is real before thanking.`,
        priority: 90, action: "confirm-gift",
        totalGiving: parseFloat(g.total_giving) || 0,
        confirmGift: { name: flagged.name, dollars: flagged.dollars },
      });
      continue;
    }
    upsertItem({
      donorId: g.donor_id, donorName: g.donor_name,
      reason: `Gave $${Number(g.amount).toLocaleString()} on ${giftDate} — not yet thanked`,
      priority: 75, action: "thank",
      totalGiving: parseFloat(g.total_giving) || 0,
    });
  }

  // Tax receipts — $250+ gifts with no acknowledgment yet (see CLAUDE.md
  // "Tax receipting"), org has receipts enabled, gift within the last 60
  // days. Online gifts auto-receipt near-instantly via the webhook (which
  // sets acknowledgement_sent=true), so in practice this bucket only ever
  // surfaces offline/manually-entered gifts, which never auto-receipt.
  // Deliberately priority 76, not 75 — one point above the "not yet
  // thanked" bucket above, so a legally-required receipt wins the
  // upsertItem tie (strict `<` — equal priorities keep whichever bucket
  // ran first) when both could apply to the same offline gift.
  if (receiptsEnabled) {
    for (const g of needsReceipt) {
      const giftDate = new Date(g.date).toLocaleDateString("en-US", { month: "long", day: "numeric" });
      upsertItem({
        donorId: g.donor_id, donorName: g.donor_name,
        reason: `Gift of $${Number(g.amount).toLocaleString()} on ${giftDate} needs a tax receipt`,
        priority: 76, action: "receipt", giftId: g.gift_id,
        totalGiving: parseFloat(g.total_giving) || 0,
      });
    }

    // Receipt/gift mismatch — a gift was edited (amount or date) or
    // deleted after its receipt already issued. See PUT/DELETE /gifts/:id:
    // deliberately never auto-voided, staff reviews and voids+reissues on
    // purpose, since a receipt is a legal record of what was actually
    // sent — not something that should silently change to match an edit.
    // LEFT JOIN (not JOIN) so a deleted gift (g.id IS NULL) is caught too,
    // not just an amount/date edit on a gift that still exists.
    for (const m of mismatched) {
      const reason = m.gift_amount == null
        ? `Receipt #${m.receipt_number} — the gift it was issued for has been deleted — review`
        : `Receipt #${m.receipt_number} no longer matches its gift ($${Number(m.receipt_amount).toLocaleString()} receipted vs. $${Number(m.gift_amount).toLocaleString()} now on the gift) — review`;
      upsertItem({
        donorId: m.donor_id, donorName: m.donor_name,
        reason, priority: 70, action: "receipt_mismatch", receiptId: m.receipt_id,
        totalGiving: parseFloat(m.total_giving) || 0,
      });
    }
  }

  // Overdue donor-linked tasks
  for (const t of dueTasks) {
    // Two civil dates compared as civil dates — never an instant, never
    // millisecond arithmetic across a DST boundary. ORG_TZ_SEAM_OK
    const daysOverdue = orgDaysOverdue(t.due, org, today);
    upsertItem({
      donorId: t.donor_id, donorName: t.donor_name,
      reason: `Task: "${t.title}"`,
      priority: 90, action: "call",
      totalGiving: parseFloat(t.total_giving) || 0,
      daysOverdue,
      taskId: t.id, taskTitle: t.title, taskDue: t.due, taskPriority: t.task_priority, taskType: t.task_type,
    });
  }

  // Milestone-ready donors — pending AI-drafted stewardship emails awaiting
  // staff review (see milestone_drafts / retention feature). Unified into
  // the same ranked queue as lapsed/no-contact/overdue-task reasons so this
  // one endpoint is the single source for "needs your attention".
  for (const m of milestoneRows) {
    const milestoneItem = {
      donorId: m.donor_id, donorName: m.donor_name,
      reason: `Milestone email drafted — "${m.subject}" ready for review`,
      priority: 80, action: "milestone",
      totalGiving: parseFloat(m.total_giving) || 0,
      draftId: m.draft_id,
    };
    upsertItem(milestoneItem);
  }

  // At-risk re-engagement drafts — pending, unreviewed AI-drafted emails
  // queued by the 'at_risk' auto-enroll trigger (see computeAtRiskCandidates
  // / autoEnroll below) for a donor who just crossed into the earliest,
  // most-recoverable risk window. These share the milestone_drafts table
  // (milestone_key='at_risk') and so are already caught by the generic
  // bucket above with the generic "Milestone email drafted" reason — this
  // bucket re-upserts the same donor with a distinct reason and a priority
  // just above it (81 > 80) so staff can tell "just flagged today, draft
  // ready" apart from a plain milestone draft or a bare no-contact reason.
  for (const a of atRiskDraftRows) {
    upsertItem({
      donorId: a.donor_id, donorName: a.donor_name,
      reason: "Flagged today — AI-drafted re-engagement email ready for review",
      priority: 81, action: "milestone",
      totalGiving: parseFloat(a.total_giving) || 0,
      draftId: a.draft_id, isLapsing: true,
    });
  }

  // Personal-note reminders — the "write a note" sibling of the milestone
  // drafts above. Priority 82: a hair above milestone-drafted emails (80),
  // since these represent the org's highest-value/most-personal moments by
  // design (see isNoteMoment()).
  for (const n of noteReminderRows) {
    const points = typeof n.talking_points === "string" ? JSON.parse(n.talking_points) : n.talking_points;
    upsertItem({
      donorId: n.donor_id, donorName: n.donor_name,
      reason: "Worth a personal note — see talking points",
      priority: 82, action: "note",
      totalGiving: parseFloat(n.total_giving) || 0,
      reminderId: n.reminder_id, talkingPoints: points || [],
    });
  }

  // At-risk recurring gifts — failed/retrying donor subscriptions. This is
  // real, already-identified revenue actively draining away that the
  // nonprofit would otherwise never notice (see CLAUDE.md "Recurring gift
  // recovery"), so it's folded into the same ranked queue rather than living
  // only on a separate report.
  for (const rs of atRiskSubs) {
    const amountStr = rs.amount != null ? `$${Number(rs.amount).toLocaleString()}/${rs.interval === "year" ? "yr" : "mo"}` : "a recurring gift";
    upsertItem({
      donorId: rs.donor_id, donorName: rs.donor_name,
      reason: `Recurring gift failed — ${amountStr} at risk`,
      priority: 85, action: "recurring",
      totalGiving: parseFloat(rs.total_giving) || 0,
      subscriptionId: rs.stripe_subscription_id,
    });
  }

  // BUILD-45 §6.3 drift wire — a donor who canceled or paused their recurring
  // gift FROM THE PORTAL in the last 7 days is a "needs you today" item. A
  // cancellation the org learns about in minutes is a save opportunity; one it
  // discovers at month-end is a lapse statistic. Outranks the failed-card
  // bucket (85): this donor made a deliberate choice minutes-to-days ago.
  for (const pd of portalDrift) {
    const verb = pd.action === "recurring_cancel" ? "canceled" : "paused";
    const amountStr = pd.amount != null ? `$${Number(pd.amount).toLocaleString()}/${pd.interval === "year" ? "yr" : "mo"}` : "their recurring gift";
    upsertItem({
      donorId: pd.donor_id, donorName: pd.donor_name,
      reason: `${verb === "canceled" ? "Canceled" : "Paused"} ${amountStr} via the portal — reach out today, thank them, learn what changed`,
      priority: 88, action: "call",
      totalGiving: parseFloat(pd.total_giving) || 0,
    });
  }

  // Matching-gift opportunities — a recent donor whose employer has a known
  // matching-gift program (see matchingGifts.js), real dollar upside for a
  // simple ask. Low priority relative to everything above (failed payments,
  // overdue tasks, drafted emails): this is a nice-to-have opportunity, not
  // time-sensitive, so it should never crowd out those. Only considered for
  // donors not already claimed by a higher-priority bucket above — computed
  // as a hard exclusion (not just a priority contest), matching "isn't
  // already flagged for something else."
  const alreadyFlaggedIds = new Set(items.map(i => i.donorId));
  let matchingGiftCount = 0;
  for (const d of employerDonorRows) {
    if (matchingGiftCount >= 5) break;
    if (alreadyFlaggedIds.has(d.id)) continue;
    const match = lookupMatchingGift(d.employer);
    if (!match) continue;
    upsertItem({
      donorId: d.id, donorName: d.name,
      reason: `${match.companyName} matches employee gifts ${match.ratio} — ask about submitting a match request`,
      priority: 30, action: "matching_gift",
      totalGiving: parseFloat(d.total_giving) || 0,
      matchCompany: match.companyName, matchRatio: match.ratio,
    });
    matchingGiftCount++;
  }

  items.sort((a, b) => b.priority - a.priority);
  res.json(items.slice(0, 10));
}));

// ── BUILD-76 Part 2 — the Drifting surface ─────────────────────────────────
// The list the product is named for. High confidence only by default
// (?includeMedium=1 opts in, and every row carries its labelled confidence —
// a medium flag is NEVER presented as high); ranked by value at risk,
// descending; capped at DRIFT.HOME_LIST_CAP (?all=1 lifts the cap for the
// see-all view). Rows already handled (a meaningful contact inside the
// snooze window) are filtered from the LIST but stay in the headline —
// the money is still at risk until a gift lands.
app.get("/drift", requireAuth, wrap(async (req, res) => {
  const { orgId } = req.user;
  const includeMedium = req.query.includeMedium === "1" || req.query.includeMedium === "true";
  const uncapped = req.query.all === "1" || req.query.all === "true";
  const { map, today } = await computeDriftForDonors(orgId);
  // BUILD-79 Part 6 — "1,111 giving patterns checked" was once said about an
  // org with ZERO gifts; zero patterns were checked. The chip's honest count.
  const giftedDonorCount = (await query(
    "SELECT COUNT(*)::int AS n FROM donors WHERE org_id=? AND deleted_at IS NULL AND COALESCE(gift_count,0) > 0", [orgId]))[0].n;

  const drifting = [...map.values()].filter(a => a.state === "drifting");
  const high = drifting.filter(a => a.confidence === "high");
  const medium = drifting.filter(a => a.confidence === "medium");
  const lapsed = [...map.values()].filter(a => a.state === "lapsed");

  // BUILD-76 follow-up — a zero that shows its work. The empty state must
  // name what was checked and who was excluded and why, or a healthy file
  // and a silently failed import read identically. Tallied from the same
  // map every other figure reads.
  const excludedTally = { singleGift: 0, activeRecurring: 0, deceased: 0, doNotContact: 0, doNotSolicit: 0, pledgeCadence: 0, unlinkedSustainer: 0, organisation: 0 };
  let onPattern = 0;
  for (const a of map.values()) {
    if (a.state === "excluded") {
      if (a.excludedReason === "organisation") excludedTally.organisation++;
      else if (a.excludedReason === "deceased") excludedTally.deceased++;
      else if (a.excludedReason === "do_not_contact") excludedTally.doNotContact++;
      else if (a.excludedReason === "do_not_solicit") excludedTally.doNotSolicit++;
      else if (a.excludedReason === "active_recurring") excludedTally.activeRecurring++;
      else if (a.excludedReason === "unlinked_sustainer") excludedTally.unlinkedSustainer++;
      else if (a.excludedReason === "pledge_cadence") excludedTally.pledgeCadence++;
    } else if (a.state === "not_eligible") excludedTally.singleGift++;
    else if (a.state === "ok") onPattern++;
  }

  // The headline: dollars at risk from drift, in this organisation's own
  // file — the same sentence the landing page makes. High confidence only:
  // a number that includes guesses is not a number a director repeats.
  // BUILD-83 Parts 3.3 + 4 — AT RISK IS THE NEXT GIFT. The headline is the sum
  // of each drifting donor's USUAL gift (the amount their own sentence names),
  // not their trailing-24-month total and never their lifetime. The list is
  // sorted by that same figure, so what ranks a row is what the row displays.
  const atRiskAmount = toDollars(high.reduce((s, a) => s + toCents(a.usualGift || 0), 0));

  // ENGAGE-1 — ENGAGEMENT IS ONE INPUT TO THE EARLY SIGNS. A medium-confidence
  // drift (an early sign) is stronger when the person has also gone quiet
  // (engagement Distant), and the row says so; and the list can be put in
  // engagement order (?sort=engagement, closest first: who is likeliest to
  // pick up). The default order is unchanged: the usual gift at risk.
  const engRows = await query(`SELECT donor_id, engagement, band FROM donor_scores WHERE org_id = ?`, [orgId]);
  const engMap = new Map(engRows.map(r => [r.donor_id, r]));
  const byEngagement = req.query.sort === "engagement";
  const surfaced = (includeMedium ? drifting : high)
    .filter(a => !a.handled)
    .sort(byEngagement
      ? (x, y) => ((engMap.get(y.donorId) || {}).engagement || 0) - ((engMap.get(x.donorId) || {}).engagement || 0) || (y.usualGift || 0) - (x.usualGift || 0)
      : (x, y) => (y.usualGift || 0) - (x.usualGift || 0));
  const cap = driftEngine.DRIFT.HOME_LIST_CAP;
  // FIX-33 · "Meeting set for 16 Oct" on a drifting row, so nobody calls her twice.
  const meetingSet = await require("../meetingEffects").meetingSetFor(orgId, drifting.map(a => a.donorId)).catch(() => new Map());
  const row = a => ({
    meetingSet: meetingSet.get(a.donorId)?.sentence || null,
    donorId: a.donorId, donorName: a.donorName, reason: a.reason,
    confidence: a.confidence, valueAtRisk: a.valueAtRisk,
    usualGift: a.usualGift || 0,          // the labelled "at risk" figure on the row
    kind: a.kind || null, contactName: a.contactName || null,
    lastGiftDate: a.lastGiftDate, assignedTo: a.assignedTo, assignedToName: a.assignedToName,
    basis: a.basis, seasonal: !!a.seasonal,
    engagement: engMap.has(a.donorId) ? engMap.get(a.donorId).engagement : null,
    engagementBand: engMap.has(a.donorId) ? engMap.get(a.donorId).band : null,
    earlySign: a.confidence === "medium" && engMap.has(a.donorId) && engMap.get(a.donorId).band === "distant"
      ? "Their giving has slipped and they have gone quiet too: engagement is Distant." : null,
  });
  // BUILD-80 Part 7 — "Institutional giving": organisations get their own
  // list with grant-cycle language, never a Re-engage button.
  // FIX-1 — each row says what that organisation gave: a grant from a
  // foundation or DAF, a gift from anyone else (shared/institutional.js), and
  // the date as it reads, computed once here for Home to print.
  const INST = await import("../shared/institutional.js");
  const institutional = (await query(
    `SELECT id, name, kind, funder_type, donor_type, total_giving, last_gift_date, gift_count FROM donors
      WHERE org_id = ? AND deleted_at IS NULL AND kind = 'organisation' AND COALESCE(gift_count,0) > 0
      ORDER BY total_giving DESC NULLS LAST LIMIT 50`, [orgId]))
    .map(r => ({ donorId: r.id, name: r.name, totalGiving: r.total_giving, lastGiftDate: r.last_gift_date, giftCount: r.gift_count,
                 lastWord: INST.lastGiftWord(r), lastGiftLabel: INST.shortCivilDate(r.last_gift_date) }));

  const { caveat: importCaveat } = await importHealth(orgId);
  res.json({
    today,
    institutional,
    importCaveat,
    atRiskAmount,
    atRiskBasis: "usualGift",   // BUILD-83 Part 3.3 — the next gift, not the lifetime
    counts: {
      driftingHigh: high.length,
      driftingMedium: medium.length,
      handled: drifting.filter(a => a.handled).length,
      lapsed: lapsed.length,
    },
    evaluated: map.size,          // every non-deleted donor the computation looked at
    giftedDonorCount,             // BUILD-79 Part 6 — donors with ≥1 gift: the only count "patterns checked" may claim
    onPattern,                    // inside their own pattern (state 'ok')
    excluded: excludedTally,      // and exactly why the rest can never drift
    // BUILD-83 Part 3.3 — the funnel's "Lapsed, window closed" keeps its COUNT
    // and loses its dollars: lifetime giving of people who stopped is history,
    // not risk. Kept on the payload as null so a stale client renders nothing.
    lapsedAmount: null,
    cap,
    total: surfaced.length,
    list: (uncapped ? surfaced : surfaced.slice(0, cap)).map(row),
  });
}));

// BUILD-76 Part 4 — logging as a byproduct. Marking a drift row done asks for
// ONE line, in the flow; Skip is one keypress. BOTH record the interaction —
// the call happened either way, which is what makes the donor record read
// "you called her three weeks ago" and stops the list resurfacing them
// (HANDLED_SNOOZE_DAYS). A skip is recorded as metadata.skipped, never as
// nothing — that is what lets log_capture_rate be measured honestly.
app.post("/drift/:donorId/done", requireAuth, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  const donorRows = await query("SELECT id FROM donors WHERE id = ? AND org_id = ? AND deleted_at IS NULL",
    [req.params.donorId, orgId]);
  if (!donorRows.length) return res.status(404).json({ error: "Donor not found" });

  const note = typeof req.body?.note === "string" ? req.body.note.trim() : "";
  const skipped = note === "";
  const type = ["call", "meeting", "email", "stewardship"].includes(req.body?.type) ? req.body.type : "call";
  const userRow = await query("SELECT name FROM users WHERE id=?", [userId]);
  const org = await orgTz(orgId);
  const todayStr = orgToday(org);                           // ORG_TZ_SEAM_OK
  // Idempotent under a double-tap: ONE drift-done per (donor, org-local day,
  // actor) — the second Save neither duplicates the interaction nor
  // half-clears. Advisory lock because this is a check-then-insert (the
  // BUILD-27 primitive; a unique constraint on a JSONB marker is the wrong
  // tool). A retap that DOES carry a line upgrades the skip in place.
  const result = await withAdvisoryLock(`driftdone:${orgId}:${req.params.donorId}:${userId}:${todayStr}`, async () => {
    const existing = await query(
      `SELECT id FROM interactions WHERE org_id = ? AND donor_id = ? AND created_by = ?
         AND date = ? AND metadata->>'via' = 'drift_done'`,
      [orgId, req.params.donorId, userId, todayStr]);
    if (existing.length) {
      if (!skipped) await run("UPDATE interactions SET note = ?, metadata = jsonb_set(metadata, '{skipped}', 'false') WHERE id = ?",
        [note, existing[0].id]);
      return { id: existing[0].id, deduped: true, status: 200 };
    }
    const id = "int_" + uuid().slice(0, 8);
    await run(
      "INSERT INTO interactions (id,org_id,donor_id,type,note,date,created_by,logged_by_name,metadata) VALUES (?,?,?,?,?,?,?,?,?)",
      [id, orgId, req.params.donorId, type, note, todayStr, userId,
       userRow[0]?.name || "", JSON.stringify({ via: "drift_done", skipped })]
    );
    return { id, skipped, status: 201 };
  });

  // BUILD-81 — marking a drift item done WITH a logged line opens a thread:
  // this is BUILD-76's byproduct logging, unchanged, now visibly the point.
  // The next-step prompt runs in the same flow; {skipped:true} is recorded as
  // skipped on the interaction (never as nothing), an explicit {type,due} is
  // the user's decision, and an absent nextStep takes the call default
  // (the call default, or whatever the line itself asks for) — the drift row
  // was a call to make.
  let thread = null;
  if (!skipped) {
    const shape = await threadShapeMod();
    const ns = req.body?.nextStep;
    if (ns && ns.skipped === true) {
      await run("UPDATE interactions SET metadata = jsonb_set(metadata, '{next_step}', '\"skipped\"') WHERE id = ?", [result.id]);
    } else {
      let step = null;
      if (ns && shape.nextStepLabelFor(ns.type) && /^\d{4}-\d{2}-\d{2}$/.test(String(ns.due || ""))) {
        step = { type: ns.type, label: shape.sanitizeStepLabel(ns.label) || shape.nextStepLabelFor(ns.type), due: ns.due };
      } else {
        // The drift line IS a note: if it names an ask or a promise, that is
        // the next step — same precedence as the log flow.
        const s = shape.nextStepSuggestion("call_reached", todayStr, note);
        step = { type: s.type, label: s.label, due: s.due };
      }
      const [dRow] = await query("SELECT assigned_to, assigned_to_name FROM donors WHERE id = ? AND org_id = ?", [req.params.donorId, orgId]);
      thread = await withTransaction(client => openThreadTx(client, {
        orgId, donorId: req.params.donorId, step, openedOn: todayStr,
        ownerId: dRow?.assigned_to || userId, ownerName: dRow?.assigned_to ? dRow.assigned_to_name : (userRow[0]?.name || ""),
        actorId: userId, actorName: userRow[0]?.name || "", openingInteractionId: result.id,
      }));
      await run("UPDATE interactions SET metadata = jsonb_set(metadata, '{next_step}', '\"set\"') WHERE id = ?", [result.id]);
    }
  }
  res.status(result.status).json({ id: result.id, skipped: result.skipped, deduped: result.deduped, thread });
}));

// ── BUILD-85 — THE QUEUE ───────────────────────────────────────────────────
// BUILD-81 composed every open thread in the org, unbounded, sorted by
// overdue-then-due-date, and handed the same list to everyone. Three things
// were wrong with that and all three are fixed here:
//
//   OWNERSHIP. A thread carries `owner_id` (the donor's officer, else the
//   person who logged it) and nothing read it. `scope=mine` is now the
//   default and the server ENFORCES it: a non-admin asking for `all` is
//   downgraded rather than refused (the BUILD-31 pipeline precedent — the
//   cross-officer view is the oversight Team sells, so staff never get it by
//   editing a query param). Unowned threads are nobody's by definition, so
//   they ride the ADMIN's own list rather than vanishing — a backstop, and
//   the reason `unowned` is reported separately in the stat.
//
//   A CAP. shared/threadRank.js QUEUE_CAP. A list you cannot finish is a list
//   you stop opening; the remainder is stated as a number, never hidden.
//
//   AN ORDER WITH A REASON. Ranking lives in shared/threadRank.js, and every
//   signal it uses is read HERE, in four batched queries — never per row.
//
// Snoozed threads (revisit dates still in the future) stay off the list and
// out of the stat; they resurface by construction the day snoozed_until
// arrives. `donorId` asks for one donor's thread and bypasses scope and cap —
// a donor record shows its own thread whoever owns it.
async function composeThreads(orgId, { donorId = null, scope = "mine", userId = null, isAdmin = false, cap = null } = {}) {
  const org = await orgTz(orgId);
  const today = orgToday(org);                         // ORG_TZ_SEAM_OK
  const rank = await threadRankMod();

  // Non-admins may not read across officers, whatever the query string says.
  const effScope = donorId ? "all" : (scope === "all" && isAdmin ? "all" : "mine");
  const ownerClause = effScope === "all" || !userId
    ? ""
    : (isAdmin ? "AND (t.owner_id = ? OR t.owner_id IS NULL)" : "AND t.owner_id = ?");
  const ownerParams = ownerClause ? [userId] : [];

  const rows = await query(
    `SELECT t.*, d.name AS donor_name, d.total_giving, d.gift_count,
            i.type AS touch_type, i.note AS touch_note, i.date AS touch_date, i.logged_by_name AS touch_actor,
            g.amount AS gift_amount, g.date AS gift_date
       FROM threads t
       JOIN donors d ON d.id = t.donor_id AND d.org_id = t.org_id
       LEFT JOIN interactions i ON i.id = t.opening_interaction_id
       LEFT JOIN gifts g ON g.id = t.opening_gift_id
      WHERE t.org_id = ? AND t.closed_at IS NULL AND d.deleted_at IS NULL
        ${donorId ? "AND t.donor_id = ?" : ""} ${ownerClause}
      ORDER BY t.due_date ASC, t.opened_on ASC`,
    donorId ? [orgId, donorId, ...ownerParams] : [orgId, ...ownerParams]);

  // ── BUILD-88a A.2 — ONE COMPOSER, EVERY OPEN ITEM ────────────────────────
  // A follow-up created by the conversation flow is a THREAD; one created by
  // "+ Add task", a pipeline move or a workflow recipe is a TASK. They are two
  // tables and they will stay two tables in this build — the thread carries an
  // opening interaction, a close kind and a one-open-per-donor constraint that
  // a task row has no place for. What they must not be is two LISTS: a donor
  // with an open thread and an open task had one of them on the profile and the
  // other on a screen nobody opens, and "what do I owe this person?" had two
  // answers.
  //
  // So they are read through ONE composer, ranked by the ONE ranking
  // (shared/threadRank.js), and carry `kind` so a row can say which it is.
  // Only a task ATTACHED TO A DONOR joins: an org to-do ("renew the insurance")
  // is not a follow-up and does not belong on a donor's record.
  const taskRows = await query(
    `SELECT k.id, k.title, k.due, k.type, k.donor_id, k.assigned_to, k.assigned_to_name, k.calendar_event_id,
            k.created_at, d.name AS donor_name, d.total_giving, d.gift_count
       FROM tasks k
       JOIN donors d ON d.id = k.donor_id AND d.org_id = k.org_id
      WHERE k.org_id = ? AND k.done = 0 AND k.voided_at IS NULL AND k.donor_id IS NOT NULL AND d.deleted_at IS NULL
        AND k.due IS NOT NULL AND k.due <> ''
        -- FIX-31: a next step's own task IS the thread row above, and a deadline
        -- whose follow-up thread is open is that thread; each shows once.
        AND COALESCE(k.link_kind, '') <> 'next_step'
        AND NOT EXISTS (SELECT 1 FROM grant_milestones m JOIN threads th ON th.id = m.thread_id AND th.closed_at IS NULL
                         WHERE m.id = k.milestone_id AND m.org_id = k.org_id AND k.link_kind = 'deadline')
        ${donorId ? "AND k.donor_id = ?" : ""}
        ${effScope === "all" || !userId ? "" : "AND (k.assigned_to = ? OR (k.assigned_to IS NULL AND d.assigned_to = ?))"}
      ORDER BY k.due ASC, k.id ASC`,
    donorId
      ? (effScope === "all" || !userId ? [orgId, donorId] : [orgId, donorId, userId, userId])
      : (effScope === "all" || !userId ? [orgId] : [orgId, userId, userId]));

  // ── The rank signals, read in BATCHES ────────────────────────────────────
  // Four queries for the whole list, never one per row (the BUILD-15 board
  // discipline). Each is scoped to the donors actually on the list.
  const donorIds = [...new Set([...rows.map(r => r.donor_id), ...taskRows.map(r => r.donor_id)])];
  let asks = {}, atRisk = new Set(), majorThreshold = 0;
  if (donorIds.length) {
    const ph = donorIds.map(() => "?").join(",");
    for (const a of await query(
      `SELECT donor_id, COALESCE(SUM(target_amount),0) AS amt FROM opportunities
        WHERE org_id = ? AND status = 'open' AND donor_id IN (${ph}) GROUP BY donor_id`,
      [orgId, ...donorIds])) asks[a.donor_id] = parseFloat(a.amt) || 0;
    for (const r of await query(
      `SELECT DISTINCT donor_id FROM recurring_subscriptions
        WHERE org_id = ? AND donor_id IN (${ph}) AND status IN ('past_due','recovering')`,
      [orgId, ...donorIds])) atRisk.add(r.donor_id);
  }
  // THE ORG'S OWN SCALE, never an absolute dollar figure: p90 of lifetime
  // giving among donors who have given at all. A $5,000 ask is the year for
  // one organization and noise for another; ranking on absolute money is how
  // a CRM starts telling a food pantry its work is small.
  const [{ p90 } = {}] = await query(
    `SELECT percentile_cont(0.9) WITHIN GROUP (ORDER BY total_giving) AS p90
       FROM donors WHERE org_id = ? AND deleted_at IS NULL AND total_giving > 0`, [orgId]);
  majorThreshold = parseFloat(p90) || 0;

  const list = [];
  let snoozed = 0, unowned = 0;
  for (const t of rows) {
    const snoozedOut = t.snoozed_until && String(t.snoozed_until) > today;
    if (snoozedOut && !donorId) { snoozed++; continue; }
    if (!t.owner_id) unowned++;
    const daysOpen = orgTime.daysBetween(t.opened_on, today) ?? 0;
    const lastTouch = t.opening_interaction_id
      ? { kind: "interaction", type: t.touch_type, date: t.touch_date, line: t.touch_note, actor: t.touch_actor }
      : t.opening_gift_id
        ? { kind: "gift", type: "gift", date: t.gift_date ? String(t.gift_date).slice(0, 10) : t.opened_on, amount: t.gift_amount != null ? parseFloat(t.gift_amount) : null, actor: t.created_by_name || null }
        : { kind: "none", type: null, date: t.opened_on, line: null, actor: t.created_by_name || null };
    list.push({
      id: t.id, kind: "thread", donorId: t.donor_id, donorName: t.donor_name,
      nextStep: { type: t.next_step_type, label: t.next_step_label, due: t.due_date, time: t.due_time || null,
                  // The day this was first promised, when a revisit has moved
                  // the due date since. Null on a thread nobody deferred.
                  originalDue: t.original_due_date || null },
      overdue: t.due_date < today,
      // BUILD-86 — HOW LATE, computed ONCE, server-side, on the civil calendar.
      // The morning sentence was deriving it from Date.now() against the due
      // date and landing a day off the row's own "Overdue 23 days" — two
      // numbers for one fact, on one screen. There is one now and both read it.
      overdueDays: t.due_date < today ? (orgTime.daysBetween(t.due_date, today) ?? 0) : 0,
      daysOpen, openedOn: t.opened_on,
      // FIX-14: the rail's next step shows "Edited" from these.
      edited_at: t.edited_at || null, edited_by_name: t.edited_by_name || null,
      owner: t.owner_id ? { id: t.owner_id, name: t.owner_name } : null,
      calendarEventId: t.calendar_event_id || null,   // FIX-33: a meeting step opens its meeting
      lastTouch, snoozedUntil: snoozedOut ? t.snoozed_until : null,
      followon: t.followon_type ? { type: t.followon_type, label: t.followon_label, due: t.followon_due } : null,
      // The rank inputs ride ALONG so the client can explain a row without a
      // second request, and so the pure module stays the only place that
      // decides what they mean.
      signals: {
        dueDate: t.due_date, stepType: t.next_step_type, stepLabel: t.next_step_label, daysOpen,
        openAskAmount: asks[t.donor_id] || 0,
        recurringAtRisk: atRisk.has(t.donor_id),
        // The opening gift was this donor's FIRST when the thread was opened
        // by a gift and the donor has exactly one on record. Cheap, and right
        // for the moment that matters: the gift that decides whether a second
        // one ever comes.
        isFirstGift: !!t.opening_gift_id && Number(t.gift_count) === 1,
        lifetimeGiving: parseFloat(t.total_giving) || 0,
        majorThreshold,
      },
    });
    // ENGAGE-1 §3 — a step that IS an ask carries the suggested ask, worked
    // out from this donor's own gifts (engagement.js; never wealth data).
    if (t.next_step_type === "check_in_ask" || /\bask\b/i.test(String(t.next_step_label || ""))) {
      list[list.length - 1].suggestedAsk = await engagementMod.suggestedAsk(query, orgId, t.donor_id).catch(() => null);
    }
  }

  // The tasks, in the same shape, so the ranking cannot tell them apart by
  // anything except what they actually say.
  for (const k of taskRows) {
    const due = String(k.due).slice(0, 10);
    const openedOn = k.created_at ? new Date(k.created_at).toISOString().slice(0, 10) : due;
    const daysOpen = orgTime.daysBetween(openedOn, today) ?? 0;
    list.push({
      id: k.id, kind: "task", donorId: k.donor_id, donorName: k.donor_name,
      nextStep: { type: k.type || "task", label: k.title, due, time: null, originalDue: null },
      // FIX-33: a meeting's prep and after tasks open the meeting they belong to.
      calendarEventId: k.calendar_event_id || null,
      // FIX-34: Done on a task row finishes THAT task, through its own route,
      // never the donor's open thread (logging a conversation would close the
      // meeting step a prep task belongs to). The row then shows the next step.
      doneRoute: `/tasks/${encodeURIComponent(k.id)}/complete`,
      overdue: due < today,
      overdueDays: due < today ? (orgTime.daysBetween(due, today) ?? 0) : 0,
      daysOpen: Math.max(0, daysOpen), openedOn,
      owner: k.assigned_to ? { id: k.assigned_to, name: k.assigned_to_name } : null,
      lastTouch: { kind: "none", type: null, date: openedOn, line: null, actor: k.assigned_to_name || null },
      snoozedUntil: null, followon: null,
      signals: {
        dueDate: due, stepType: k.type || "task", stepLabel: k.title, daysOpen: Math.max(0, daysOpen),
        openAskAmount: asks[k.donor_id] || 0,
        recurringAtRisk: atRisk.has(k.donor_id),
        isFirstGift: false,
        lifetimeGiving: parseFloat(k.total_giving) || 0,
        majorThreshold,
      },
    });
  }

  // FIX-34 · ONE ROW PER DONOR. A booked meeting put three rows on the Thread
  // for one person (the prep, the meeting, "How did it go?"). The Thread is a
  // list of PEOPLE: each donor shows once, as the soonest open step, carrying
  // the rest as `moreSteps` (the row opens them in place). Done on that row
  // leaves the next one soonest. Tasks still lists every step; a profile read
  // (donorId) keeps every row. Counts below are donors, not steps.
  let shownList = list;
  if (!donorId) {
    const soon = (a, b) => String(a.nextStep.due || "9999").localeCompare(String(b.nextStep.due || "9999"))
      || (a.kind === b.kind ? 0 : a.kind === "thread" ? -1 : 1) || String(a.nextStep.time || "").localeCompare(String(b.nextStep.time || ""));
    const byDonor = new Map();
    for (const r of list) { if (!byDonor.has(r.donorId)) byDonor.set(r.donorId, []); byDonor.get(r.donorId).push(r); }
    shownList = [];
    for (const rs of byDonor.values()) {
      rs.sort(soon);
      const [head, ...rest] = rs;
      head.moreSteps = rest.map(r => ({ id: r.id, kind: r.kind, label: r.nextStep.label, due: r.nextStep.due, time: r.nextStep.time || null,
        overdue: r.overdue, calendarEventId: r.calendarEventId || null }));
      shownList.push(head);
    }
  }
  // Rank + band + cap in the ONE place that decides it.
  const forRank = shownList.map(t => ({ ...t, ...t.signals }));
  const q = rank.buildQueue(forRank, today, { cap: donorId ? 0 : (cap == null ? rank.QUEUE_CAP : cap) });
  const ranked = q.list.map(r => {
    const { signals, ...rest } = r;
    return { ...rest, rank: r.rank, band: r.band };
  });

  const overdue = shownList.filter(t => t.overdue).length;
  // FIX-1 §9 — "oldest" is the oldest ROW, by the one figure its badge and the
  // Home sentence also read (shared/threadFigures.js), over the whole list, not
  // the capped one. It used to be max(daysOpen) while the badges said overdue.
  const { threadFigures } = await import("../shared/threadFigures.js");
  const figures = threadFigures(shownList);
  const oldestDays = figures.oldest ? figures.oldest.days : 0;
  const oldest = figures.oldest && figures.oldest.days > 0 ? figures.oldest : null;
  const [{ n: everCount } = { n: 0 }] = await query(`SELECT COUNT(*)::int AS n FROM threads WHERE org_id = ?`, [orgId]);
  return {
    list: ranked, bands: q.bands, more: q.more,
    stat: { open: shownList.length, steps: list.length, overdue, oldestDays, oldest, snoozed, unowned, shown: ranked.length },
    scope: effScope, canViewAll: isAdmin, hasAny: everCount > 0, today,
  };
}

// One thread's next step, as a calendar event. The ONE place a task becomes an
// appointment — every output below reads this, so they cannot disagree.
async function calendarEventForThread(orgId, threadId) {
  await CAL_READY;
  const [t] = await query(
    `SELECT t.id, t.next_step_label, t.next_step_type, t.due_date, t.due_time,
            d.id AS donor_id, d.name AS donor_name
       FROM threads t JOIN donors d ON d.id = t.donor_id
      WHERE t.id = ? AND t.org_id = ?`, [threadId, orgId]);
  if (!t) return null;
  const [org] = await query(`SELECT name FROM orgs WHERE id = ?`, [orgId]);
  const tzName = await orgTzName(orgId);
  // The time is HH:MM in the ORG's zone (BUILD-84). No time = an ALL-DAY
  // event; inventing 9am would put a fictional appointment in her morning.
  const startInstant = t.due_time
    ? orgTime.localToInstant(`${t.due_date}T${t.due_time}`, tzName)   // ORG_TZ_SEAM_OK
    : null;
  // The last logged line on this person — what she will actually need to
  // remember when the reminder fires three days from now.
  const [last] = await query(
    `SELECT note FROM interactions WHERE org_id = ? AND donor_id = ?
      ORDER BY date DESC, created_at DESC LIMIT 1`, [orgId, t.donor_id]).catch(() => []);
  const recordUrl = `${publicAppUrl()}/donors/${t.donor_id}`;
  return {
    uid: CAL.taskUid(orgId, t.id),
    // "Call Bill Harmon" — the step and the person, which is the whole
    // subject somebody needs in a calendar three days from now.
    subject: `${t.next_step_label} ${t.donor_name}`.replace(/\s+/g, " ").trim(),
    description: CAL.eventDescription({
      lastLine: last?.note || null, personName: t.donor_name,
      recordUrl, orgName: org?.name || null,
    }),
    startInstant, dueCivil: t.due_date, minutes: CAL.DEFAULT_MINUTES,
    timezone: tzName, donorId: t.donor_id, donorName: t.donor_name,
  };
}

// The three links for one next step. A GET, and it changes nothing.
app.get("/threads/:id/calendar", requireAuth, wrap(async (req, res) => {
  await CAL_READY;
  const ev = await calendarEventForThread(req.user.orgId, req.params.id);
  if (!ev) return res.status(404).json({ error: "Not found" });
  res.json({
    subject: ev.subject,
    startsAt: ev.startInstant ? new Date(ev.startInstant).toISOString() : null,
    allDay: !ev.startInstant, dueDate: ev.dueCivil, timezone: ev.timezone,
    outlook: CAL.outlookUrl(ev),
    google: CAL.googleUrl(ev),
    ics: `/threads/${req.params.id}/calendar.ics`,
    uid: ev.uid,
    note: CAL.NOT_SYNC_NOTE,
  });
}));

// The .ics itself, generated SERVER-SIDE so the UID rule lives in one place.
app.get("/threads/:id/calendar.ics", requireAuth, wrap(async (req, res) => {
  await CAL_READY;
  const ev = await calendarEventForThread(req.user.orgId, req.params.id);
  if (!ev) return res.status(404).json({ error: "Not found" });
  const filename = (ev.subject || "task").replace(/[^A-Za-z0-9]+/g, "-").replace(/^-|-$/g, "").toLowerCase() || "task";
  res.set("Content-Type", "text/calendar; charset=utf-8");
  res.set("Content-Disposition", `attachment; filename="${filename}.ics"`);
  // No caching: the step's time can change, and a cached .ics is a stale
  // appointment that looks current.
  res.set("Cache-Control", "no-store");
  res.send(CAL.buildIcs(ev));
}));

app.get("/threads", requireAuth, wrap(async (req, res) => {
  const donorId = req.query.donorId ? String(req.query.donorId) : null;
  const cap = /^\d+$/.test(String(req.query.cap || "")) ? Math.min(200, parseInt(req.query.cap, 10)) : null;
  res.json(await composeThreads(req.user.orgId, {
    donorId, cap,
    scope: String(req.query.scope || "mine"),
    userId: req.user.userId,
    isAdmin: req.user.role === "admin",
  }));
}));

// POST /donors/:id/conversations — THE write path of the Thread. Logs the
// touch (one line, an interactions row with the BUILD-75 actor), and the
// next-step decision travels IN THE SAME REQUEST: {type, due} opens the next
// thread, {skipped:true} is recorded as skipped on the interaction (the
// BUILD-76 rule — never as nothing). If the donor had an open thread, this
// conversation IS its outcome: the thread closes pointing at this
// interaction, and the next-step prompt's answer decides whether another
// opens. One request, one transaction — no half-logged state.
app.post("/donors/:id/conversations", requireAuth, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  const [donor] = await query(
    "SELECT id, assigned_to, assigned_to_name FROM donors WHERE id = ? AND org_id = ? AND deleted_at IS NULL",
    [req.params.id, orgId]);
  if (!donor) return res.status(404).json({ error: "Donor not found" });

  const shape = await threadShapeMod();
  const touch = shape.touchTypeFor(String(req.body?.touch || ""));
  if (!touch) return res.status(400).json({ error: "Unknown touch type" });
  const line = typeof req.body?.line === "string" ? req.body.line.trim().slice(0, 8000) : "";
  if (!line) return res.status(400).json({ error: "The one line is required — what happened?" });
  // FIX-14 Part 1 — where it happened, for a meeting or a visit. The card is
  // titled by it ("Meeting at Starbucks").
  const place = typeof req.body?.place === "string" ? req.body.place.trim().slice(0, 200) : "";

  const org = await orgTz(orgId);
  const today = orgToday(org);                          // ORG_TZ_SEAM_OK
  const date = /^\d{4}-\d{2}-\d{2}$/.test(String(req.body?.date || "")) ? req.body.date : today;

  const ns = req.body?.nextStep;
  const nsSkipped = !!(ns && ns.skipped === true);
  let step = null;
  if (!nsSkipped) {
    const typeLabel = shape.nextStepLabelFor(ns?.type);
    if (!ns || !typeLabel) return res.status(400).json({ error: "nextStep must be {type, due} from the offered set, or {skipped:true} — a skip is recorded, silence is not accepted" });
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(ns.due || ""))) return res.status(400).json({ error: "nextStep.due must be a date (YYYY-MM-DD)" });
    // The label is the user's own sentence when they wrote one (a note-derived
    // step, or one they retyped in the row); the type's label otherwise. A
    // suggestion the user has to retype costs time instead of saving it.
    const label = shape.sanitizeStepLabel(ns.label) || typeLabel;
    // BUILD-84 FEATURE — the optional time. A 2:00 reminder does not forgive
    // being an hour off, so it is refused outright for an org whose timezone
    // is still Steward's default guess rather than a choice someone made.
    let time = shape.sanitizeStepTime(ns.time);
    if (ns.time != null && ns.time !== "" && !time)
      return res.status(400).json({ error: "nextStep.time must be a 24-hour HH:MM, or omitted for a date-only step" });
    if (time && !org.timezone_confirmed_at) {
      return res.status(400).json({ error: "timezone_unset",
        message: "Set your organization's timezone in Settings before scheduling a reminder at a specific time — Steward will not fire one at a guessed hour." });
    }
    step = { type: ns.type, label, due: ns.due, time };
  }
  // Which rule produced the proposal — "note" or "touch" — recorded with the
  // conversation so a wrong guess can be found later, not just corrected once.
  const nsSource = ["note", "touch"].includes(String(req.body?.nextStep?.source || "")) ? req.body.nextStep.source : null;

  const userRow = await query("SELECT name FROM users WHERE id=?", [userId]);
  const userName = userRow[0]?.name || "";

  // ── BUILD-88a A.1 — THE OPTIONAL AMOUNT ──────────────────────────────────
  // A gift mentioned in a conversation IS a gift: it is written as a gift row,
  // through the one function, with its fund and method inline. It defaults to
  // the org's unrestricted fund and to "Needs you" as the method — a blank
  // reads the same as "nobody has looked", and this one is worth asking about.
  // The gift is written BEFORE the conversation, because the money must land
  // even if the follow-up write fails; the idempotency key is this exact
  // conversation, so a retried save cannot mint a second gift.
  let giftWritten = null;
  const giftIn = req.body && req.body.gift;
  if (giftIn && giftIn.amount != null && String(giftIn.amount).trim() !== "") {
    let giftAmt;
    try { giftAmt = toDollars(parseMoneyOrThrow(giftIn.amount, "gift.amount")); }
    catch (e) { return res.status(400).json({ error: e.message, code: e.code }); }
    if (!(giftAmt > 0)) return res.status(400).json({ error: "A gift on a conversation must be more than zero — leave it blank if there was none." });
    if (giftIn.fundId && !(await orgOwns("fin_funds", giftIn.fundId, orgId)))
      return res.status(404).json({ error: "Fund not found" });
    giftWritten = await recordGift({
      orgId, donorId: req.params.id, amount: giftAmt, date, type: "cash",
      fundId: giftIn.fundId || null, paymentMethod: giftIn.paymentMethod,
      notes: line, timeline: false,          // the conversation IS the timeline entry
      idempotencyKey: `conversation:${req.params.id}:${date}:${giftAmt}:${line}`.slice(0, 128),
      conflict: "idempotency",
      actorId: userId, actorName: userName, source: "conversation",
    });
  }
  const giftIdForTimeline = giftWritten && giftWritten.gift ? giftWritten.gift.id : null;

  const out = await withTransaction(async (client) => {
    const intId = "int_" + uuid().slice(0, 8);
    await runTx(client,
      "INSERT INTO interactions (id,org_id,donor_id,type,note,date,created_by,logged_by_name,gift_id,metadata) VALUES (?,?,?,?,?,?,?,?,?,?)",
      [intId, orgId, req.params.id, touch.interactionType, line, date, userId, userName, giftIdForTimeline,
       JSON.stringify({ via: "thread_log", touch: touch.key, next_step: nsSkipped ? "skipped" : "set", ...(place ? { location: place } : {}),
                        ...(step ? { next_step_label: step.label } : {}), ...(nsSource ? { next_step_source: nsSource } : {}) })]);

    // An open thread on this donor closes on this conversation — the outcome.
    const closedRows = await queryTx(client,
      `UPDATE threads SET closed_at = NOW(), close_kind = 'outcome', closing_interaction_id = ?
        WHERE org_id = ? AND donor_id = ? AND closed_at IS NULL RETURNING id`,
      [intId, orgId, req.params.id]);

    let thread = null;
    if (step) {
      // The meeting/visit chain: when the user KEPT the thank-you-note
      // default, the second thread (Follow up, +14 from the touch) rides
      // along and prefills the prompt when this one closes. A changed type
      // is the user's decision replacing the plan — no follow-on.
      const def = shape.NEXT_STEP_DEFAULTS[touch.key];
      const followon = def?.followon && step.type === def.type && step.label === def.label
        ? { type: def.followon.type, label: def.followon.label, due: shape.addCivilDays(date, def.followon.plusDays) }
        : null;
      thread = await openThreadTx(client, {
        orgId, donorId: req.params.id, step, openedOn: today,
        ownerId: donor.assigned_to || userId, ownerName: donor.assigned_to ? donor.assigned_to_name : userName,
        actorId: userId, actorName: userName, openingInteractionId: intId, followon,
      });
    }
    return { interactionId: intId, closedThreadId: closedRows[0]?.id || null, thread };
  });

  calcWealthScore(req.params.id, orgId).catch(e => console.error("score recalc:", e.message));
  // FIX-14 Part 2 — the audit row names the conversation that was logged
  // (the response's first object is the thread, which is the wrong record),
  // and carries it, so the log can say "Logged a meeting with ...".
  if (req.audit) {
    const [logged] = await query("SELECT * FROM interactions WHERE id = ?", [out.interactionId]);
    req.audit.entity("interaction", out.interactionId);
    req.audit.after(logged ? { ...logged, next_step: step ? { label: step.label, due: step.due } : "skipped" } : null);
  }
  // BUILD-99 Part 3 — A PLAN STEP IS DONE WHEN ITS THREAD CLOSES, and the next
  // one opens. Called AFTER the transaction, so the plan reads the thread rows
  // this conversation actually committed. It is idempotent and self-healing: if
  // the officer's own next step already took the donor's one open thread slot,
  // the plan's next step stays PENDING and the next close advances it — which is
  // what makes this work with no background tick (production has none).
  await advanceCultivationPlan(orgId, req.params.id, {
    actorId: actor(req).id, actorName: actor(req).name, today: date,
  }).catch(e => console.error("[plan] advance:", e.message));
  // A.1 — the gift the conversation carried, named in the response so the
  // screen can say what it recorded instead of the user going to look.
  const giftOut = giftWritten && giftWritten.gift
    ? { id: giftWritten.gift.id, amount: round2(parseFloat(giftWritten.gift.amount) || 0),
        fundId: giftWritten.fundId, paymentMethod: giftWritten.paymentMethod }
    : (giftWritten && giftWritten.duplicate ? { duplicate: true } : null);
  res.status(201).json({ ...out, skipped: nsSkipped, gift: giftOut });
}));

// ── FIX-14 Part 1 — WHAT STEWARD HEARD IN A LOGGED CONVERSATION ────────────
// The FIX-12 after-meeting engine, for a conversation logged by hand: the
// Agent engine reads the note through the one AI door (aiClient.js asks the
// org's switch), and shared/meetingNote.js's simple reader is the fallback.
// Three chips, and NOTHING is recorded until a person says yes:
//   next     sets the profile's next step: the donor's one open Thread step
//   spouse   links the spouse named in the note into one household, matching
//            a person already on file by name or adding them (the one person
//            record: a row in donors, person type "other")
//   planned  marks the record a planned-giving prospect (the designation)
// A chip answered either way is remembered on the interaction
// (metadata.chips_done), so it is offered once.
const CONVO_CHIP_TTL_MS = 10 * 60 * 1000;
const _convoChipCache = new Map();   // interaction id + note → the engine's chips, briefly
async function loggedConversation(orgId, id) {
  const [i] = await query(
    `SELECT i.id, i.donor_id, i.type, i.note, i.date, i.metadata, d.name AS donor_name, d.household_id
       FROM interactions i JOIN donors d ON d.id = i.donor_id AND d.org_id = i.org_id
      WHERE i.id = ? AND i.org_id = ? AND d.deleted_at IS NULL`, [id, orgId]);
  if (!i) return null;
  i.meta = typeof i.metadata === "string" ? (() => { try { return JSON.parse(i.metadata); } catch { return {}; } })() : (i.metadata || {});
  i.done = Array.isArray(i.meta.chips_done) ? i.meta.chips_done : [];
  return i;
}
async function spouseCandidate(orgId, i, name) {
  const given = String(name || "").trim();
  const ln = lastName(i.donor_name);
  const full = given.includes(" ") || !ln ? given : `${given} ${ln}`;
  const rows = await query(
    `SELECT id, name, household_id FROM donors WHERE org_id = ? AND deleted_at IS NULL AND id <> ?
        AND (LOWER(name) = LOWER(?) OR LOWER(name) = LOWER(?)) ORDER BY (LOWER(name) = LOWER(?)) DESC LIMIT 2`,
    [orgId, i.donor_id, full, given, full]);
  return { full, match: rows.length >= 1 && (rows.length === 1 || rows[0].name.toLowerCase() === full.toLowerCase()) ? rows[0] : null };
}

app.post("/interactions/:id/suggest", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  if (req.audit) req.audit.skip("reads a note and writes nothing");
  const i = await loggedConversation(orgId, req.params.id);
  if (!i) return res.status(404).json({ error: "Not found" });
  const N = await import("../shared/meetingNote.js");
  const note = String(i.note || "").slice(0, 4000);
  const ctx = { date: String(i.date || "").slice(0, 10) };
  let suggestions = null, source = "reader", aiOff = false;
  const ck = i.id + "\u0000" + note;
  const hit = _convoChipCache.get(ck);
  if (hit && hit.until > Date.now()) { suggestions = hit.chips; source = "agent"; }
  else if (note.trim()) {
    try {
      const r = await anthropicFor(orgId).messages.create({
        model: AGENT_MODEL, max_tokens: 600, system: N.CONVERSATION_CHIP_SYSTEM,
        messages: [{ role: "user", content: `Her note:\n"""${note}"""` }],
        tools: [N.CONVERSATION_CHIP_TOOL], tool_choice: { type: "tool", name: N.CONVERSATION_CHIP_TOOL.name } });
      const use = (r.content || []).find(c => c.type === "tool_use");
      const chips = N.validateConversationChips(use && use.input && use.input.chips, note, ctx);
      if (chips.length) { suggestions = chips; source = "agent"; _convoChipCache.set(ck, { chips, until: Date.now() + CONVO_CHIP_TTL_MS }); }
    } catch (e) {
      if (e instanceof AiOffError) aiOff = e.reason === "ai_disabled";
      else console.error("[conversation-chips] engine:", e.message);
    }
  }
  if (!suggestions) suggestions = N.suggestFromConversation(note, ctx);
  // Only what is not already true, and not already answered.
  const out = [];
  for (const c of suggestions) {
    if (i.done.includes(c.kind)) continue;
    if (c.kind === "planned") {
      const [has] = await query(`SELECT 1 FROM donor_designations WHERE org_id = ? AND donor_id = ? AND kind IN ('planned_prospect','planned_confirmed','estate')`, [orgId, i.donor_id]);
      if (has) continue;
    }
    if (c.kind === "spouse") {
      const { full, match } = await spouseCandidate(orgId, i, c.name);
      if (match && i.household_id && match.household_id === i.household_id) continue;
      out.push({ ...c, fullName: full, matchId: match ? match.id : null,
        label: match ? `Link ${match.name} to the household` : `Add ${full} and link the household` });
      continue;
    }
    if (c.kind === "next") {
      const [open] = await query(`SELECT due_date FROM threads WHERE org_id = ? AND donor_id = ? AND closed_at IS NULL`, [orgId, i.donor_id]);
      if (open && open.due_date === c.due) continue;
    }
    out.push(c);
  }
  res.json({ suggestions: out, source,
    sentence: aiOff ? AI_OFF_MESSAGE + ". These come from Steward's simple reader. Nothing changes until you say yes."
      : "Read from the note. Nothing changes until you say yes." });
}));

app.post("/interactions/:id/chips", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  const i = await loggedConversation(orgId, req.params.id);
  if (!i) return res.status(404).json({ error: "Not found" });
  const kind = String(req.body?.kind || "");
  if (!["next", "spouse", "planned"].includes(kind)) return res.status(400).json({ error: "kind must be next, spouse or planned" });
  const answer = req.body?.answer === "no" ? "no" : "yes";
  const who = actor(req);
  let sentence = "Fine. Steward will not offer that again for this note.";
  if (answer === "yes" && kind === "next") {
    const shape = await threadShapeMod();
    const label = shape.sanitizeStepLabel(req.body?.label) || "Follow up";
    const due = String(req.body?.due || "");
    if (!/^\d{4}-\d{2}-\d{2}$/.test(due)) return res.status(400).json({ error: "due must be a date (YYYY-MM-DD)" });
    const [donor] = await query("SELECT assigned_to, assigned_to_name FROM donors WHERE id = ? AND org_id = ?", [i.donor_id, orgId]);
    const today = orgToday(await orgTz(orgId));   // ORG_TZ_SEAM_OK
    const [open] = await query("SELECT id FROM threads WHERE org_id = ? AND donor_id = ? AND closed_at IS NULL", [orgId, i.donor_id]);
    if (open) {
      // One open step per person: her yes replaces what it says and when.
      await run("UPDATE threads SET next_step_type = ?, next_step_label = ?, due_date = ?, snoozed_until = NULL WHERE id = ? AND org_id = ?",
        [shape.nextStepTypeForLabel(label), label, due, open.id, orgId]);
    } else {
      await withTransaction(client => openThreadTx(client, {
        orgId, donorId: i.donor_id, step: { type: shape.nextStepTypeForLabel(label), label, due, time: null }, openedOn: today,
        ownerId: donor?.assigned_to || userId, ownerName: donor?.assigned_to ? donor.assigned_to_name : who.name,
        actorId: who.id, actorName: who.name, openingInteractionId: i.id,
      }));
    }
    sentence = `Next step set: ${label}, due ${due}.`;
  } else if (answer === "yes" && kind === "spouse") {
    const name = String(req.body?.name || "").trim().slice(0, 120);
    if (!name) return res.status(400).json({ error: "name is required" });
    let spouseId = null;
    if (req.body?.matchId) {
      const [m] = await query("SELECT id, household_id FROM donors WHERE id = ? AND org_id = ? AND deleted_at IS NULL", [String(req.body.matchId), orgId]);
      if (!m) return res.status(404).json({ error: "That person is not on file." });
      if (m.household_id && i.household_id && m.household_id !== i.household_id)
        return res.status(400).json({ error: "That person is already in another household." });
      spouseId = m.id;
    }
    await withTransaction(async client => {
      if (!spouseId) {
        // THE ONE PERSON RECORD: a spouse is a row in donors, not a field.
        spouseId = "d_" + uuid().slice(0, 8);
        await runTx(client,
          `INSERT INTO donors (id,org_id,name,email,phone,status,stage,total_giving,last_gift_amount,gift_count,tags,notes,created_by,created_by_name,person_types)
           VALUES (?,?,?,'','','new','prospect',0,0,0,'[]','',?,?,?)`,
          [spouseId, orgId, name, who.id, who.name, JSON.stringify(["other"])]);
      }
      let hh = i.household_id;
      if (!hh) {
        const [sp] = await queryTx(client, "SELECT household_id FROM donors WHERE id = ? AND org_id = ?", [spouseId, orgId]);
        hh = sp && sp.household_id;
      }
      if (!hh) {
        hh = "hh_" + uuid().slice(0, 8);
        const ln = lastName(i.donor_name);
        await runTx(client, "INSERT INTO households (id,org_id,name,primary_donor_id,joint_acknowledgment,created_by,created_by_name) VALUES (?,?,?,?,?,?,?)",
          [hh, orgId, ln ? `The ${ln} Household` : "Household", i.donor_id, true, who.id, who.name]);
      }
      await runTx(client, "UPDATE donors SET household_id = ? WHERE org_id = ? AND id = ANY(?)", [hh, orgId, [i.donor_id, spouseId]]);
    });
    sentence = `${name} is linked to ${i.donor_name}'s household.`;
  } else if (answer === "yes" && kind === "planned") {
    await run("INSERT INTO donor_designations (id,org_id,donor_id,kind) VALUES (?,?,?,?) ON CONFLICT (donor_id, kind) DO NOTHING",
      ["dsg_" + uuid().slice(0, 8), orgId, i.donor_id, "planned_prospect"]);
    sentence = `${i.donor_name} is marked as a planned-giving prospect.`;
  }
  await run(`UPDATE interactions SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('chips_done', ?::jsonb)
              WHERE id = ? AND org_id = ?`, [JSON.stringify([...new Set([...i.done, kind])]), i.id, orgId]);
  if (req.audit) { req.audit.entity("donor", i.donor_id); req.audit.action(answer === "yes" ? `confirmed the ${kind} suggestion` : `declined the ${kind} suggestion`); }
  res.json({ ok: true, kind, answer, sentence });
}));

// POST /threads/:id/dismiss — the other way out. reason ∈ the short fixed
// list; "revisit" is a snooze (the thread stays open, resurfaces on the
// date), the other two close the thread with the reason on the row.
app.post("/threads/:id/dismiss", requireAuth, wrap(async (req, res) => {
  const { orgId } = req.user;
  const [t] = await query("SELECT * FROM threads WHERE id = ? AND org_id = ?", [req.params.id, orgId]);
  if (!t) return res.status(404).json({ error: "Thread not found" });
  if (t.closed_at) return res.status(400).json({ error: "Thread is already closed" });

  const { DISMISS_REASONS } = await threadShapeMod();
  const reason = String(req.body?.reason || "");
  if (!DISMISS_REASONS.some(r => r.key === reason)) {
    return res.status(400).json({ error: "reason must be one of: " + DISMISS_REASONS.map(r => r.key).join(", ") });
  }
  if (reason === "revisit") {
    const on = String(req.body?.revisitOn || "");
    if (!/^\d{4}-\d{2}-\d{2}$/.test(on)) return res.status(400).json({ error: "revisitOn must be a date (YYYY-MM-DD)" });
    const org = await orgTz(orgId);
    if (on <= orgToday(org)) return res.status(400).json({ error: "revisitOn must be a future date — a revisit today is just the open thread" });   // ORG_TZ_SEAM_OK
    // MOVE the due date, and keep the first one. A revisit is a new promise
    // about when; leaving due_date behind made every deferred thread return as
    // a false alarm, and dropping it would lose the day she originally said.
    // COALESCE means a thread snoozed twice still remembers the FIRST date.
    await run(
      `UPDATE threads
          SET original_due_date = COALESCE(original_due_date, due_date),
              due_date = ?, snoozed_until = ?
        WHERE id = ?`, [on, on, req.params.id]);
    return res.json({ ok: true, snoozedUntil: on, dueDate: on, originalDue: t.original_due_date || t.due_date });
  }
  await run(
    "UPDATE threads SET closed_at = NOW(), close_kind = 'dismissed', close_reason = ? WHERE id = ?",
    [reason, req.params.id]);
  // BUILD-99 Part 3 — a dismissal closes a plan step too. Deciding not to do
  // something is still deciding; the plan moves on rather than sitting on a
  // thread nobody is going to act on.
  await advanceCultivationPlan(orgId, t.donor_id, {
    actorId: actor(req).id, actorName: actor(req).name,
  }).catch(e => console.error("[plan] advance:", e.message));
  res.json({ ok: true, dismissed: reason });
}));

// ── BUILD-85 — PLANNING FORWARD ────────────────────────────────────────────
// Every BUILD-81 opener required something to have ALREADY HAPPENED: a logged
// conversation, a gift, a drift-done, a sustainer lapse. Half of a
// fundraiser's week is not reactive — "I am calling these twenty lapsed
// donors this month" had nowhere to live, so it lived in Tasks, which is what
// kept two follow-up systems alive at once.
//
// This does NOT reopen the tasks battle. That rule was "logging a
// conversation must not require a second step", not "you may never plan". A
// planned thread is the same row as any other: one donor, one open step, one
// owner, closed honestly by the same conversation flow. Its `lastTouch.kind`
// is "none", a case composeThreads has always handled.
app.post("/donors/:id/threads", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  const [donor] = await query(
    "SELECT id, name, assigned_to, assigned_to_name FROM donors WHERE id = ? AND org_id = ? AND deleted_at IS NULL",
    [req.params.id, orgId]);
  if (!donor) return res.status(404).json({ error: "Donor not found" });

  const shape = await threadShapeMod();
  const label = shape.sanitizeStepLabel(req.body?.label);
  if (!label) return res.status(400).json({ error: "A next step needs a label — say what you are going to do." });
  const due = String(req.body?.due || "");
  if (!/^\d{4}-\d{2}-\d{2}$/.test(due)) return res.status(400).json({ error: "due must be a date (YYYY-MM-DD)" });

  const org = await orgTz(orgId);
  const today = orgToday(org);                          // ORG_TZ_SEAM_OK
  let time = shape.sanitizeStepTime(req.body?.time);
  if (req.body?.time != null && req.body.time !== "" && !time)
    return res.status(400).json({ error: "time must be a 24-hour HH:MM, or omitted for a date-only step" });
  if (time && !org.timezone_confirmed_at)
    return res.status(400).json({ error: "timezone_unset", message: "Set your organization's timezone in Settings before scheduling a reminder at a specific time." });

  // ONE OPEN THREAD PER DONOR is the model, and the DB enforces it
  // (threads_one_open). Refuse with the thread that is already there rather
  // than silently replacing a commitment somebody made.
  const [open] = await query(
    "SELECT id, next_step_label, due_date FROM threads WHERE org_id = ? AND donor_id = ? AND closed_at IS NULL",
    [orgId, req.params.id]);
  if (open) return res.status(409).json({ error: "thread_open",
    message: `${donor.name} already has an open next step: "${open.next_step_label}", due ${open.due_date}.`,
    thread: { id: open.id, label: open.next_step_label, due: open.due_date } });

  // FIX-19: an ownerId from the body is an active user of THIS org, or the
  // request is refused before anything is written.
  const named = await OU.orgUser(orgId, req.body?.ownerId);
  if (!named.ok) return OU.refuse(res, "ownerId");
  const userRow = await query("SELECT name FROM users WHERE id=?", [userId]);
  const userName = userRow[0]?.name || "";
  const step = { type: shape.nextStepTypeForLabel(label), label, due, time };
  const thread = await withTransaction(client => openThreadTx(client, {
    orgId, donorId: req.params.id, step, openedOn: today,
    ownerId: named.user ? named.user.id : (donor.assigned_to || userId),
    ownerName: named.user ? named.user.name : (donor.assigned_to ? donor.assigned_to_name : userName),
    actorId: userId, actorName: userName,
  }));
  res.status(201).json({ thread });
}));

// POST /threads/plan — the same act, for a selection. "Call these twenty
// lapsed donors" in one request. A donor who ALREADY has an open thread is
// SKIPPED and REPORTED, never overwritten: the whole point of the one-open
// rule is that a commitment already made outranks a plan being drawn up.
const BULK_PLAN_MAX = 200;
app.post("/threads/plan", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  const ids = Array.isArray(req.body?.donorIds) ? req.body.donorIds.map(String).filter(Boolean) : [];
  if (!ids.length) return res.status(400).json({ error: "donorIds must be a non-empty array" });
  if (ids.length > BULK_PLAN_MAX) return res.status(400).json({ error: `At most ${BULK_PLAN_MAX} donors at a time` });

  const shape = await threadShapeMod();
  const label = shape.sanitizeStepLabel(req.body?.label);
  if (!label) return res.status(400).json({ error: "A next step needs a label — say what you are going to do." });
  const due = String(req.body?.due || "");
  if (!/^\d{4}-\d{2}-\d{2}$/.test(due)) return res.status(400).json({ error: "due must be a date (YYYY-MM-DD)" });

  const org = await orgTz(orgId);
  const today = orgToday(org);                          // ORG_TZ_SEAM_OK
  const userRow = await query("SELECT name FROM users WHERE id=?", [userId]);
  const userName = userRow[0]?.name || "";

  // Org-scoped up front: an id from another org is not found, never planted.
  const ph = ids.map(() => "?").join(",");
  const donors = await query(
    `SELECT id, name, assigned_to, assigned_to_name FROM donors
      WHERE org_id = ? AND deleted_at IS NULL AND id IN (${ph})`, [orgId, ...ids]);
  const byId = new Map(donors.map(d => [d.id, d]));
  const openAlready = new Set((await query(
    `SELECT donor_id FROM threads WHERE org_id = ? AND closed_at IS NULL AND donor_id IN (${ph})`,
    [orgId, ...ids])).map(r => r.donor_id));

  const planned = [], skipped = [];
  for (const id of ids) {
    const d = byId.get(id);
    if (!d) { skipped.push({ donorId: id, reason: "not_found" }); continue; }
    if (openAlready.has(id)) { skipped.push({ donorId: id, donorName: d.name, reason: "already_open" }); continue; }
    try {
      const t = await withTransaction(client => openThreadTx(client, {
        orgId, donorId: id, step: { type: shape.nextStepTypeForLabel(label), label, due, time: null },
        openedOn: today, ownerId: d.assigned_to || userId,
        ownerName: d.assigned_to ? d.assigned_to_name : userName,
        actorId: userId, actorName: userName,
      }));
      planned.push({ donorId: id, donorName: d.name, threadId: t?.id || null });
    } catch (e) {
      // The partial unique index is the arbiter under a race — a loser is a
      // skip with a reason, never a 500 and never a second open thread.
      skipped.push({ donorId: id, donorName: d.name, reason: "already_open" });
    }
  }
  res.status(201).json({ planned: planned.length, skipped: skipped.length, details: { planned, skipped } });
}));

app.get("/threads/health", requireAuth, wrap(async (req, res) => {
  const days = /^\d+$/.test(String(req.query.days || "")) ? Math.min(365, parseInt(req.query.days, 10)) : 30;
  res.json(await computeThreadHealth(req.user.orgId, { days }));
}));

// ── Fundraising goals (home screen goal banner) ─────────────────────────────
app.get("/goals/active", requireAuth, wrap(async (req, res) => {
  // Civil date: a goal's period is a range of DAYS ON A CALENDAR, so whether
  // today falls inside it is a question about the org's calendar, not UTC's.
  // On the last evening of a goal's period a UTC slice drops the goal off the
  // Home banner hours early.
  const today = orgToday(await orgTz(req.user.orgId));  // ORG_TZ_SEAM_OK
  const rows = await query(
    "SELECT * FROM fundraising_goals WHERE org_id = ? AND period_start <= ? AND period_end >= ? ORDER BY created_at DESC LIMIT 1",
    [req.user.orgId, today, today]
  );
  if (!rows.length) return res.json(null);
  const goal = rows[0];
  const goalAmount = parseFloat(goal.goal_amount) || 0;

  let currentAmount = 0;
  if (goal.goal_type === "lapsed_recovery") {
    // A gift counts toward recovery when it's a donor's most recent gift in
    // the period AND it followed a gap of more than 365 days since their
    // prior gift — i.e. it's the gift that actually pulled them back from
    // lapsed, reconstructed from gift history rather than a stage-history
    // table (which doesn't exist).
    const rows2 = await query(
      `SELECT COALESCE(SUM(g.amount),0) AS total
       FROM gifts g
       JOIN donors d ON d.id = g.donor_id
       WHERE g.org_id = ? AND g.date >= ? AND g.date <= ? AND g.date = d.last_gift_date
         AND (SELECT MAX(g2.date) FROM gifts g2 WHERE g2.donor_id = d.id AND g2.date < g.date) IS NOT NULL
         AND g.date::date - (SELECT MAX(g2.date) FROM gifts g2 WHERE g2.donor_id = d.id AND g2.date < g.date)::date > 365`,
      [req.user.orgId, goal.period_start, goal.period_end]
    );
    currentAmount = parseFloat(rows2[0]?.total) || 0;
  } else {
    const rows2 = await query(
      "SELECT COALESCE(SUM(amount),0) AS total FROM gifts WHERE org_id = ? AND date >= ? AND date <= ?",
      [req.user.orgId, goal.period_start, goal.period_end]
    );
    currentAmount = parseFloat(rows2[0]?.total) || 0;
  }

  const percent = goalAmount > 0 ? Math.min(100, Math.round((currentAmount / goalAmount) * 100)) : 0;
  // Uncapped truth + overage, so the Home hero reads a beaten goal as a win
  // ("Goal met · 302% · $50k over") instead of a misleading flat 100%.
  const rawPercent = goalAmount > 0 ? Math.round((currentAmount / goalAmount) * 100) : 0;
  const over = goalAmount > 0 && currentAmount > goalAmount ? currentAmount - goalAmount : 0;

  // Trailing-7-day slice of the same real activity above — powers the Home
  // hero banner's "what's driving this" hint with actual recent gifts
  // instead of an invented/decorative line. Bounded to stay inside the
  // goal's own period so it never reaches back before period_start.
  let recentAmount = 0, recentDonorCount = 0;
  // Seven days back from the ORG'S civil today, not from UTC's. `today` above
  // is already the org's civil date; deriving the other end of the same window
  // from a UTC slice made the window start on the wrong day for four hours a
  // night and, worse, could put its END before its start.
  const sevenDaysAgoStr = orgTime.addDays(today, -6);
  const recentStart = sevenDaysAgoStr > goal.period_start ? sevenDaysAgoStr : goal.period_start;
  if (recentStart <= today) {
    if (goal.goal_type === "lapsed_recovery") {
      const rows3 = await query(
        `SELECT COALESCE(SUM(g.amount),0) AS total, COUNT(DISTINCT g.donor_id) AS donors
         FROM gifts g
         JOIN donors d ON d.id = g.donor_id
         WHERE g.org_id = ? AND g.date >= ? AND g.date <= ? AND g.date = d.last_gift_date
           AND (SELECT MAX(g2.date) FROM gifts g2 WHERE g2.donor_id = d.id AND g2.date < g.date) IS NOT NULL
           AND g.date::date - (SELECT MAX(g2.date) FROM gifts g2 WHERE g2.donor_id = d.id AND g2.date < g.date)::date > 365`,
        [req.user.orgId, recentStart, today]
      );
      recentAmount = parseFloat(rows3[0]?.total) || 0;
      recentDonorCount = parseInt(rows3[0]?.donors, 10) || 0;
    } else {
      const rows3 = await query(
        "SELECT COALESCE(SUM(amount),0) AS total, COUNT(DISTINCT donor_id) AS donors FROM gifts WHERE org_id = ? AND date >= ? AND date <= ?",
        [req.user.orgId, recentStart, today]
      );
      recentAmount = parseFloat(rows3[0]?.total) || 0;
      recentDonorCount = parseInt(rows3[0]?.donors, 10) || 0;
    }
  }

  res.json({
    label: goal.label, goalType: goal.goal_type, goalAmount, currentAmount, percent, rawPercent, over,
    periodStart: goal.period_start, periodEnd: goal.period_end,
    recentAmount, recentDonorCount,
  });
}));

app.post("/goals", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const { label, goalAmount, goalType, periodStart, periodEnd } = req.body;
  if (!label || !goalAmount || !goalType || !periodStart || !periodEnd) {
    return res.status(400).json({ error: "label, goalAmount, goalType, periodStart, and periodEnd required" });
  }
  if (!["lapsed_recovery", "total_raised"].includes(goalType)) {
    return res.status(400).json({ error: "goalType must be lapsed_recovery or total_raised" });
  }
  const id = "goal_" + uuid().slice(0, 8);
  await run(
    "INSERT INTO fundraising_goals (id,org_id,period_start,period_end,goal_type,goal_amount,label) VALUES (?,?,?,?,?,?,?)",
    [id, req.user.orgId, periodStart, periodEnd, goalType, parseFloat(goalAmount), label]
  );
  res.status(201).json({ id });
}));

// Computes both metrics live (so the number shown is never stale), persists
// today's snapshot for this org (so the trend line fills in as the page
// gets viewed, on top of the periodic background job), and returns the
// last 30 days of history for each.
// Wipes the org's own metric-trend history and re-snapshots today from live
// data. Built for baseline pollution (BUILD-06 Phase E): after a mass
// purge-trash (e.g. the CREO 3,905-test-donor cleanup), the Home trends
// compared real data against snapshots of deleted test data ("↓1,153 vs 3
// weeks ago"). Org-scoped + admin — an org resetting its own analytics
// baseline is its own business; trends read "no trend data yet" until real
// history re-accumulates, which is the honest state.
app.post("/metrics/reset-baselines", requireAuth, requireAdmin, wrap(async (req, res) => {
  const del = await run("DELETE FROM metric_snapshots WHERE org_id = ?", [req.user.orgId]);
  await snapshotMetricsForOrg(req.user.orgId);
  res.json({ deleted: del.changes, resnapshotted: true });
}));

app.get("/metrics/stewardship-summary", requireAuth, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  // ?scope=mine (default) scopes Debt/Retention to the logged-in user's own
  // assigned donors, same as GET /dashboard/today; ?scope=all is org-wide.
  // Only the "current" figures are scoped — the trend/sparkline history
  // below stays org-wide (metric_snapshots has no per-user dimension, and
  // building one is out of scope here), and a scoped read is never persisted
  // as a snapshot, so one user's "mine" view can't pollute the org's daily
  // trend. First-Touch Delay is intentionally left unscoped.
  const scope = req.query.scope === "all" ? "all" : "mine";
  const since = new Date(); since.setDate(since.getDate() - 30);
  const sinceStr = since.toISOString().slice(0, 10);
  // BUILD-54 §1 — the three metric computations and three trend reads are
  // independent; one parallel batch (was 6 sequential round trips).
  const [debt, firstTouch, retention, debtTrend, touchTrend, retentionTrend] = await Promise.all([
    scope === "all" ? snapshotMetricsForOrg(orgId) : computeStewardshipDebt(orgId, { userId }),
    computeFirstTouchDelay(orgId),
    scope === "all" ? computeRetentionRate(orgId) : computeRetentionRate(orgId, { userId }),
    query(
      "SELECT snapshot_date, value FROM metric_snapshots WHERE org_id=? AND metric_key='stewardship_debt' AND snapshot_date >= ? ORDER BY snapshot_date ASC",
      [orgId, sinceStr]),
    query(
      "SELECT snapshot_date, value FROM metric_snapshots WHERE org_id=? AND metric_key='first_touch_delay' AND snapshot_date >= ? ORDER BY snapshot_date ASC",
      [orgId, sinceStr]),
    query(
      "SELECT snapshot_date, value FROM metric_snapshots WHERE org_id=? AND metric_key='retention_rate' AND snapshot_date >= ? ORDER BY snapshot_date ASC",
      [orgId, sinceStr]),
  ]);

  const trendDelta = trend => trend.length >= 2 ? Math.round(Number(trend[trend.length - 1].value) - Number(trend[0].value)) : null;

  res.json({
    stewardshipDebt: { current: debt, trend: debtTrend.map(r => ({ date: r.snapshot_date, value: Number(r.value) })), deltaVsTrendStart: trendDelta(debtTrend) },
    firstTouchDelay: { current: firstTouch.avgDays, sampleSize: firstTouch.sampleSize, untouchedCount: firstTouch.untouchedCount, newestUntouched: firstTouch.newestUntouched, trend: touchTrend.map(r => ({ date: r.snapshot_date, value: Number(r.value) })), deltaVsTrendStart: trendDelta(touchTrend) },
    importCaveat: (await importHealth(orgId)).caveat,
    retentionRate: {
      // BUILD-80 Part 9 — the sector comparison is GONE (the sentence
      // BUILD-73 banned: no benchmarking an org on first contact, no
      // unsourced sector statistics). Rate, window, denominator — nothing else.
      current: retention.retentionRate,
      // BUILD-76 follow-up — the confidence floor: below it the client says
      // "not enough history yet" and drops the sector comparison entirely.
      thinData: retention.thinData, historyDays: retention.historyDays, floor: retention.floor,
      retained: retention.retained, prevYearCount: retention.prevYearCount,
      // Lets the client tell "0% because nothing has been logged this year
      // yet" (day-one org, too early to measure) apart from a genuine 0%.
      thisYearCount: retention.thisYearCount,
      // BUILD-77 Part 4 — the tile STATES its window + denominator (a rate is
      // meaningless without them: 66% "above sector average" over 204
      // prior-year donors where half the file is lapsed reads as fake).
      year: retention.year, prevYear: retention.prevYear,
      trend: retentionTrend.map(r => ({ date: r.snapshot_date, value: Number(r.value) })), deltaVsTrendStart: trendDelta(retentionTrend),
    },
  });
}));

// Ranked, per-donor drill-down behind the Stewardship Debt headline number —
// every donor with total_giving > 0 has a precise, individually-attributable
// contribution to that aggregate (see computeStewardshipDebtBreakdown), so
// this surfaces it directly instead of leaving it as one opaque figure.
// Capped at a page size since a large org could have hundreds of qualifying
// donors; `count` is the true total so the UI can say "top 50 of 214".
app.get("/dashboard/stewardship-debt/breakdown", requireAuth, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  const PAGE_SIZE = 50;
  const scope = req.query.scope === "all" ? "all" : "mine";
  const breakdown = await computeStewardshipDebtBreakdown(orgId, scope === "mine" ? { userId } : {});
  const total = breakdown.reduce((sum, d) => sum + d.contribution, 0);
  const rows = breakdown.slice(0, PAGE_SIZE).map(d => ({
    donorId: d.donorId,
    donorName: d.donorName,
    totalGiving: d.totalGiving,
    daysSinceContact: d.daysSinceContact,
    contribution: Math.round(d.contribution * 10) / 10,
    percentOfTotal: total > 0 ? Math.round((d.contribution / total) * 1000) / 10 : 0,
  }));
  // BUILD-73 Part 2 — was Math.round(total); the headline of a money breakdown.
  res.json({ total: toDollars(toCents(total) || 0), count: breakdown.length, rows });
}));

// Ranked drill-down behind the Retention Rate headline number — the actual
// donors who gave last year but haven't given again this year, i.e. the
// specific list dragging the rate down. Shares computeRetentionRate's exact
// donor-set math (thisYearDonorIds/prevYearDonorIds) so the headline % and
// this list can never disagree: nonRetained.length always equals
// prevYearCount - retained by construction (set difference vs set
// intersection of the same two sets).
app.get("/dashboard/retention/breakdown", requireAuth, wrap(async (req, res) => {
  const { orgId, userId } = req.user;
  const PAGE_SIZE = 50;
  const scope = req.query.scope === "all" ? "all" : "mine";
  const retention = await computeRetentionRate(orgId, scope === "mine" ? { userId } : {});
  const nonRetainedIds = [...retention.prevYearDonorIds].filter(id => !retention.thisYearDonorIds.has(id));

  let rows = [];
  if (nonRetainedIds.length) {
    const donorRows = await query(
      `SELECT id, name, last_gift_amount, last_gift_date FROM donors
       WHERE org_id = ? AND deleted_at IS NULL AND id IN (${nonRetainedIds.map(() => "?").join(",")})`,
      [orgId, ...nonRetainedIds]
    );
    rows = donorRows
      .sort((a, b) => new Date(b.last_gift_date || 0) - new Date(a.last_gift_date || 0))
      .slice(0, PAGE_SIZE)
      .map(d => ({
        donorId: d.id,
        donorName: d.name,
        lastGiftAmount: Number(d.last_gift_amount) || 0,
        lastGiftDate: d.last_gift_date,
      }));
  }

  res.json({
    retentionRate: retention.retentionRate,
    thinData: retention.thinData, historyDays: retention.historyDays, floor: retention.floor,
    retained: retention.retained, prevYearCount: retention.prevYearCount,
    year: retention.year, prevYear: retention.prevYear,
    nonRetainedCount: nonRetainedIds.length, rows,
  });
}));

