app.get("/campaigns/:id/progress", requireAuth, wrap(async (req, res) => {
  const rows = await query("SELECT * FROM campaigns WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!rows.length) return res.status(404).json({ error: "Campaign not found" });
  const c = rows[0];
  // Same raised definition as fundraisingCampaignRows (one definition):
  // gift payments net of donor-covered fees + awarded grants; open pledges
  // are a SEPARATE pledged figure, never summed into raised.
  const [giftSum, pledgeSum, grantSum] = await Promise.all([
    query(
      `SELECT COALESCE(SUM(amount - COALESCE(cover_fee_amount,0)),0) as total, COUNT(DISTINCT donor_id) as donor_count FROM gifts WHERE org_id=? AND (campaign=? OR campaign_id=?)`,
      [req.user.orgId, c.name, c.id]
    ),
    // F-5: pledged = honest REMAINING balance (amount − payments already
    // linked via gifts.pledge_id), so a partially-paid pledge counts only
    // what is still committed-but-unpaid.
    query(
      `SELECT COALESCE(SUM(p.amount - COALESCE(pp.paid,0)),0) AS total
       FROM pledges p
       LEFT JOIN (SELECT pledge_id, SUM(amount) AS paid FROM gifts WHERE org_id=? AND pledge_id IS NOT NULL GROUP BY pledge_id) pp ON pp.pledge_id=p.id
       WHERE p.org_id=? AND p.campaign_id=? AND p.status='open'`,
      [req.user.orgId, req.user.orgId, c.id]),
    query(`SELECT COALESCE(SUM(amount),0) AS total FROM grants WHERE org_id=? AND campaign_id=? AND awarded_at IS NOT NULL`, [req.user.orgId, c.id]),
  ]);
  const grantAwarded = parseFloat(grantSum[0]?.total || 0);
  const raised = parseFloat(giftSum[0]?.total || 0) + grantAwarded;
  const donorCount = parseInt(giftSum[0]?.donor_count || 0);
  const daysRemaining = c.end_date ? Math.ceil((new Date(c.end_date) - new Date()) / 86400000) : null;
  res.json({
    goal: parseFloat(c.goal_amount || 0),
    raised,
    grantAwarded,
    pledged: parseFloat(pledgeSum[0]?.total || 0),
    donorCount,
    daysRemaining,
    startDate: c.start_date,
    endDate: c.end_date,
    briefing: c.briefing || "",
  });
}));

// ── Fundraising (BUILD-11) ──────────────────────────────────────────────────
// The Fundraising tab is a home over primitives that already exist: org-level
// goals (fundraising_goals), campaigns that carry a goal (campaigns.goal_amount),
// and giving pages. Nothing here stores a "raised" total — every figure is a
// live SUM over gifts, so a thermometer can never drift from reality. A
// "fundraising campaign" is simply a campaigns row with goal_amount set; the
// email lifecycle (campaigns.status) is untouched — fundraising lifecycle is
// derived from the campaign's dates instead.
//
// computeFundraisingPace: shared pace/thermometer math. Degrades gracefully —
// no goal → no thermometer (percent null); no dates → progress with no
// "days left"/pace; goal met → celebratory state. Never invents a number.
function computeFundraisingPace(raised, goal, startDate, endDate) {
  const g = parseFloat(goal) || 0;
  const r = parseFloat(raised) || 0;
  // `percent` stays capped at 100 (thermometer bar width). `rawPercent` is the
  // true, UNCAPPED figure so the UI can honestly say "302% · $50k over" instead
  // of a misleading flat 100% when a goal is exceeded. `over` = dollars past goal.
  const percent = g > 0 ? Math.min(100, Math.round((r / g) * 100)) : null;
  const rawPercent = g > 0 ? Math.round((r / g) * 100) : null;
  const over = g > 0 && r > g ? r - g : 0;
  const now = new Date();
  let daysLeft = null, lifecycle = "active";
  if (startDate && new Date(startDate) > now) lifecycle = "upcoming";
  if (endDate) {
    daysLeft = Math.ceil((new Date(endDate) - now) / 86400000);
    if (daysLeft < 0) { lifecycle = "ended"; daysLeft = 0; }
  }
  // ── FIX-7 Part 5 · PACE IS ONE FUNCTION, AND IT SAYS WHY ────────────────
  // shared/pace.js owns the definition (raised share against the share of the
  // campaign's OWN window that has gone) and the ten-point band. This used to
  // be a 2%-of-expected-dollars test living here, and a separate 8-point test
  // living in Dashboard.jsx, which is how two screens said different things
  // about the same money. No start or no deadline: no pace at all — the caller
  // shows raised against goal, which is the honest thing to show.
  let paceState = null, expected = null, paceSentence = null, paceRaisedPct = null, paceElapsedPct = null;
  const p = PACE && PACE.paceOf({ raised: r, goal: g, start: startDate, end: endDate, today: now.toISOString().slice(0, 10) });
  if (p) {
    paceState = p.state === "on_pace" ? "on_track" : p.state;   // the wire word the screens already read
    paceSentence = p.sentence;
    paceRaisedPct = p.raisedPct;
    paceElapsedPct = p.elapsedPct;
    const total = new Date(endDate) - new Date(startDate);
    const elapsed = Math.max(0, Math.min(total, now - new Date(startDate)));
    expected = total > 0 ? g * (elapsed / total) : null;
  } else if (g > 0 && r >= g) {
    paceState = "met";
  }
  // FIX-34: "On pace" beside "$0 of $25,000, 0%" said two things. Nothing
  // counted yet is never on pace; the bar says $0 and no badge rides it.
  if (r <= 0 && (paceState === "on_track" || paceState === "ahead")) { paceState = null; paceSentence = null; }
  return { percent, rawPercent, over, daysLeft, lifecycle, paceState, expected,
           paceSentence, paceRaisedPct, paceElapsedPct };
}

// Live totals for a set of campaigns, matched the same way
// /campaigns/:id/progress matches: campaign_id OR the legacy campaign-name text
// column. One query per component, grouped, so the list view never N+1s.
//
// Attribution completeness (FIX, 2026-08-04) — what "raised" MEANS here:
//   raised = giftRaised + grantAwarded
//   · giftRaised   = Σ attributed gift PAYMENTS RECEIVED, net of any donor-
//     covered fee portion (amount − cover_fee_amount): goal progress counts
//     what the donor intended for the mission; the charged total stays in
//     Reports/Finance/receipts.
//   · grantAwarded = Σ attributed grants' amounts once AWARDED (awarded_at
//     set) — a real capital campaign counts foundation money toward its
//     target. If grant money ALSO arrives as a gift from the foundation
//     donor, attribute ONE of the two, never both (documented, surfaced in
//     the grant UI helper text).
//   · pledged      = Σ attributed OPEN pledges — committed-but-unpaid, a
//     SEPARATE figure. NEVER summed into raised: a pledge's payments arrive
//     as gifts (which inherit the pledge's campaign), so pledge+payments in
//     one number would double-count and a treasurer would catch it.
async function fundraisingCampaignRows(orgId) {
  await PACE_READY;
  const campaigns = await query(
    `SELECT id, name, goal_amount, start_date, end_date, status, type, goal_category, parent_goal_id, created_at,
            donor_facing_name, donor_description, donor_story, hero_image_url, hero_crop, hero_focal_x, hero_focal_y, goal_progress_public
     FROM campaigns WHERE org_id = ? AND goal_amount IS NOT NULL AND goal_amount > 0
     ORDER BY created_at DESC`,
    [orgId]
  );
  if (!campaigns.length) return [];
  const [sums, pledgeSums, grantSums] = await Promise.all([
    query(
      `SELECT c.id AS cid,
              COALESCE(SUM(g.amount - COALESCE(g.cover_fee_amount, 0)), 0) AS raised,
              COUNT(DISTINCT g.donor_id) AS donor_count
         FROM campaigns c
         LEFT JOIN gifts g ON g.org_id = c.org_id AND (g.campaign_id = c.id OR g.campaign = c.name)
        WHERE c.org_id = ? AND c.goal_amount IS NOT NULL AND c.goal_amount > 0
        GROUP BY c.id`,
      [orgId]
    ),
    query(
      `SELECT p.campaign_id AS cid,
              COALESCE(SUM(GREATEST(p.amount - COALESCE(pp.paid,0), 0)), 0) AS pledged,
              COUNT(*) AS pledge_count
         FROM pledges p
         LEFT JOIN (SELECT pledge_id, SUM(amount) AS paid FROM gifts WHERE org_id = ? AND pledge_id IS NOT NULL GROUP BY pledge_id) pp ON pp.pledge_id = p.id
        WHERE p.org_id = ? AND p.campaign_id IS NOT NULL AND p.status = 'open'
        GROUP BY p.campaign_id`,
      [orgId, orgId]
    ),
    query(
      `SELECT campaign_id AS cid, COALESCE(SUM(amount), 0) AS grant_awarded, COUNT(*) AS grant_count
         FROM grants WHERE org_id = ? AND campaign_id IS NOT NULL AND awarded_at IS NOT NULL
        GROUP BY campaign_id`,
      [orgId]
    ),
  ]);
  const byId = Object.fromEntries(sums.map(s => [s.cid, s]));
  const pledgeById = Object.fromEntries(pledgeSums.map(s => [s.cid, s]));
  const grantById = Object.fromEntries(grantSums.map(s => [s.cid, s]));
  return campaigns.map(c => {
    const s = byId[c.id] || {};
    const giftRaised = parseFloat(s.raised) || 0;
    const grantAwarded = parseFloat(grantById[c.id]?.grant_awarded) || 0;
    const raised = giftRaised + grantAwarded;
    const pledged = parseFloat(pledgeById[c.id]?.pledged) || 0;
    const pace = computeFundraisingPace(raised, c.goal_amount, c.start_date, c.end_date);
    return {
      id: c.id,
      name: c.name,
      goalAmount: parseFloat(c.goal_amount) || 0,
      raised,
      giftRaised,
      grantAwarded,
      grantCount: parseInt(grantById[c.id]?.grant_count, 10) || 0,
      pledged,
      pledgeCount: parseInt(pledgeById[c.id]?.pledge_count, 10) || 0,
      donorCount: parseInt(s.donor_count, 10) || 0,
      startDate: c.start_date,
      endDate: c.end_date,
      type: c.type,
      goalCategory: GOAL_CATEGORIES.includes(c.goal_category) ? c.goal_category : "project",
      parentGoalId: c.parent_goal_id || null,
      // BUILD-54 §2 — donor-facing content (org-authored; the CRM edit form
      // round-trips these; donor surfaces read them via the portal payloads).
      donorFacingName: c.donor_facing_name || null,
      donorDescription: c.donor_description || null,
      donorStory: Array.isArray(c.donor_story) ? c.donor_story : null,
      heroImageUrl: c.hero_image_url || null,
      heroCrop: parseCrop(c.hero_crop),
      heroFocal: { x: Math.min(1, Math.max(0, Number(c.hero_focal_x ?? 0.5) || 0.5)), y: Math.min(1, Math.max(0, Number(c.hero_focal_y ?? 0.5) || 0.5)) },
      goalProgressPublic: c.goal_progress_public === true,
      ...pace,
    };
  });
}

// BUILD-16 Part 2 — typed, multiple, roll-up goals. A "goal" is a goal'd
// campaign; several run at once, each with its own category (annual/project/
// capital). An overarching goal is a campaign that other campaigns name as
// their parent_goal_id — its progress rolls up its children's live raised. The
// roll-up is a live SUM over the same gift rows (never a stored counter), so it
// can't drift. Returns the goal portfolio + an org-wide roll-up header figure.
const GOAL_CATEGORIES = ["annual", "project", "capital"];
function fundraisingGoalsPortfolio(rows) {
  // rows = fundraisingCampaignRows output.
  // Child raised/goal rolled up onto each parent.
  const childrenByParent = {};
  for (const r of rows) {
    if (r.parentGoalId) (childrenByParent[r.parentGoalId] = childrenByParent[r.parentGoalId] || []).push(r);
  }
  const goals = rows.map(r => {
    const kids = childrenByParent[r.id] || [];
    const isOverarching = kids.length > 0;
    const childRaised = kids.reduce((s, k) => s + k.raised, 0);
    const childGoal = kids.reduce((s, k) => s + k.goalAmount, 0);
    // An overarching goal shows its children's combined progress toward its own
    // target (the roll-up); a leaf goal shows its own SUM(gifts).
    const rolledRaised = isOverarching ? childRaised : r.raised;
    const rolled = isOverarching ? computeFundraisingPace(childRaised, r.goalAmount, r.startDate, r.endDate) : null;
    return {
      ...r,
      isOverarching,
      childCount: kids.length,
      childRaised, childGoal,
      childIds: kids.map(k => k.id),
      // Pledged rolls up alongside raised but stays a SEPARATE figure —
      // committed-but-unpaid is never summed into a raised number.
      rolledPledged: (r.pledged || 0) + kids.reduce((s, k) => s + (k.pledged || 0), 0),
      rolledRaised,
      rolledPercent: isOverarching ? rolled.percent : r.percent,
      rolledRawPercent: isOverarching ? rolled.rawPercent : r.rawPercent,
      rolledOver: isOverarching ? rolled.over : r.over,
      rolledPaceState: isOverarching ? rolled.paceState : r.paceState,
      rolledPaceSentence: isOverarching ? rolled.paceSentence : r.paceSentence,
      // FIX-27 Part 1: every figure on a campaign card and page opens its rows
      // (figureSources.js), so the list and the page foot to the same rows.
      sources: {
        raised: { key: isOverarching ? "goal-rollup-raised" : "goal-raised", params: { campaign: r.id } },
        goal: { key: "campaign-goal", params: { campaign: r.id } },
        percent: { key: isOverarching ? "goal-rollup-progress" : "goal-progress", params: { campaign: r.id } },
        donors: { key: "campaign-donors", params: { campaign: r.id } },
        pledged: { key: "pledges-open", params: { campaign: r.id } },
        grants: { key: "campaign-grants", params: { campaign: r.id } },
      },
    };
  });
  // Org roll-up header: total raised vs total goal across ACTIVE top-level goals
  // only (a child's raised is already inside its parent's roll-up — counting
  // both would double-count). Top-level = has no parent_goal_id; active = not
  // ended. Computed over the ENRICHED goals (so rolledRaised is present).
  const topActive = goals.filter(g => !g.parentGoalId && g.lifecycle !== "ended");
  const totalGoal = topActive.reduce((s, g) => s + g.goalAmount, 0);
  const totalRaised = topActive.reduce((s, g) => s + g.rolledRaised, 0);
  const rollup = topActive.length ? {
    totalRaised, totalGoal,
    percent: totalGoal > 0 ? Math.min(100, Math.round((totalRaised / totalGoal) * 100)) : null,
    rawPercent: totalGoal > 0 ? Math.round((totalRaised / totalGoal) * 100) : null,
    over: totalGoal > 0 && totalRaised > totalGoal ? totalRaised - totalGoal : 0,
    activeGoalCount: topActive.length,
  } : null;
  return { goals: goals.map(g => ({ ...g, isTopLevel: !g.parentGoalId })), rollup };
}

// Overview — the money-moving command view. Everything the Fundraising home
// needs in one call: the active org goal with pace, this-period momentum vs
// the prior period (same FY/calendar basis as Finance — one source of truth),
// campaign + giving-page rollups, and recent real gifts.
app.get("/fundraising/overview", requireAuth, wrap(async (req, res) => {
  await PACE_READY;
  await FISCAL_READY;   // FIX-10 Part B — the period label is the shared one, not a race
  const { orgId } = req.user;
  const yearMode = req.query.yearMode === "calendar" ? "calendar" : "fiscal";
  const _fpTz = await orgTz(orgId);   // ORG_TZ_SEAM_OK
  const cur = finPeriodBounds(yearMode, 0, _fpTz);
  const prior = finPeriodBounds(yearMode, -1, _fpTz);
  const today = orgToday(_fpTz);   // ORG_TZ_SEAM_OK (FIX-14 Part 2b)
  // BUILD-32 Part 3 — the Home hero's "this week's giving" figure. A true
  // Monday-based calendar week (weekBounds), independent of the fiscal/calendar
  // period above, so the hero shows a number that genuinely moves week to week.
  const wk = weekBounds(0, await orgTz(orgId));   // ORG_TZ_SEAM_OK

  // FIX-10 Part B — A ZERO THAT EXPLAINS ITSELF. Fundraising opened on
  // "$0 RAISED · FY 2026–27" to an org that had imported $19,750 the hour
  // before, because the fiscal year had turned in July and every imported
  // gift was dated before it. Finance already handles exactly this ("$19,750
  // of imported giving across 23 gifts isn't in this ledger…") and this is
  // that pattern, on Fundraising: the last twelve months, beside the empty
  // year, each opening its own rows. Same JOIN and deleted_at predicate as
  // the period query above, so both figures foot to Reports.
  const l12Start = orgTime.addDays(orgToday(_fpTz), -364);
  const l12End = orgToday(_fpTz);
  const [goalRows, curRows, priorRows, weekRows, recentGifts, campaigns, givingPages, l12Rows, anyGiftRows] = await Promise.all([
    query(
      "SELECT * FROM fundraising_goals WHERE org_id = ? AND period_start <= ? AND period_end >= ? ORDER BY created_at DESC LIMIT 1",
      [orgId, today, today]
    ),
    // BUILD-33: period totals exclude soft-deleted (trashed) donors' gifts —
    // same JOIN + deleted_at IS NULL predicate as Reports' giving-summary, so
    // Fundraising and Reports report the SAME period number (the BUILD-23
    // cross-surface invariant). Trashing a donor hides them from Reports; the
    // Fundraising header must not keep counting them.
    query("SELECT COALESCE(SUM(g.amount),0) AS total, COUNT(*) AS gifts, COUNT(DISTINCT g.donor_id) AS donors FROM gifts g JOIN donors d ON d.id = g.donor_id WHERE g.org_id = ? AND d.deleted_at IS NULL AND g.date >= ? AND g.date <= ?", [orgId, cur.start, cur.end]),
    query("SELECT COALESCE(SUM(g.amount),0) AS total FROM gifts g JOIN donors d ON d.id = g.donor_id WHERE g.org_id = ? AND d.deleted_at IS NULL AND g.date >= ? AND g.date <= ?", [orgId, prior.start, prior.end]),
    query("SELECT COALESCE(SUM(g.amount),0) AS total, COUNT(*) AS gifts FROM gifts g JOIN donors d ON d.id = g.donor_id WHERE g.org_id = ? AND d.deleted_at IS NULL AND g.date >= ? AND g.date <= ?", [orgId, wk.start, wk.end]),
    query(
      `SELECT g.id, g.amount, g.date, g.stripe_payment_id, g.campaign, g.donor_id, d.name AS donor_name
         FROM gifts g LEFT JOIN donors d ON d.id = g.donor_id
        WHERE g.org_id = ? AND d.deleted_at IS NULL ORDER BY g.date DESC, g.id DESC LIMIT 8`,
      [orgId]
    ),
    fundraisingCampaignRows(orgId),
    query(
      `SELECT gp.id, gp.title, gp.slug, gp.goal_amount, gp.status,
              COALESCE((SELECT SUM(amount - COALESCE(cover_fee_amount,0)) FROM gifts WHERE giving_page_id = gp.id), 0) AS raised
         FROM giving_pages gp WHERE gp.org_id = ? ORDER BY gp.created_at DESC`,
      [orgId]
    ),
    query("SELECT COALESCE(SUM(g.amount),0) AS total, COUNT(*) AS gifts, COUNT(DISTINCT g.donor_id) AS donors FROM gifts g JOIN donors d ON d.id = g.donor_id WHERE g.org_id = ? AND d.deleted_at IS NULL AND g.date >= ? AND g.date <= ?", [orgId, l12Start, l12End]),
    query("SELECT COALESCE(SUM(g.amount),0) AS total, COUNT(*) AS gifts FROM gifts g JOIN donors d ON d.id = g.donor_id WHERE g.org_id = ? AND d.deleted_at IS NULL", [orgId]),
  ]);

  // Active org goal with pace (reuses the goal-progress math shape).
  let goal = null;
  if (goalRows.length) {
    const gr = goalRows[0];
    const goalAmount = parseFloat(gr.goal_amount) || 0;
    let currentAmount = 0;
    if (gr.goal_type === "lapsed_recovery") {
      const r2 = await query(
        `SELECT COALESCE(SUM(g.amount),0) AS total FROM gifts g JOIN donors d ON d.id = g.donor_id
          WHERE g.org_id = ? AND g.date >= ? AND g.date <= ? AND g.date = d.last_gift_date
            AND (SELECT MAX(g2.date) FROM gifts g2 WHERE g2.donor_id = d.id AND g2.date < g.date) IS NOT NULL
            AND g.date::date - (SELECT MAX(g2.date) FROM gifts g2 WHERE g2.donor_id = d.id AND g2.date < g.date)::date > 365`,
        [orgId, gr.period_start, gr.period_end]
      );
      currentAmount = parseFloat(r2[0]?.total) || 0;
    } else {
      // FIX-34 · ONE RAISED FIGURE. The goal bar summed its own window (the
      // 90 days onboarding proposed) with its own query, and read "$0 of
      // $25,000" directly above "Raised FY 2026-27 $119,737.03". With no
      // campaign, a raised-money goal counts the same gifts as the Raised card:
      // the same rows, the same total (curRows, computed once), and says so.
      currentAmount = parseFloat(curRows[0]?.total) || 0;
    }
    const totalRaised = gr.goal_type !== "lapsed_recovery";
    const pStart = totalRaised ? cur.start : gr.period_start, pEnd = totalRaised ? cur.end : gr.period_end;
    const pace = computeFundraisingPace(currentAmount, goalAmount, pStart, pEnd);
    // A label that is only the amount again ("25,000") is not a name.
    const label = /^[\s$£€\d,.]*$/.test(String(gr.label || "")) ? null : gr.label;
    goal = {
      id: gr.id, label, goalType: gr.goal_type, goalAmount, currentAmount,
      periodStart: pStart, periodEnd: pEnd, source: "goal", ...pace,
      ...(totalRaised ? { sourceNote: `Counts every gift dated in ${cur.chartLabel}, the same gifts as Raised below.` } : {}),
    };
  }

  // ── BUILD-88a A.3 — FINANCE FEEDS FUNDRAISING ─────────────────────────────
  // An org that budgets $200,000 of contributions for the year HAS a $200,000
  // fundraising goal. It was typing that number twice — once into Finance and
  // once into a fundraising goal — which is how two screens come to disagree
  // about the same commitment. With no goal of its own set, the card reads the
  // year's CONTRIBUTIONS BUDGET, says where the figure came from, and moves the
  // moment an admin edits the budget. An explicit goal still wins: a goal
  // somebody set on purpose outranks one Steward inferred.
  if (!goal) {
    const fyLabel = Number(String(cur.end).slice(0, 4));
    const [bud] = await query(
      `SELECT COALESCE(SUM(b.amount),0) AS v FROM budgets b
         JOIN accounts a ON a.id = b.account_id AND a.org_id = b.org_id
        WHERE b.org_id = ? AND b.year = ? AND a.type = 'revenue' AND a.subtype = 'contributions'`,
      [orgId, yearMode === "fiscal" ? fyLabel : Number(String(cur.start).slice(0, 4))]);
    const budgeted = parseFloat(bud?.v) || 0;
    if (budgeted > 0) {
      const pace = computeFundraisingPace((parseFloat(curRows[0]?.total) || 0), budgeted, cur.start, cur.end);
      goal = {
        id: null, label: `Contributions budget, ${yearMode === "fiscal" ? `FY${fyLabel}` : fyLabel}`,
        goalType: "budget", goalAmount: budgeted, currentAmount: (parseFloat(curRows[0]?.total) || 0),
        periodStart: cur.start, periodEnd: cur.end, source: "budget",
        sourceNote: "From your Finance budget for contributions this year. Set a fundraising goal to use a different number.",
        ...pace,
      };
    }
  }

  const periodTotal = parseFloat(curRows[0]?.total) || 0;
  const priorTotal = parseFloat(priorRows[0]?.total) || 0;
  const activePages = givingPages.filter(p => p.status === "active");

  // BUILD-16 Part 2 — the goal portfolio + roll-up header replaces the single
  // org goal as the Fundraising Overview centerpiece.
  const portfolio = fundraisingGoalsPortfolio(campaigns);

  res.json({
    yearMode,
    periodLabel: cur.chartLabel,
    goal,
    rollup: portfolio.rollup,
    goals: portfolio.goals,
    period: {
      raised: periodTotal,
      giftCount: parseInt(curRows[0]?.gifts, 10) || 0,
      donorCount: parseInt(curRows[0]?.donors, 10) || 0,
      priorRaised: priorTotal,
      delta: periodTotal - priorTotal,
      // FIX-10 Part B — the bounds this figure was summed over, so the tile can
      // open EXACTLY the rows it claims instead of a whole-Reports link.
      start: cur.start,
      end: cur.end,
    },
    // FIX-10 Part B — the last twelve months, and whether this org has any
    // giving at all. `emptyYearWithHistory` is the single condition the client
    // reads: the fiscal year has no gifts AND the file is not empty, which is
    // the only case where "$0 raised" is true and useless at the same time.
    last12: {
      raised: parseFloat(l12Rows[0]?.total) || 0,
      giftCount: parseInt(l12Rows[0]?.gifts, 10) || 0,
      donorCount: parseInt(l12Rows[0]?.donors, 10) || 0,
      start: l12Start,
      end: l12End,
    },
    allTime: {
      raised: parseFloat(anyGiftRows[0]?.total) || 0,
      giftCount: parseInt(anyGiftRows[0]?.gifts, 10) || 0,
    },
    emptyYearWithHistory: periodTotal === 0 && (parseInt(anyGiftRows[0]?.gifts, 10) || 0) > 0,
    thisWeek: {
      raised: parseFloat(weekRows[0]?.total) || 0,
      giftCount: parseInt(weekRows[0]?.gifts, 10) || 0,
      // Week bounds exposed so the Home hero's "This week" chip can deep-link
      // to a gifts view filtered to EXACTLY this window (the chip's number and
      // its destination must agree — count-matches-destination rule).
      start: wk.start,
      end: wk.end,
    },
    campaigns: {
      count: campaigns.length,
      activeCount: campaigns.filter(c => c.lifecycle === "active").length,
      raised: campaigns.reduce((s, c) => s + c.raised, 0),
      top: campaigns.slice().sort((a, b) => b.raised - a.raised)[0] || null,
    },
    givingPages: {
      count: activePages.length,
      raised: activePages.reduce((s, p) => s + (parseFloat(p.raised) || 0), 0),
      pages: activePages.map(p => ({ id: p.id, title: p.title, slug: p.slug, goalAmount: p.goal_amount != null ? parseFloat(p.goal_amount) : null, raised: parseFloat(p.raised) || 0 })),
    },
    recentGifts: recentGifts.map(g => ({
      id: g.id, amount: parseFloat(g.amount) || 0, date: g.date,
      source: g.stripe_payment_id ? "online" : "offline", campaign: g.campaign || null,
      donorId: g.donor_id || null,
      donorName: g.donor_name || "Anonymous",
    })),
  });
}));

app.get("/fundraising/campaigns", requireAuth, wrap(async (req, res) => {
  res.json(await fundraisingCampaignRows(req.user.orgId));
}));

// BUILD-16 Part 2 — the typed goal portfolio + org roll-up header.
app.get("/fundraising/goals", requireAuth, wrap(async (req, res) => {
  const rows = await fundraisingCampaignRows(req.user.orgId);
  res.json(fundraisingGoalsPortfolio(rows));
}));

// BUILD-54 §2 — the donor-facing fields ride the SAME create/edit routes the
// CRM campaign form uses (setup happens where the campaign is created — no
// separate configuration screen to forget). Shared validator for both routes;
// returns { sets, params } column assignments or { status, body } to reject.
async function parseDonorFacingCampaignFields(b, orgId) {
  const sets = [], params = [];
  if (b.donorFacingName !== undefined) { sets.push("donor_facing_name = ?"); params.push(String(b.donorFacingName || "").trim().slice(0, 120) || null); }
  if (b.donorDescription !== undefined) { sets.push("donor_description = ?"); params.push(String(b.donorDescription || "").trim().slice(0, 600) || null); }
  if (b.donorStory !== undefined) {
    const v = validateStoryBlocks(b.donorStory);
    if (v.error) return { status: 400, body: { error: v.error, message: "The story must be paragraphs, headings, and lists — no HTML or embeds." } };
    sets.push("donor_story = ?"); params.push(v.blocks && v.blocks.length ? JSON.stringify(v.blocks) : null);
  }
  if (b.heroImageData !== undefined) {
    const h = await storeCampaignHero(orgId, b.heroImageData);
    if (h.error) return { status: 400, body: { error: h.error, message: h.message } };
    if (h.url !== undefined) { sets.push("hero_image_url = ?"); params.push(h.url); }
  }
  // BUILD-65 Part 3 — non-destructive crop + focal for the hero (same library
  // and validation as the banner: parseCrop; a crop wins, focal is the fallback).
  if (b.heroCrop !== undefined) {
    if (b.heroCrop === "" || b.heroCrop == null) { sets.push("hero_crop = NULL"); }
    else {
      const c = parseCrop(b.heroCrop);
      if (!c) return { status: 400, body: { error: "bad_crop", message: "Crop must be a rectangle {x,y,w,h} within the image." } };
      sets.push("hero_crop = ?"); params.push(JSON.stringify(c));
    }
  }
  for (const [key, col] of [["heroFocalX", "hero_focal_x"], ["heroFocalY", "hero_focal_y"]]) {
    if (b[key] === undefined) continue;
    const nn = Number(b[key]);
    if (!Number.isFinite(nn)) return { status: 400, body: { error: "bad_focal", message: "Focal point must be a number between 0 and 1." } };
    sets.push(`${col} = ?`); params.push(Math.min(1, Math.max(0, nn)));
  }
  if (b.goalProgressPublic !== undefined) { sets.push("goal_progress_public = ?"); params.push(b.goalProgressPublic === true); }
  return { sets, params };
}

app.post("/fundraising/campaigns", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { name, goalAmount, startDate, endDate, goalCategory, parentGoalId } = req.body;
  if (!name || !name.trim()) return res.status(400).json({ error: "Name required" });
  const goal = parseFloat(goalAmount);
  if (!Number.isFinite(goal) || goal <= 0) return res.status(400).json({ error: "Goal amount must be a positive number" });
  const category = GOAL_CATEGORIES.includes(goalCategory) ? goalCategory : "project";
  // A parent goal, if given, must be another goal'd campaign in this org.
  let parent = null;
  if (parentGoalId) {
    const p = await query("SELECT id FROM campaigns WHERE id=? AND org_id=? AND goal_amount IS NOT NULL AND goal_amount > 0", [parentGoalId, req.user.orgId]);
    if (!p.length) return res.status(400).json({ error: "parentGoalId must be an existing goal in this org" });
    parent = parentGoalId;
  }
  const df = await parseDonorFacingCampaignFields(req.body, req.user.orgId);
  if (df.status) return res.status(df.status).json(df.body);
  const id = "cmp_" + uuid().slice(0, 8);
  await run(
    `INSERT INTO campaigns (id,org_id,name,type,subject,body,status,segment,goal_amount,start_date,end_date,goal_category,parent_goal_id,recipient_count,open_count,created_by,created_by_name)
     VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,0,0,?,?)`,
    [id, req.user.orgId, name.trim(), "appeal", "", "", "draft", JSON.stringify({}), goal, startDate || null, endDate || null, category, parent, actor(req).id, actor(req).name]
  );
  if (df.sets.length) {
    await run(`UPDATE campaigns SET ${df.sets.join(", ")} WHERE id = ? AND org_id = ?`, [...df.params, id, req.user.orgId]);
  }
  if (req.body.heroImageData !== undefined) {
    const [c] = await query(`SELECT hero_image_url FROM campaigns WHERE id = ?`, [id]);
    await recordAssetPointerHistory(req.user.orgId, "campaign.hero", id, null, c?.hero_image_url || null, req.user);
  }
  const rows = await fundraisingCampaignRows(req.user.orgId);
  res.status(201).json(rows.find(r => r.id === id) || { id });
}));

app.put("/fundraising/campaigns/:id", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { name, goalAmount, startDate, endDate, goalCategory, parentGoalId } = req.body;
  const existing = await query("SELECT id, hero_image_url FROM campaigns WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!existing.length) return res.status(404).json({ error: "Campaign not found" });
  if (goalAmount !== undefined) {
    const goal = parseFloat(goalAmount);
    if (!Number.isFinite(goal) || goal <= 0) return res.status(400).json({ error: "Goal amount must be a positive number" });
  }
  if (goalCategory !== undefined && !GOAL_CATEGORIES.includes(goalCategory)) {
    return res.status(400).json({ error: "goalCategory must be annual, project, or capital" });
  }
  // A goal can't be its own parent, and the parent must exist in this org.
  let parentUpdate = null, parentProvided = parentGoalId !== undefined;
  if (parentProvided && parentGoalId) {
    if (parentGoalId === req.params.id) return res.status(400).json({ error: "A goal cannot be its own parent" });
    const p = await query("SELECT id FROM campaigns WHERE id=? AND org_id=? AND goal_amount IS NOT NULL AND goal_amount > 0", [parentGoalId, req.user.orgId]);
    if (!p.length) return res.status(400).json({ error: "parentGoalId must be an existing goal in this org" });
    parentUpdate = parentGoalId;
  }
  const df = await parseDonorFacingCampaignFields(req.body, req.user.orgId);
  if (df.status) return res.status(df.status).json(df.body);
  await run(
    `UPDATE campaigns SET name=COALESCE(?,name), goal_amount=COALESCE(?,goal_amount),
       start_date=?, end_date=?, goal_category=COALESCE(?,goal_category),
       parent_goal_id=CASE WHEN ? THEN ? ELSE parent_goal_id END, updated_at=NOW() WHERE id=? AND org_id=?`,
    [name || null, goalAmount !== undefined ? parseFloat(goalAmount) : null,
     startDate || null, endDate || null, goalCategory || null,
     parentProvided, parentUpdate, req.params.id, req.user.orgId]
  );
  if (df.sets.length) {
    await run(`UPDATE campaigns SET ${df.sets.join(", ")} WHERE id = ? AND org_id = ?`, [...df.params, req.params.id, req.user.orgId]);
    // A replaced/cleared hero leaves no orphaned asset (content addressing —
    // one photo may back several campaigns; reference-counted like impact).
    // BUILD-56: prune = soft delete + a pointer-history row.
    if (req.body.heroImageData !== undefined) {
      await pruneCampaignAssets(req.user.orgId);
      const [c] = await query(`SELECT hero_image_url FROM campaigns WHERE id = ?`, [req.params.id]);
      await recordAssetPointerHistory(req.user.orgId, "campaign.hero", req.params.id,
        existing[0].hero_image_url || null, c?.hero_image_url || null, req.user);
    }
  }
  const rows = await fundraisingCampaignRows(req.user.orgId);
  res.json(rows.find(r => r.id === req.params.id) || { id: req.params.id });
}));

// Segment → recipient list. Shared by the manual send route and the
// scheduled-campaign job (BUILD-06 Phase C) so both resolve audiences
// identically. Note the predicates read d.stage — the DB column — matching
// what the client's SegmentPicker previews (fixed same pass; it read a
// nonexistent d.pipeline_stage and showed 0 for stage segments).
// ── BUILD-97 — AUDIENCES: THE THINGS WITH NAMES ───────────────────────────
// The registry is shared/audiences.js so the rail and the resolver cannot
// disagree about what exists. Loaded through the depositMod() convention
// rather than a top-level .then that assigns a module-scope binding — that
// leaves a window at boot where the list is empty and every audience is
// unknown (the BUILD-95 §5B part 1 lesson).
let _audMod = null;
async function audienceMod() {
  if (!_audMod) _audMod = await import("../shared/audiences.js");
  return _audMod;
}

// ONE donor query, every audience counted off it. See filterBySegment.
async function audienceRoster(orgId) {
  const A = await audienceMod();
  const donors = await query(
    "SELECT * FROM donors WHERE org_id = ? AND email IS NOT NULL AND email != '' AND deleted_at IS NULL",
    [orgId]);
  const saved = await query(
    "SELECT id, name, description, segment, created_at, kind, rules FROM audiences WHERE org_id=? ORDER BY LOWER(name)",
    [orgId]).catch(() => []);
  // PARITY-1 Part D — a Group is offered wherever an audience is, counted by
  // its own members (the live rule or the hand-kept list).
  const groupCounts = new Map();
  for (const r of saved.filter(x => x.kind)) {
    const ids = new Set(await GR.memberIds(orgId, GR.shapeGroup(r)));
    groupCounts.set(r.id, donors.filter(d => ids.has(d.id)).length);
  }

  const builtins = A.BUILT_IN_AUDIENCES.map(a => ({
    id: a.id, name: a.name, description: a.description, kind: "builtin", tone: a.tone,
    mode: a.mode,
    count: filterBySegment(donors, { mode: a.mode }).length,
    // WHERE THESE PEOPLE LIVE. Allie should never have to wonder where her
    // volunteers are kept — an audience names the screen its people are on.
    // FIX-1 D/C — Donors shows donors now, so volunteers live in the
    // Volunteers hub and staff and board under Settings; nobody is on one
    // list any more, so "everyone" names the three places.
    livesOn: a.mode === "everyone" ? { tab: "donors", filter: null, label: "Donors, Volunteers, and Settings for staff and board" }
           : a.mode === "donors" ? { tab: "donors", filter: "donor", label: "Donors" }
           : a.mode === "volunteers" ? { tab: "volunteers", filter: null, label: "Volunteers" }
           : a.mode === "staff_board" ? { tab: "settings", filter: null, label: "Settings, under Organization" }
           : { tab: "donors", filter: a.mode, label: "Donors, filtered to " + a.name.toLowerCase() },
  }));

  const custom = saved.map(r => {
    const seg = typeof r.segment === "string" ? JSON.parse(r.segment || "{}") : (r.segment || {});
    return {
      id: r.id, name: r.name, description: r.description || "", kind: r.kind ? "group" : "saved", tone: "greenMid",
      groupKind: r.kind || null,
      mode: r.kind ? "audience" : seg.mode, segment: r.kind ? { mode: "audience", audienceId: r.id } : seg, created_at: r.created_at,
      count: r.kind ? groupCounts.get(r.id) : filterBySegment(donors, seg).length,
      livesOn: { tab: "donors", filter: seg.mode, label: "Donors" },
    };
  });

  return {
    audiences: [...builtins, ...custom],
    // The reach line. DISTINCT people, not the sum of the audiences — a
    // volunteer who gives is in two of them and must be one person here.
    reach: donors.length,
  };
}

app.get("/audiences", requireAuth, wrap(async (req, res) => {
  res.json(await audienceRoster(req.user.orgId));
}));

app.post("/audiences", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const A = await audienceMod();
  const v = A.validateAudience(req.body || {});
  if (!v.ok) return res.status(400).json({ error: v.errors[0], errors: v.errors });
  const seg = A.segmentFor({ mode: v.mode, stages: req.body.stages, tiers: req.body.tiers });
  const id = "aud_" + uuid().slice(0, 8);
  try {
    await run(`INSERT INTO audiences (id, org_id, name, description, segment, created_by, created_by_name)
               VALUES (?,?,?,?,?,?,?)`,
      [id, req.user.orgId, v.name, v.description || null, JSON.stringify(seg),
       req.user.userId, req.user.name || req.user.email || null]);
  } catch (err) {
    if (err.code === "23505") return res.status(409).json({ error: "You already have an audience called that." });
    throw err;
  }
  const [row] = await query("SELECT * FROM audiences WHERE id=?", [id]);
  res.status(201).json(row);
}));

app.patch("/audiences/:id", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const A = await audienceMod();
  const [existing] = await query("SELECT * FROM audiences WHERE id=? AND org_id=?",
    [req.params.id, req.user.orgId]);
  if (!existing) return res.status(404).json({ error: "Not found" });
  const prev = typeof existing.segment === "string" ? JSON.parse(existing.segment || "{}") : existing.segment;
  const v = A.validateAudience({
    name: req.body.name !== undefined ? req.body.name : existing.name,
    description: req.body.description !== undefined ? req.body.description : existing.description,
    mode: req.body.mode !== undefined ? req.body.mode : prev.mode,
    stages: req.body.stages !== undefined ? req.body.stages : prev.stages,
    tiers: req.body.tiers !== undefined ? req.body.tiers : prev.tiers,
  });
  if (!v.ok) return res.status(400).json({ error: v.errors[0], errors: v.errors });
  const seg = A.segmentFor({ mode: v.mode,
    stages: req.body.stages !== undefined ? req.body.stages : prev.stages,
    tiers: req.body.tiers !== undefined ? req.body.tiers : prev.tiers });
  try {
    await run("UPDATE audiences SET name=?, description=?, segment=?, updated_at=NOW() WHERE id=? AND org_id=?",
      [v.name, v.description || null, JSON.stringify(seg), req.params.id, req.user.orgId]);
  } catch (err) {
    if (err.code === "23505") return res.status(409).json({ error: "You already have an audience called that." });
    throw err;
  }
  const [row] = await query("SELECT * FROM audiences WHERE id=?", [req.params.id]);
  res.json(row);
}));

app.delete("/audiences/:id", requireAuth, wrap(async (req, res) => {
  const r = await run("DELETE FROM audiences WHERE id=? AND org_id=?", [req.params.id, req.user.orgId]);
  if (!r.changes) return res.status(404).json({ error: "Not found" });
  // A campaign already sent keeps its recipient rows, so history is intact.
  // A DRAFT pointing at this audience now resolves to nobody rather than to
  // everybody — resolveSegmentSpec returns an empty manual list for a missing
  // audience, which is the BUILD-88c rule held at the one place it matters.
  res.json({ deleted: true });
}));

// The hub's single read. One payload so the landing screen is one request
// rather than five that arrive in a different order every time.
// MAIL-1 Part 3: ONE SENTENCE ABOUT WHETHER HER EMAIL GOES, decided by the
// mail policy (mailPolicy.js), never a raw flag. Before the donor file is in:
// "Email turns on once your donor file is in." Once it sends: the From address.
const mailPolicy = require("../mailPolicy");
async function hubMailState(orgId) {
  const [org] = await query("SELECT id, emails_enabled, is_demo_org, onboarded_at FROM orgs WHERE id=?", [orgId]).catch(() => []);
  const d = mailPolicy.orgMailDecision(org || null, mailPolicy.CATEGORY.DONOR);
  if (!d.send) return { sends: false, sentence: mailPolicy.REASON_SENTENCE[d.reason] || "Email is not going out from this organization right now." };
  const ident = await orgSendingIdentity(orgId).catch(() => null);
  return { sends: true, from: ident ? ident.from : null, sentence: ident ? `Your email goes out from ${ident.from}.` : null };
}

app.get("/communications/hub", requireAuth, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [roster, campaigns, seqs] = await Promise.all([
    audienceRoster(orgId),
    query(`SELECT id, name, subject, status, recipient_count, open_count, sent_at, created_at
             FROM campaigns WHERE org_id=? ORDER BY COALESCE(sent_at, created_at) DESC LIMIT 6`, [orgId]),
    query(`SELECT s.id, s.name, s.status,
                  (SELECT COUNT(*) FROM sequence_enrollments e WHERE e.sequence_id=s.id AND e.status='active') AS active
             FROM sequences s WHERE s.org_id=? AND s.trigger <> 'onboarding'
            ORDER BY s.created_at DESC LIMIT 5`, [orgId]).catch(() => []),
  ]);
  const sent = campaigns.filter(c => c.status === "sent");
  const totalSent = sent.reduce((n, c) => n + (c.recipient_count || 0), 0);
  const totalOpen = sent.reduce((n, c) => n + (c.open_count || 0), 0);
  res.json({
    ...roster,
    mail: await hubMailState(orgId),
    campaigns,
    sequences: seqs.map(s => ({ ...s, active: parseInt(s.active, 10) || 0 })),
    stats: {
      totalSent,
      openRate: totalSent > 0 ? Math.round(totalOpen / totalSent * 100) : null,
      activeSequences: seqs.filter(s => s.status === "active").length,
    },
  });
}));

app.post("/campaigns/:id/send", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const campaigns = await query(
    "SELECT * FROM campaigns WHERE id = ? AND org_id = ?",
    [req.params.id, req.user.orgId]
  );
  if (!campaigns.length) return res.status(404).json({ error: "Campaign not found" });
  const campaign = campaigns[0];
  if (campaign.status === "sent") return res.status(400).json({ error: "Campaign already sent" });
  // BUILD-94 Part 4 — NO ADDRESS, NO SEND. Before the recipients are resolved,
  // before anything is marked sending: nothing in bulk leaves without one.
  const addrGate = await bulkSendAddressGate(req.user.orgId);
  if (!addrGate.ok) return res.status(400).json({ error: addrGate.reason, message: addrGate.message });
  // EMAIL-1 — A TEMPLATE CAMPAIGN WITH A HOLE IN IT IS REFUSED WHOLE: a
  // picture with no alt text, a field Steward does not fill, no footer.
  if (campaign.status === "awaiting_approval") {
    return res.status(400).json({ error: "awaiting_approval", message: "This campaign is waiting for approval. Approve it first, then it can go." });
  }
  const pre = await emailCompose.campaignPreflight(campaign, req.user.orgId);
  if (!pre.ok) return res.status(400).json({ error: "email_not_ready", message: pre.message, problems: pre.problems });

  const orgs = await query("SELECT * FROM orgs WHERE id = ?", [req.user.orgId]);
  const org = orgs[0];
  // The send's list is the server's, always: the segment resolved here, never
  // a list from the browser. Each person is then decided by donorMailDecision
  // in the loop (suppressed ones keep a row with their reason), and the count
  // returned is that same decision taken for the whole list (FIX-26).
  const donors = await resolveCampaignRecipients(campaign, req.user.orgId);
  const aud = await campaignAudience(campaign, req.user.orgId);

  // Mark as sending and respond immediately (non-blocking)
  await run("UPDATE campaigns SET status='sending', updated_at=NOW() WHERE id=?", [campaign.id]);
  res.json({ queued: true, recipientCount: aud.orgGate.send ? aud.recipients.length : 0 });

  setImmediate(() => runCampaignSend(campaign, org, donors));
}));

