// markDonorsForGeocoding(orgId, opts) — recompute every affected donor's
// address key and set the status the key implies. A row whose key is unchanged
// AND already `ok` is left alone: that is the caching requirement, enforced in
// SQL rather than trusted to a caller.
//   · no address at all      → 'no_address', coordinates cleared
//   · key changed / new      → 'pending'
//   · key same and 'ok'      → untouched, never looked up twice
// `donorIds` scopes it to one write; omitted, it sweeps the org (used after an
// import, where naming every id would be a 25,000-element array).
async function markDonorsForGeocoding(orgId, { donorIds = null } = {}) {
  const scope = donorIds && donorIds.length ? " AND id = ANY(?)" : "";
  const params = donorIds && donorIds.length ? [orgId, donorIds] : [orgId];
  const rows = await query(
    `SELECT id, address, address2, city, state, zip, country, geocode_key, geocode_status
       FROM donors WHERE org_id = ? AND deleted_at IS NULL${scope}`, params);
  const toPending = [], toNoAddress = [];
  const keyById = new Map();
  for (const d of rows) {
    const key = geocode.addressKey(d);
    if (!key) {
      if (d.geocode_status !== "no_address") toNoAddress.push(d.id);
      continue;
    }
    if (d.geocode_status === "ok" && d.geocode_key === key) continue;   // never twice
    if (d.geocode_status === "pending" && d.geocode_key === key) continue;
    toPending.push(d.id);
    keyById.set(d.id, key);
  }
  const CH = 1000;
  for (let i = 0; i < toNoAddress.length; i += CH)
    await run(`UPDATE donors SET geocode_status='no_address', geocode_key=NULL, latitude=NULL, longitude=NULL,
                 geocoded_at=NOW(), geocode_provider=NULL WHERE org_id=? AND id = ANY(?)`,
              [orgId, toNoAddress.slice(i, i + CH)]);
  for (let i = 0; i < toPending.length; i += CH) {
    const slice = toPending.slice(i, i + CH);
    // One statement per chunk, key per row via an unnested pair list.
    await run(`UPDATE donors SET geocode_status='pending', geocode_key=v.key, latitude=NULL, longitude=NULL
                 FROM (SELECT * FROM UNNEST(?::text[], ?::text[]) AS t(id, key)) AS v
                WHERE donors.id = v.id AND donors.org_id = ?`,
              [slice, slice.map(id => keyById.get(id)), orgId]);
  }
  return { pending: toPending.length, noAddress: toNoAddress.length, scanned: rows.length };
}

// Only the mapped column, and only a string. Anything else is not a URL and
// the row is left alone rather than queued to fail.
function photoImportUrl(d) {
  const v = d && d.photo;
  return typeof v === "string" && v.trim() ? v.trim() : null;
}

// POST /photos/run — drive the queue for the caller's org NOW. The ops/test
// hook, same bar as /geocode/run: admin, org-scoped, and the only way a suite
// gets a deterministic drain without waiting on a tick.
app.post("/photos/run", requireAuth, requireAdmin, wrap(async (req, res) => {
  res.json(await processPhotoQueue({ orgId: req.user.orgId, limit: Math.min(parseInt(req.body?.limit, 10) || PHOTO_FETCH_BUDGET, 1000) }));
}));

// POST /geocode/run — drive the queue for the caller's org NOW. The ops/test
// hook, same bar as POST /nudges/run. {mark:true} re-derives every donor's
// key first (what an import does); {limit} caps the spend.
app.post("/geocode/run", requireAuth, requireAdmin, wrap(async (req, res) => {
  const marked = req.body && req.body.mark ? await markDonorsForGeocoding(req.user.orgId) : null;
  const limit = Math.min(Math.max(parseInt(req.body?.limit, 10) || GEOCODE_TICK_BUDGET, 1), 5000);
  const out = await processGeocodeQueue({ limit, orgId: req.user.orgId });
  res.json({ marked, ...out });
}));

// GET /geocode/status — what the map needs to describe itself in a sentence:
// the counts by status and whether a provider is configured at all. A read
// path, and it makes NO provider call.
app.get("/geocode/status", requireAuth, wrap(async (req, res) => {
  const cfg = geocode.providerConfig();
  const rows = await query(
    `SELECT COALESCE(geocode_status, 'pending') AS s, COUNT(*)::int AS c
       FROM donors WHERE org_id = ? AND deleted_at IS NULL GROUP BY 1`, [req.user.orgId]);
  const counts = Object.fromEntries(geocode.GEOCODE_STATUSES.map(s => [s, 0]));
  for (const r of rows) counts[r.s] = (counts[r.s] || 0) + r.c;
  res.json({ provider: cfg.name, reason: cfg.reason || null, counts,
             total: Object.values(counts).reduce((a, b) => a + b, 0) });
}));

// POST /nudges/run (requireAuth + requireAdmin) — drive the thread nudge for
// the caller's org NOW (ops/test hook, /digests/run-daily's bar). {today?}
// pins the date; the WEEKDAY rule still applies to the pinned date (that is
// how the schedule is testable) unless {force:true}; the wall-clock morning
// window deliberately does not (it would make the hook time-of-day flaky).
app.post("/nudges/run", requireAuth, requireAdmin, wrap(async (req, res) => {
  const [org] = await query("SELECT id, name, legal_name, timezone, receipt_address, thread_nudge_weekends FROM orgs WHERE id=?", [req.user.orgId]);
  if (!org) return res.status(404).json({ error: "Org not found" });
  const today = (req.body && req.body.today) || orgToday(org);   // ORG_TZ_SEAM_OK
  if (!req.body?.force && !threadNudgeDayOk(org, today)) {
    return res.json({ today, skippedWeekend: true, sent: [], skipped: [] });
  }
  const out = await runThreadNudgesForOrg(org, { today, send: !(req.body && req.body.dryRun) });
  res.json({ today, ...out });
}));

// POST /step-reminders/run — the ops/test hook, same bar as POST /nudges/run.
// {today, now} pin the org's date and wall clock so the SCHEDULE is testable;
// {force:true} ignores the delivery window; {dryRun:true} composes only.
app.post("/step-reminders/run", requireAuth, requireAdmin, wrap(async (req, res) => {
  const [org] = await query("SELECT id, name, legal_name, timezone, receipt_address FROM orgs WHERE id=?", [req.user.orgId]);
  if (!org) return res.status(404).json({ error: "Org not found" });
  const clock = orgTime.orgClock(org);                  // ORG_TZ_SEAM_OK
  const today = (req.body && req.body.today) || clock.date;
  const nowHHMM = (req.body && req.body.now)
    || `${String(clock.hour).padStart(2, "0")}:${String(clock.minute).padStart(2, "0")}`;
  const out = await runStepRemindersForOrg(org, {
    today, nowHHMM, force: !!req.body?.force, send: !(req.body && req.body.dryRun) });
  res.json({ today, now: nowHHMM, ...out });
}));

// GET /digests/preview — compose (never send) the caller's current digest, for
// the in-app "Week in Review" view. Scope follows the caller's role/plan.
app.get("/digests/preview", requireAuth, wrap(async (req, res) => {
  const type = req.query.type === "monthly" ? "monthly" : "weekly";
  const orgRows = await query("SELECT id, name, plan, subscription_status FROM orgs WHERE id=?", [req.user.orgId]);
  const org = orgRows[0];
  if (!org) return res.status(404).json({ error: "Org not found" });
  const tier = orgPlanTier(org);
  const [me] = await query("SELECT id, name, role FROM users WHERE id=?", [req.user.userId]);
  // Preview the most-recently-completed period (what actually gets emailed),
  // matching the tick — offset -1.
  if (type === "monthly") {
    // Core: return the caller's own monthly report as a READ-only locked
    // preview (their own gifts/portfolio — a pure read), flagged locked so the
    // client dims it behind LockedFeature instead of a bare 403 card.
    const mo = monthBounds(-1, await orgTz(org.id));   // ORG_TZ_SEAM_OK
    const report = await composeOfficerMonthly(org.id, mo, { id: me.id, name: me.name });
    return res.json({ type, window: mo, report, locked: tier !== "team" });
  }
  const wk = weekBounds(-1, await orgTz(org.id));   // ORG_TZ_SEAM_OK
  const isOfficerScope = tier === "team" && me.role !== "admin";
  const sections = await composeWeekInReview(org.id, wk, isOfficerScope ? me.id : null);
  const teamRollup = isOfficerScope ? (await composeWeekInReview(org.id, wk, null)).totals : null;
  res.json({ type, window: wk, scope: isOfficerScope ? "officer" : "org", tier, sections, teamRollup });
}));

// POST /digests/run — actually reserve + send the caller's org digests now
// (requireAuth + requireAdmin). Drives the same path the tick uses, for ops
// and for the committed test suite. Optional window overrides pin the period
// (so tests can seed a specific week/month); dryRun composes without sending.
app.post("/digests/run", requireAuth, requireAdmin, wrap(async (req, res) => {
  const orgRows = await query("SELECT id, name, plan, subscription_status FROM orgs WHERE id=?", [req.user.orgId]);
  const org = orgRows[0];
  if (!org) return res.status(404).json({ error: "Org not found" });
  const { weekStart, monthStart, type, dryRun } = req.body || {};
  const types = type === "weekly" || type === "monthly" ? [type] : ["weekly", "monthly"];
  // Build windows: explicit override (a Monday / month-start date) or the
  // most-recently-completed period.
  // ORG_TZ_SEAM_OK — an explicit override pins the window to a civil date the
  // caller supplied; otherwise the org's own most-recently-completed period.
  const _tz = await orgTz(org.id);
  const wk = weekStart ? weekBounds(0, _tz, new Date(weekStart + "T12:00:00Z")) : weekBounds(-1, _tz);
  const mo = monthStart ? monthBounds(0, _tz, new Date(monthStart + "T12:00:00Z")) : monthBounds(-1, _tz);
  const result = await runDigestsForOrg(org, { wk, mo, types, send: !dryRun });
  res.json({ windows: { weekly: wk, monthly: mo }, ...result });
}));

// The badge's read of the assessment — minimal, and null unless the donor is
// actually DRIFTING (an excluded/ok/lapsed/not-eligible donor gets no badge
// by construction; the Part 1 exclusion assertions ride on this being the
// only shape any list payload carries).
function driftBadgeField(a) {
  return a && a.state === "drifting"
    ? { state: "drifting", confidence: a.confidence, reason: a.reason }
    : null;
}

// One-page printable/mailable "Impact Summary" for a single donor — cumulative
// giving, milestones reached, and org-configured impact translations. Reuses
// the pdfkit pattern from POST /reports/board (same require, buffer-to-Promise
// approach, page-footer loop) rather than a new rendering system.
app.get("/donors/:id/impact-summary/pdf", requireAuth, wrap(async (req, res) => {
  let PDFDocument;
  try {
    PDFDocument = require("pdfkit");
  } catch (e) {
    return res.status(500).json({ error: "pdfkit module missing: " + e.message });
  }

  const { orgId } = req.user;
  const [donor] = await query("SELECT * FROM donors WHERE id = ? AND org_id = ? AND deleted_at IS NULL", [req.params.id, orgId]);
  if (!donor) return res.status(404).json({ error: "Donor not found" });
  // BUILD-64: a donor-facing document (printable/mailable) — carries the org's
  // OWN identity from the shared resolver, never a hardcoded Steward-green band
  // and never the staff-side "(Demo)" name (white-label).
  const brand = await resolveOrgBrandTheme(orgId).catch(() => null);
  const org = { name: brand ? brand.displayName : "" };

  const totalGiving = Number(donor.total_giving) || 0;
  const giftCount = Number(donor.gift_count) || 0;
  const now = new Date();

  const thresholdsReached = MILESTONE_THRESHOLDS.filter(t => totalGiving >= t).sort((a, b) => a - b);

  let yearsGiving = null;
  let firstGiftLabel = null;
  if (donor.first_gift_date) {
    const first = new Date(donor.first_gift_date);
    if (!isNaN(first.getTime())) {
      yearsGiving = now.getFullYear() - first.getFullYear() - ((now.getMonth() < first.getMonth() || (now.getMonth() === first.getMonth() && now.getDate() < first.getDate())) ? 1 : 0);
      firstGiftLabel = first.toLocaleDateString("en-US", { month: "long", year: "numeric" });
    }
  }

  const metricRows = await query(
    "SELECT * FROM impact_metrics WHERE org_id = ? AND active = true AND dollar_threshold <= ? ORDER BY dollar_threshold ASC",
    [orgId, totalGiving]
  );
  const impactLines = metricRows.map(m => {
    const n = Math.max(1, Math.floor(totalGiving / Number(m.dollar_threshold)));
    return String(m.outcome_template || "")
      .replace(/\{amount\}/g, totalGiving.toLocaleString())
      .replace(/\{n\}/g, n);
  });

  const recentGifts = await query(
    "SELECT amount, date, campaign FROM gifts WHERE donor_id = ? AND org_id = ? ORDER BY date DESC LIMIT 5",
    [donor.id, orgId]
  );

  const doc = new PDFDocument({ margin: 50, size: "LETTER", bufferPages: true });
  const pdfBuffer = await new Promise((resolve, reject) => {
    const chunks = [];
    doc.on("data", c => chunks.push(c));
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);

    // BUILD-64: header band + accent = the org's OWN theme (shared resolver);
    // GREEN stays only as the money-figure color (money = green semantics, same
    // as the receipt PDF), never the band.
    const BAND   = brand ? brand.band : "#1a6b4a";
    const BANDFG = brand ? brand.bandFg : "#ffffff";
    const BANDSUB = BANDFG === "#ffffff" ? "#ffffffcc" : "#0f1a12aa";
    const GREEN = "#1a6b4a";
    const INK   = "#1a1a1a";
    const INK3  = "#6b7280";
    const BG    = "#f5f5f0";
    const PW    = doc.page.width;
    const fmtD  = n => "$" + (parseFloat(n) || 0).toLocaleString("en-US", { maximumFractionDigits: 0 });
    const genDate = now.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });

    doc.rect(0, 0, PW, 96).fill(BAND);
    doc.font("Helvetica").fontSize(9).fillColor(BANDSUB).text("I M P A C T   S U M M A R Y", 50, 22);
    doc.font("Helvetica-Bold").fontSize(24).fillColor(BANDFG).text(donor.name || "Valued Donor", 50, 38);
    doc.font("Helvetica").fontSize(10).fillColor(BANDSUB).text(org.name, 50, 70);

    let y = 128;
    doc.font("Helvetica-Bold").fontSize(12).fillColor(INK).text("Giving Summary", 50, y); y += 20;
    const boxes = [
      ["Total Given", fmtD(totalGiving)],
      ["Gifts Given", String(giftCount)],
      ["Donor Since", firstGiftLabel || "—"],
      ["Years Giving", yearsGiving != null ? String(Math.max(yearsGiving, 0)) : "—"],
    ];
    const bw = (PW - 100) / boxes.length;
    boxes.forEach(([label, value], i) => {
      const x = 50 + i * bw;
      doc.rect(x, y, bw - 8, 56).fill(BG);
      doc.font("Helvetica").fontSize(7).fillColor(INK3).text(label.toUpperCase(), x + 10, y + 10, { width: bw - 26 });
      doc.font("Helvetica-Bold").fontSize(15).fillColor(GREEN).text(value, x + 10, y + 26, { width: bw - 26 });
    });
    y += 76;

    doc.font("Helvetica-Bold").fontSize(12).fillColor(INK).text("Milestones Reached", 50, y); y += 18;
    const milestoneLabels = [
      ...thresholdsReached.map(t => `Crossed $${t.toLocaleString()} in lifetime giving`),
      ...(yearsGiving != null && yearsGiving >= 1 ? [`${yearsGiving} year${yearsGiving === 1 ? "" : "s"} of continuous giving`] : []),
    ];
    if (milestoneLabels.length === 0) {
      doc.font("Helvetica").fontSize(10).fillColor(INK3).text("No milestones reached yet.", 50, y); y = doc.y + 10;
    } else {
      milestoneLabels.forEach(label => {
        doc.font("Helvetica").fontSize(10).fillColor(INK).text("•  " + label, 50, y, { width: PW - 100 });
        y = doc.y + 4;
      });
      y += 8;
    }

    doc.font("Helvetica-Bold").fontSize(12).fillColor(INK).text("Your Impact", 50, y); y += 18;
    if (impactLines.length === 0) {
      doc.font("Helvetica").fontSize(10).fillColor(INK3).text("Impact translations will appear here once configured for this organization.", 50, y, { width: PW - 100 }); y = doc.y + 10;
    } else {
      impactLines.forEach(line => {
        doc.font("Helvetica").fontSize(10).fillColor(INK).text("•  " + line, 50, y, { width: PW - 100, lineGap: 2 });
        y = doc.y + 6;
      });
      y += 8;
    }

    if (recentGifts.length > 0) {
      doc.moveTo(50, y).lineTo(PW - 50, y).strokeColor("#e5e7eb").lineWidth(0.5).stroke(); y += 16;
      doc.font("Helvetica-Bold").fontSize(12).fillColor(INK).text("Recent Gifts", 50, y); y += 18;
      recentGifts.forEach((g, i) => {
        const d = g.date ? new Date(g.date).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }) : "—";
        doc.rect(50, y, PW - 100, 19).fill(i % 2 === 0 ? "#ffffff" : BG);
        doc.font("Helvetica").fontSize(8).fillColor(INK).text(d, 58, y + 5, { width: 90 });
        doc.fillColor(INK3).text(g.campaign || "General", 155, y + 5, { width: 250 });
        doc.font("Helvetica-Bold").fillColor(GREEN).text(fmtD(g.amount), PW - 150, y + 5, { width: 100, align: "right" });
        y += 19;
      });
    }

    const range = doc.bufferedPageRange();
    for (let i = range.start; i < range.start + range.count; i++) {
      doc.switchToPage(i);
      doc.font("Helvetica").fontSize(7).fillColor("#9ca3af")
        .text(`${org.name}  ·  Impact Summary  ·  Generated ${genDate}`, 50, doc.page.height - 28, { width: PW - 130, height: 20, align: "left" })
        .text(`${i - range.start + 1} / ${range.count}`, PW - 80, doc.page.height - 28, { width: 30, height: 20, align: "right" });
    }

    doc.end();
  });

  const safeDonor = (donor.name || "donor").replace(/[^a-z0-9]/gi, "-").replace(/-+/g, "-").toLowerCase();
  res.setHeader("Content-Type", "application/pdf");
  res.setHeader("Content-Disposition", `attachment; filename="${safeDonor}-impact-summary.pdf"`);
  res.setHeader("Content-Length", pdfBuffer.length);
  res.end(pdfBuffer);
}));

// ── Impact metrics (org-configured milestone/anniversary email content) ────
app.get("/impact-metrics", requireAuth, wrap(async (req, res) => {
  const rows = await query("SELECT * FROM impact_metrics WHERE org_id=? ORDER BY dollar_threshold ASC", [req.user.orgId]);
  res.json(rows);
}));

app.post("/impact-metrics", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const { name, dollarThreshold, outcomeTemplate } = req.body;
  if (!name || !dollarThreshold || !outcomeTemplate) return res.status(400).json({ error: "name, dollarThreshold, and outcomeTemplate required" });
  const id = "im_" + uuid().slice(0, 8);
  await run(
    "INSERT INTO impact_metrics (id,org_id,name,dollar_threshold,outcome_template) VALUES (?,?,?,?,?)",
    [id, req.user.orgId, name, parseFloat(dollarThreshold), outcomeTemplate]
  );
  const rows = await query("SELECT * FROM impact_metrics WHERE id=?", [id]);
  res.status(201).json(rows[0]);
}));

app.put("/impact-metrics/:id", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const { name, dollarThreshold, outcomeTemplate, active } = req.body;
  const affected = await run(
    "UPDATE impact_metrics SET name=?, dollar_threshold=?, outcome_template=?, active=? WHERE id=? AND org_id=?",
    [name, parseFloat(dollarThreshold), outcomeTemplate, active !== false, req.params.id, req.user.orgId]
  );
  if (!affected.changes) return res.status(404).json({ error: "Not found" });
  const rows = await query("SELECT * FROM impact_metrics WHERE id=?", [req.params.id]);
  res.json(rows[0]);
}));

app.delete("/impact-metrics/:id", requireAuth, requireAdmin, wrap(async (req, res) => {
  const undoId = await trashRow("impact_metrics", req.params.id, req);
  if (!undoId) return res.status(404).json({ error: "Not found" }); // BUILD-75 B: a foreign/unknown id answers 404, never a false success — one answer everywhere
  res.json({ success: true, deleted: 1, undoId, undoSeconds: UNDO_SECONDS });
}));

// ── Milestone drafts (AI-drafted, staff-reviewed before sending — see
// processSequences()'s 'milestone' branch for why this isn't auto-sent) ────
app.get("/milestone-drafts", requireAuth, wrap(async (req, res) => {
  const status = req.query.status || "pending_review";
  const rows = await query(
    `SELECT md.*, d.name AS donor_name, d.email AS donor_email, d.total_giving AS donor_total_giving
     FROM milestone_drafts md
     JOIN donors d ON d.id = md.donor_id
     WHERE md.org_id = ? AND md.status = ?
     ORDER BY md.created_at DESC`,
    [req.user.orgId, status]
  );
  res.json(rows);
}));

app.put("/milestone-drafts/:id", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { subject, body } = req.body;
  if (!subject || !body) return res.status(400).json({ error: "subject and body required" });
  const affected = await run(
    // Saving her own edit is reviewing it: she has just read every word.
    "UPDATE milestone_drafts SET subject=?, body=?, reviewed_at=NOW(), reviewed_by=?, reviewed_by_name=? WHERE id=? AND org_id=? AND status='pending_review'",
    [subject, body, actor(req).id, actor(req).name, req.params.id, req.user.orgId]
  );
  if (!affected.changes) return res.status(404).json({ error: "Not found or already sent" });
  const rows = await query("SELECT * FROM milestone_drafts WHERE id=?", [req.params.id]);
  res.json(rows[0]);
}));

// EMAIL-1 — START FROM A TEMPLATE. The draft's subject and words become the
// template's, rendered as text with this person's name and last gift in it,
// and the draft remembers the template. It is still a draft: a person reads
// it and presses Send. Undo is /restore with the words it had before.
app.post("/milestone-drafts/:id/from-template", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const [d] = await query("SELECT * FROM milestone_drafts WHERE id=? AND org_id=? AND status='pending_review'", [req.params.id, orgId]);
  if (!d) return res.status(404).json({ error: "Not found or already sent" });
  const t = await emailCompose.templateFor(orgId, req.body && req.body.templateId);
  if (!t) return res.status(404).json({ error: "template_not_found", message: "That template is not one of yours." });
  const [donor] = await query("SELECT * FROM donors WHERE id=? AND org_id=?", [d.donor_id, orgId]);
  const words = await emailCompose.templateTextFor(orgId, t, donor || null);
  if (!words.body) return res.status(400).json({ error: "template_empty", message: "That template has no words in it yet." });
  await run("UPDATE milestone_drafts SET subject=?, body=?, template_id=? WHERE id=? AND org_id=? AND status='pending_review'",
    [words.subject || d.subject, words.body, t.id, d.id, orgId]);
  const [row] = await query("SELECT * FROM milestone_drafts WHERE id=?", [d.id]);
  res.json({ draft: row, previous: { subject: d.subject, body: d.body, templateId: d.template_id || null },
    sentence: `The draft now starts from ${t.name}. Read it before you send it.` });
}));

app.post("/milestone-drafts/:id/restore", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { subject, body, templateId } = req.body || {};
  if (!subject || !body) return res.status(400).json({ error: "subject and body required" });
  const { changes } = await run(
    "UPDATE milestone_drafts SET subject=?, body=?, template_id=? WHERE id=? AND org_id=? AND status='pending_review'",
    [String(subject), String(body), templateId ? ((await emailCompose.templateFor(req.user.orgId, templateId)) || {}).id || null : null,
     req.params.id, req.user.orgId]);
  if (!changes) return res.status(404).json({ error: "Not found or already sent" });
  const [row] = await query("SELECT * FROM milestone_drafts WHERE id=?", [req.params.id]);
  res.json({ draft: row });
}));

app.post("/milestone-drafts/:id/dismiss", requireAuth, wrap(async (req, res) => {
  const affected = await run(
    "UPDATE milestone_drafts SET status='dismissed' WHERE id=? AND org_id=? AND status='pending_review'",
    [req.params.id, req.user.orgId]
  );
  if (!affected.changes) return res.status(404).json({ error: "Not found or already sent" });
  res.json({ success: true });
}));

// One send of one draft, by the person who pressed the button. Used by the
// single "Send" and by "Send all reviewed", so the two cannot drift apart.
// FIX-12 Part 2: workflow recipes' emails arrive here as drafts too.
async function sendMilestoneDraft(req, draft, opts = {}) {
  const donorRows = await query("SELECT * FROM donors WHERE id=? AND org_id=?", [draft.donor_id, req.user.orgId]);
  const donor = donorRows[0];
  if (!donor || !donor.email) return { status: 400, error: "Donor has no email on file" };

  // PARITY-3 — a volunteer's shift reminder is transactional (FIX-14), so it is
  // asked as one: a marketing opt-out does not stop the reminder for a shift
  // they signed up for. Everything else here is asked as a milestone.
  // FIX-20 Part 5: an auction winner's pay link is service mail about a bid
  // they made, so it is asked as transactional too. A bounce or a complaint
  // still refuses it, and the auction screen offers its Copy link instead.
  const kind = draft.source === "volunteer_reminder" ? "volunteer_reminder"
    : String(draft.milestone_key || "").startsWith("auction-winner:") ? "auction_winner" : "milestone";
  const decision = await donorMailDecision(kind, donor.email, req.user.orgId);
  if (!decision.send) return { status: 400, error: `Cannot send: ${decision.reason === "deceased" ? "this donor is marked deceased" : decision.reason === "do_not_contact" ? "this donor is marked do-not-contact" : (mailPolicy.REASON_SENTENCE[decision.reason] || `this donor is suppressed (${String(decision.reason).replace(/_/g, " ")})`)}` };

  if (process.env.RESEND_API_KEY) {
    // PARITY-2 Part 4: a link in a draft (a winner's pay link, an auction
    // page, a video thank-you) is a link in the email, not text to retype.
    // Only http(s) links, matched AFTER escaping, so nothing typed can open a tag.
    const bodyHtml = `<p>${escapeHtml(draft.body).replace(/https?:\/\/[^\s<]+/g, u => `<a href="${u}">${u}</a>`)
      .replace(/\n\n+/g, "</p><p>").replace(/\n/g, "<br>")}</p>`
      + await unsubscribeEmailFooterHtml(donor.email, req.user.orgId, "sequence");
    try {
      const { error: sendErr } = await resend.emails.send({
        ...(await donorSendOpts(req.user.orgId, donor.email, "sequence")),
        to: donor.email, subject: draft.subject, html: bodyHtml,
      });
      if (sendErr) return { status: 502, error: `Send failed: ${sendErr.message}` };
    } catch (e) {
      return { status: 502, error: `Send failed: ${e.message}` };
    }
  }

  const who = actor(req);
  await run(
    "UPDATE milestone_drafts SET status='sent', sent_at=NOW(), reviewed_by=?, reviewed_by_name=COALESCE(reviewed_by_name, ?) WHERE id=?",
    [req.user.userId, who.name, draft.id]
  );
  const today = orgToday(await orgTz(req.user.orgId));   // ORG_TZ_SEAM_OK (FIX-14 Part 2b)
  const intId = "i_" + uuid().slice(0, 8);
  await run(
    "INSERT INTO interactions (id, org_id, donor_id, type, note, date, created_by, logged_by_name, metadata) VALUES (?, ?, ?, 'email', ?, ?, ?, ?, ?)",
    [intId, req.user.orgId, draft.donor_id, `${draft.source ? "Email" : "Milestone email"}: ${draft.subject}`, today, who.id, who.name,
     opts.taskId ? JSON.stringify({ via: "task_email", taskId: opts.taskId, touch: "email" }) : null]
  ).catch(() => {});
  return { status: 200, interactionId: intId };
}

// PARITY-3 — the volunteer routes send their drafts through this one function.
if (typeof ctx.registerDraftSender === "function") ctx.registerDraftSender(sendMilestoneDraft);

app.post("/milestone-drafts/:id/send", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const drafts = await query(
    "SELECT * FROM milestone_drafts WHERE id=? AND org_id=? AND status='pending_review'",
    [req.params.id, req.user.orgId]
  );
  if (!drafts.length) return res.status(404).json({ error: "Not found or already sent" });
  const r = await sendMilestoneDraft(req, drafts[0]);
  if (r.status !== 200) return res.status(r.status).json({ error: r.error });
  res.json({ success: true });
}));

// She read it and the words are right. Not sent: that is still her press.
app.post("/milestone-drafts/:id/reviewed", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const who = actor(req);
  const { changes } = await run(
    "UPDATE milestone_drafts SET reviewed_at=NOW(), reviewed_by=?, reviewed_by_name=? WHERE id=? AND org_id=? AND status='pending_review'",
    [who.id, who.name, req.params.id, req.user.orgId]);
  if (!changes) return res.status(404).json({ error: "Not found or already sent" });
  res.json({ success: true });
}));

// "Send all reviewed": every draft somebody marked reviewed, and nothing else.
// One press by one person; each draft is still checked against the mail rules.
app.post("/milestone-drafts/send-reviewed", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const drafts = await query(
    "SELECT * FROM milestone_drafts WHERE org_id=? AND status='pending_review' AND reviewed_at IS NOT NULL ORDER BY created_at ASC LIMIT 200",
    [req.user.orgId]);
  let sent = 0; const failed = [];
  for (const d of drafts) {
    const r = await sendMilestoneDraft(req, d);
    if (r.status === 200) sent++; else failed.push({ id: d.id, error: r.error });
  }
  req.audit && req.audit.action(`sent ${sent} reviewed draft${sent === 1 ? "" : "s"}`);
  res.json({ sent, failed });
}));

// ── Personal-note reminders (non-AI-drafted sibling of milestone_drafts) ───
app.get("/note-reminders", requireAuth, wrap(async (req, res) => {
  const status = req.query.status || "pending";
  const rows = await query(
    `SELECT nr.*, d.name AS donor_name, d.email AS donor_email, d.total_giving AS donor_total_giving
     FROM note_reminders nr
     JOIN donors d ON d.id = nr.donor_id
     WHERE nr.org_id = ? AND nr.status = ?
     ORDER BY nr.created_at DESC`,
    [req.user.orgId, status]
  );
  res.json(rows.map(r => ({ ...r, talking_points: typeof r.talking_points === "string" ? JSON.parse(r.talking_points) : r.talking_points })));
}));

// Marks the reminder sent and logs a stewardship interaction confirming a
// personal note went out — never generates or stores any note content.
app.post("/note-reminders/:id/send", requireAuth, wrap(async (req, res) => {
  const rows = await query(
    "SELECT * FROM note_reminders WHERE id=? AND org_id=? AND status='pending'",
    [req.params.id, req.user.orgId]
  );
  if (!rows.length) return res.status(404).json({ error: "Not found or already handled" });
  const reminder = rows[0];
  const points = typeof reminder.talking_points === "string" ? JSON.parse(reminder.talking_points) : reminder.talking_points;

  await run(
    "UPDATE note_reminders SET status='sent', sent_at=NOW(), sent_by=? WHERE id=?",
    [req.user.userId, reminder.id]
  );
  const today = orgToday(await orgTz(req.user.orgId));   // ORG_TZ_SEAM_OK (FIX-14 Part 2b)
  await run(
    "INSERT INTO interactions (id, org_id, donor_id, type, note, date, metadata) VALUES (?, ?, ?, 'stewardship', ?, ?, ?)",
    ["i_" + uuid().slice(0, 8), req.user.orgId, reminder.donor_id, "Personal note sent", today,
     JSON.stringify({ stewardship_type: "personal_note", detail: (points || []).join(" · ") })]
  ).catch(() => {});

  res.json({ success: true });
}));

app.post("/note-reminders/:id/dismiss", requireAuth, wrap(async (req, res) => {
  const affected = await run(
    "UPDATE note_reminders SET status='dismissed' WHERE id=? AND org_id=? AND status='pending'",
    [req.params.id, req.user.orgId]
  );
  if (!affected.changes) return res.status(404).json({ error: "Not found or already handled" });
  res.json({ success: true });
}));

// ── Voice memos ──────────────────────────────────────────────────────────────
// Two-step, human-in-the-loop flow: /transcribe uploads + transcribes audio
// and runs one narrow AI extraction pass, but saves NOTHING — the officer
// reviews the transcript and suggestions client-side and only /save persists
// anything (the interaction, and optionally the extracted detail/task, only
// if the officer confirmed each). Requires OPENAI_API_KEY (Whisper) — if
// unset, returns a clear error rather than failing silently or falling back
// to a stub.
app.post("/voice-memos/transcribe", requireAuth, wrap(async (req, res) => {
  const { donorId, audioBase64, mimeType } = req.body;
  if (!donorId || !audioBase64) return res.status(400).json({ error: "A donor and a recording are both needed." });
  if (!process.env.OPENAI_API_KEY) {
    console.error("[voice-memo] transcription refused: no transcription key is configured on this server");
    return res.status(503).json({ error: "Voice notes aren't available yet. We'll let you know when they are." });
  }

  const donorRows = await query("SELECT id, name FROM donors WHERE id=? AND org_id=?", [donorId, req.user.orgId]);
  if (!donorRows.length) return res.status(404).json({ error: "Donor not found" });

  let transcript;
  // FIX-12 Part 3: the recording goes to OpenAI only through the one AI door,
  // which refuses when the org has AI turned off.
  try { await requireAi(req.user.orgId, "openai"); }
  catch (e) { if (e instanceof AiOffError) return res.status(403).json({ error: AI_OFF_MESSAGE, code: "ai_off" }); throw e; }
  try {
    const audioBuffer = Buffer.from(audioBase64, "base64");
    const ext = (mimeType || "").includes("mp4") ? "mp4" : (mimeType || "").includes("wav") ? "wav" : "webm";
    const whisperResp = await transcribeAudio(req.user.orgId, { audioBuffer, mimeType, ext });
    if (!whisperResp.ok) {
      const errText = await whisperResp.text();
      console.error("[voice-memo] Whisper error:", whisperResp.status, errText);
      return res.status(502).json({ error: "Transcription failed — please try again." });
    }
    const whisperJson = await whisperResp.json();
    transcript = (whisperJson.text || "").trim();
  } catch (e) {
    console.error("[voice-memo] transcription failed:", e.message);
    return res.status(502).json({ error: "Transcription failed: " + e.message });
  }

  if (!transcript) return res.json({ transcript: "", suggestedDetail: null, suggestedAction: null });

  // Single narrow extraction pass — not a general chatbot, one specific job.
  let suggestedDetail = null, suggestedAction = null;
  try {
    const client = anthropicFor(req.user.orgId);
    const msg = await client.messages.create({
      model: "claude-sonnet-4-6",
      max_tokens: 200,
      thinking: { type: "disabled" },   // FIX-28: a short extraction needs no thinking (the ASK-3 rule)
      system: `Extract from a voice memo a nonprofit development officer just recorded about a donor. Return ONLY valid JSON: {"personalDetail":"..." or null,"suggestedAction":"..." or null} — no markdown, no explanation. personalDetail: one short, specific, worth-remembering fact about the donor (family, interests, preferences, life event) mentioned in the memo — null if nothing like that was mentioned. suggestedAction: one short, concrete next step implied by the memo (e.g. "Send the gala invite", "Follow up after their trip in March") — null if none is implied.`,
      messages: [{ role: "user", content: `Donor: ${donorRows[0].name}\nTranscript: ${transcript}` }],
    });
    // FIX-28: an unfinished reply suggests nothing.
    const text = msg.stop_reason && msg.stop_reason !== "end_turn" ? ""
      : (msg.content || []).filter(b => b.type === "text").map(b => b.text).join("").trim();
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      suggestedDetail = parsed.personalDetail || null;
      suggestedAction = parsed.suggestedAction || null;
    }
  } catch (e) {
    console.error("[voice-memo] extraction failed (non-fatal, transcript still returned):", e.message);
  }

  res.json({ transcript, suggestedDetail, suggestedAction });
}));

app.post("/voice-memos/save", requireAuth, checkWriteAccess, wrap(async (req, res) => {
  const { donorId, transcript, addDetailToNotes, detailText, createFollowUpTask, actionText } = req.body;
  if (!donorId || !transcript) return res.status(400).json({ error: "donorId and transcript required" });
  const donorRows = await query("SELECT * FROM donors WHERE id=? AND org_id=?", [donorId, req.user.orgId]);
  if (!donorRows.length) return res.status(404).json({ error: "Donor not found" });
  const donor = donorRows[0];

  const today = orgToday(await orgTz(req.user.orgId));   // ORG_TZ_SEAM_OK (FIX-14 Part 2b)
  await run(
    "INSERT INTO interactions (id,org_id,donor_id,type,note,date,created_by) VALUES (?,?,?,?,?,?,?)",
    ["i_" + uuid().slice(0, 8), req.user.orgId, donorId, "voice_memo", transcript, today, req.user.userId]
  );

  // Both of these are opt-in — the officer explicitly confirmed each one
  // client-side before this request was sent. Nothing AI-inferred is saved
  // to the donor record without that confirmation.
  if (addDetailToNotes && detailText && detailText.trim()) {
    const updatedNotes = donor.notes ? `${donor.notes}\n\n${detailText.trim()}` : detailText.trim();
    await run("UPDATE donors SET notes=? WHERE id=? AND org_id=?", [updatedNotes, donorId, req.user.orgId]);
  }

  let taskId = null;
  if (createFollowUpTask && actionText && actionText.trim()) {
    taskId = "t_" + uuid().slice(0, 8);
    const due = new Date(); due.setDate(due.getDate() + 7);
    await run(
      "INSERT INTO tasks (id,org_id,title,due,priority,type,done,donor_id,created_by,created_by_name) VALUES (?,?,?,?,?,?,0,?,?,?)",
      [taskId, req.user.orgId, actionText.trim(), due.toISOString().slice(0, 10), "medium", "donor", donorId, actor(req).id, actor(req).name]
    );
  }

  res.json({ success: true, taskId });
}));

// ── Custom Fields (BUILD-78) ────────────────────────────────────────────────
// The definitions table (custom_field_defs) is the ONLY authority on shape;
// values live in a custom_fields JSONB column ON the donor/gift row. Every
// value write goes through validateCustomFields (customFields.js) — THE one
// seam (spec 1.4); a second validation implementation anywhere is the defect.
// There is NO hard-delete path in this build: archive hides a field from the
// record, the mapper and the export, and destroys nothing (spec 1.6).
const CF_ENTITIES = ["donor", "gift"];
const cfDefOut = d => ({
  id: d.id, entity: d.entity, key: d.key, label: d.label, type: d.type,
  options: Array.isArray(d.options) ? d.options : JSON.parse(d.options || "[]"),
  position: d.position, showInDirectory: !!d.show_in_directory,
  archivedAt: d.archived_at || null, createdBy: d.created_by || null,
  createdByName: d.created_by_name || null, createdSource: d.created_source || null,
  createdAt: d.created_at,
});
// Part 9 — definition changes and value writes land in the audit trail as
// their OWN event types, each carrying an actor identity (never a boolean).
async function cfEvent(req, orgId, entity, event, { fieldId, entityId, detail } = {}) {
  await run(
    `INSERT INTO custom_field_events (id,org_id,entity,field_id,entity_id,event,detail,created_by,created_by_name)
     VALUES (?,?,?,?,?,?,?,?,?)`,
    ["cfe_" + uuid().slice(0, 12), orgId, entity, fieldId || null, entityId || null, event,
     JSON.stringify(detail || {}), actor(req).id, actor(req).name]
  );
}
async function cfShape() { return import("../shared/customFieldShape.js"); }

app.get("/import-field-mappings", requireAuth, wrap(async (req, res) => {
  const entity = String(req.query.entity || "").toLowerCase();
  const rows = await query(
    `SELECT m.entity, m.header_norm, m.field_id FROM import_field_mappings m
     JOIN custom_field_defs d ON d.id = m.field_id
     WHERE m.org_id=?${CF_ENTITIES.includes(entity) ? " AND m.entity=?" : ""} AND d.archived_at IS NULL`,
    CF_ENTITIES.includes(entity) ? [req.user.orgId, entity] : [req.user.orgId]
  );
  res.json(rows.map(r => ({ entity: r.entity, header: r.header_norm, fieldId: r.field_id })));
}));

app.get("/custom-fields", requireAuth, wrap(async (req, res) => {
  const entity = String(req.query.entity || "donor").toLowerCase();
  if (!CF_ENTITIES.includes(entity)) return res.status(400).json({ error: "entity must be donor or gift" });
  const defs = await loadCfDefs(entity, req.user.orgId, { includeArchived: req.query.includeArchived === "1" });
  res.json(defs.map(cfDefOut));
}));

// BUILD-80 Part 10 — the KEPT-RAW surface (BUILD-78's named gap): every
// stored custom value that does not coerce under its field's current type,
// listed with donor, field and value so an admin can fix it in place (the
// fix goes through the normal validated donor-update path). The population
// is a frozen migration artifact — no write path can add to it — but it must
// not sit there quietly forever.
app.get("/custom-fields/kept-raw", requireAuth, requireAdmin, wrap(async (req, res) => {
  const { coerceCustomValue } = await cfShape();
  const orgId = req.user.orgId;
  const defs = await loadCfDefs("donor", orgId, {});
  const byKey = new Map(defs.map(d => [d.key, d]));
  const rows = await query(
    "SELECT id, name, custom_fields FROM donors WHERE org_id=? AND deleted_at IS NULL AND custom_fields IS NOT NULL", [orgId]);
  const keptRaw = [];
  for (const r of rows) {
    let cf = r.custom_fields;
    if (typeof cf === "string") { try { cf = JSON.parse(cf); } catch { continue; } }
    if (!cf || typeof cf !== "object") continue;
    for (const [k, v] of Object.entries(cf)) {
      const def = byKey.get(k);
      if (!def) { keptRaw.push({ donorId: r.id, donorName: r.name, key: k, label: k, value: v, problem: "no field definition" }); continue; }
      const c = coerceCustomValue(def, v);
      if (!c.ok) keptRaw.push({ donorId: r.id, donorName: r.name, key: k, label: def.label, type: def.type, value: v, problem: c.errors?.[0] || "does not match the field's type" });
    }
    if (keptRaw.length >= 500) break;
  }
  res.json({ keptRaw, count: keptRaw.length });
}));

// The fix-in-place: one donor, one key, one corrected value — validated
// through the SAME seam every other custom-field write uses.
app.put("/custom-fields/kept-raw/:donorId", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const orgId = req.user.orgId;
  const { key, value } = req.body || {};
  if (!key) return res.status(400).json({ error: "key required" });
  const [donor] = await query("SELECT id, custom_fields FROM donors WHERE id=? AND org_id=? AND deleted_at IS NULL", [req.params.donorId, orgId]);
  if (!donor) return res.status(404).json({ error: "donor not found" });
  const v = await validateCustomFields("donor", orgId, { [key]: value });
  if (!v.ok) return res.status(422).json({ error: "invalid value", details: v.errors });
  let cf = donor.custom_fields;
  if (typeof cf === "string") { try { cf = JSON.parse(cf); } catch { cf = {}; } }
  cf = { ...(cf || {}), ...v.values };
  if (value === "" || value === null) delete cf[key];
  await run("UPDATE donors SET custom_fields=?, updated_at=NOW() WHERE id=?", [JSON.stringify(cf), donor.id]);
  res.json({ ok: true, stored: v.values[key] ?? null });
}));

app.post("/custom-fields", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const { CF_TYPES, CF_LIMITS, generateFieldKey } = await cfShape();
  const entity = String(req.body.entity || "donor").toLowerCase();
  if (!CF_ENTITIES.includes(entity)) return res.status(400).json({ error: "entity must be donor or gift" });
  const label = String(req.body.label || "").trim();
  const type = String(req.body.type || req.body.fieldType || "").trim();
  if (!label) return res.status(400).json({ error: "label required" });
  if (label.length > CF_LIMITS.LABEL_MAX) return res.status(400).json({ error: `label is over the ${CF_LIMITS.LABEL_MAX}-character limit` });
  if (!CF_TYPES.includes(type)) return res.status(400).json({ error: `type must be one of: ${CF_TYPES.join(", ")}` });
  const wantsOptions = type === "select" || type === "multi_select";
  const options = [...new Set((Array.isArray(req.body.options) ? req.body.options : []).map(o => String(o).trim()).filter(Boolean))];
  if (wantsOptions && !options.length) return res.status(400).json({ error: "select fields need at least one option" });
  if (!wantsOptions && options.length) return res.status(400).json({ error: `a ${type} field does not take options` });
  if (options.length > CF_LIMITS.OPTIONS_PER_SELECT)
    return res.status(400).json({ error: `that is ${options.length} options — the limit is ${CF_LIMITS.OPTIONS_PER_SELECT}. Past that a select is free text wearing a costume; consider a text field.` });

  // The 40-field cap counts LIVE fields; archiving frees a slot, and restore
  // is never blocked by the cap (restore must always work — spec 1.6).
  const live = await query(`SELECT COUNT(*)::int AS n FROM custom_field_defs WHERE org_id=? AND entity=? AND archived_at IS NULL`, [req.user.orgId, entity]);
  if (live[0].n >= CF_LIMITS.FIELDS_PER_ENTITY)
    return res.status(400).json({ error: `this org already has ${live[0].n} ${entity} fields — the limit is ${CF_LIMITS.FIELDS_PER_ENTITY}. Archive fields you no longer use to make room.` });

  const existingKeys = (await query(`SELECT key FROM custom_field_defs WHERE org_id=? AND entity=?`, [req.user.orgId, entity])).map(r => r.key);
  const key = generateFieldKey(label, existingKeys);   // immutable forever from here
  const maxPos = await query(`SELECT COALESCE(MAX(position),0) AS mp FROM custom_field_defs WHERE org_id=? AND entity=?`, [req.user.orgId, entity]);
  const id = "cfd_" + uuid().slice(0, 12);
  const source = req.body.source ? String(req.body.source).slice(0, 200) : null;
  await run(
    `INSERT INTO custom_field_defs (id,org_id,entity,key,label,type,options,position,created_by,created_by_name,created_source)
     VALUES (?,?,?,?,?,?,?,?,?,?,?)`,
    [id, req.user.orgId, entity, key, label, type, JSON.stringify(options), (maxPos[0]?.mp || 0) + 1,
     actor(req).id, actor(req).name, source]
  );
  await cfEvent(req, req.user.orgId, entity, "definition_created", { fieldId: id, detail: { key, label, type, source } });
  const [field] = await query(`SELECT * FROM custom_field_defs WHERE id=?`, [id]);
  res.json(cfDefOut(field));
}));

// reorder MUST be before /:id
app.put("/custom-fields/reorder", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const { ids } = req.body;
  const entity = String(req.body.entity || "donor").toLowerCase();
  if (!Array.isArray(ids)) return res.status(400).json({ error: "ids array required" });
  for (let i = 0; i < ids.length; i++) {
    await run(`UPDATE custom_field_defs SET position=? WHERE id=? AND org_id=? AND entity=?`, [i + 1, ids[i], req.user.orgId, entity]);
  }
  await cfEvent(req, req.user.orgId, entity, "definition_reordered", { detail: { ids } });
  res.json({ ok: true });
}));

app.put("/custom-fields/:id", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const { CF_LIMITS } = await cfShape();
  const [field] = await query(`SELECT * FROM custom_field_defs WHERE id=? AND org_id=?`, [req.params.id, req.user.orgId]);
  if (!field) return res.status(404).json({ error: "Not found" });
  // Type is IMMUTABLE after creation (spec 5.3): changing a type is a data
  // migration wearing a dropdown, and the honest version of it is out of
  // scope. The key never changes, period (1.2).
  if ((req.body.type || req.body.fieldType) && String(req.body.type || req.body.fieldType) !== field.type)
    return res.status(400).json({ error: "a field's type cannot change after creation — archive this field and create a new one" });
  if (req.body.key && req.body.key !== field.key)
    return res.status(400).json({ error: "a field's key never changes" });

  const label = req.body.label !== undefined ? String(req.body.label || "").trim() : field.label;
  if (!label) return res.status(400).json({ error: "label required" });
  if (label.length > CF_LIMITS.LABEL_MAX) return res.status(400).json({ error: `label is over the ${CF_LIMITS.LABEL_MAX}-character limit` });

  let options = Array.isArray(field.options) ? field.options : JSON.parse(field.options || "[]");
  if (req.body.options !== undefined) {
    const next = [...new Set((Array.isArray(req.body.options) ? req.body.options : []).map(o => String(o).trim()).filter(Boolean))];
    if (field.type !== "select" && field.type !== "multi_select") {
      if (next.length) return res.status(400).json({ error: `a ${field.type} field does not take options` });
    } else {
      // Options can be ADDED, never removed or renamed here — a removed
      // option orphans every value that holds it. (An honest option
      // migration is future work; recorded in the findings.)
      const missing = options.filter(o => !next.includes(o));
      if (missing.length) return res.status(400).json({ error: `options cannot be removed: ${missing.join(", ")} — stored values still point at them` });
      if (next.length > CF_LIMITS.OPTIONS_PER_SELECT)
        return res.status(400).json({ error: `that is ${next.length} options — the limit is ${CF_LIMITS.OPTIONS_PER_SELECT}` });
      options = next;
    }
  }
  const showInDirectory = req.body.showInDirectory !== undefined ? !!req.body.showInDirectory : field.show_in_directory;
  await run(`UPDATE custom_field_defs SET label=?, options=?, show_in_directory=? WHERE id=? AND org_id=?`,
    [label, JSON.stringify(options), showInDirectory, req.params.id, req.user.orgId]);
  if (label !== field.label)
    await cfEvent(req, req.user.orgId, field.entity, "definition_renamed", { fieldId: field.id, detail: { from: field.label, to: label, key: field.key } });
  else
    await cfEvent(req, req.user.orgId, field.entity, "definition_updated", { fieldId: field.id, detail: { key: field.key } });
  const [updated] = await query(`SELECT * FROM custom_field_defs WHERE id=?`, [req.params.id]);
  res.json(cfDefOut(updated));
}));

app.post("/custom-fields/:id/archive", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const [field] = await query(`SELECT * FROM custom_field_defs WHERE id=? AND org_id=?`, [req.params.id, req.user.orgId]);
  if (!field) return res.status(404).json({ error: "Not found" });
  if (!field.archived_at) {
    await run(`UPDATE custom_field_defs SET archived_at=NOW() WHERE id=? AND org_id=?`, [req.params.id, req.user.orgId]);
    await cfEvent(req, req.user.orgId, field.entity, "definition_archived", { fieldId: field.id, detail: { key: field.key, label: field.label } });
  }
  const [updated] = await query(`SELECT * FROM custom_field_defs WHERE id=?`, [req.params.id]);
  res.json(cfDefOut(updated));
}));

app.post("/custom-fields/:id/restore", requireAuth, requireAdmin, checkWriteAccess, wrap(async (req, res) => {
  const [field] = await query(`SELECT * FROM custom_field_defs WHERE id=? AND org_id=?`, [req.params.id, req.user.orgId]);
  if (!field) return res.status(404).json({ error: "Not found" });
  if (field.archived_at) {
    await run(`UPDATE custom_field_defs SET archived_at=NULL WHERE id=? AND org_id=?`, [req.params.id, req.user.orgId]);
    await cfEvent(req, req.user.orgId, field.entity, "definition_restored", { fieldId: field.id, detail: { key: field.key, label: field.label } });
  }
  const [updated] = await query(`SELECT * FROM custom_field_defs WHERE id=?`, [req.params.id]);
  res.json(cfDefOut(updated));   // restored — every value comes back with it, because none ever left
}));

